// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC4626} from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IStrategyAdapter} from "./IStrategyAdapter.sol";

interface ITokenMessenger {
    function depositForBurn(
        uint256 amount,
        uint32 destinationDomain,
        bytes32 mintRecipient,
        address burnToken,
        bytes32 destinationCaller,
        uint256 maxFee,
        uint32 minFinalityThreshold
    ) external;
}

/// @notice CCTP V2 MessageTransmitter — only the function needed for atomic settle.
interface IMessageTransmitterV2 {
    function receiveMessage(bytes calldata message, bytes calldata attestation) external returns (bool success);
    function localDomain() external view returns (uint32);
}

/// @notice Decoder for native Circle MessageV2 / BurnMessageV2, not a compatibility envelope.
/// @dev All fields are big-endian. Header offsets (148 bytes before body):
///      0: version uint32 (1); 4: sourceDomain uint32; 8: destinationDomain uint32;
///      12: nonce bytes32; 44: sender bytes32 (remote TokenMessenger);
///      76: recipient bytes32 (local TokenMessenger); 108: destinationCaller bytes32;
///      140: minFinalityThreshold uint32; 144: finalityThresholdExecuted uint32; 148: body.
///      Body offsets (228 fixed bytes, relative to 148):
///      0: version uint32 (1); 4: burnToken bytes32; 36: mintRecipient bytes32;
///      68: amount uint256; 100: messageSender bytes32; 132: maxFee uint256;
///      164: feeExecuted uint256; 196: expirationBlock uint256; 228: optional hookData.
library CctpMessageDecoder {
    uint256 internal constant HEADER_LEN = 148;
    uint256 internal constant MIN_MESSAGE_LEN = 148 + 228;

    error InvalidMessageRange(uint256 length, uint256 offset, uint256 size);
    error WrongHeaderVersion(uint32 actual);
    error WrongBodyVersion(uint32 actual);

    struct Header {
        uint32 sourceDomain;
        uint32 destinationDomain;
        bytes32 nonce;
        bytes32 sender;
        bytes32 recipient;
        bytes32 destinationCaller;
    }

    /// @dev Subtraction-based bounds checks also reject oversized offsets without arithmetic panic.
    function _field(bytes calldata message, uint256 offset, uint256 size)
        internal pure returns (bytes calldata)
    {
        if (offset > message.length || size > message.length - offset) {
            revert InvalidMessageRange(message.length, offset, size);
        }
        return message[offset:offset + size];
    }

    function decodeHeader(bytes calldata message) internal pure returns (Header memory h) {
        _field(message, 0, HEADER_LEN);
        uint32 version = uint32(bytes4(_field(message, 0, 4)));
        if (version != 1) revert WrongHeaderVersion(version);
        h.sourceDomain = uint32(bytes4(_field(message, 4, 4)));
        h.destinationDomain = uint32(bytes4(_field(message, 8, 4)));
        h.nonce = bytes32(_field(message, 12, 32));
        h.sender = bytes32(_field(message, 44, 32));
        h.recipient = bytes32(_field(message, 76, 32));
        h.destinationCaller = bytes32(_field(message, 108, 32));
    }

    function decodeBody(bytes calldata message)
        internal pure returns (uint256 amount, bytes32 mintRecipient, uint256 feeExecuted)
    {
        _field(message, 0, MIN_MESSAGE_LEN);
        uint32 version = uint32(bytes4(_field(message, HEADER_LEN, 4)));
        if (version != 1) revert WrongBodyVersion(version);
        mintRecipient = bytes32(_field(message, HEADER_LEN + 36, 32));
        amount = uint256(bytes32(_field(message, HEADER_LEN + 68, 32)));
        feeExecuted = uint256(bytes32(_field(message, HEADER_LEN + 164, 32)));
    }
}

/// @notice ERC-4626 vault with native Circle CCTP V2 burns and atomic return settlement.
/// @dev Pending uint64 keys are local position IDs; inbound Circle nonces are bytes32.
contract AutonomousVault is ERC4626, Ownable2Step {
    using SafeERC20 for IERC20;

    error Paused();
    error NotManager();
    error AllocationExceedsLimit();
    error InvalidBps();
    error CrossChainNotConfigured();
    error SameDomainDeploy();
    error NonceMismatch(uint64 expected, uint64 actual);
    error ZeroAddress();
    error WrongDestinationDomain(uint32 expected, uint32 actual);
    error WrongSourceDomain(uint32 expected, uint32 actual);
    error WrongMessageRecipient(bytes32 actual);
    error InboundAlreadyConsumed();
    error WrongDestinationCaller(bytes32 actual);
    error LocalDomainMismatch(uint32 expected, uint32 actual);
    /// @notice Thrown when a cross-chain deploy would push pending cross-chain > maxPendingCrossChainBps.
    error PendingCrossChainCapExceeded();
    /// @notice Thrown when profitUnlockPeriod is set above MAX_PROFIT_UNLOCK_PERIOD.
    error InvalidUnlockPeriod();
    /// @notice Thrown by settleCrossChainWithMessage when the decoded mintRecipient is not this vault.
    error WrongMintRecipient(bytes32 recipient);
    /// @notice Thrown by settleCrossChainWithMessage when the net minted amount
    ///         (message amount minus feeExecuted) does not equal the actual USDC balance delta.
    error MessageAmountMismatch(uint256 expectedNet, uint256 balanceDelta);
    /// @notice Thrown by the write-off path when received > 0 (write-off must book a full loss).
    error WriteOffMustBeZero();
    error InvalidCrossChainMinFinality();
    error RemoteMessengerNotSet(uint32 domain);
    error WrongRemoteSender(bytes32 expected, bytes32 actual);
    error MessageReceiveFailed();

    event CrossChainMinFinalityUpdated(uint32 previous, uint32 updated);
    event CrossChainMaxFeeBpsUpdated(uint256 previous, uint256 updated);
    event RemoteTokenMessengerUpdated(uint32 indexed domain, bytes32 messenger);

    uint64 public crossChainPositionCounter;
    uint32 public crossChainMinFinality = 2000;
    uint256 public crossChainMaxFeeBps;
    uint256 public constant MAX_CROSS_CHAIN_FEE_BPS = 100;
    mapping(uint32 => bytes32) public remoteTokenMessenger;

    function setCrossChainMinFinality(uint32 finality) external onlyOwner {
        if (finality != 1000 && finality != 2000) revert InvalidCrossChainMinFinality();
        emit CrossChainMinFinalityUpdated(crossChainMinFinality, finality);
        crossChainMinFinality = finality;
    }

    function setCrossChainMaxFeeBps(uint256 bps) external onlyOwner {
        if (bps > MAX_CROSS_CHAIN_FEE_BPS) revert InvalidBps();
        emit CrossChainMaxFeeBpsUpdated(crossChainMaxFeeBps, bps);
        crossChainMaxFeeBps = bps;
    }

    function setRemoteTokenMessenger(uint32 domain, bytes32 messenger) external onlyOwner {
        if (messenger == bytes32(0)) revert ZeroAddress();
        remoteTokenMessenger[domain] = messenger;
        emit RemoteTokenMessengerUpdated(domain, messenger);
    }

    event ManagerUpdated(address indexed previousManager, address indexed newManager);
    event MaxAllocationBpsUpdated(uint256 previousBps, uint256 newBps);
    event PauseUpdated(bool paused);
    event CapitalDeployed(address indexed strategy, uint256 amount);
    event CapitalReturned(address indexed strategy, uint256 amount);
    event CapitalRecalledFromAdapter(address indexed adapter, uint256 requested, uint256 returned);
    /// @notice positionId is a local pending-position key, not Circle's offchain bytes32 nonce.
    event CapitalDeployedCrossChain(
        uint32 indexed destinationDomain,
        bytes32 indexed recipient,
        uint256 amount,
        uint64 positionId
    );
    event CrossChainSettled(uint64 indexed positionId, uint256 amount, uint256 shortfall);
    /// @notice Emitted when a CCTP Fast Transfer fee is deducted from the minted amount.
    ///         `feeExecuted` is booked as part of the cross-chain cost alongside any strategy loss.
    event CrossChainFeeDeducted(uint64 indexed positionId, uint256 feeExecuted);
    event TokenMessengerUpdated(address indexed previousMessenger, address indexed newMessenger);
    event MessageTransmitterUpdated(address indexed previous, address indexed updated);
    event ProfitLocked(uint256 amount, uint256 unlockedAt);
    event CrossChainCapUpdated(uint256 newBps);

    address public manager;
    bool public paused;
    uint256 public maxAllocationBps = 8_000;
    uint256 public totalDeployed;
    address public tokenMessenger;
    /// @dev The CCTP domain of THIS chain (set in constructor, used to guard deployCrossChain)
    uint32 public immutable sourceDomain;
    /// @dev Constructor domain is the fallback for transmitters without localDomain().
    uint32 public localDomain;
    /// @dev Tracks pending cross-chain positions: local positionId => amount.
    mapping(uint64 => uint256) public pendingCrossChain;
    mapping(uint64 => uint32) public pendingCrossChainDestinationDomain;
    mapping(uint32 => mapping(bytes32 => bool)) public consumedInbound;
    /// @dev Sum of all outstanding cross-chain positions (for cap enforcement — PR3.3).
    uint256 public totalPendingCrossChain;
    /// @notice Max fraction of totalAssets allowed in-flight cross-chain (default 2000 = 20%).
    uint256 public maxPendingCrossChainBps = 2_000;
    /// @notice Hard cap for maxPendingCrossChainBps.
    uint256 public constant MAX_PENDING_CROSS_CHAIN_BPS = 5_000;

    /// @notice CCTP V2 MessageTransmitter used by settleCrossChainWithMessage.
    ///         Set via setMessageTransmitter(). Optional — only needed for atomic settle.
    address public messageTransmitter;

    /// @notice Profit locked for linear unlock (PR3.2 — Yearn-style streaming).
    ///         Locked profit is excluded from totalAssets until unlockedAt.
    uint256 public lockedProfit;
    /// @notice Timestamp when lockedProfit finishes unlocking linearly.
    uint256 public unlockedAt;
    /// @notice Duration over which profit is linearly streamed into NAV (default 3 days).
    uint256 public profitUnlockPeriod = 3 days;
    /// @notice Hard cap for profitUnlockPeriod.
    uint256 public constant MAX_PROFIT_UNLOCK_PERIOD = 14 days;

    constructor(IERC20 asset_, address initialOwner, uint32 sourceDomain_)
        ERC4626(asset_)
        ERC20("Autonomous Vault Share", "avUSDC")
        Ownable(initialOwner)
    {
        sourceDomain = sourceDomain_;
        localDomain = sourceDomain_;
    }

    /// @dev Virtual offset of 6 decimals (matching USDC) makes the first-depositor
    ///      inflation/donation attack economically impractical by requiring an
    ///      attacker to donate 10^6 × more than the seed deposit to move the price.
    function _decimalsOffset() internal pure override returns (uint8) {
        return 6;
    }

    modifier onlyManagerOrOwner() {
        if (msg.sender != owner() && msg.sender != manager) revert NotManager();
        _;
    }

    /// @notice Returns the current locked profit (linearly decreasing to 0 over profitUnlockPeriod).
    function _currentLockedProfit() internal view returns (uint256) {
        if (lockedProfit == 0 || block.timestamp >= unlockedAt) return 0;
        uint256 duration = profitUnlockPeriod;
        if (duration == 0 || unlockedAt < duration) return 0;
        uint256 start = unlockedAt - duration;
        if (start > block.timestamp) return 0;
        uint256 elapsed = block.timestamp - start;
        // Linear: lockedProfit * (duration - elapsed) / duration
        if (elapsed >= duration) return 0;
        return (lockedProfit * (duration - elapsed)) / duration;
    }

    function totalAssets() public view virtual override returns (uint256) {
        uint256 base = super.totalAssets() + totalDeployed;
        uint256 locked = _currentLockedProfit();
        return base > locked ? base - locked : 0;
    }

    /**
     * @dev Internal helper — stacks amount on top of any remaining locked profit.
     *      Derived vaults decide which external entry points may lock profit.
     */
    function _lockProfitInternal(uint256 amount) internal {
        uint256 remaining = _currentLockedProfit();
        lockedProfit = remaining + amount;
        unlockedAt   = block.timestamp + profitUnlockPeriod;
        emit ProfitLocked(amount, unlockedAt);
    }

    /// @notice Owner updates profit unlock period (board-settable; max 14 days).
    function setProfitUnlockPeriod(uint256 period) external onlyOwner {
        if (period > MAX_PROFIT_UNLOCK_PERIOD) revert InvalidUnlockPeriod();
        uint256 remaining = _currentLockedProfit();
        lockedProfit = remaining;
        profitUnlockPeriod = period;
        if (remaining > 0) unlockedAt = block.timestamp + period;
    }

    /// @notice Owner updates max pending cross-chain cap.
    function setMaxPendingCrossChainBps(uint256 bps) external onlyOwner {
        if (bps > MAX_PENDING_CROSS_CHAIN_BPS) revert InvalidBps();
        maxPendingCrossChainBps = bps;
        emit CrossChainCapUpdated(bps);
    }

    function deployCapital(address strategy, uint256 amount, bytes calldata data) external virtual onlyManagerOrOwner {
        if (paused) revert Paused();
        data;

        // Enforce cumulative cap: already-deployed + new amount must stay within the BPS limit
        uint256 currentAssets = totalAssets();
        uint256 maxDeployable = (currentAssets * maxAllocationBps) / 10_000;
        if (totalDeployed + amount > maxDeployable) revert AllocationExceedsLimit();

        IERC20(asset()).safeTransfer(strategy, amount);
        totalDeployed += amount;

        emit CapitalDeployed(strategy, amount);
    }

    function deployCrossChain(
        uint32 destinationDomain,
        bytes32 recipient,
        uint256 amount
    ) public virtual onlyManagerOrOwner {
        if (paused) revert Paused();
        if (tokenMessenger == address(0)) revert CrossChainNotConfigured();
        // Use immutable sourceDomain (not a hardcoded constant) to block same-chain burns
        if (destinationDomain == sourceDomain) revert SameDomainDeploy();

        uint256 currentAssets = totalAssets();
        uint256 maxDeployable = (currentAssets * maxAllocationBps) / 10_000;
        if (totalDeployed + amount > maxDeployable) revert AllocationExceedsLimit();

        // PR3.3: Enforce cross-chain pending cap BEFORE burning tokens so totalAssets() is correct.
        uint256 maxPending = (totalAssets() * maxPendingCrossChainBps) / 10_000;
        if (totalPendingCrossChain + amount > maxPending) revert PendingCrossChainCapExceeded();

        CctpSettlementLogic.burn(
            asset(), tokenMessenger, destinationDomain, recipient, amount,
            crossChainMaxFeeBps, crossChainMinFinality
        );
        // Preserve the position-counter update before clearing the burn allowance.
        uint64 positionId = ++crossChainPositionCounter;
        IERC20(asset()).forceApprove(tokenMessenger, 0);
        totalDeployed += amount;
        totalPendingCrossChain += amount;
        pendingCrossChain[positionId] = amount;
        pendingCrossChainDestinationDomain[positionId] = destinationDomain;
        emit CapitalDeployedCrossChain(destinationDomain, recipient, amount, positionId);
    }

    function returnCapital(address strategy, uint256 amount) external virtual onlyManagerOrOwner {
        if (paused) revert Paused();
        // Pull actual tokens back from the strategy before adjusting accounting
        IERC20(asset()).safeTransferFrom(strategy, address(this), amount);
        totalDeployed -= amount;
        emit CapitalReturned(strategy, amount);
    }

    /// @notice Recall capital from an IStrategyAdapter. The adapter unwinds its position,
    ///         transfers USDC back to this vault, and returns the actual amount received.
    ///         totalDeployed is decremented by the actual return (not the requested amount)
    ///         so NAV accounting stays accurate even when slippage or fees reduce proceeds.
    /// @param adapter  Address implementing IStrategyAdapter (must have vault == address(this))
    /// @param amount   Requested USDC amount to recall (adapter may return less due to slippage)
    function recallCapital(address adapter, uint256 amount) external virtual onlyManagerOrOwner {
        if (paused) revert Paused();
        uint256 balanceBefore = IERC20(asset()).balanceOf(address(this));
        uint256 returned = IStrategyAdapter(adapter).recall(amount);
        uint256 balanceAfter = IERC20(asset()).balanceOf(address(this));

        // Use the higher of adapter-reported return and actual balance delta for safety
        uint256 actualReturn = balanceAfter > balanceBefore
            ? balanceAfter - balanceBefore
            : returned;

        if (actualReturn > totalDeployed) {
            totalDeployed = 0;
        } else {
            totalDeployed -= actualReturn;
        }

        emit CapitalRecalledFromAdapter(adapter, amount, actualReturn);
    }

    /**
     * @notice Atomic cross-chain settle: calls MessageTransmitter.receiveMessage in the same
     *         transaction, measures the exact USDC balance delta, and books the result.
     * @dev    J1: Replaces the old snapshot-based approach. Nothing else can move the USDC
     *         balance inside a single call, so `received` is always exact.
     *         Also verifies that the decoded mintRecipient is this vault and that the
     *         message-encoded amount matches the actual balance delta.
     * @param positionId   Local pending-position ID emitted by deployCrossChain, not a CCTP nonce.
     * @param message      Attested CCTP message bytes (returned by the CCTP attestation API).
     * @param attestation  Corresponding attestation bytes.
     */
    function settleCrossChainWithMessage(
        uint64 positionId,
        bytes calldata message,
        bytes calldata attestation
    ) external onlyManagerOrOwner {
        uint256 sent = pendingCrossChain[positionId];
        if (sent == 0) revert NonceMismatch(positionId, 0);

        if (messageTransmitter == address(0)) revert CrossChainNotConfigured();
        uint256 received = CctpSettlementLogic.receiveSettlement(
            _settlementConfig(positionId), remoteTokenMessenger, consumedInbound,
            positionId, message, attestation
        );
        _doSettle(positionId, sent, received);
    }

    /**
     * @notice Write off a lost cross-chain transfer (USDC never arrives or is unrecoverable).
     * @dev    J1: Degraded path — `received` MUST be 0. Books the full sent amount as a loss.
     *         Only callable by the owner (not the manager) to prevent accidental write-offs.
     * @param positionId  Local pending-position ID emitted by deployCrossChain.
     */
    function settleCrossChain(uint64 positionId, uint256 received) external onlyOwner {
        if (received != 0) revert WriteOffMustBeZero();
        uint256 sent = pendingCrossChain[positionId];
        if (sent == 0) revert NonceMismatch(positionId, 0);
        _doSettle(positionId, sent, 0);
    }

    /// @dev Values are passed explicitly; mappings retain their original storage roots.
    function _settlementConfig(uint64 positionId) internal view returns (CctpSettlementLogic.Config memory) {
        return CctpSettlementLogic.Config(
            asset(), messageTransmitter, tokenMessenger, localDomain,
            pendingCrossChainDestinationDomain[positionId]
        );
    }

    function _validateSettlementHeader(uint64 positionId, bytes calldata message) internal view {
        CctpSettlementLogic.validateHeader(_settlementConfig(positionId), remoteTokenMessenger, message);
    }

    function _consumeInbound(bytes calldata message) internal {
        CctpSettlementLogic.consumeInbound(consumedInbound, message);
    }

    /// @dev Shared accounting for both settle paths.
    function _doSettle(uint64 positionId, uint256 sent, uint256 received) internal {
        delete pendingCrossChain[positionId];
        delete pendingCrossChainDestinationDomain[positionId];

        uint256 shortfall = sent > received ? sent - received : 0;
        // Decrement totalDeployed by the full sent amount. The received USDC tokens are
        // already in vault balance (minted by CCTP). Do NOT add received back — that would
        // double-count. Net NAV change = received - sent = -shortfall (immediate loss).
        totalDeployed          = totalDeployed >= sent ? totalDeployed - sent : 0;
        totalPendingCrossChain = totalPendingCrossChain >= sent ? totalPendingCrossChain - sent : 0;

        emit CrossChainSettled(positionId, received, shortfall);
    }

    function setManager(address newManager) external onlyOwner {
        address previousManager = manager;
        manager = newManager;
        emit ManagerUpdated(previousManager, newManager);
    }

    function setMaxAllocationBps(uint256 bps) external onlyOwner {
        if (bps > 9_500) revert InvalidBps();

        uint256 previousBps = maxAllocationBps;
        maxAllocationBps = bps;
        emit MaxAllocationBpsUpdated(previousBps, bps);
    }

    function setTokenMessenger(address messenger) external onlyOwner {
        if (messenger == address(0)) revert ZeroAddress();
        address previous = tokenMessenger;
        tokenMessenger = messenger;
        emit TokenMessengerUpdated(previous, messenger);
    }

    event LocalDomainUpdated(uint32 domain);

    function setLocalDomain(uint32 domain) external onlyOwner {
        if (messageTransmitter == address(0)) revert ZeroAddress();
        (bool ok, bytes memory data) = messageTransmitter.staticcall(abi.encodeWithSignature("localDomain()"));
        if (ok && data.length == 32) {
            uint32 reported = abi.decode(data, (uint32));
            if (domain != reported) revert LocalDomainMismatch(reported, domain);
        }
        localDomain = domain; // Domain zero is valid.
        emit LocalDomainUpdated(domain);
    }

    function setMessageTransmitter(address transmitter) external onlyOwner {
        if (transmitter == address(0)) revert ZeroAddress();
        (bool ok, bytes memory data) = transmitter.staticcall(abi.encodeWithSignature("localDomain()"));
        localDomain = ok && data.length == 32 ? abi.decode(data, (uint32)) : sourceDomain;
        emit LocalDomainUpdated(localDomain);
        address previous = messageTransmitter;
        messageTransmitter = transmitter;
        emit MessageTransmitterUpdated(previous, transmitter);
    }

    function setPaused(bool newPaused) external onlyOwner {
        paused = newPaused;
        emit PauseUpdated(newPaused);
    }

    function deposit(uint256 assets, address receiver) public virtual override returns (uint256) {
        if (paused) revert Paused();
        return super.deposit(assets, receiver);
    }

    function mint(uint256 shares, address receiver) public virtual override returns (uint256) {
        if (paused) revert Paused();
        return super.mint(shares, receiver);
    }
}

/// @dev Linked CCTP execution in the vault's context; no independent storage or authority.
library CctpSettlementLogic {
    using SafeERC20 for IERC20;

    struct Config {
        address asset;
        address transmitter;
        address messenger;
        uint32 fallbackDomain;
        uint32 expectedSource;
    }

    function burn(
        address token, address messenger, uint32 destinationDomain, bytes32 recipient,
        uint256 amount, uint256 maxFeeBps, uint32 minFinality
    ) external {
        IERC20(token).forceApprove(messenger, amount);
        ITokenMessenger(messenger).depositForBurn(
            amount, destinationDomain, recipient, token, bytes32(0),
            (amount * maxFeeBps) / 10_000, minFinality
        );
    }

    function validateHeader(
        Config memory c, mapping(uint32 => bytes32) storage remoteMessenger, bytes calldata message
    ) external view {
        _validateHeader(c, remoteMessenger, message);
    }

    function _validateHeader(
        Config memory c, mapping(uint32 => bytes32) storage remoteMessenger, bytes calldata message
    ) private view {
        CctpMessageDecoder.Header memory h = CctpMessageDecoder.decodeHeader(message);
        uint32 domain = c.fallbackDomain;
        (bool ok, bytes memory data) = c.transmitter.staticcall(abi.encodeWithSignature("localDomain()"));
        if (ok && data.length == 32) domain = abi.decode(data, (uint32));
        if (h.destinationDomain != domain) revert AutonomousVault.WrongDestinationDomain(domain, h.destinationDomain);
        if (h.sourceDomain != c.expectedSource) revert AutonomousVault.WrongSourceDomain(c.expectedSource, h.sourceDomain);
        if (h.recipient != bytes32(uint256(uint160(c.messenger)))) revert AutonomousVault.WrongMessageRecipient(h.recipient);
        if (h.destinationCaller != bytes32(uint256(uint160(address(this))))) {
            revert AutonomousVault.WrongDestinationCaller(h.destinationCaller);
        }
        bytes32 expectedSender = remoteMessenger[h.sourceDomain];
        if (expectedSender == bytes32(0)) revert AutonomousVault.RemoteMessengerNotSet(h.sourceDomain);
        if (h.sender != expectedSender) revert AutonomousVault.WrongRemoteSender(expectedSender, h.sender);
    }

    function consumeInbound(
        mapping(uint32 => mapping(bytes32 => bool)) storage consumed, bytes calldata message
    ) external {
        _consumeInbound(consumed, message);
    }

    function _consumeInbound(
        mapping(uint32 => mapping(bytes32 => bool)) storage consumed, bytes calldata message
    ) private {
        CctpMessageDecoder.Header memory h = CctpMessageDecoder.decodeHeader(message);
        if (consumed[h.sourceDomain][h.nonce]) revert AutonomousVault.InboundAlreadyConsumed();
        consumed[h.sourceDomain][h.nonce] = true;
    }

    function receiveSettlement(
        Config memory c,
        mapping(uint32 => bytes32) storage remoteMessenger,
        mapping(uint32 => mapping(bytes32 => bool)) storage consumed,
        uint64 positionId, bytes calldata message, bytes calldata attestation
    ) external returns (uint256 received) {
        _validateHeader(c, remoteMessenger, message);
        (uint256 msgAmount, bytes32 mintRecipient, uint256 feeExecuted) = CctpMessageDecoder.decodeBody(message);
        if (mintRecipient != bytes32(uint256(uint160(address(this))))) {
            revert AutonomousVault.WrongMintRecipient(mintRecipient);
        }
        _consumeInbound(consumed, message);
        uint256 expectedNet = feeExecuted <= msgAmount ? msgAmount - feeExecuted : 0;
        received = _receive(c, message, attestation, expectedNet);
        if (feeExecuted > 0) emit AutonomousVault.CrossChainFeeDeducted(positionId, feeExecuted);
    }

    function _receive(Config memory c, bytes calldata message, bytes calldata attestation, uint256 expectedNet)
        private returns (uint256 received)
    {
        uint256 balBefore = IERC20(c.asset).balanceOf(address(this));
        if (!IMessageTransmitterV2(c.transmitter).receiveMessage(message, attestation)) {
            revert AutonomousVault.MessageReceiveFailed();
        }
        uint256 balAfter = IERC20(c.asset).balanceOf(address(this));
        received = balAfter > balBefore ? balAfter - balBefore : 0;
        if (expectedNet != received) revert AutonomousVault.MessageAmountMismatch(expectedNet, received);
    }
}

contracts/CharityModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @dev Minimal interface to query board membership from ShariahAdapterRegistry (I4).
interface IShariahRegistry {
    function isBoard(address account) external view returns (bool);
}

/**
 * @title  CharityModule
 * @notice Routes a configurable percentage of Shariah vault profit to a board-approved
 *         charity wallet (sadaqah) before the Musharakah profit split.
 *
 * @dev    Replaces the fixed-rate ZakatModule (now @deprecated) with:
 *           - A board-settable `charityBps` (default 250 = 2.5%, hard cap 500 = 5%)
 *           - 30-day timelock on both the charity wallet and the rate
 *           - Separate `totalCharityDistributed` counter (does NOT add to ZakatModule's counter)
 *
 *         Terminology: "Zakat" is a specific religious obligation with precise
 *         nisab and haul rules. This module distributes voluntary sadaqah.
 *         The word "Zakat" MUST NOT appear in any user-facing string without a
 *         board pronouncement per AGENTS.md rule on terminology.
 *
 *         Board rulings required before live use: SR-002 (rate), SR-003 (wallet).
 */
contract CharityModule is Ownable2Step {
    using SafeERC20 for IERC20;

    // ── Errors ──────────────────────────────────────────────────────────────

    error NotVault();
    error ZeroAmount();
    error ZeroWallet();
    error EscrowAlreadySet();
    error NoPendingChange();
    error TimelockNotElapsed(uint256 remaining);
    /// @dev Thrown when a proposed charityBps exceeds MAX_CHARITY_BPS.
    error CharityRateAboveCap(uint256 proposed, uint256 cap);
    /// @dev Thrown when caller is neither owner nor a board member per the registry (I4).
    error NotBoardOrOwner(address caller);
    /// @dev Thrown when deployed without a registry (J3).
    error RegistryRequired();

    // ── Events ──────────────────────────────────────────────────────────────

    event CharityDistributed(
        uint256 amount,
        address indexed charityWallet,
        uint256 charityBps,
        uint256 timestamp
    );
    event CharityWalletChangeProposed(address indexed proposed, uint256 executeAfter);
    event CharityWalletConfirmed(address indexed previous, address indexed confirmed);
    event CharityWalletChangeCancelled(address indexed cancelled);
    event CharityRateChangeProposed(uint256 proposed, uint256 executeAfter);
    event CharityRateConfirmed(uint256 previous, uint256 confirmed);
    event CharityRateChangeCancelled(uint256 cancelled);
    event EscrowSet(address indexed escrow);

    // ── Constants ────────────────────────────────────────────────────────────

    uint256 public constant TIMELOCK_PERIOD   = 30 days;
    /// @notice Hard cap on the charity rate — cannot exceed 5% of gross profit.
    ///         Requires a contract upgrade to raise. Protects depositor principal.
    uint256 public constant MAX_CHARITY_BPS   = 500;
    /// @notice Default charity rate: 2.5% of gross Musharakah profit.
    ///         Must be confirmed by the board (SR-002) before live use.
    uint256 public constant DEFAULT_CHARITY_BPS = 250;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Active charity wallet. Must be a board-approved address (SR-003).
    address public charityWallet;
    /// @notice Pending wallet change (awaiting 30-day timelock).
    address public pendingCharityWallet;
    uint256 public walletChangeRequestTime;

    /// @notice Current charity rate in basis points (default 250 = 2.5%).
    uint256 public charityBps;
    /// @notice Pending rate change (awaiting 30-day timelock).
    uint256 public pendingCharityBps;
    uint256 public rateChangeRequestTime;
    bool    public hasPendingRateChange;

    /// @notice Lifetime USDC distributed to the charity wallet.
    uint256 public totalCharityDistributed;

    address public immutable asset;
    address public immutable vault;
    /// @notice PurificationEscrow address.  Set after escrow deploy via setEscrow().
    ///         distributeCharity() accepts calls from either vault or escrow so that
    ///         the waterfall path (vault → escrow → charityModule) works correctly.
    address public escrow;
    /// @notice Optional Shariah registry for single-source board membership (I4).
    ///         When set, board-gated functions check registry.isBoard(msg.sender).
    ///         When address(0), only the owner can call those functions.
    address public immutable boardRegistry;

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(
        address charityWallet_,
        address asset_,
        address vault_,
        address initialOwner,
        address boardRegistry_ // J3: must be non-zero for Shariah deploys
    ) Ownable(initialOwner) {
        if (charityWallet_ == address(0)) revert ZeroWallet();
        if (boardRegistry_ == address(0)) revert RegistryRequired();
        charityWallet  = charityWallet_;
        asset          = asset_;
        vault          = vault_;
        boardRegistry  = boardRegistry_;
        charityBps     = DEFAULT_CHARITY_BPS;
    }

    // ── Board modifier (I4 / K2) ──────────────────────────────────────────────

    /// @dev Allows only board members per the registry (boardRegistry is always set — J3).
    ///      The owner alone CANNOT call these functions unless they are also on the board.
    ///      An owner who is also the initialBoardMember of the registry may call.
    ///      Renamed from onlyBoardOrOwner to onlyBoard (K2) since boardRegistry is mandatory
    ///      and an owner who is not on the board is blocked regardless.
    modifier onlyBoard() {
        if (!IShariahRegistry(boardRegistry).isBoard(msg.sender)) revert NotBoardOrOwner(msg.sender);
        _;
    }

    // ── Distribution ─────────────────────────────────────────────────────────

    /**
     * @notice Deduct `charityBps` from `grossProfit` and transfer it to the charity wallet.
     * @dev    Called by the ShariahVault (via PurificationEscrow waterfall) BEFORE the
     *         Musharakah split. Caller must have approved this contract for `grossProfit`.
     * @param  grossProfit  Total USDC profit before any split. Must be > 0.
     * @return charityAmount  USDC sent to the charity wallet.
     * @return remaining      grossProfit minus charityAmount; passed on to Musharakah split.
     */
    /// @notice Wire the PurificationEscrow after it is deployed.
    ///         Must be called once by the owner before any profit claim.
    ///         The escrow calls distributeCharity() as part of executeWaterfall().
    function setEscrow(address escrow_) external onlyOwner {
        if (escrow != address(0)) revert EscrowAlreadySet();
        if (escrow_ == address(0)) revert ZeroWallet();
        escrow = escrow_;
        emit EscrowSet(escrow_);
    }

    function distributeCharity(uint256 grossProfit)
        external
        returns (uint256 charityAmount, uint256 remaining)
    {
        // Accept calls from the vault (direct) or from the escrow (waterfall path).
        if (msg.sender != vault && msg.sender != escrow) revert NotVault();
        if (grossProfit == 0) revert ZeroAmount();

        charityAmount = (grossProfit * charityBps) / 10_000;
        remaining     = grossProfit - charityAmount;

        if (charityAmount > 0) {
            // Pull from msg.sender (the escrow holds the profit and has already
            // called forceApprove(charityModule, grossProfit) before this call).
            IERC20(asset).safeTransferFrom(msg.sender, charityWallet, charityAmount);
        }

        totalCharityDistributed += charityAmount;
        emit CharityDistributed(charityAmount, charityWallet, charityBps, block.timestamp);
    }

    // ── Charity wallet timelock ──────────────────────────────────────────────

    function proposeCharityWalletChange(address newWallet) external onlyBoard {
        if (newWallet == address(0)) revert ZeroWallet();
        pendingCharityWallet   = newWallet;
        walletChangeRequestTime = block.timestamp;
        emit CharityWalletChangeProposed(newWallet, block.timestamp + TIMELOCK_PERIOD);
    }

    function confirmCharityWalletChange() external onlyBoard {
        address proposed = pendingCharityWallet;
        if (proposed == address(0)) revert NoPendingChange();
        uint256 executeAfter = walletChangeRequestTime + TIMELOCK_PERIOD;
        if (block.timestamp < executeAfter) revert TimelockNotElapsed(executeAfter - block.timestamp);

        address previous = charityWallet;
        charityWallet         = proposed;
        pendingCharityWallet   = address(0);
        walletChangeRequestTime = 0;

        emit CharityWalletConfirmed(previous, charityWallet);
    }

    function cancelCharityWalletChange() external onlyBoard {
        address proposed = pendingCharityWallet;
        if (proposed == address(0)) revert NoPendingChange();
        emit CharityWalletChangeCancelled(proposed);
        pendingCharityWallet   = address(0);
        walletChangeRequestTime = 0;
    }

    // ── Charity rate timelock ────────────────────────────────────────────────

    function proposeCharityRateChange(uint256 newBps) external onlyBoard {
        if (newBps > MAX_CHARITY_BPS) revert CharityRateAboveCap(newBps, MAX_CHARITY_BPS);
        pendingCharityBps    = newBps;
        rateChangeRequestTime = block.timestamp;
        hasPendingRateChange  = true;
        emit CharityRateChangeProposed(newBps, block.timestamp + TIMELOCK_PERIOD);
    }

    function confirmCharityRateChange() external onlyBoard {
        if (!hasPendingRateChange) revert NoPendingChange();
        uint256 executeAfter = rateChangeRequestTime + TIMELOCK_PERIOD;
        if (block.timestamp < executeAfter) revert TimelockNotElapsed(executeAfter - block.timestamp);

        uint256 previous = charityBps;
        charityBps           = pendingCharityBps;
        pendingCharityBps    = 0;
        rateChangeRequestTime = 0;
        hasPendingRateChange  = false;

        emit CharityRateConfirmed(previous, charityBps);
    }

    function cancelCharityRateChange() external onlyBoard {
        if (!hasPendingRateChange) revert NoPendingChange();
        emit CharityRateChangeCancelled(pendingCharityBps);
        pendingCharityBps    = 0;
        rateChangeRequestTime = 0;
        hasPendingRateChange  = false;
    }
}

contracts/ConventionalVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AutonomousVault} from "./AutonomousVault.sol";
import {TreasuryModule} from "./TreasuryModule.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract ConventionalVault is AutonomousVault {
    using SafeERC20 for IERC20;

    error InsufficientFeeBalance(uint256 available, uint256 required);

    event AdminFeeAccrued(uint256 amount);

    TreasuryModule public immutable conventionalTreasury;
    uint256 public lastFeeAccrualTime;

    constructor(IERC20 asset_, address initialOwner, uint32 sourceDomain_, address conventionalTreasury_)
        AutonomousVault(asset_, initialOwner, sourceDomain_)
    {
        conventionalTreasury = TreasuryModule(conventionalTreasury_);
        lastFeeAccrualTime = block.timestamp;
    }

    function name() public pure override(ERC20, IERC20Metadata) returns (string memory) {
        return "Conventional Vault Share";
    }

    function symbol() public pure override(ERC20, IERC20Metadata) returns (string memory) {
        return "cvUSDC";
    }

    /// @dev Accrued fees are held here but are not depositor assets.
    function totalAssets() public view override returns (uint256) {
        uint256 assets = super.totalAssets();
        uint256 fees = conventionalTreasury.pendingFees();
        return assets > fees ? assets - fees : 0;
    }

    /// @dev Preserve the former inherited entry point without changing conventional profit locking.
    function lockProfit(uint256 amount) public virtual onlyManagerOrOwner {
        _lockProfitInternal(amount);
    }

    function accrueAdminFee() public {
        _accrueAdminFeeInternal();
    }

    /// @notice Conventional deployment path with post-deploy admin fee accrual.
    /// @dev AutonomousVault.deployCapital is non-virtual, so this function is provided instead.
    function deployCapitalWithFeeAccrual(address strategy, uint256 amount, bytes calldata data)
        external
        onlyManagerOrOwner
    {
        if (paused) revert Paused();
        data;

        uint256 currentAssets = totalAssets();
        uint256 maxDeployable = (currentAssets * maxAllocationBps) / 10_000;
        if (totalDeployed + amount > maxDeployable) revert AllocationExceedsLimit();

        IERC20(asset()).safeTransfer(strategy, amount);
        totalDeployed += amount;

        emit CapitalDeployed(strategy, amount);

        _accrueAdminFeeInternal();
    }

    /// @notice Sweep accrued fees to a receiver. Amount is capped to `pendingFees` to
    ///         prevent owner from sweeping depositor principal under the guise of fee claims.
    function sweepFeesToTreasury(address receiver, uint256 amount) external onlyOwner {
        uint256 pending = conventionalTreasury.pendingFees();
        if (amount > pending) revert AllocationExceedsLimit();
        uint256 available = IERC20(asset()).balanceOf(address(this));
        if (available < amount) revert InsufficientFeeBalance(available, amount);
        IERC20(asset()).safeTransfer(receiver, amount);
        conventionalTreasury.claimFees(receiver, amount);
    }

    function _accrueAdminFeeInternal() internal {
        uint256 elapsed = block.timestamp - lastFeeAccrualTime;
        uint256 aum = totalAssets();
        uint256 fee = (aum * conventionalTreasury.adminFeeBps() * elapsed) / (10_000 * 365 days);

        if (fee > 0) {
            conventionalTreasury.accrue(fee);
        }

        lastFeeAccrualTime = block.timestamp;
        emit AdminFeeAccrued(fee);
    }
}

contracts/IStrategyAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title IStrategyAdapter
 * @notice Standard interface every protocol adapter must implement.
 *         The vault calls deploy() to send USDC in, recall() to pull it back.
 *         currentValue() returns mark-to-market NAV of the position.
 */
interface IStrategyAdapter {
    /// @notice Deploy `amount` of vault's USDC into the underlying protocol.
    ///         Caller must have already transferred `amount` to this adapter.
    ///         Returns the actual amount deployed (may differ due to fees).
    function deploy(uint256 amount) external returns (uint256 deployed);

    /// @notice Recall up to `amount` of USDC from the protocol back to `vault`.
    ///         Returns the actual amount returned (may differ due to slippage/fees).
    function recall(uint256 amount) external returns (uint256 returned);

    /// @notice Current total value (in USDC) of all assets held in the protocol.
    function currentValue() external view returns (uint256);

    /// @notice Human-readable protocol identifier, e.g. "Compound V3" or "Curve 3pool".
    function protocolName() external view returns (string memory);

    /// @notice Address of the vault that owns this adapter (receives recalled funds).
    function vault() external view returns (address);
}

contracts/PositionTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

import {ScoreAggregator} from "./ScoreAggregator.sol";

contract PositionTracker is Ownable2Step {
    enum PositionStatus {
        OPEN,
        CLOSING,
        CLOSED
    }

    struct Position {
        uint256 id;
        ScoreAggregator.Strategy strategy;
        address target;
        uint256 amountDeployed;
        uint256 entryTimestamp;
        uint256 exitTimestamp;
        uint256 pnl;
        int256 pnlNet;
        PositionStatus status;
        bytes32 txHash;
        uint32 destinationDomain;
    }

    error NotReporter();
    error PositionNotFound();
    error PositionAlreadyClosed();

    event ReporterUpdated(address indexed previousReporter, address indexed newReporter);
    event PositionOpened(
        uint256 indexed id,
        ScoreAggregator.Strategy indexed strategy,
        address indexed target,
        uint256 amount,
        uint32 destinationDomain
    );
    event PositionClosed(uint256 indexed id, uint256 returnAmount, int256 pnlNet);
    event PositionStatusUpdated(uint256 indexed id, PositionStatus status);

    address public reporter;
    uint256 public positionCount;

    mapping(uint256 => Position) public positions;
    uint256[] public activePositionIds;

    constructor(address initialOwner) Ownable(initialOwner) {}

    modifier onlyReporterOrOwner() {
        if (msg.sender != owner() && msg.sender != reporter) revert NotReporter();
        _;
    }

    function openPosition(
        ScoreAggregator.Strategy strategy,
        address target,
        uint256 amount,
        bytes32 txHash,
        uint32 destinationDomain
    ) external onlyReporterOrOwner returns (uint256 id) {
        id = ++positionCount;

        positions[id] = Position({
            id: id,
            strategy: strategy,
            target: target,
            amountDeployed: amount,
            entryTimestamp: block.timestamp,
            exitTimestamp: 0,
            pnl: 0,
            pnlNet: 0,
            status: PositionStatus.OPEN,
            txHash: txHash,
            destinationDomain: destinationDomain
        });

        activePositionIds.push(id);

        emit PositionOpened(id, strategy, target, amount, destinationDomain);
    }

    function closePosition(uint256 id, uint256 returnAmount, bytes32 closeTxHash) external onlyReporterOrOwner {
        if (id == 0 || id > positionCount) revert PositionNotFound();

        Position storage position = positions[id];
        if (position.status == PositionStatus.CLOSED) revert PositionAlreadyClosed();

        position.status = PositionStatus.CLOSED;
        position.exitTimestamp = block.timestamp;
        position.txHash = closeTxHash;

        if (returnAmount >= position.amountDeployed) {
            position.pnl = returnAmount - position.amountDeployed;
            position.pnlNet = int256(returnAmount - position.amountDeployed);
        } else {
            position.pnl = position.amountDeployed - returnAmount;
            position.pnlNet = -int256(position.amountDeployed - returnAmount);
        }

        _removeActivePosition(id);

        emit PositionClosed(id, returnAmount, position.pnlNet);
    }

    function updateStatus(uint256 id, PositionStatus status) external onlyReporterOrOwner {
        if (id == 0 || id > positionCount) revert PositionNotFound();

        Position storage position = positions[id];
        if (position.status == PositionStatus.CLOSED) revert PositionAlreadyClosed();

        position.status = status;
        emit PositionStatusUpdated(id, status);
    }

    function getActivePositions() external view returns (Position[] memory activePositions) {
        uint256 length = activePositionIds.length;
        activePositions = new Position[](length);

        for (uint256 i = 0; i < length; i++) {
            activePositions[i] = positions[activePositionIds[i]];
        }
    }

    function getTotalPnl() external view returns (int256 totalPnl) {
        for (uint256 id = 1; id <= positionCount; id++) {
            Position storage position = positions[id];
            if (position.status == PositionStatus.CLOSED) {
                totalPnl += position.pnlNet;
            }
        }
    }

    function setReporter(address newReporter) external onlyOwner {
        address previousReporter = reporter;
        reporter = newReporter;
        emit ReporterUpdated(previousReporter, newReporter);
    }

    function _removeActivePosition(uint256 id) internal {
        uint256 length = activePositionIds.length;
        for (uint256 i = 0; i < length; i++) {
            if (activePositionIds[i] == id) {
                if (i != length - 1) {
                    activePositionIds[i] = activePositionIds[length - 1];
                }
                activePositionIds.pop();
                return;
            }
        }
    }
}

contracts/PurificationEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {CharityModule} from "./CharityModule.sol";
import {TreasuryModule} from "./TreasuryModule.sol";

/// @dev Minimal interface to query board membership from ShariahAdapterRegistry (I4).
interface IShariahRegistry {
    function isBoard(address account) external view returns (bool);
}

/**
 * @title  PurificationEscrow
 * @notice Implements the Shariah profit-distribution waterfall:
 *
 *           1. Purification (optional, rate = purificationBps)
 *              Deducted FIRST — routes impure income to charity before any split.
 *              Rate is set to 0 until the board identifies non-compliant income.
 *
 *           2. Charitable contribution (sadaqah via CharityModule)
 *              Applied to (grossProfit - purified). Default 2.5% (SR-002 pending).
 *
 *           3. Musharakah split (TreasuryModule.calculateMusharakahSplit)
 *              Applied to remainder: 10% vault share above 4% hurdle.
 *
 *         Invariant: purified + charity + vaultShare + depositorShare == grossProfit
 *         (proven by FuzzPurificationEscrow — see contracts/test/)
 *
 * @dev    Replaces the direct call sequence in ShariahVault.claimMusharakahProfit.
 *         The vault approves this contract for `grossProfit` then calls
 *         `executeWaterfall(grossProfit, elapsed, principal)`.
 *
 *         `purificationBps` is intentionally set to 0 by default. It is ONLY
 *         raised when the board identifies a specific impure-income event
 *         (e.g. a protocol rebate that fails the income screening). Setting a
 *         non-zero rate without a board ruling violates the depositor's trust.
 *
 *         Board rulings required: SR-002, SR-003, SR-004.
 */
contract PurificationEscrow is Ownable2Step {
    using SafeERC20 for IERC20;

    // ── Errors ──────────────────────────────────────────────────────────────

    error NotVault();
    error ZeroAmount();
    /// @dev Thrown when purificationBps + charityModule.charityBps would exceed 5000 (50%).
    ///      Safeguard against misconfiguration that would drain depositor principal.
    error CombinedDeductionAboveCap(uint256 combined, uint256 cap);
    /// @dev Thrown when purificationBps is set above the hard cap (1000 = 10%).
    error PurificationAboveCap(uint256 proposed, uint256 cap);
    /// @dev PR2: board role required to propose rate change.
    error NotBoardRole(address caller);
    /// @dev Proposal executed before timelock elapsed.
    error TimelockNotElapsed(uint256 earliest, uint256 current);
    /// @dev No pending proposal to execute or cancel.
    error NoPendingProposal();
    /// @dev A proposal already exists; cancel it first.
    error ProposalAlreadyExists();
    /// @dev Thrown when deployed without a registry (J3).
    error RegistryRequired();

    // ── Events ──────────────────────────────────────────────────────────────

    event WaterfallExecuted(
        uint256 grossProfit,
        uint256 purified,
        uint256 charity,
        uint256 vaultShare,
        uint256 depositorShare
    );
    event PurificationBpsUpdated(uint256 previous, uint256 updated);
    event PurificationRateProposed(uint256 newBps, uint256 executeAfter);
    event PurificationRateProposalCancelled();

    // ── Constants ────────────────────────────────────────────────────────────

    /// @notice Hard cap: purificationBps cannot exceed 10% of gross profit.
    uint256 public constant MAX_PURIFICATION_BPS = 1000;
    /// @notice Hard cap: purification + charity combined cannot exceed 50%.
    uint256 public constant MAX_COMBINED_DEDUCTION_BPS = 5000;
    /// @notice Board role must propose; 30-day timelock before execution (PR2, SR-G6 → SR-012).
    uint256 public constant PURIFICATION_TIMELOCK = 30 days;

    // ── State ────────────────────────────────────────────────────────────────

    /// @notice Fraction of grossProfit to set aside as purification (default 0).
    ///         Raised only when the board identifies a specific impure-income event.
    uint256 public purificationBps;

    /// @notice Optional Shariah registry for single-source board membership (I4).
    ///         When set, board-gated functions delegate to registry.isBoard(msg.sender).
    ///         When address(0), falls back to the local boardRole mapping (backward compat).
    address public immutable boardRegistry;

    /// @notice Local board role mapping — used only when boardRegistry == address(0) (I4).
    mapping(address => bool) public boardRole;

    struct PendingRateChange {
        uint256 newBps;
        uint256 executeAfter;
        bool exists;
    }
    /// @notice Pending purification rate proposal.
    PendingRateChange public pendingRateChange;

    address public immutable vault;
    address public immutable asset;
    CharityModule  public immutable charityModule;
    TreasuryModule public immutable shariahTreasury;

    // ── Constructor ──────────────────────────────────────────────────────────

    constructor(
        address vault_,
        address asset_,
        address charityModule_,
        address shariahTreasury_,
        address initialOwner,
        address boardRegistry_ // J3: must be non-zero for Shariah deploys
    ) Ownable(initialOwner) {
        if (boardRegistry_ == address(0)) revert RegistryRequired();
        vault           = vault_;
        asset           = asset_;
        charityModule   = CharityModule(charityModule_);
        shariahTreasury = TreasuryModule(shariahTreasury_);
        boardRegistry   = boardRegistry_;
        purificationBps = 0; // no impure income identified at deploy
        // Board membership is managed entirely by the registry (boardRegistry always set).
    }

    // ── Waterfall ────────────────────────────────────────────────────────────

    /**
     * @notice Execute the full Shariah profit waterfall.
     * @dev    The vault MUST have approved this contract for `grossProfit` before calling.
     *         Approval is typically done with `forceApprove` directly before this call.
     *
     *         Steps:
     *           1. Pull grossProfit from vault into escrow
     *           2. Deduct purification (purificationBps) — send to charityWallet directly
     *           3. Approve CharityModule for remaining; call distributeCharity()
     *           4. Call shariahTreasury.calculateMusharakahSplit() on remainder after charity
     *           5. Push vaultShare to shariahTreasury via recordMusharakahProfit
     *           6. Push depositorShare back to vault
     *           7. Emit WaterfallExecuted
     *
     * @param  grossProfit  Total USDC profit. Must be > 0.
     * @param  elapsed      Seconds since hurdleStartTime (passed from vault).
     * @param  principal    Hurdle principal (passed from vault).
     * @return purified       Amount sent as purification.
     * @return charity        Amount sent as charitable contribution.
     * @return vaultShare     Manager's Musharakah share (accrued in treasury).
     * @return depositorShare  Depositor's share (returned to vault).
     */
    function executeWaterfall(
        uint256 grossProfit,
        uint256 elapsed,
        uint256 principal
    )
        external
        returns (
            uint256 purified,
            uint256 charity,
            uint256 vaultShare,
            uint256 depositorShare
        )
    {
        return _executeWaterfall(grossProfit, elapsed, principal, 0);
    }

    /// @notice Execute the waterfall after reserving recovery of the realized NAV deficit.
    /// @param hwmDeficit Unrecovered loss in asset units, on the same basis as grossProfit.
    function executeWaterfallHWM(
        uint256 grossProfit,
        uint256 elapsed,
        uint256 principal,
        uint256 hwmDeficit
    ) external returns (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) {
        return _executeWaterfall(grossProfit, elapsed, principal, hwmDeficit);
    }

    function _executeWaterfall(
        uint256 grossProfit,
        uint256 elapsed,
        uint256 principal,
        uint256 hwmDeficit
    ) internal returns (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) {
        if (msg.sender != vault) revert NotVault();
        if (grossProfit == 0) revert ZeroAmount();

        // Validate combined deduction will not exceed cap before pulling funds.
        uint256 combinedBps = purificationBps + charityModule.charityBps();
        if (combinedBps > MAX_COMBINED_DEDUCTION_BPS) {
            revert CombinedDeductionAboveCap(combinedBps, MAX_COMBINED_DEDUCTION_BPS);
        }

        // 1. Pull grossProfit from vault into escrow.
        IERC20(asset).safeTransferFrom(vault, address(this), grossProfit);

        // 2. Purification: send directly to charity wallet, no CharityModule counter.
        if (purificationBps > 0) {
            purified = (grossProfit * purificationBps) / 10_000;
            IERC20(asset).safeTransfer(charityModule.charityWallet(), purified);
        }

        uint256 afterPurification = grossProfit - purified;

        // 3. Charitable contribution via CharityModule.
        //    Approve charityModule to pull from escrow, then call distributeCharity.
        IERC20(asset).forceApprove(address(charityModule), afterPurification);
        (, uint256 afterCharity) = charityModule.distributeCharity(afterPurification);
        charity = afterPurification - afterCharity;
        IERC20(asset).forceApprove(address(charityModule), 0);

        // 4. Musharakah split on the remainder.
        (, uint256 vaultShareCalc, uint256 depositorShareCalc) =
            shariahTreasury.calculateMusharakahSplitHWM(afterCharity, elapsed, principal, hwmDeficit);
        vaultShare     = vaultShareCalc;
        depositorShare = depositorShareCalc;

        // 5. Record the fee liability and return its token backing to the vault.
        shariahTreasury.recordMusharakahProfit(vaultShare);
        if (vaultShare > 0) {
            IERC20(asset).safeTransfer(vault, vaultShare);
        }

        // 6. Return depositor share to vault.
        if (depositorShare > 0) {
            IERC20(asset).safeTransfer(vault, depositorShare);
        }

        // Forward residual tokens without changing the gross-profit split.
        uint256 dust = IERC20(asset).balanceOf(address(this));
        if (dust > 0) IERC20(asset).safeTransfer(vault, dust);
        emit WaterfallExecuted(grossProfit, purified, charity, vaultShare, depositorShare);
    }

    // ── Owner controls ───────────────────────────────────────────────────────

    // ── Board role management ────────────────────────────────────────────────

    modifier onlyBoard() {
        bool ok = boardRegistry != address(0)
            ? IShariahRegistry(boardRegistry).isBoard(msg.sender)
            : boardRole[msg.sender];
        if (!ok) revert NotBoardRole(msg.sender);
        _;
    }

    /// @notice Owner grants board membership (no timelock — owner is trusted for membership).
    function grantBoardRole(address account) external onlyOwner { boardRole[account] = true; }

    /// @notice Owner revokes board membership.
    function revokeBoardRole(address account) external onlyOwner { boardRole[account] = false; }

    // ── Purification rate — timelocked (PR2 / SR-012) ───────────────────────

    /**
     * @notice Board proposes a new purification rate (30-day timelock).
     * @dev    ONLY raise this when the board has identified a specific impure-income event.
     */
    function proposePurificationRate(uint256 newBps) external onlyBoard {
        if (newBps > MAX_PURIFICATION_BPS) revert PurificationAboveCap(newBps, MAX_PURIFICATION_BPS);
        uint256 combined = newBps + charityModule.charityBps();
        if (combined > MAX_COMBINED_DEDUCTION_BPS) revert CombinedDeductionAboveCap(combined, MAX_COMBINED_DEDUCTION_BPS);
        if (pendingRateChange.exists) revert ProposalAlreadyExists();
        uint256 executeAfter = block.timestamp + PURIFICATION_TIMELOCK;
        pendingRateChange = PendingRateChange({newBps: newBps, executeAfter: executeAfter, exists: true});
        emit PurificationRateProposed(newBps, executeAfter);
    }

    /// @notice Board confirms the pending rate change after the 30-day timelock.
    function confirmPurificationRate() external onlyBoard {
        PendingRateChange memory p = pendingRateChange;
        if (!p.exists) revert NoPendingProposal();
        if (block.timestamp < p.executeAfter) revert TimelockNotElapsed(p.executeAfter, block.timestamp);
        delete pendingRateChange;
        uint256 previous = purificationBps;
        purificationBps  = p.newBps;
        emit PurificationBpsUpdated(previous, p.newBps);
    }

    /// @notice Board cancels the pending rate proposal.
    function cancelPurificationRate() external onlyBoard {
        if (!pendingRateChange.exists) revert NoPendingProposal();
        delete pendingRateChange;
        emit PurificationRateProposalCancelled();
    }
}

contracts/RiskTieredExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {AutonomousVault} from "./AutonomousVault.sol";
import {ShariahVault} from "./ShariahVault.sol";
import {ScoreAggregator} from "./ScoreAggregator.sol";
import {ShariahScoreAggregator} from "./ShariahScoreAggregator.sol";
import {IStrategyAdapter} from "./IStrategyAdapter.sol";

contract RiskTieredExecutor is Ownable2Step {
    enum RiskTier {
        PASSIVE,
        AGGRESSIVE,
        SHARIAH_CONSERVATIVE, // Gold Spread (bit1) + Halal LP (bit2) — low-vol only; RWA_SUKUK removed per SR-001
        SHARIAH_DYNAMIC       // All active halal strategies (5, bits 0-3+5) — full Shariah universe
    }

    struct StrategyConfig {
        address adapter;
        bytes32 recipient;
        bool enabled;
        uint256 minAmount;
        uint256 maxAmount;
    }

    error ScoreTooLow(uint8 score, uint8 min);
    error CooldownNotElapsed(uint256 remaining);
    error StrategyDisabled();
    error StrategyNotAllowedForTier(uint8 strategyIdx, uint8 mask);
    error GasPriceTooHigh();
    error NothingToExecute();
    error AdapterNotSet();
    error NonAtomicGoldExchange();

    event ExecutionTriggered(
        ScoreAggregator.Strategy indexed strategy,
        uint8 score,
        uint256 amount,
        address indexed adapter,
        RiskTier tier
    );
    event ShariahExecutionTriggered(
        ShariahScoreAggregator.ShariahStrategy indexed strategy,
        uint8 score,
        uint256 amount,
        address indexed adapter,
        RiskTier tier
    );
    event CrossChainExecutionTriggered(
        ScoreAggregator.Strategy indexed strategy,
        uint8 score,
        uint256 amount,
        uint32 indexed destinationDomain,
        bytes32 recipient,
        RiskTier tier
    );
    event StrategyConfigUpdated(
        ScoreAggregator.Strategy indexed strategy,
        address adapter,
        bool enabled,
        RiskTier tier
    );
    event ShariahStrategyConfigUpdated(uint8 indexed strategyIdx, address adapter, bool enabled, RiskTier tier);
    event MinScoreUpdated(uint8 prev, uint8 next);
    event CooldownUpdated(uint256 prev, uint256 next);
    event MaxGasPriceUpdated(uint256 prev, uint256 next);
    event StrategyMaskUpdated(uint8 prev, uint8 next);
    event ShariahAggregatorUpdated(address prev, address next);

    AutonomousVault public immutable vault;
    ScoreAggregator public immutable aggregator;
    RiskTier public immutable riskTier;
    string public tierName;

    ShariahScoreAggregator public shariahAggregator;

    uint8 public minScoreToExecute;
    uint256 public executionCooldown;
    uint256 public maxGasPrice;
    uint256 public lastExecutionTime;
    bool private _executionLocked;

    uint8 public strategyMask;

    mapping(ScoreAggregator.Strategy => StrategyConfig) public strategyConfigs;
    mapping(uint8 => StrategyConfig) public shariahStrategyConfigs;

    constructor(address vault_, address aggregator_, RiskTier tier_, address initialOwner) Ownable(initialOwner) {
        vault = AutonomousVault(vault_);
        aggregator = ScoreAggregator(aggregator_);
        riskTier = tier_;

        if (tier_ == RiskTier.PASSIVE) {
            minScoreToExecute = 80;
            executionCooldown = 2 hours;
            maxGasPrice = 20 gwei;
            strategyMask = 9;   // 0b00001001 — S0 + S3
            tierName = "Passive";
        } else if (tier_ == RiskTier.SHARIAH_CONSERVATIVE) {
            // Gold Spread (bit1) + Halal LP (bit2) + Gold Allocation (bit5) = 0b100110 — SR-001 removed bit4
            minScoreToExecute = 80;
            executionCooldown = 2 hours;
            maxGasPrice = 20 gwei;
            strategyMask = 38;  // 0b100110 — bits 1,2,5 (Gold Spread + LP + Gold Allocation)
            tierName = "Shariah Conservative";
        } else if (tier_ == RiskTier.SHARIAH_DYNAMIC) {
            // All active halal strategies (5) = 0b101111 — bit4 (RESERVED_4) off, bit5 (GOLD_ALLOCATION) on
            minScoreToExecute = 70;
            executionCooldown = 1 hours;
            maxGasPrice = 30 gwei;
            strategyMask = 47;  // 0b101111 — bits 0,1,2,3,5
            tierName = "Shariah Dynamic";
        } else {
            // AGGRESSIVE
            minScoreToExecute = 60;
            executionCooldown = 30 minutes;
            maxGasPrice = 50 gwei;
            strategyMask = 15;  // 0b00001111 — all 4 conventional
            tierName = "Aggressive";
        }
    }

    /// @notice Execute the winning strategy for this tier.
    /// @dev Shariah tiers stay local-only: aggregator domain 0 is ambiguous with CCTP domain 0.
    ///      Gold winners with a nonzero reported destination remain forbidden.
    function executeWinner() external {
        if (tx.gasprice > maxGasPrice) revert GasPriceTooHigh();

        uint256 nextExecutionTime = lastExecutionTime + executionCooldown;
        if (block.timestamp < nextExecutionTime) {
            revert CooldownNotElapsed(nextExecutionTime - block.timestamp);
        }
        if (_executionLocked) revert("ReentrancyGuard: reentrant call");
        _executionLocked = true;

        uint8 score;
        uint8 idx;
        uint32 destinationDomain;
        StrategyConfig memory config;

        ScoreAggregator.Strategy strategy;
        ShariahScoreAggregator.ShariahStrategy shariahStrategy;

        if (riskTier == RiskTier.SHARIAH_CONSERVATIVE || riskTier == RiskTier.SHARIAH_DYNAMIC) {
            (shariahStrategy, score, destinationDomain) = shariahAggregator.getWinningShariahStrategy();
            if (score < minScoreToExecute) revert ScoreTooLow(score, minScoreToExecute);

            idx = uint8(shariahStrategy);
            if (((strategyMask >> idx) & 1) == 0) {
                revert StrategyNotAllowedForTier(idx, strategyMask);
            }

            uint32 reportedDomain = destinationDomain;
            if (reportedDomain != 0 && (
                idx == uint8(ShariahScoreAggregator.ShariahStrategy.GOLD_SPREAD)
                    || idx == uint8(ShariahScoreAggregator.ShariahStrategy.GOLD_ALLOCATION)
            )) revert NonAtomicGoldExchange();

            config = shariahStrategyConfigs[idx];
            destinationDomain = 0;
        } else {
            (strategy, score, destinationDomain) = aggregator.getWinningStrategy();
            if (score < minScoreToExecute) revert ScoreTooLow(score, minScoreToExecute);

            idx = uint8(strategy);
            if (((strategyMask >> idx) & 1) == 0) {
                revert StrategyNotAllowedForTier(idx, strategyMask);
            }

            config = strategyConfigs[strategy];
        }

        if (!config.enabled) revert StrategyDisabled();
        if (config.adapter == address(0)) revert AdapterNotSet();

        uint256 totalAssets_ = vault.totalAssets();
        uint256 allocationCap = (totalAssets_ * vault.maxAllocationBps()) / 10_000;
        uint256 deployed = vault.totalDeployed();
        if (allocationCap <= deployed) revert NothingToExecute();

        uint256 remainingAllocation = allocationCap - deployed;
        uint256 idleAssets = IERC20(vault.asset()).balanceOf(address(vault));

        uint256 amount = remainingAllocation;
        if (amount > config.maxAmount) amount = config.maxAmount;
        if (amount > idleAssets) amount = idleAssets;

        if (amount < config.minAmount || amount == 0) revert NothingToExecute();

        bool isShariahTier = (riskTier == RiskTier.SHARIAH_CONSERVATIVE || riskTier == RiskTier.SHARIAH_DYNAMIC);
        lastExecutionTime = block.timestamp;
        if (isShariahTier || destinationDomain == 0) {
            if (isShariahTier) {
                ShariahVault(address(vault)).deployCapitalAndExecute(config.adapter, amount, "");
            } else {
                vault.deployCapital(config.adapter, amount, "");
                IStrategyAdapter(config.adapter).deploy(amount);
            }

            if (isShariahTier) {
                emit ShariahExecutionTriggered(shariahStrategy, score, amount, config.adapter, riskTier);
            } else {
                emit ExecutionTriggered(strategy, score, amount, config.adapter, riskTier);
            }
        } else {
            vault.deployCrossChain(destinationDomain, config.recipient, amount);

            emit CrossChainExecutionTriggered(strategy, score, amount, destinationDomain, config.recipient, riskTier);
        }

        _executionLocked = false;
    }

    function setStrategyConfig(
        ScoreAggregator.Strategy strategy,
        address adapter,
        bytes32 recipient,
        bool enabled,
        uint256 minAmount,
        uint256 maxAmount
    ) external onlyOwner {
        strategyConfigs[strategy] = StrategyConfig({
            adapter: adapter,
            recipient: recipient,
            enabled: enabled,
            minAmount: minAmount,
            maxAmount: maxAmount
        });

        emit StrategyConfigUpdated(strategy, adapter, enabled, riskTier);
    }

    function setShariahStrategyConfig(
        uint8 strategyIdx,
        address adapter,
        bytes32 recipient,
        bool enabled,
        uint256 minAmount,
        uint256 maxAmount
    ) external onlyOwner {
        shariahStrategyConfigs[strategyIdx] = StrategyConfig({
            adapter: adapter,
            recipient: recipient,
            enabled: enabled,
            minAmount: minAmount,
            maxAmount: maxAmount
        });

        emit ShariahStrategyConfigUpdated(strategyIdx, adapter, enabled, riskTier);
    }

    function setShariahAggregator(address aggregator_) external onlyOwner {
        address prev = address(shariahAggregator);
        shariahAggregator = ShariahScoreAggregator(aggregator_);
        emit ShariahAggregatorUpdated(prev, aggregator_);
    }

    function setMinScore(uint8 newMinScore) external onlyOwner {
        require(newMinScore <= 100, "Score too high");
        uint8 prev = minScoreToExecute;
        minScoreToExecute = newMinScore;
        emit MinScoreUpdated(prev, newMinScore);
    }

    function setCooldown(uint256 newCooldown) external onlyOwner {
        require(newCooldown <= 24 hours, "Cooldown too long");
        uint256 prev = executionCooldown;
        executionCooldown = newCooldown;
        emit CooldownUpdated(prev, newCooldown);
    }

    function setMaxGasPrice(uint256 newMaxGasPrice) external onlyOwner {
        uint256 prev = maxGasPrice;
        maxGasPrice = newMaxGasPrice;
        emit MaxGasPriceUpdated(prev, newMaxGasPrice);
    }

    function setStrategyMask(uint8 mask) external onlyOwner {
        uint8 prev = strategyMask;
        strategyMask = mask;
        emit StrategyMaskUpdated(prev, mask);
    }

    function isStrategyAllowed(ScoreAggregator.Strategy strategy) external view returns (bool) {
        uint8 idx = uint8(strategy);
        return ((strategyMask >> idx) & 1) == 1;
    }

    function getConfig(ScoreAggregator.Strategy strategy) external view returns (StrategyConfig memory) {
        return strategyConfigs[strategy];
    }
}

contracts/ScoreAggregator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

contract ScoreAggregator is Ownable2Step {
    enum Strategy {
        STABLECOIN_SPREAD,
        FUNDING_RATE_ARB,
        BRIDGE_FLOW,
        LIQUIDATION_RWA
    }

    struct Score {
        uint8 value;
        uint40 timestamp;
        bytes32 dataHash;
        uint32 destinationDomain;
    }

    error NotOracle();
    error InvalidScore();
    error NoValidScores();
    error StaleScore(Strategy strategy);

    event OracleUpdated(address indexed previousOracle, address indexed newOracle);
    event ScoreUpdated(Strategy indexed strategy, uint8 value, uint40 timestamp, bytes32 dataHash, uint32 destinationDomain);

    address public oracle;

    mapping(Strategy => Score) public scores;
    mapping(Strategy => Score[]) public scoreHistory;
    mapping(Strategy => uint8) public historyIndex;

    constructor(address initialOwner) Ownable(initialOwner) {}

    modifier onlyOracleOrOwner() {
        if (msg.sender != owner() && msg.sender != oracle) revert NotOracle();
        _;
    }

    function writeScore(
        Strategy strategy,
        uint8 value,
        bytes32 dataHash,
        uint32 destinationDomain
    ) external onlyOracleOrOwner {
        _writeScore(strategy, value, dataHash, destinationDomain);
    }

    function writeBatchScores(
        Strategy[] calldata strategies,
        uint8[] calldata values,
        bytes32[] calldata dataHashes,
        uint32[] calldata destinationDomains
    ) external onlyOracleOrOwner {
        uint256 length = strategies.length;
        if (length != values.length || length != dataHashes.length || length != destinationDomains.length) {
            revert InvalidScore();
        }

        for (uint256 i = 0; i < length; i++) {
            _writeScore(strategies[i], values[i], dataHashes[i], destinationDomains[i]);
        }
    }

    function getWinningStrategy() external view returns (Strategy strategy, uint8 score, uint32 destinationDomain) {
        Strategy bestStrategy;
        uint8 bestScore;
        uint32 bestDestinationDomain;
        bool foundValid;
        bool foundStale;
        Strategy firstStale;

        for (uint8 i = 0; i < 4; i++) {
            Strategy currentStrategy = Strategy(i);
            Score memory current = scores[currentStrategy];

            if (current.value == 0) {
                continue;
            }

            if (block.timestamp > uint256(current.timestamp) + 5 minutes) {
                if (!foundStale) {
                    foundStale = true;
                    firstStale = currentStrategy;
                }
                continue;
            }

            if (!foundValid || current.value > bestScore) {
                bestScore = current.value;
                bestStrategy = currentStrategy;
                bestDestinationDomain = current.destinationDomain;
                foundValid = true;
            }
        }

        if (!foundValid) {
            if (foundStale) revert StaleScore(firstStale);
            revert NoValidScores();
        }

        return (bestStrategy, bestScore, bestDestinationDomain);
    }

    function getAllScores()
        external
        view
        returns (uint8[4] memory values, uint40[4] memory timestamps, uint32[4] memory destinationDomains)
    {
        for (uint8 i = 0; i < 4; i++) {
            Score memory current = scores[Strategy(i)];
            values[i] = current.value;
            timestamps[i] = current.timestamp;
            destinationDomains[i] = current.destinationDomain;
        }
    }

    function getScoreHistory(Strategy strategy) external view returns (Score[10] memory history) {
        Score[] storage stored = scoreHistory[strategy];
        uint256 length = stored.length;

        if (length == 0) {
            return history;
        }

        if (length < 10) {
            for (uint256 i = 0; i < length; i++) {
                history[i] = stored[i];
            }
            return history;
        }

        uint256 start = historyIndex[strategy];
        for (uint256 i = 0; i < 10; i++) {
            history[i] = stored[(start + i) % 10];
        }
    }

    function setOracle(address newOracle) external onlyOwner {
        address previousOracle = oracle;
        oracle = newOracle;
        emit OracleUpdated(previousOracle, newOracle);
    }

    function _writeScore(Strategy strategy, uint8 value, bytes32 dataHash, uint32 destinationDomain) internal {
        if (value > 100) revert InvalidScore();

        Score memory nextScore = Score({
            value: value,
            timestamp: uint40(block.timestamp),
            dataHash: dataHash,
            destinationDomain: destinationDomain
        });
        scores[strategy] = nextScore;

        Score[] storage history = scoreHistory[strategy];
        uint8 index = historyIndex[strategy];

        if (history.length < 10) {
            history.push(nextScore);
            historyIndex[strategy] = uint8(history.length % 10);
        } else {
            history[index] = nextScore;
            historyIndex[strategy] = uint8((index + 1) % 10);
        }

        emit ScoreUpdated(strategy, value, nextScore.timestamp, dataHash, destinationDomain);
    }
}

contracts/ShariahAdapterRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  ShariahAdapterRegistry
 * @notice Governance-gated registry of Shariah-screened strategy adapters.
 *
 * ## Design
 * Every screening entry carries a `pronouncementHash` (keccak256 of the board
 * resolution document) and an `expiresAt` timestamp.  ShariahVaultV2 queries
 * this registry before any capital deployment.
 *
 * ## Timelock
 * All add/update/remove operations must be *proposed* first, then *executed*
 * after `TIMELOCK_PERIOD` has elapsed.  This prevents any single actor from
 * silently slip-streaming an unscreened adapter.
 *
 * ## Roles
 * - `BOARD_ROLE`   : can propose and execute screening changes
 * - `owner`        : can grant/revoke BOARD_ROLE (Ownable)
 *
 * @dev    SR-005 through SR-011 are cited per adapter — see docs/agents/SHARIAH_REVIEW.md.
 */
contract ShariahAdapterRegistry is Ownable {

    // ─────────────────────────────────────────────────────────────
    // Constants
    // ─────────────────────────────────────────────────────────────

    /// @notice Minimum time between a proposal and its execution.
    uint256 public constant TIMELOCK_PERIOD = 30 days;

    /// @notice Maximum screening validity period (prevents stale entries).
    uint256 public constant MAX_EXPIRY_PERIOD = 730 days; // 2 years

    // ─────────────────────────────────────────────────────────────
    // Errors
    // ─────────────────────────────────────────────────────────────

    error NotBoardRole(address caller);
    error TimelockNotElapsed(uint256 earliest, uint256 current);
    error NoPendingProposal(address adapter);
    error AlreadyProposed(address adapter);
    error ExpiryTooFar(uint256 expiresAt, uint256 maxAllowed);
    error ZeroHash();
    error ZeroAdapter();

    // ─────────────────────────────────────────────────────────────
    // Events
    // ─────────────────────────────────────────────────────────────

    event BoardRoleGranted(address indexed account);
    event BoardRoleRevoked(address indexed account);
    event BoardRoleChangeProposed(address indexed account, bool grant, uint256 executeAfter);
    event BoardRoleChangeCancelled(address indexed account);
    event ScreeningProposed(address indexed adapter, bytes32 pronouncementHash, uint256 expiresAt, uint256 executeAfter);
    event ScreeningExecuted(address indexed adapter, bytes32 pronouncementHash, uint256 expiresAt);
    event ScreeningRemoved(address indexed adapter);
    event RemovalProposed(address indexed adapter, uint256 executeAfter);
    event RemovalExecuted(address indexed adapter);

    // ─────────────────────────────────────────────────────────────
    // Storage
    // ─────────────────────────────────────────────────────────────

    struct Screening {
        /// @notice keccak256 of the board resolution document. Zero = not screened.
        bytes32 pronouncementHash;
        /// @notice Unix timestamp after which this screening expires (re-review required).
        uint256 expiresAt;
        /// @notice Block timestamp when the screening was last set.
        uint256 setAt;
    }

    struct Proposal {
        bytes32 pronouncementHash;
        uint256 expiresAt;
        /// @notice Earliest timestamp at which this proposal may be executed.
        uint256 executeAfter;
        bool    exists;
    }

    /// @notice Board members who can propose + execute screening changes.
    mapping(address => bool) public boardRole;

    struct BoardRoleProposal {
        bool grant;           // true = grant, false = revoke
        uint256 executeAfter;
        bool exists;
    }

    /// @notice Pending board-role change proposals. Proposed by board, executed after timelock.
    /// @dev    G4 fix: owner cannot unilaterally grant/revoke board membership.
    ///         A board member must propose; any board member (or proposer) can execute after delay.
    mapping(address => BoardRoleProposal) public boardRoleProposals;

    /// @notice Active screenings — the live registry.
    mapping(address => Screening) public screenings;

    /// @notice Pending proposals (add/update).
    mapping(address => Proposal) public proposals;

    /// @notice Pending removal proposals.
    mapping(address => uint256) public removalProposals; // adapter → executeAfter (0 = none)

    // ─────────────────────────────────────────────────────────────
    // Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyBoard() {
        if (!boardRole[msg.sender]) revert NotBoardRole(msg.sender);
        _;
    }

    // ─────────────────────────────────────────────────────────────
    // Constructor
    // ─────────────────────────────────────────────────────────────

    /// @param initialOwner       Contract owner (Ownable2Step pattern). Can emergency-revoke
    ///                           board members. Does NOT automatically receive boardRole (I5).
    /// @param initialBoardMember The multisig or board address that receives boardRole at deploy.
    ///                           Pass a safe/multisig — not the deployer EOA — to satisfy the
    ///                           H PR2.2 / I5 requirement that the deployer is not sole board.
    ///                           May equal initialOwner only when no separate multisig is available
    ///                           (e.g. testnet single-signer setup); document the risk in README.
    constructor(address initialOwner, address initialBoardMember) Ownable(initialOwner) {
        boardRole[initialBoardMember] = true;
        emit BoardRoleGranted(initialBoardMember);
    }

    // ─────────────────────────────────────────────────────────────
    // Role management
    // ─────────────────────────────────────────────────────────────

    // ─────────────────────────────────────────────────────────────
    // Board role management — G4 fix
    // ─────────────────────────────────────────────────────────────
    // Grant and revoke require a board member to propose + 30-day timelock.
    // The owner retains only pause-level rights and cannot self-appoint.
    // ─────────────────────────────────────────────────────────────

    error BoardRoleProposalExists(address account);
    error NoBoardRoleProposal(address account);

    /// @notice A board member proposes granting or revoking board membership.
    ///         Owner alone cannot propose — only an existing board member can.
    function proposeBoardRoleChange(address account, bool grant) external onlyBoard {
        if (boardRoleProposals[account].exists) revert BoardRoleProposalExists(account);
        uint256 executeAfter = block.timestamp + TIMELOCK_PERIOD;
        boardRoleProposals[account] = BoardRoleProposal({grant: grant, executeAfter: executeAfter, exists: true});
        emit BoardRoleChangeProposed(account, grant, executeAfter);
    }

    /// @notice Any board member may execute a pending board-role change after the timelock.
    function executeBoardRoleChange(address account) external onlyBoard {
        BoardRoleProposal memory p = boardRoleProposals[account];
        if (!p.exists) revert NoBoardRoleProposal(account);
        if (block.timestamp < p.executeAfter) revert TimelockNotElapsed(p.executeAfter, block.timestamp);
        delete boardRoleProposals[account];
        boardRole[account] = p.grant;
        if (p.grant) emit BoardRoleGranted(account);
        else         emit BoardRoleRevoked(account);
    }

    /// @notice Cancel a pending board-role proposal.
    function cancelBoardRoleChange(address account) external onlyBoard {
        if (!boardRoleProposals[account].exists) revert NoBoardRoleProposal(account);
        delete boardRoleProposals[account];
        emit BoardRoleChangeCancelled(account);
    }

    /// @notice Owner-only emergency: revoke a board member immediately (pause power).
    /// @dev    Intentionally asymmetric: owner can remove but not add without the board.
    ///         This prevents a rogue board member from being impossible to remove.
    function emergencyRevokeBoardRole(address account) external onlyOwner {
        boardRole[account] = false;
        emit BoardRoleRevoked(account);
    }

    // ─────────────────────────────────────────────────────────────
    // Screening — propose / execute (add or update)
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Propose a new or updated screening for an adapter.
     * @param adapter           Address of the strategy adapter.
     * @param pronouncementHash keccak256 of the board resolution document.
     * @param expiresAt         Screening expiry (unix seconds). Max 2 years out.
     */
    function proposeScreening(
        address adapter,
        bytes32 pronouncementHash,
        uint256 expiresAt
    ) external onlyBoard {
        if (adapter == address(0))         revert ZeroAdapter();
        if (pronouncementHash == bytes32(0)) revert ZeroHash();
        if (proposals[adapter].exists)     revert AlreadyProposed(adapter);
        if (expiresAt > block.timestamp + MAX_EXPIRY_PERIOD)
            revert ExpiryTooFar(expiresAt, block.timestamp + MAX_EXPIRY_PERIOD);

        uint256 executeAfter = block.timestamp + TIMELOCK_PERIOD;
        proposals[adapter] = Proposal({
            pronouncementHash: pronouncementHash,
            expiresAt:         expiresAt,
            executeAfter:      executeAfter,
            exists:            true
        });

        emit ScreeningProposed(adapter, pronouncementHash, expiresAt, executeAfter);
    }

    /**
     * @notice Execute a previously proposed screening after the timelock has elapsed.
     */
    function executeScreening(address adapter) external onlyBoard {
        Proposal memory p = proposals[adapter];
        if (!p.exists) revert NoPendingProposal(adapter);
        if (block.timestamp < p.executeAfter)
            revert TimelockNotElapsed(p.executeAfter, block.timestamp);

        screenings[adapter] = Screening({
            pronouncementHash: p.pronouncementHash,
            expiresAt:         p.expiresAt,
            setAt:             block.timestamp
        });
        delete proposals[adapter];

        emit ScreeningExecuted(adapter, p.pronouncementHash, p.expiresAt);
    }

    /**
     * @notice Cancel a pending proposal before it is executed.
     */
    function cancelProposal(address adapter) external onlyBoard {
        if (!proposals[adapter].exists) revert NoPendingProposal(adapter);
        delete proposals[adapter];
    }

    // ─────────────────────────────────────────────────────────────
    // Removal — propose / execute
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Propose removal of a screened adapter.
     */
    function proposeRemoval(address adapter) external onlyBoard {
        if (adapter == address(0)) revert ZeroAdapter();
        uint256 executeAfter = block.timestamp + TIMELOCK_PERIOD;
        removalProposals[adapter] = executeAfter;
        emit RemovalProposed(adapter, executeAfter);
    }

    /**
     * @notice Execute a pending removal after the timelock has elapsed.
     */
    function executeRemoval(address adapter) external onlyBoard {
        uint256 executeAfter = removalProposals[adapter];
        if (executeAfter == 0) revert NoPendingProposal(adapter);
        if (block.timestamp < executeAfter)
            revert TimelockNotElapsed(executeAfter, block.timestamp);

        delete screenings[adapter];
        delete removalProposals[adapter];
        emit RemovalExecuted(adapter);
    }

    // ─────────────────────────────────────────────────────────────
    // Read helpers
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Returns true only when the adapter is screened AND the screening
     *         has not expired.  ShariahVaultV2 calls this before deployCapital.
     */
    function isScreened(address adapter) external view returns (bool) {
        Screening memory s = screenings[adapter];
        return s.pronouncementHash != bytes32(0) && block.timestamp < s.expiresAt;
    }

    /**
     * @notice Returns the full Screening struct for an adapter.
     */
    function getScreening(address adapter) external view returns (Screening memory) {
        return screenings[adapter];
    }

    /**
     * @notice Single-source board membership query (I4).
     *         CharityModule and PurificationEscrow call this instead of maintaining
     *         their own local boardRole mappings, so governance changes propagate to
     *         all contracts simultaneously.
     */
    function isBoard(address account) external view returns (bool) {
        return boardRole[account];
    }
}

contracts/ShariahScoreAggregator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

contract ShariahScoreAggregator is Ownable2Step {
    enum ShariahStrategy {
        ETH_SPREAD,
        GOLD_SPREAD,
        HALAL_LP,
        MURABAHA,
        RWA_SUKUK, // RESERVED_4 // deprecated: was RWA_SUKUK — blocked per SR-001
        GOLD_ALLOCATION // index 5 — S6-H XAUT spot allocation; appended per hard rule (no reorder)
    }

    struct Score {
        uint8 value;
        uint40 timestamp;
        bytes32 dataHash;
        uint32 destinationDomain;
    }

    error NotOracle();
    error InvalidScore();
    error NoValidScores();
    error StrategyDeprecated(uint8 strategyIndex);

    event OracleUpdated(address indexed previousOracle, address indexed newOracle);
    event ScoreUpdated(
        ShariahStrategy indexed strategy,
        uint8 value,
        uint40 timestamp,
        bytes32 dataHash,
        uint32 destinationDomain
    );
    /// @dev Renamed from StrategyCertified — "certified" implies a board ruling that has
    ///      not yet been recorded. Use "enabled" for testnet operation (G3).
    event StrategyEnabledUpdated(ShariahStrategy indexed strategy, bool enabled);
    event StrategyFlaggedDeprecated(uint8 indexed strategyIndex);

    address public oracle;

    mapping(ShariahStrategy => Score) public scores;
    mapping(ShariahStrategy => Score[]) public scoreHistory;
    mapping(ShariahStrategy => uint8) public historyIndex;
    /// @dev Renamed from shariahCertified — "certified" implies a board ruling.
    ///      On testnet, set to true for demo purposes only ("enabled (testnet)").
    ///      Do NOT set to true on any production chain without a recorded board pronouncement.
    mapping(ShariahStrategy => bool) public strategyEnabled;

    constructor(address initialOwner) Ownable(initialOwner) {}

    modifier onlyOracleOrOwner() {
        if (msg.sender != owner() && msg.sender != oracle) revert NotOracle();
        _;
    }

    function writeScore(ShariahStrategy strategy, uint8 value, bytes32 dataHash, uint32 destinationDomain)
        external
        onlyOracleOrOwner
    {
        _writeScore(strategy, value, dataHash, destinationDomain);
    }

    function writeBatchScores(
        ShariahStrategy[] calldata strategies,
        uint8[] calldata values,
        bytes32[] calldata dataHashes,
        uint32[] calldata destinationDomains
    ) external onlyOracleOrOwner {
        uint256 length = strategies.length;
        if (length != values.length || length != dataHashes.length || length != destinationDomains.length) {
            revert InvalidScore();
        }

        for (uint256 i = 0; i < length; i++) {
            _writeScore(strategies[i], values[i], dataHashes[i], destinationDomains[i]);
        }
    }

    function getWinningShariahStrategy()
        external
        view
        returns (ShariahStrategy strategy, uint8 score, uint32 destinationDomain)
    {
        ShariahStrategy bestStrategy;
        uint8 bestScore;
        uint32 bestDestinationDomain;
        bool foundValid;

        for (uint8 i = 0; i < 6; i++) {
            ShariahStrategy currentStrategy = ShariahStrategy(i);
            if (!strategyEnabled[currentStrategy]) {
                continue;
            }

            Score memory current = scores[currentStrategy];
            if (current.value == 0) {
                continue;
            }

            if (block.timestamp > uint256(current.timestamp) + 5 minutes) {
                continue;
            }

            if (!foundValid || current.value > bestScore) {
                bestScore = current.value;
                bestStrategy = currentStrategy;
                bestDestinationDomain = current.destinationDomain;
                foundValid = true;
            }
        }

        if (!foundValid) revert NoValidScores();

        return (bestStrategy, bestScore, bestDestinationDomain);
    }

    function getAllShariahScores()
        external
        view
        returns (
            uint8[6] memory values,
            uint40[6] memory timestamps,
            uint32[6] memory destinationDomains,
            bool[6] memory certified
        )
    {
        for (uint8 i = 0; i < 6; i++) {
            ShariahStrategy strategy = ShariahStrategy(i);
            Score memory current = scores[strategy];
            values[i] = current.value;
            timestamps[i] = current.timestamp;
            destinationDomains[i] = current.destinationDomain;
            certified[i] = strategyEnabled[strategy];
        }
    }

    function getScoreHistory(ShariahStrategy strategy) external view returns (Score[10] memory history) {
        Score[] storage stored = scoreHistory[strategy];
        uint256 length = stored.length;

        if (length == 0) {
            return history;
        }

        if (length < 10) {
            for (uint256 i = 0; i < length; i++) {
                history[i] = stored[i];
            }
            return history;
        }

        uint256 start = historyIndex[strategy];
        for (uint256 i = 0; i < 10; i++) {
            history[i] = stored[(start + i) % 10];
        }
    }

    /// @notice Enable or disable a strategy for winner selection.
    /// @dev    On testnet: may be set true for demos. On production chains: requires a
    ///         recorded board pronouncement before setting true (G3 deploy-script guard).
    ///         Renamed from setCertified — "certified" is reserved for board rulings.
    function setEnabled(ShariahStrategy strategy, bool enabled) external onlyOwner {
        strategyEnabled[strategy] = enabled;
        emit StrategyEnabledUpdated(strategy, enabled);
    }

    /// @notice Backward-compat alias for setEnabled (test suites may use old name).
    function setCertified(ShariahStrategy strategy, bool certified) external onlyOwner {
        strategyEnabled[strategy] = certified;
        emit StrategyEnabledUpdated(strategy, certified);
    }

    function setOracle(address newOracle) external onlyOwner {
        address previousOracle = oracle;
        oracle = newOracle;
        emit OracleUpdated(previousOracle, newOracle);
    }

    function _writeScore(ShariahStrategy strategy, uint8 value, bytes32 dataHash, uint32 destinationDomain) internal {
        if (uint8(strategy) == 4) revert StrategyDeprecated(4);
        if (value > 100) revert InvalidScore();

        Score memory nextScore = Score({
            value: value,
            timestamp: uint40(block.timestamp),
            dataHash: dataHash,
            destinationDomain: destinationDomain
        });
        scores[strategy] = nextScore;

        Score[] storage history = scoreHistory[strategy];
        uint8 index = historyIndex[strategy];

        if (history.length < 10) {
            history.push(nextScore);
            historyIndex[strategy] = uint8(history.length % 10);
        } else {
            history[index] = nextScore;
            historyIndex[strategy] = uint8((index + 1) % 10);
        }

        emit ScoreUpdated(strategy, value, nextScore.timestamp, dataHash, destinationDomain);
    }
}

contracts/ShariahVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AutonomousVault} from "./AutonomousVault.sol";
import {TreasuryModule} from "./TreasuryModule.sol";
import {ZakatModule} from "./ZakatModule.sol";
import {PurificationEscrow} from "./PurificationEscrow.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IStrategyAdapter} from "./IStrategyAdapter.sol";

/// @dev Minimal interface to read currentValue() and isPriceSane() from a gold adapter.
interface IGoldAdapter {
    function currentValue() external view returns (uint256);
    function isPriceSane() external view returns (bool);
}

/// @dev Optional marker for strategies that require linked gold accounting.
interface IGoldMarker {
    function isGoldStrategy() external pure returns (bool);
}

/// @dev Minimal Chainlink-style oracle interface for price reads (same as AggregatorV3Interface).
interface IGoldOracle {
    function latestRoundData() external view returns (
        uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound
    );
    function decimals() external view returns (uint8);
}

contract ShariahVault is AutonomousVault {
    using SafeERC20 for IERC20;

    error ZeroAmount();
    error AdapterNotScreened();
    error ProfitExceedsRealized(uint256 requested, uint256 available);
    error AdapterExecutionReentered();
    error UseAtomicDeploy(address adapter);
    error RemoteRecipientNotApproved(uint32 domain, bytes32 recipient);
    error NoPendingRemoteRecipient();
    error RemoteRecipientProposalExists();
    error RemoteRecipientTimelockNotElapsed(uint256 earliest, uint256 current);
    error ZeroRecipient();
    error AssetNotPermitted(address asset_);
    /// @dev Gold strategies cannot use a nonzero destination domain: SR-005 governs
    ///      atomic gold settlement. SR-023's vault-wide transfer restriction is superseded.
    error NonAtomicGoldExchange();
    /// @dev Thrown when deploying to either gold adapter would push combined gold above MAX_GOLD_BPS.
    error GoldCapExceeded(uint256 combinedGoldValue, uint256 cap);
    error GoldAdapterHasExposure(address adapter, uint256 value);
    error RetiredGoldAdapter(address adapter);
    error UntrackedGoldAdapter(address adapter);

    error PurificationEscrowNotSet();
    error InsufficientFeeBalance(uint256 available, uint256 required);
    error NotBoardRole(address caller);
    error DustThresholdAboveCap(uint256 proposed, uint256 cap);
    error DustTimelockNotElapsed(uint256 earliest, uint256 current);
    error NoPendingDustProposal();
    error DustProposalAlreadyExists();

    event AdapterScreened(address indexed adapter, bool approved);
    event PermittedAssetUpdated(address indexed asset_, bool permitted);
    event WakalaFeeAccrued(uint256 amount);
    event WakalaAccrualSkipped(uint256 fee);
    event MusharakahProfitClaimed(uint256 grossProfit, uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare);
    event ShariahScreeningToggled(bool enabled);
    event GoldAllocationAdapterUpdated(address indexed adapter);
    event GoldSpreadAdapterUpdated(address indexed adapter);
    event PurificationEscrowUpdated(address indexed escrow);
    event DustThresholdUpdated(uint256 previous, uint256 updated);
    event DustThresholdProposed(uint256 newValue, uint256 executeAfter);
    event DustThresholdProposalCancelled();
    event RemoteRecipientProposed(uint32 indexed domain, bytes32 indexed recipient, bool approved, uint256 executeAfter);
    event RemoteRecipientProposalCancelled(uint32 indexed domain, bytes32 indexed recipient);
    event RemoteRecipientUpdated(uint32 indexed domain, bytes32 indexed recipient, bool approved);

    TreasuryModule public immutable shariahTreasury;
    /// @dev v1 — DEPRECATED. Kept for history. New profit routing uses purificationEscrow.
    ZakatModule public immutable zakatModule;
    /// @notice v2 profit-distribution waterfall: purification → sadaqah → Musharakah split.
    ///         Set via setPurificationEscrow(). If zero, claimMusharakahProfit reverts.
    PurificationEscrow public purificationEscrow;

    /// @notice Hard cap: combined S2-H (PAXG) + S6-H (XAUT) value must not exceed 30% of totalAssets.
    /// @dev    Hard-coded — not board-settable. Requires a contract upgrade to change.
    uint256 public constant MAX_GOLD_BPS = 3000;

    bool public shariahScreeningEnabled;
    mapping(address => bool) public screened;
    mapping(address => bool) public permittedAssets;
    /// @dev Indices in ShariahScoreAggregator.ShariahStrategy; enum order must remain unchanged.
    uint8 public constant GOLD_SPREAD_IDX = 1;
    uint8 public constant GOLD_ALLOCATION_IDX = 5;

    /// @notice S2-H gold spread adapter (GoldExchangeAdapter — PAXG). Used for combined cap check.
    address public goldSpreadAdapter;

    /// @notice S6-H gold allocation adapter (GoldAllocationAdapter — XAUT). Used for combined cap check.
    address public goldAllocationAdapter;

    /// @notice Minimum adapter principal (USDC, 6 dec) that triggers a deposit pause when price is stale.
    ///         An adapter at or below effectiveDustThreshold() never blocks deposits even if stale.
    ///         Default 1e6 = 1 USDC. Changes require board approval and a 30-day delay.
    uint256 public dustThreshold = 1e6;
    uint256 public constant MAX_DUST_BPS = 50;
    uint256 public constant MIN_DUST_CAP = 1e6;
    uint256 public constant DUST_TIMELOCK = 30 days;

    struct PendingDustThreshold {
        uint256 newValue;
        uint256 executeAfter;
        bool exists;
    }
    PendingDustThreshold public pendingDustThreshold;

    uint256 public lastFeeAccrualTime;
    uint256 public hurdlePrincipal;
    uint256 public hurdleStartTime;
    /// @notice Highest processed realized assets per share, including locked depositor profit, scaled by 1e18.
    /// @dev Uses the same virtual assets/shares as ERC-4626; cash flows never reset it.
    uint256 public highWaterMarkPerShare;
    /// @notice Principal checkpoint in net asset units; deposits are not realized profit.
    uint256 public profitBase;
    bool private _adapterExecutionLocked;
    /// @notice Outstanding locally funded principal per adapter, independent of recall proceeds.
    mapping(address => uint256) public principalOf;

    event PrincipalRetired(address indexed adapter, uint256 retired, uint256 proceeds);

    uint256 public constant REMOTE_RECIPIENT_TIMELOCK = 30 days;
    struct PendingRemoteRecipient {
        bool approved;
        uint256 executeAfter;
        bool exists;
    }
    mapping(uint32 => mapping(bytes32 => bool)) public approvedRemoteRecipient;
    mapping(uint32 => mapping(bytes32 => PendingRemoteRecipient)) public pendingRemoteRecipient;
    /// @notice Previously tracked gold adapters cannot receive capital until explicitly linked again.
    mapping(address => bool) public retiredGoldAdapter;

    constructor(
        IERC20 asset_,
        address initialOwner,
        uint32 sourceDomain_,
        address shariahTreasury_,
        address zakatModule_ // pass address(0) for V2 deployments (ZakatModule is deprecated)
    ) AutonomousVault(asset_, initialOwner, sourceDomain_) {
        shariahTreasury = TreasuryModule(shariahTreasury_);
        zakatModule = ZakatModule(zakatModule_); // zero address is valid — v2 uses PurificationEscrow

        shariahScreeningEnabled = true;
        lastFeeAccrualTime = block.timestamp;
        hurdleStartTime    = block.timestamp;
        highWaterMarkPerShare = 1e18 / (10 ** _decimalsOffset());
        permittedAssets[address(asset_)] = true;
    }

    function name() public pure virtual override(ERC20, IERC20Metadata) returns (string memory) {
        return "Shariah Vault Share";
    }

    /// @dev Mark gold in both directions before deducting locked profit and fees.
    function _navBeforeUnbookedFee() internal view returns (uint256) {
        uint256 assets = IERC20(asset()).balanceOf(address(this)) + totalDeployed;
        uint256 writedown = goldWritedown();
        assets = assets > writedown ? assets - writedown : 0;
        assets += goldUnrealizedGain();
        uint256 locked = _currentLockedProfit();
        assets = assets > locked ? assets - locked : 0;
        uint256 fees = shariahTreasury.pendingFees();
        return assets > fees ? assets - fees : 0;
    }

    /// @dev Independent realized AUM base: never calls totalAssets or pendingWakalaFee.
    function _navExGainBeforeUnbookedFee() internal view returns (uint256) {
        uint256 assets = IERC20(asset()).balanceOf(address(this)) + totalDeployed;
        uint256 writedown = goldWritedown();
        assets = assets > writedown ? assets - writedown : 0;
        uint256 locked = _currentLockedProfit();
        assets = assets > locked ? assets - locked : 0;
        uint256 fees = shariahTreasury.pendingFees();
        return assets > fees ? assets - fees : 0;
    }

    /// @notice Unbooked time-based fee on realized AUM, already reflected in share pricing.
    function pendingWakalaFee() public view returns (uint256) {
        return Math.mulDiv(
            _navExGainBeforeUnbookedFee(),
            shariahTreasury.adminFeeBps() * (block.timestamp - lastFeeAccrualTime),
            10_000 * 365 days
        );
    }

    function totalAssets() public view virtual override returns (uint256) {
        uint256 assets = _navBeforeUnbookedFee();
        uint256 fee = pendingWakalaFee();
        return assets > fee ? assets - fee : 0;
    }

    /// @notice Aggregate loss below principal for the tracked gold adapters.
    function goldWritedown() public view returns (uint256 writedown) {
        return ShariahAccountingLogic.goldWritedown(principalOf, goldSpreadAdapter, goldAllocationAdapter);
    }

    /// @notice Aggregate appreciation above principal for the tracked gold adapters.
    function goldUnrealizedGain() public view returns (uint256 gain) {
        return ShariahAccountingLogic.goldUnrealizedGain(principalOf, goldSpreadAdapter, goldAllocationAdapter);
    }

    /// @dev Saturate when liabilities consume NAV including some unrealized appreciation.
    function _assetsExcludingGoldGain() internal view returns (uint256) {
        uint256 assets = totalAssets();
        uint256 gain = goldUnrealizedGain();
        return assets > gain ? assets - gain : 0;
    }

    /// @dev Price uses one virtual asset and 10**offset virtual shares, like ERC-4626.
    function _realizedPricePerShare(uint256 realizedNav) internal view returns (uint256) {
        return Math.mulDiv(realizedNav + 1, 1e18, totalSupply() + 10 ** _decimalsOffset());
    }

    /// @dev Exclude unprocessed yield, but retain processed depositor profit throughout unlock.
    ///      The checkpoint cap prevents gross tokens already in NAV from advancing the high.
    function _processedNav() internal view returns (uint256) {
        return Math.min(_assetsExcludingGoldGain() + _currentLockedProfit(), profitBase);
    }

    /// @notice Asset equivalent of the processed per-share high at the current virtual supply.
    function highWaterMark() public view returns (uint256) {
        uint256 assets = Math.mulDiv(
            highWaterMarkPerShare, totalSupply() + 10 ** _decimalsOffset(), 1e18
        );
        return assets > 0 ? assets - 1 : 0;
    }

    function _hwmDeficit(uint256 realizedNav) internal view returns (uint256) {
        uint256 price = _realizedPricePerShare(realizedNav);
        if (price >= highWaterMarkPerShare) return 0;
        return Math.mulDiv(
            highWaterMarkPerShare - price, totalSupply() + 10 ** _decimalsOffset(), 1e18
        );
    }

    /// @notice Live unrecovered loss on the processed basis, including locked profit, excluding paper appreciation.
    function hwmDeficit() public view returns (uint256) {
        return _hwmDeficit(_processedNav());
    }

    /// @notice Net realized assets above the checkpoint; gold appreciation is never distributable.
    function realizedProfit() public view returns (uint256) {
        uint256 assetsNow = _assetsExcludingGoldGain();
        return assetsNow > profitBase ? assetsNow - profitBase : 0;
    }

    function lockProfit(uint256 amount) external virtual onlyManagerOrOwner {
        if (amount == 0) revert ZeroAmount();
        uint256 available = realizedProfit();
        if (amount > available) revert ProfitExceedsRealized(amount, available);
        _lockProfitInternal(amount);
    }

    function _deposit(address caller, address receiver, uint256 assets, uint256 shares)
        internal
        virtual
        override
    {
        _tryAccrueWakalaFee();
        profitBase += assets;
        super._deposit(caller, receiver, assets, shares);
    }

    function _withdraw(address caller, address receiver, address owner_, uint256 assets, uint256 shares)
        internal
        virtual
        override
    {
        _tryAccrueWakalaFee();
        // Reduce the checkpoint by the share of supply being burned, not by assets over
        // totalAssets(): totalAssets() excludes locked profit and pending fees, while profitBase
        // includes the locked depositor share, so an assets-based ratio would under-reduce it and
        // make already-distributed profit claimable again after it unlocks.
        uint256 supplyBefore = totalSupply();
        if (supplyBefore != 0) {
            uint256 reduction = shares >= supplyBefore
                ? profitBase : Math.mulDiv(profitBase, shares, supplyBefore);
            profitBase = reduction >= profitBase ? 0 : profitBase - reduction;
        }
        super._withdraw(caller, receiver, owner_, assets, shares);
    }

    function symbol() public pure virtual override(ERC20, IERC20Metadata) returns (string memory) {
        return "svUSDC";
    }

    /// @notice Override deployCapital to enforce Shariah screening and accrue Wakala fee.
    /// @dev Transfer-only compatibility path for non-gold strategies; configured gold requires atomic execution.
    function deployCapital(address strategy, uint256 amount, bytes calldata data)
        external
        virtual
        override
        onlyManagerOrOwner
    {
        if (strategy != address(0) && (strategy == goldSpreadAdapter || strategy == goldAllocationAdapter)) {
            revert UseAtomicDeploy(strategy);
        }
        _deployCapital(strategy, amount, data);
        principalOf[strategy] += amount;
        _accrueWakalaFee();
    }

    /// @notice Transfer capital and execute the adapter atomically with this vault as caller.
    function deployCapitalAndExecute(address strategy, uint256 amount, bytes calldata data)
        external
        virtual
        onlyManagerOrOwner
    {
        if (_adapterExecutionLocked) revert AdapterExecutionReentered();
        _deployCapital(strategy, amount, data);
        _adapterExecutionLocked = true;
        IStrategyAdapter(strategy).deploy(amount);
        // Book principal and accrue against completed adapter state, never a half-funded gold position.
        principalOf[strategy] += amount;
        _accrueWakalaFee();
        _adapterExecutionLocked = false;
    }

    /// @notice Return transferred capital while retiring the corresponding strategy principal.
    function returnCapital(address strategy, uint256 amount) external virtual override onlyManagerOrOwner {
        if (paused) revert Paused();
        IERC20(asset()).safeTransferFrom(strategy, address(this), amount);
        uint256 retired = Math.min(amount, principalOf[strategy]);
        principalOf[strategy] -= retired;
        totalDeployed -= Math.min(retired, totalDeployed);
        emit CapitalReturned(strategy, amount);
        emit PrincipalRetired(strategy, retired, amount);
    }

    /// @notice Recognize a total adapter loss before replacing or unlinking its address.
    /// @dev Only a zero-valued position can be written off; principal and deployed cost retire atomically.
    function writeOffAdapterPrincipal(address adapter) external onlyOwner {
        uint256 value = IStrategyAdapter(adapter).currentValue();
        if (value != 0) revert GoldAdapterHasExposure(adapter, value);
        uint256 retired = principalOf[adapter];
        principalOf[adapter] = 0;
        totalDeployed = totalDeployed >= retired ? totalDeployed - retired : 0;
        emit PrincipalRetired(adapter, retired, 0);
    }

    /// @notice Retire requested principal (all remaining principal on full exit), not recall proceeds.
    function recallCapital(address adapter, uint256 amount) external virtual override onlyManagerOrOwner {
        if (paused) revert Paused();
        (uint256 actualReturn, uint256 retired) = ShariahAccountingLogic.recall(
            principalOf, asset(), adapter, amount
        );
        totalDeployed = totalDeployed >= retired ? totalDeployed - retired : 0;

        emit CapitalRecalledFromAdapter(adapter, amount, actualReturn);
        emit PrincipalRetired(adapter, retired, actualReturn);
    }

    /// @dev Screening hook includes pause/asset checks to preserve each version's revert ordering.
    function _checkDeploymentScreening(address strategy) internal view virtual {
        if (paused) revert Paused();
        if (!permittedAssets[asset()]) revert AssetNotPermitted(asset());
        if (shariahScreeningEnabled && !screened[strategy]) revert AdapterNotScreened();
    }

    function _deployCapital(address strategy, uint256 amount, bytes calldata data) internal {
        if (retiredGoldAdapter[strategy]) revert RetiredGoldAdapter(strategy);
        _checkDeploymentScreening(strategy);
        ShariahAccountingLogic.checkGoldMarker(strategy, goldSpreadAdapter, goldAllocationAdapter);
        data;

        uint256 currentAssets = totalAssets();
        uint256 maxDeployable = (currentAssets * maxAllocationBps) / 10_000;
        if (totalDeployed + amount > maxDeployable) revert AllocationExceedsLimit();

        // Combined gold cap: S2-H (PAXG) + S6-H (XAUT) must not exceed MAX_GOLD_BPS of totalAssets.
        // Check only when deploying to either gold adapter.
        ShariahAccountingLogic.checkGoldCap(
            strategy, goldSpreadAdapter, goldAllocationAdapter, amount, currentAssets
        );

        IERC20(asset()).safeTransfer(strategy, amount);
        totalDeployed += amount;

        emit CapitalDeployed(strategy, amount);
    }

    /// @notice Strategy-tagged cross-chain transfer. A gold strategy (S2-H, S6-H) is never routed
    ///         cross-chain: this entry point always moves USDC over CCTP, and domain 0 is a real
    ///         CCTP domain (Ethereum), not "local". Gold strategies that execute locally go
    ///         through deployCapital / the executor instead.
    function deployCrossChainForStrategy(
        uint8 shariahStrategyIdx,
        uint32 destinationDomain,
        bytes32 recipient,
        uint256 amount
    ) external onlyManagerOrOwner {
        if (shariahStrategyIdx == GOLD_SPREAD_IDX || shariahStrategyIdx == GOLD_ALLOCATION_IDX) {
            revert NonAtomicGoldExchange();
        }
        deployCrossChain(destinationDomain, recipient, amount);
    }

    function deployCrossChain(uint32 destinationDomain, bytes32 recipient, uint256 amount)
        public virtual override onlyManagerOrOwner
    {
        if (!permittedAssets[asset()]) revert AssetNotPermitted(asset());
        if (!approvedRemoteRecipient[destinationDomain][recipient]) {
            revert RemoteRecipientNotApproved(destinationDomain, recipient);
        }
        super.deployCrossChain(destinationDomain, recipient, amount);
    }

    /// @notice Board proposes an approval or revocation; both require the full delay.
    function proposeRemoteRecipient(uint32 domain, bytes32 recipient, bool approved) external onlyBoard {
        ShariahGovernanceLogic.proposeRemoteRecipient(pendingRemoteRecipient, domain, recipient, approved);
    }

    function confirmRemoteRecipient(uint32 domain, bytes32 recipient) external onlyBoard {
        ShariahGovernanceLogic.confirmRemoteRecipient(
            pendingRemoteRecipient, approvedRemoteRecipient, domain, recipient
        );
    }

    function cancelRemoteRecipient(uint32 domain, bytes32 recipient) external onlyBoard {
        ShariahGovernanceLogic.cancelRemoteRecipient(pendingRemoteRecipient, domain, recipient);
    }

    function _accrueWakalaFee() internal {
        uint256 fee = pendingWakalaFee();
        if (fee > 0) {
            shariahTreasury.accrue(fee);
        } else if (_feeCanAccrue()) {
            // A fee that rounds to zero keeps its elapsed time so frequent zero-value calls cannot erase accrual.
            return;
        }
        lastFeeAccrualTime = block.timestamp;
        emit WakalaFeeAccrued(fee);
    }

    /// @dev True when a fee is configured and there is AUM, i.e. elapsed time is worth preserving.
    function _feeCanAccrue() internal view returns (bool) {
        return shariahTreasury.adminFeeBps() > 0 && _navExGainBeforeUnbookedFee() > 0;
    }

    /// @dev Booking replaces an equal view deduction; failed booking cannot gate user exits.
    function _tryAccrueWakalaFee() internal {
        uint256 fee = pendingWakalaFee();
        if (fee == 0) {
            if (_feeCanAccrue()) return; // keep elapsed time so rounding to zero never discards accrual
            lastFeeAccrualTime = block.timestamp;
            emit WakalaFeeAccrued(0);
            return;
        }
        try shariahTreasury.accrue(fee) {
            lastFeeAccrualTime = block.timestamp;
            emit WakalaFeeAccrued(fee);
        } catch {
            emit WakalaAccrualSkipped(fee);
        }
    }

    /**
     * @notice Distribute Shariah profit through the v2 waterfall (purification → sadaqah → Musharakah).
     * @dev    Requires `purificationEscrow` to be set (setPurificationEscrow).
     *         The escrow contract enforces the full invariant:
     *           purified + charity + vaultShare + depositorShare == grossProfit
     *
     *         v1 ZakatModule path has been removed. Existing v1 vaults retain their
     *         ZakatModule and continue to function — only new profit claims use this path.
     */
    function claimMusharakahProfit(uint256 grossProfit) external onlyManagerOrOwner {
        if (address(purificationEscrow) == address(0)) revert PurificationEscrowNotSet();
        _tryAccrueWakalaFee();
        uint256 available = realizedProfit();
        if (grossProfit > available) revert ProfitExceedsRealized(grossProfit, available);

        // Approve escrow to pull the gross profit from vault.
        IERC20(asset()).forceApprove(address(purificationEscrow), grossProfit);

        // Gross tokens are already in NAV: cap at the pre-claim checkpoint, rather than
        // subtracting this claim (which would leave any unprocessed remainder in the price).
        uint256 deficit = _hwmDeficit(_processedNav());

        (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) =
            purificationEscrow.executeWaterfallHWM(
                grossProfit,
                block.timestamp - hurdleStartTime,
                hurdlePrincipal,
                deficit
            );

        // Clear any leftover allowance (defensive).
        IERC20(asset()).forceApprove(address(purificationEscrow), 0);

        // N-11 / N-24 / N-19: the depositor share is NOT locked. The gross profit was already in
        // NAV before this claim, so returning the depositor share changes nothing about the share
        // price, and hiding it for an unlock period would only discount entrants (N-11), dilute the
        // processed per-share value (N-24) and strand tokens after the last redemption (N-19).
        // Manager-called lockProfit remains available for streaming genuinely new yield.

        // Realized checkpoints must not absorb appreciation before a later recall realizes it.
        hurdlePrincipal = _assetsExcludingGoldGain();
        // Advance only by profit already distributed to depositors, not unprocessed yield, so the
        // depositor share cannot be claimed as profit a second time.
        profitBase += depositorShare;
        hurdleStartTime = block.timestamp;
        // Record the earned depositor peak, never the unprocessed remainder.
        uint256 postClaimPrice = _realizedPricePerShare(_processedNav());
        if (postClaimPrice > highWaterMarkPerShare) highWaterMarkPerShare = postClaimPrice;

        emit MusharakahProfitClaimed(grossProfit, purified, charity, vaultShare, depositorShare);
    }

    /// @notice Sweep accrued fees to a receiver. Amount is capped to `pendingFees` to
    ///         prevent owner from sweeping depositor principal under the guise of fee claims.
    function sweepFeesToTreasury(address receiver, uint256 amount) external onlyOwner {
        uint256 pending = shariahTreasury.pendingFees();
        if (amount > pending) revert AllocationExceedsLimit(); // reuse error: amount > accrued
        uint256 available = IERC20(asset()).balanceOf(address(this));
        if (available < amount) revert InsufficientFeeBalance(available, amount);
        IERC20(asset()).safeTransfer(receiver, amount);
        shariahTreasury.claimFees(receiver, amount);
    }

    function setScreened(address adapter, bool approved) external onlyOwner {
        screened[adapter] = approved;
        emit AdapterScreened(adapter, approved);
    }

    function setPermittedAsset(address asset_, bool permitted) external onlyOwner {
        permittedAssets[asset_] = permitted;
        emit PermittedAssetUpdated(asset_, permitted);
    }

    function setShariahScreening(bool enabled) external onlyOwner {
        shariahScreeningEnabled = enabled;
        emit ShariahScreeningToggled(enabled);
    }

    /**
     * @notice Returns 0 when any gold adapter reports an insane price (PR1 — deposit pause).
     * @dev    Keeps redemptions open — only blocks new capital entering at a wrong price.
     *         If neither gold adapter is set, falls through to the ERC-4626 default.
     */
    function maxDeposit(address receiver) public view virtual override returns (uint256) {
        if (_goldPriceInsane()) return 0;
        return super.maxDeposit(receiver);
    }

    /// @notice Mirror of maxDeposit — blocks minting when oracle is insane.
    function maxMint(address receiver) public view virtual override returns (uint256) {
        if (_goldPriceInsane()) return 0;
        return super.maxMint(receiver);
    }

    /// @notice Board-set threshold clamped to the current asset-based cap at enforcement time.
    function effectiveDustThreshold() public view returns (uint256) {
        uint256 cap = (totalAssets() * MAX_DUST_BPS) / 10_000;
        if (cap < MIN_DUST_CAP) cap = MIN_DUST_CAP;
        return dustThreshold < cap ? dustThreshold : cap;
    }

    /// @dev Returns true when at least one gold adapter is set, reports price insanity,
    ///      AND has more than effectiveDustThreshold() USDC of outstanding principal.
    ///      An adapter with no material position (e.g. S6-H disabled, S2-H idle) never
    ///      blocks deposits even if its oracle or last-swap timestamp is stale (J2).
    function _goldPriceInsane() internal view returns (bool) {
        if (goldAllocationAdapter != address(0)) {
            IGoldAdapter adp = IGoldAdapter(goldAllocationAdapter);
            if (!adp.isPriceSane() && principalOf[address(adp)] > effectiveDustThreshold()) return true;
        }
        if (goldSpreadAdapter != address(0)) {
            IGoldAdapter adp = IGoldAdapter(goldSpreadAdapter);
            if (!adp.isPriceSane() && principalOf[address(adp)] > effectiveDustThreshold()) return true;
        }
        return false;
    }

    modifier onlyBoard() {
        if (!_isBoard(msg.sender)) revert NotBoardRole(msg.sender);
        _;
    }

    /// @dev V1 has no registry; V2 resolves membership through its registry.
    function _isBoard(address account) internal view virtual returns (bool) {
        return account == owner();
    }

    function _checkDustCap(uint256 proposed) internal view {
        uint256 cap = (totalAssets() * MAX_DUST_BPS) / 10_000;
        if (cap < MIN_DUST_CAP) cap = MIN_DUST_CAP;
        if (proposed > cap) revert DustThresholdAboveCap(proposed, cap);
    }

    /// @notice Board proposes a capped threshold with a 30-day delay.
    function proposeDustThreshold(uint256 newValue) external onlyBoard {
        _checkDustCap(newValue);
        ShariahGovernanceLogic.proposeDustThreshold(pendingDustThreshold, newValue);
    }

    /// @notice Board confirms after the delay, subject to the current asset-based cap.
    function confirmDustThreshold() external onlyBoard {
        PendingDustThreshold memory p = pendingDustThreshold;
        ShariahGovernanceLogic.checkDustConfirmation(pendingDustThreshold);
        _checkDustCap(p.newValue);
        delete pendingDustThreshold;
        uint256 previous = dustThreshold;
        dustThreshold = p.newValue;
        emit DustThresholdUpdated(previous, p.newValue);
    }

    /// @notice Board cancels a pending threshold proposal.
    function cancelDustThreshold() external onlyBoard {
        ShariahGovernanceLogic.cancelDustThreshold(pendingDustThreshold);
    }

    function setHurdlePrincipal(uint256 principal) external onlyOwner {
        hurdlePrincipal = principal;
    }

    /// @notice Set the S2-H gold spread adapter address for combined cap tracking.
    /// @dev    Only used for cap calculation — does not screen the adapter.
    ///         Call setScreened(adapter, true) separately.
    function setGoldSpreadAdapter(address adapter) external onlyOwner {
        ShariahAccountingLogic.replaceGoldAdapter(principalOf, retiredGoldAdapter, goldSpreadAdapter, adapter);
        goldSpreadAdapter = adapter;
        if (adapter != address(0)) retiredGoldAdapter[adapter] = false;
        emit GoldSpreadAdapterUpdated(adapter);
    }

    /// @notice Set the S6-H gold allocation adapter address for combined cap tracking.
    /// @dev    Only used for cap calculation — does not screen the adapter.
    ///         Call setScreened(adapter, true) separately.
    function setGoldAllocationAdapter(address adapter) external onlyOwner {
        ShariahAccountingLogic.replaceGoldAdapter(principalOf, retiredGoldAdapter, goldAllocationAdapter, adapter);
        goldAllocationAdapter = adapter;
        if (adapter != address(0)) retiredGoldAdapter[adapter] = false;
        emit GoldAllocationAdapterUpdated(adapter);
    }

    /// @notice Set the PurificationEscrow address for v2 Musharakah profit distribution.
    /// @dev    Must be set before claimMusharakahProfit() can be called.
    ///         The escrow must be constructed with this vault's address, asset,
    ///         a CharityModule, and the shariahTreasury.
    function setPurificationEscrow(address escrow) external onlyOwner {
        purificationEscrow = PurificationEscrow(escrow);
        emit PurificationEscrowUpdated(escrow);
    }
}

/// @dev Linked timelock operations. Authorization and NAV-dependent cap checks stay in the vault.
library ShariahGovernanceLogic {
    function proposeRemoteRecipient(
        mapping(uint32 => mapping(bytes32 => ShariahVault.PendingRemoteRecipient)) storage pending,
        uint32 domain, bytes32 recipient, bool approved
    ) external {
        if (recipient == bytes32(0)) revert ShariahVault.ZeroRecipient();
        if (pending[domain][recipient].exists) revert ShariahVault.RemoteRecipientProposalExists();
        uint256 executeAfter = block.timestamp + 30 days;
        pending[domain][recipient] = ShariahVault.PendingRemoteRecipient(approved, executeAfter, true);
        emit ShariahVault.RemoteRecipientProposed(domain, recipient, approved, executeAfter);
    }

    function confirmRemoteRecipient(
        mapping(uint32 => mapping(bytes32 => ShariahVault.PendingRemoteRecipient)) storage pending,
        mapping(uint32 => mapping(bytes32 => bool)) storage approved,
        uint32 domain, bytes32 recipient
    ) external {
        ShariahVault.PendingRemoteRecipient memory p = pending[domain][recipient];
        if (!p.exists) revert ShariahVault.NoPendingRemoteRecipient();
        if (block.timestamp < p.executeAfter) {
            revert ShariahVault.RemoteRecipientTimelockNotElapsed(p.executeAfter, block.timestamp);
        }
        delete pending[domain][recipient];
        approved[domain][recipient] = p.approved;
        emit ShariahVault.RemoteRecipientUpdated(domain, recipient, p.approved);
    }

    function cancelRemoteRecipient(
        mapping(uint32 => mapping(bytes32 => ShariahVault.PendingRemoteRecipient)) storage pending,
        uint32 domain, bytes32 recipient
    ) external {
        if (!pending[domain][recipient].exists) revert ShariahVault.NoPendingRemoteRecipient();
        delete pending[domain][recipient];
        emit ShariahVault.RemoteRecipientProposalCancelled(domain, recipient);
    }

    function proposeDustThreshold(ShariahVault.PendingDustThreshold storage pending, uint256 newValue) external {
        if (pending.exists) revert ShariahVault.DustProposalAlreadyExists();
        uint256 executeAfter = block.timestamp + 30 days;
        pending.newValue = newValue;
        pending.executeAfter = executeAfter;
        pending.exists = true;
        emit ShariahVault.DustThresholdProposed(newValue, executeAfter);
    }

    function checkDustConfirmation(ShariahVault.PendingDustThreshold storage pending) external view {
        if (!pending.exists) revert ShariahVault.NoPendingDustProposal();
        if (block.timestamp < pending.executeAfter) {
            revert ShariahVault.DustTimelockNotElapsed(pending.executeAfter, block.timestamp);
        }
    }

    function cancelDustThreshold(ShariahVault.PendingDustThreshold storage pending) external {
        if (!pending.exists) revert ShariahVault.NoPendingDustProposal();
        delete pending.newValue;
        delete pending.executeAfter;
        delete pending.exists;
        emit ShariahVault.DustThresholdProposalCancelled();
    }
}

/// @dev Linked gold valuation; each read and saturating subtraction follows the vault's original order.
library ShariahAccountingLogic {
    function recall(
        mapping(address => uint256) storage principalOf, address token, address adapter, uint256 amount
    ) external returns (uint256 actualReturn, uint256 retired) {
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        uint256 returned = IStrategyAdapter(adapter).recall(amount);
        uint256 balanceAfter = IERC20(token).balanceOf(address(this));
        actualReturn = balanceAfter > balanceBefore ? balanceAfter - balanceBefore : returned;
        bool closed = IStrategyAdapter(adapter).currentValue() == 0;
        uint256 principal = principalOf[adapter];
        retired = closed ? principal : Math.min(amount, principal);
        principalOf[adapter] = principal - retired;
    }

    function replaceGoldAdapter(
        mapping(address => uint256) storage principalOf,
        mapping(address => bool) storage retired, address previous, address replacement
    ) external {
        if (previous != address(0)) {
            uint256 value = IGoldAdapter(previous).currentValue();
            if (value > 0) revert ShariahVault.GoldAdapterHasExposure(previous, value);
            uint256 principal = principalOf[previous];
            if (principal > 0) revert ShariahVault.GoldAdapterHasExposure(previous, principal);
        }
        if (previous != address(0) && previous != replacement) retired[previous] = true;
    }

    function checkGoldMarker(address strategy, address spread, address allocation) external view {
        if (strategy.code.length != 0) {
            try IGoldMarker(strategy).isGoldStrategy() returns (bool g) {
                if (g && strategy != spread && strategy != allocation) {
                    revert ShariahVault.UntrackedGoldAdapter(strategy);
                }
            } catch {
                // Missing/reverting markers retain the non-gold compatibility path.
            }
        }
    }

    function checkGoldCap(
        address strategy, address spread, address allocation, uint256 amount, uint256 currentAssets
    ) external view {
        if (strategy == spread || strategy == allocation) {
            uint256 paxgValue = spread != address(0) ? IGoldAdapter(spread).currentValue() : 0;
            uint256 xautValue = allocation != address(0) && allocation != spread
                ? IGoldAdapter(allocation).currentValue() : 0;
            uint256 combined = paxgValue + xautValue + amount;
            uint256 goldCap = (currentAssets * 3000) / 10_000;
            if (combined > goldCap) revert ShariahVault.GoldCapExceeded(combined, goldCap);
        }
    }

    function goldWritedown(
        mapping(address => uint256) storage principalOf, address spread, address allocation
    ) external view returns (uint256 writedown) {
        if (spread != address(0)) {
            uint256 value = IGoldAdapter(spread).currentValue();
            uint256 principal = principalOf[spread];
            if (principal > value) writedown = principal - value;
        }
        if (allocation != address(0) && allocation != spread) {
            uint256 value = IGoldAdapter(allocation).currentValue();
            uint256 principal = principalOf[allocation];
            if (principal > value) writedown += principal - value;
        }
    }

    function goldUnrealizedGain(
        mapping(address => uint256) storage principalOf, address spread, address allocation
    ) external view returns (uint256 gain) {
        if (spread != address(0)) {
            uint256 value = IGoldAdapter(spread).currentValue();
            uint256 principal = principalOf[spread];
            if (value > principal) gain = value - principal;
        }
        if (allocation != address(0) && allocation != spread) {
            uint256 value = IGoldAdapter(allocation).currentValue();
            uint256 principal = principalOf[allocation];
            if (value > principal) gain += value - principal;
        }
    }
}

contracts/ShariahVaultV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ShariahVault} from "./ShariahVault.sol";
import {ShariahAdapterRegistry} from "./ShariahAdapterRegistry.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title  ShariahVaultV2
 * @notice V2 extension of ShariahVault that delegates adapter screening to
 *         ShariahAdapterRegistry rather than a simple `screened[addr]` mapping.
 *
 * ## Changes from V1
 * 1. `deployCapital` now checks `registry.isScreened(strategy)` which verifies:
 *    - `pronouncementHash != bytes32(0)` (board resolution recorded on-chain)
 *    - `block.timestamp < expiresAt` (screening has not expired)
 * 2. The legacy `screened` mapping in ShariahVault is retained for backward
 *    compatibility (V1 operators can still call V1 methods on the V1 vault).
 *    V2 ignores `screened` and always uses the registry.
 * 3. Registry changes require current-board approval and a 30-day timelock.
 *
 * ## Migration
 * V1 vault deposits and redemptions are always available at NAV (no forced
 * migration). V2 is a new deployment; depositors migrate voluntarily.
 * See docs/migration-v1-to-v2.md.
 *
 * ## Task E checklist
 * - deployCapital reverts NotScreened when pronouncementHash == 0   ✓
 * - deployCapital reverts when block.timestamp >= expiresAt           ✓
 * - non-boardRole cannot call setScreening (uses registry — onlyOwner) ✓
 * - ShariahAdapterRegistry enforces 30-day timelock on all changes    ✓
 * - V1 vault stays live; this is a new deployment, not an upgrade     ✓
 */
contract ShariahVaultV2 is ShariahVault {
    using SafeERC20 for IERC20;

    // ─────────────────────────────────────────────────────────────
    // Errors
    // ─────────────────────────────────────────────────────────────

    /// @notice Thrown when the strategy adapter is not in the registry OR
    ///         its screening has expired.
    error NotScreened(address adapter);

    /// @notice Thrown when trying to deploy to a strategy whose board screening
    ///         has passed its expiresAt timestamp.
    error ScreeningExpired(address adapter, uint256 expiresAt);
    error ZeroRegistry();
    error NoPendingRegistryProposal();
    error RegistryProposalAlreadyExists();
    error RegistryTimelockNotElapsed(uint256 earliest, uint256 current);

    // ─────────────────────────────────────────────────────────────
    // Events
    // ─────────────────────────────────────────────────────────────

    event RegistryUpdated(address indexed registry);
    event RegistryProposed(address newRegistry, uint256 executeAfter);
    event RegistryProposalCancelled();

    // ─────────────────────────────────────────────────────────────
    // Storage
    // ─────────────────────────────────────────────────────────────

    /// @notice Governance-gated adapter registry.
    ShariahAdapterRegistry public registry;

    uint256 public constant REGISTRY_TIMELOCK = 30 days;

    struct PendingRegistry {
        address newRegistry;
        uint256 executeAfter;
        bool exists;
    }
    PendingRegistry public pendingRegistry;

    // ─────────────────────────────────────────────────────────────
    // Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        IERC20 asset_,
        address initialOwner,
        uint32 sourceDomain_,
        address shariahTreasury_,
        address zakatModule_,
        address registry_
    ) ShariahVault(asset_, initialOwner, sourceDomain_, shariahTreasury_, zakatModule_) {
        registry = ShariahAdapterRegistry(registry_);
    }

    // ─────────────────────────────────────────────────────────────
    // ERC-20 overrides (distinct symbol/name from V1)
    // ─────────────────────────────────────────────────────────────

    function name() public pure virtual override returns (string memory) {
        return "Shariah Vault V2 Share";
    }

    function symbol() public pure virtual override returns (string memory) {
        return "svUSDCv2";
    }

    // ─────────────────────────────────────────────────────────────
    // deployCapital — V2 registry check
    // ─────────────────────────────────────────────────────────────

    /// @dev Transfer-only deployment inherits the nonzero gold-adapter guard from V1.
    ///      Both inherited deployment entry points route here. Registry errors retain
    ///      precedence over pause/asset errors, independently of the legacy screening flag.
    function _checkDeploymentScreening(address strategy) internal view virtual override {
        ShariahAdapterRegistry.Screening memory s = registry.getScreening(strategy);
        if (s.pronouncementHash == bytes32(0)) revert NotScreened(strategy);
        if (block.timestamp >= s.expiresAt) revert ScreeningExpired(strategy, s.expiresAt);
        if (paused) revert Paused();
        if (!permittedAssets[asset()]) revert AssetNotPermitted(asset());
    }

    // ─────────────────────────────────────────────────────────────
    // Registry management
    // ─────────────────────────────────────────────────────────────

    function _isBoard(address account) internal view override returns (bool) {
        return address(registry) != address(0) && registry.isBoard(account);
    }

    /// @dev Always authorizes against the current registry, never the proposed registry.
    ///      Testnet/bootstrap only: while the current registry is zero, only the owner
    ///      may propose, confirm or cancel, without a board check.
    modifier onlyRegistryGovernance() {
        if (address(registry) == address(0)) {
            _checkOwner();
        } else if (!_isBoard(msg.sender)) {
            revert NotBoardRole(msg.sender);
        }
        _;
    }

    /// @notice Current board proposes a nonzero registry with a 30-day delay.
    /// @dev Testnet/bootstrap only: a zero current registry permits owner proposal
    ///      and immediate confirmation without a board check or delay.
    function proposeRegistry(address registry_) external onlyRegistryGovernance {
        ShariahRegistryLogic.propose(pendingRegistry, address(registry), registry_);
    }

    /// @notice Current board confirms after the delay and clears any pending dust proposal.
    /// @dev Testnet/bootstrap only: if the current registry is zero, the owner may
    ///      confirm immediately without a board check.
    function confirmRegistry() external onlyRegistryGovernance {
        address updated = ShariahRegistryLogic.confirm(pendingRegistry, pendingDustThreshold);
        registry = ShariahAdapterRegistry(updated);
        emit RegistryUpdated(updated);
    }

    /// @notice Current board cancels a pending registry proposal without waiting.
    /// @dev Testnet/bootstrap only: with a zero current registry, only the owner may cancel.
    function cancelRegistry() external onlyRegistryGovernance {
        ShariahRegistryLogic.cancel(pendingRegistry);
    }
}

/// @dev Minimal interface to read currentValue() from a gold adapter (duplicated to avoid
///      import order issues with ShariahVault's IGoldAdapter).
interface IGoldAdapterV2 {
    function currentValue() external view returns (uint256);
}

/// @dev Linked registry proposal storage operations; current-registry authorization stays on V2.
library ShariahRegistryLogic {
    function propose(
        ShariahVaultV2.PendingRegistry storage pending, address currentRegistry, address proposed
    ) external {
        if (proposed == address(0)) revert ShariahVaultV2.ZeroRegistry();
        if (pending.exists) revert ShariahVaultV2.RegistryProposalAlreadyExists();
        uint256 executeAfter = currentRegistry == address(0)
            ? block.timestamp : block.timestamp + 30 days;
        pending.newRegistry = proposed;
        pending.executeAfter = executeAfter;
        pending.exists = true;
        emit ShariahVaultV2.RegistryProposed(proposed, executeAfter);
    }

    function confirm(
        ShariahVaultV2.PendingRegistry storage pending,
        ShariahVault.PendingDustThreshold storage dust
    ) external returns (address updated) {
        ShariahVaultV2.PendingRegistry memory p = pending;
        if (!p.exists) revert ShariahVaultV2.NoPendingRegistryProposal();
        if (block.timestamp < p.executeAfter) {
            revert ShariahVaultV2.RegistryTimelockNotElapsed(p.executeAfter, block.timestamp);
        }
        delete pending.newRegistry;
        delete pending.executeAfter;
        delete pending.exists;
        if (dust.exists) {
            delete dust.newValue;
            delete dust.executeAfter;
            delete dust.exists;
            emit ShariahVault.DustThresholdProposalCancelled();
        }
        return p.newRegistry;
    }

    function cancel(ShariahVaultV2.PendingRegistry storage pending) external {
        if (!pending.exists) revert ShariahVaultV2.NoPendingRegistryProposal();
        delete pending.newRegistry;
        delete pending.executeAfter;
        delete pending.exists;
        emit ShariahVaultV2.RegistryProposalCancelled();
    }
}

