// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @dev DEPRECATED — superseded by CharityModule + PurificationEscrow (Task B).
 *
 *      ZakatModule remains deployed and functional so that v1 vault history and
 *      existing on-chain recordings are preserved. New ShariahVault deployments
 *      MUST use CharityModule + PurificationEscrow instead.
 *
 *      ZakatModule MUST NOT be used as the primary profit-routing mechanism in any
 *      new vault deployment. See SHARIAH_REVIEW.md SR-002 / SR-003 / SR-004 for the
 *      board rulings required before CharityModule goes live.
 *
 *      "Zakat" is a specific religious obligation (2.5% of annual nisab-exceeding
 *      wealth). This contract calculates and routes a fixed 2.5% of Musharakah
 *      gross profit, which may not satisfy the legal definition of Zakat without
 *      a formal board pronouncement. CharityModule uses the term "sadaqah" instead.
 */
contract ZakatModule is Ownable2Step {
    using SafeERC20 for IERC20;

    error NotVault();
    error TimelockNotElapsed(uint256 remaining);
    error NoPendingChange();
    error ZeroWallet();
    error ZeroAmount();

    event ZakatDistributed(uint256 amount, address indexed zakatWallet, uint256 timestamp);
    event ZakatWalletChangeProposed(address indexed proposed, uint256 executeAfter);
    event ZakatWalletConfirmed(address indexed previous, address indexed confirmed);
    event ZakatWalletChangeCancelled(address indexed cancelled);

    address public zakatWallet;
    address public pendingZakatWallet;
    uint256 public walletChangeRequestTime;

    uint256 public constant TIMELOCK_PERIOD = 30 days;
    uint256 public constant ZAKAT_BPS = 250;

    uint256 public totalZakatDistributed;
    address public immutable asset;
    address public immutable vault;

    constructor(address zakatWallet_, address asset_, address vault_, address initialOwner) Ownable(initialOwner) {
        if (zakatWallet_ == address(0)) revert ZeroWallet();

        zakatWallet = zakatWallet_;
        asset = asset_;
        vault = vault_;
    }

    function distributeZakat(uint256 grossProfit) external returns (uint256 zakatAmount, uint256 remaining) {
        if (msg.sender != vault) revert NotVault();
        if (grossProfit == 0) revert ZeroAmount();

        zakatAmount = (grossProfit * ZAKAT_BPS) / 10_000;
        remaining = grossProfit - zakatAmount;

        IERC20(asset).safeTransferFrom(vault, zakatWallet, zakatAmount);

        totalZakatDistributed += zakatAmount;
        emit ZakatDistributed(zakatAmount, zakatWallet, block.timestamp);
    }

    function proposeZakatWalletChange(address newWallet) external onlyOwner {
        if (newWallet == address(0)) revert ZeroWallet();

        pendingZakatWallet = newWallet;
        walletChangeRequestTime = block.timestamp;

        emit ZakatWalletChangeProposed(newWallet, block.timestamp + TIMELOCK_PERIOD);
    }

    function confirmZakatWalletChange() external onlyOwner {
        address proposed = pendingZakatWallet;
        if (proposed == address(0)) revert NoPendingChange();

        uint256 executeAfter = walletChangeRequestTime + TIMELOCK_PERIOD;
        if (block.timestamp < executeAfter) {
            revert TimelockNotElapsed(executeAfter - block.timestamp);
        }

        address previous = zakatWallet;
        zakatWallet = proposed;
        pendingZakatWallet = address(0);
        walletChangeRequestTime = 0;

        emit ZakatWalletConfirmed(previous, zakatWallet);
    }

    function cancelZakatWalletChange() external onlyOwner {
        address proposed = pendingZakatWallet;
        if (proposed == address(0)) revert NoPendingChange();

        emit ZakatWalletChangeCancelled(proposed);

        pendingZakatWallet = address(0);
        walletChangeRequestTime = 0;
    }
}

contracts/adapters/AaveLoopAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IAavePool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;
    function borrow(address asset, uint256 amount, uint256 interestRateMode, uint16 referralCode, address onBehalfOf) external;
    function repay(address asset, uint256 amount, uint256 interestRateMode, address onBehalfOf) external returns (uint256);
    function withdraw(address asset, uint256 amount, address to) external returns (uint256);
    function getUserAccountData(address user)
        external
        view
        returns (
            uint256 totalCollateralBase,
            uint256 totalDebtBase,
            uint256 availableBorrowsBase,
            uint256 currentLiquidationThreshold,
            uint256 ltv,
            uint256 healthFactor
        );
}

interface IAToken {
    function balanceOf(address account) external view returns (uint256);
}

contract AaveLoopAdapter is IStrategyAdapter, Ownable2Step {
    using SafeERC20 for IERC20;

    error OnlyVault();
    error HealthFactorTooLow(uint256 hf);

    event LoopDeployed(uint256 principal, uint256 borrowed);
    event LoopRecalled(uint256 amount, uint256 repaid);

    address public immutable aavePool;
    address public immutable aToken;
    address public immutable usdc;
    address public immutable override vault;

    uint256 public totalDeployed;
    uint256 public totalBorrowed;

    uint256 public constant LOOP_BORROW_BPS = 5000;
    uint256 public constant MIN_HEALTH_FACTOR = 1.5e18;

    constructor(address aavePool_, address aToken_, address usdc_, address vault_, address owner_) Ownable(owner_) {
        aavePool = aavePool_;
        aToken = aToken_;
        usdc = usdc_;
        vault = vault_;
    }

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    function deploy(uint256 amount) external onlyVault returns (uint256 deployed) {
        // First supply — approve aavePool to pull USDC from this adapter
        IERC20(usdc).forceApprove(aavePool, amount);
        IAavePool(aavePool).supply(usdc, amount, address(this), 0);
        IERC20(usdc).forceApprove(aavePool, 0);

        // Borrow 50% of principal at variable rate (mode=2)
        uint256 loop1 = (amount * LOOP_BORROW_BPS) / 10_000;
        IAavePool(aavePool).borrow(usdc, loop1, 2, 0, address(this));

        // Health-factor check BEFORE second supply to catch unsafe state early
        (, , , , , uint256 healthFactor) = IAavePool(aavePool).getUserAccountData(address(this));
        if (healthFactor < MIN_HEALTH_FACTOR) revert HealthFactorTooLow(healthFactor);

        // Second supply with borrowed amount
        IERC20(usdc).forceApprove(aavePool, loop1);
        IAavePool(aavePool).supply(usdc, loop1, address(this), 0);
        IERC20(usdc).forceApprove(aavePool, 0);

        totalDeployed += amount;
        totalBorrowed += loop1;

        emit LoopDeployed(amount, loop1);
        return amount;
    }

    function recall(uint256 amount) external onlyVault returns (uint256 returned) {
        if (totalDeployed == 0) return 0;

        // Proportional unwind: repay borrow first, then withdraw collateral
        // Use live aToken balance to avoid stale-counter drift from interest accrual
        uint256 aTokenBal = IAToken(aToken).balanceOf(address(this));
        if (aTokenBal == 0) return 0;

        // Proportion of position to unwind (capped at 100%)
        uint256 proportion = amount >= totalDeployed ? 1e18 : (amount * 1e18) / totalDeployed;

        // Repay proportional borrow first (repay before withdraw to keep HF safe)
        uint256 repayAmt = (totalBorrowed * proportion) / 1e18;
        if (repayAmt > 0) {
            // Withdraw just enough to cover repayment from aToken collateral
            IAavePool(aavePool).withdraw(usdc, repayAmt, address(this));
            IERC20(usdc).forceApprove(aavePool, repayAmt);
            uint256 repaid = IAavePool(aavePool).repay(usdc, repayAmt, 2, address(this));
            IERC20(usdc).forceApprove(aavePool, 0);
            if (repaid >= totalBorrowed) {
                totalBorrowed = 0;
            } else {
                totalBorrowed -= repaid;
            }
        }

        // Withdraw the principal portion to vault
        uint256 withdrawPrincipal = amount >= totalDeployed ? type(uint256).max : amount;
        uint256 actualOut = IAavePool(aavePool).withdraw(usdc, withdrawPrincipal, vault);

        if (amount >= totalDeployed) {
            totalDeployed = 0;
        } else {
            totalDeployed -= actualOut;
        }

        emit LoopRecalled(actualOut, repayAmt);
        return actualOut;
    }

    function currentValue() external view returns (uint256) {
        uint256 aTokenBal = IAToken(aToken).balanceOf(address(this));
        if (totalBorrowed > aTokenBal) {
            return 0;
        }

        return aTokenBal - totalBorrowed;
    }

    function protocolName() external pure returns (string memory) {
        return "Aave V3 2x Loop";
    }
}

contracts/adapters/CommodityMurabahaAdap.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract CommodityMurabahaAdapter is IStrategyAdapter, Ownable2Step {
    using SafeERC20 for IERC20;

    enum TradeStatus {
        PENDING,
        EXECUTED,
        SETTLED,
        EXPIRED
    }

    struct MurabahaTrade {
        uint256 id;
        address buyer;
        uint256 costAmount;
        uint256 markupBps;
        uint256 salePrice;
        uint256 requestTime;
        uint256 executeTime;
        uint256 settleTime;
        uint256 deadline;
        TradeStatus status;
    }

    error OnlyVault();
    error OnlyVaultOrOwner();
    error TradeNotFound();
    error InvalidTradeStatus(TradeStatus current, TradeStatus expected);
    error BuyerOnly();
    error DeadlinePassed();
    error InvalidMarkup();
    error InvalidAmount();

    event Deployed(uint256 amount);
    event Recalled(uint256 amount);

    event MurabahaRequested(
        uint256 indexed id,
        address indexed buyer,
        uint256 costAmount,
        uint256 markupBps,
        uint256 salePrice,
        uint256 deadline
    );
    event MurabahaExecuted(uint256 indexed id, uint256 executeTime);
    event MurabahaSettled(uint256 indexed id, uint256 profit, uint256 settleTime);
    event MurabahaExpired(uint256 indexed id);

    address public immutable usdc;
    address public immutable override vault;

    uint256 public tradeCount;
    mapping(uint256 => MurabahaTrade) public trades;
    uint256[] public activeTrades;
    /// @dev tradeId => 1-based index in activeTrades (0 = not in array). Enables O(1) removal.
    mapping(uint256 => uint256) private _activeTradeIndex;
    uint256 public totalDeployed;
    uint256 public totalProfitRealized;
    /// @dev Rate-limit: max active trades at once to prevent unbounded array DoS
    uint256 public constant MAX_ACTIVE_TRADES = 50;

    constructor(address usdc_, address vault_, address owner_) Ownable(owner_) {
        usdc = usdc_;
        vault = vault_;
    }

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    modifier onlyVaultOrOwner() {
        if (msg.sender != vault && msg.sender != owner()) revert OnlyVaultOrOwner();
        _;
    }

    function requestMurabaha(address buyer, uint256 amount, uint256 markupBps, uint256 settlementWindow)
        external
        returns (uint256 tradeId)
    {
        if (markupBps == 0 || markupBps > 5000) revert InvalidMarkup();
        if (amount == 0) revert InvalidAmount();
        if (activeTrades.length >= MAX_ACTIVE_TRADES) revert InvalidAmount(); // DoS guard

        uint256 salePrice = amount + ((amount * markupBps) / 10_000);

        tradeId = ++tradeCount;
        uint256 deadline = block.timestamp + settlementWindow;

        trades[tradeId] = MurabahaTrade({
            id: tradeId,
            buyer: buyer,
            costAmount: amount,
            markupBps: markupBps,
            salePrice: salePrice,
            requestTime: block.timestamp,
            executeTime: 0,
            settleTime: 0,
            deadline: deadline,
            status: TradeStatus.PENDING
        });

        activeTrades.push(tradeId);
        _activeTradeIndex[tradeId] = activeTrades.length; // 1-based

        emit MurabahaRequested(tradeId, buyer, amount, markupBps, salePrice, deadline);
    }

    function executeMurabaha(uint256 tradeId) external onlyVaultOrOwner {
        MurabahaTrade storage trade = _loadTrade(tradeId);
        if (trade.status != TradeStatus.PENDING) revert InvalidTradeStatus(trade.status, TradeStatus.PENDING);
        if (block.timestamp > trade.deadline) revert DeadlinePassed();

        trade.status = TradeStatus.EXECUTED;
        trade.executeTime = block.timestamp;

        totalDeployed += trade.costAmount;

        emit MurabahaExecuted(tradeId, block.timestamp);
    }

    function settleMurabaha(uint256 tradeId) external {
        MurabahaTrade storage trade = _loadTrade(tradeId);
        if (trade.status != TradeStatus.EXECUTED) revert InvalidTradeStatus(trade.status, TradeStatus.EXECUTED);
        if (msg.sender != trade.buyer) revert BuyerOnly();
        if (block.timestamp > trade.deadline) revert DeadlinePassed();

        IERC20(usdc).safeTransferFrom(msg.sender, vault, trade.salePrice);

        trade.status = TradeStatus.SETTLED;
        trade.settleTime = block.timestamp;

        uint256 profit = trade.salePrice - trade.costAmount;
        totalProfitRealized += profit;

        if (trade.costAmount >= totalDeployed) {
            totalDeployed = 0;
        } else {
            totalDeployed -= trade.costAmount;
        }

        _removeActiveTrade(tradeId);

        emit MurabahaSettled(tradeId, profit, block.timestamp);
    }

    function expireTrade(uint256 tradeId) external onlyVaultOrOwner {
        MurabahaTrade storage trade = _loadTrade(tradeId);
        TradeStatus current = trade.status;
        bool valid = current == TradeStatus.PENDING || current == TradeStatus.EXECUTED;
        if (!valid) revert InvalidTradeStatus(current, TradeStatus.PENDING);
        if (block.timestamp <= trade.deadline) revert DeadlinePassed();

        trade.status = TradeStatus.EXPIRED;

        if (current == TradeStatus.EXECUTED) {
            if (trade.costAmount >= totalDeployed) {
                totalDeployed = 0;
            } else {
                totalDeployed -= trade.costAmount;
            }
        }

        _removeActiveTrade(tradeId);

        emit MurabahaExpired(tradeId);
    }

    function deploy(uint256 amount) external onlyVault returns (uint256 deployed) {
        totalDeployed += amount;
        emit Deployed(amount);
        return amount;
    }

    function recall(uint256 amount) external onlyVault returns (uint256 returned) {
        IERC20(usdc).safeTransfer(vault, amount);

        if (amount >= totalDeployed) {
            totalDeployed = 0;
        } else {
            totalDeployed -= amount;
        }

        emit Recalled(amount);
        return amount;
    }

    function currentValue() external view returns (uint256) {
        return totalDeployed + IERC20(usdc).balanceOf(address(this));
    }

    function protocolName() external pure returns (string memory) {
        return "Commodity Murabaha";
    }

    function getActiveTrades() external view returns (MurabahaTrade[] memory list) {
        uint256 length = activeTrades.length;
        list = new MurabahaTrade[](length);
        for (uint256 i = 0; i < length; i++) {
            list[i] = trades[activeTrades[i]];
        }
    }

    function getPendingTradeCount() external view returns (uint256 count) {
        uint256 length = activeTrades.length;
        for (uint256 i = 0; i < length; i++) {
            if (trades[activeTrades[i]].status == TradeStatus.PENDING) {
                count++;
            }
        }
    }

    function _loadTrade(uint256 tradeId) internal view returns (MurabahaTrade storage trade) {
        trade = trades[tradeId];
        if (trade.id == 0) revert TradeNotFound();
    }

    /// @dev O(1) removal using stored 1-based index mapping. No linear scan.
    function _removeActiveTrade(uint256 tradeId) internal {
        uint256 idx1 = _activeTradeIndex[tradeId]; // 1-based
        if (idx1 == 0) return; // not in active array

        uint256 idx0 = idx1 - 1;
        uint256 lastId = activeTrades[activeTrades.length - 1];

        activeTrades[idx0] = lastId;
        _activeTradeIndex[lastId] = idx1; // update moved element's index
        activeTrades.pop();
        delete _activeTradeIndex[tradeId];
    }
}

