// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IGlpManager {
    function addLiquidity(address token, uint256 amount, uint256 minUsdg, uint256 minGlp) external returns (uint256);
    function removeLiquidity(address tokenOut, uint256 glpAmount, uint256 minOut, address receiver)
        external
        returns (uint256);
}

interface IGLP {
    function balanceOf(address account) external view returns (uint256);
}

contract GmxAdapter is IStrategyAdapter, Ownable2Step {
    using SafeERC20 for IERC20;

    error OnlyVault();
    error InsufficientGlp();

    event Deployed(uint256 amount);
    event Recalled(uint256 received);

    address public immutable glpManager;
    address public immutable glpToken;
    address public immutable usdc;
    address public immutable override vault;

    uint256 public totalDeployed;

    constructor(address glpManager_, address glpToken_, address usdc_, address vault_, address owner_) Ownable(owner_) {
        glpManager = glpManager_;
        glpToken = glpToken_;
        usdc = usdc_;
        vault = vault_;
    }

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    function deploy(uint256 amount) external onlyVault returns (uint256 deployed) {
        IERC20(usdc).forceApprove(glpManager, amount);
        IGlpManager(glpManager).addLiquidity(usdc, amount, 0, 0);
        IERC20(usdc).forceApprove(glpManager, 0);

        totalDeployed += amount;

        emit Deployed(amount);
        return amount;
    }

    function recall(uint256 amount) external onlyVault returns (uint256 returned) {
        uint256 glpBal = IGLP(glpToken).balanceOf(address(this));

        uint256 glpToBurn = totalDeployed > 0 ? (glpBal * amount) / totalDeployed : glpBal;
        if (glpToBurn > glpBal) {
            glpToBurn = glpBal;
        }
        if (glpToBurn == 0) revert InsufficientGlp();

        // Use SafeERC20 forceApprove to handle non-standard GLP token approve return values
        IERC20(glpToken).forceApprove(glpManager, glpToBurn);
        uint256 received = IGlpManager(glpManager).removeLiquidity(usdc, glpToBurn, 0, vault);
        IERC20(glpToken).forceApprove(glpManager, 0);

        // Decrement by actual received (not requested) to track real capital
        if (received >= totalDeployed) {
            totalDeployed = 0;
        } else {
            totalDeployed -= received;
        }

        emit Recalled(received);
        return received;
    }

    function currentValue() external view returns (uint256) {
        uint256 glpBal = IGLP(glpToken).balanceOf(address(this));
        if (glpBal == 0) {
            return 0;
        }

        // NOTE: Simplified mark. Production should derive USDC value from
        // GlpManager.getAumInUsdg() / totalSupply * glpBal.
        return totalDeployed;
    }

    function protocolName() external pure returns (string memory) {
        return "GMX V2 GLP";
    }
}

contracts/adapters/GoldAllocationAdapter.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {AggregatorV3Interface} from "../interfaces/AggregatorV3Interface.sol";

/// @notice Uniswap V3 interface (minimal — only exactInputSingle needed)
interface ISwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external returns (uint256 amountOut);
}

/// @notice Minimal pool interface for reading slot0 sqrtPriceX96.
interface IUniswapV3PoolSlot0 {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );
}

contract GoldAllocationAdapter is IStrategyAdapter, Ownable2Step {
    using SafeERC20 for IERC20;

    error ZeroAmount();
    error StaleGoldPrice();
    error GoldPriceDeviation(uint256 poolPrice, uint256 oraclePrice, uint256 maxDeviationBps);
    error SlippageExceeded(uint256 amountOut, uint256 minOut);
    error ParamAboveHardCap(string param, uint256 value, uint256 cap);
    error TimelockNotElapsed(uint256 executeAfter, uint256 now_);
    error NoProposalPending();

    event GoldBought(uint256 usdcIn, uint256 xautOut, uint256 oraclePrice);
    event GoldSold(uint256 xautIn, uint256 usdcOut, uint256 oraclePrice);
    event ParamChangeProposed(bytes32 indexed paramId, uint256 newValue, uint256 executeAfter);
    event ParamChangeExecuted(bytes32 indexed paramId, uint256 newValue);
    /// @notice Emitted whenever lastGoodPrice is refreshed from the oracle.
    event LastGoodPriceUpdated(uint256 price, uint256 timestamp);

    uint256 public constant MAX_SLIPPAGE_BPS = 200;
    uint256 public constant MAX_DEVIATION_BPS = 300;
    uint256 public constant TIMELOCK_DELAY = 30 days;

    IERC20 public immutable usdc;
    IERC20 public immutable xaut;
    uint8 public immutable usdcDecimals;
    uint8 public immutable xautDecimals;
    /// @dev Mutable — updated atomically when goldOracle is changed via executeAddressParamChange.
    ///      Cannot be immutable because the oracle address itself is board-settable.
    uint8 public oracleDecimals;
    address public immutable vault;

    ISwapRouter public swapRouter;
    AggregatorV3Interface public goldOracle;
    uint24 public poolFee;
    uint256 public maxStalenessSecs;
    uint256 public maxSlippageBps;
    uint256 public maxDeviationBps;

    uint256 public xautHeld;
    uint256 public totalDeployed;

    /// @notice Last oracle price successfully validated (USDC per XAUT, usdc-decimal scaled).
    ///         Updated on every successful deploy(), recall(), and pokePrice() call.
    ///         Used as the conservative floor when the oracle goes stale (PR1).
    uint256 public lastGoodPrice;

    /// @notice Oracle observation timestamp of the last validated price.
    uint256 public lastGoodPriceAt;

    /// @notice Haircut applied to lastGoodPrice when oracle is stale (bps, default 500 = 5%).
    ///         Board-settable via the standard propose/execute timelock.
    ///         Hard cap: MAX_STALE_HAIRCUT_BPS = 2000.
    uint256 public staleHaircutBps;
    uint256 public emergencySlippageBps = 1000;
    uint256 public constant MAX_EMERGENCY_SLIPPAGE_BPS = 2500;
    bytes32 public constant PARAM_EMERGENCY_SLIPPAGE = keccak256("emergencySlippageBps");
    event EmergencySlippageBpsUpdated(uint256 previous, uint256 updated);
    event ParamChangeCancelled(bytes32 indexed paramId);

    /// @notice Hard cap for the stale-price haircut.
    uint256 public constant MAX_STALE_HAIRCUT_BPS = 2000;

    address public pool;

    struct PendingChange {
        uint256 newValue;
        uint256 executeAfter;
        bool pending;
    }

    struct PendingAddressChange {
        address newValue;
        uint256 executeAfter;
        bool pending;
    }

    mapping(bytes32 => PendingChange) public pendingChanges;
    mapping(bytes32 => PendingAddressChange) public pendingAddressChanges;

    bytes32 public constant PARAM_MAX_STALENESS   = keccak256("maxStalenessSecs");
    bytes32 public constant PARAM_MAX_SLIPPAGE    = keccak256("maxSlippageBps");
    bytes32 public constant PARAM_MAX_DEVIATION   = keccak256("maxDeviationBps");
    bytes32 public constant PARAM_POOL_FEE        = keccak256("poolFee");
    bytes32 public constant PARAM_SWAP_ROUTER     = keccak256("swapRouter");
    bytes32 public constant PARAM_GOLD_ORACLE     = keccak256("goldOracle");
    bytes32 public constant PARAM_STALE_HAIRCUT   = keccak256("staleHaircutBps");

    constructor(
        address usdc_,
        address xaut_,
        address swapRouter_,
        uint24 poolFee_,
        address goldOracle_,
        address vault_,
        uint256 initialMaxStalenessSecs,
        address initialOwner
    ) Ownable(initialOwner) {
        usdc = IERC20(usdc_);
        xaut = IERC20(xaut_);
        usdcDecimals = IERC20Metadata(usdc_).decimals();
        xautDecimals = IERC20Metadata(xaut_).decimals();
        oracleDecimals = AggregatorV3Interface(goldOracle_).decimals();

        swapRouter = ISwapRouter(swapRouter_);
        goldOracle = AggregatorV3Interface(goldOracle_);
        poolFee = poolFee_;
        vault = vault_;
        pool = swapRouter_;

        maxSlippageBps   = 50;
        maxDeviationBps  = 100;
        maxStalenessSecs = initialMaxStalenessSecs;
        staleHaircutBps  = 500; // 5% default haircut on stale-price valuation
    }

    modifier onlyVault() {
        require(msg.sender == vault, "GoldAllocationAdapter: caller is not vault");
        _;
    }

    function _pow10(uint8 d) internal pure returns (uint256) {
        return 10 ** uint256(d);
    }

    function _getOraclePrice() internal view returns (uint256 price, uint256 observedAt) {
        bool ok;
        (price, ok, observedAt) = _getOraclePriceSafe();
        if (!ok) revert StaleGoldPrice();
    }

    /// @notice Returns the validated price and observation timestamp, or ok=false.
    ///         Used by recall() so oracle failure does not block redemptions.
    function _getOraclePriceSafe() internal view returns (uint256 oraclePriceUsdc, bool ok, uint256 observedAt) {
        try goldOracle.latestRoundData() returns (
            uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound
        ) {
            if (startedAt == 0 || answeredInRound < roundId || answer <= 0) return (0, false, 0);
            if (updatedAt == 0 || updatedAt > block.timestamp) return (0, false, 0);
            if (block.timestamp - updatedAt > maxStalenessSecs) return (0, false, 0);
            // Normalize without an overflowing intermediate; malformed scales are invalid observations.
            if (oracleDecimals >= usdcDecimals) {
                uint8 shift = oracleDecimals - usdcDecimals;
                if (shift > 77) return (0, false, 0);
                oraclePriceUsdc = uint256(answer) / _pow10(shift);
            } else {
                uint8 shift = usdcDecimals - oracleDecimals;
                if (shift > 77) return (0, false, 0);
                uint256 scale = _pow10(shift);
                if (uint256(answer) > type(uint256).max / scale) return (0, false, 0);
                oraclePriceUsdc = uint256(answer) * scale;
            }
            ok = oraclePriceUsdc > 0;
            observedAt = updatedAt;
        } catch {
            return (0, false, 0);
        }
    }

    /// @dev USDC base units per whole XAUT; zero means unreadable or unrepresentable.
    ///      The external boundary also catches arithmetic failures for NAV reads.
    function _readPoolPrice() internal view returns (uint256 price) {
        try this.poolPriceUsdc() returns (uint256 value) {
            return value;
        } catch {
            return 0;
        }
    }

    /// @dev Read-only boundary for catching malformed pool responses and math failures.
    function poolPriceUsdc() external view returns (uint256) {
        address token0 = IUniswapV3PoolSlot0(pool).token0();
        address token1 = IUniswapV3PoolSlot0(pool).token1();
        bool xautFirst = token0 == address(xaut) && token1 == address(usdc);
        bool usdcFirst = token0 == address(usdc) && token1 == address(xaut);
        if (!xautFirst && !usdcFirst) return 0;
        (uint160 sqrtP,,,,,,) = IUniswapV3PoolSlot0(pool).slot0();
        if (sqrtP == 0) return 0;
        uint256 scale = _pow10(xautDecimals);
        if (xautFirst) {
            return Math.mulDiv(Math.mulDiv(sqrtP, sqrtP, 1 << 64), scale, 1 << 128);
        }
        return Math.mulDiv(Math.mulDiv(scale, 1 << 96, sqrtP), 1 << 96, sqrtP);
    }

    function _getPoolPrice(uint256 oraclePriceUsdc) internal view returns (uint256 poolPriceUsdc_) {
        poolPriceUsdc_ = _readPoolPrice();
        if (poolPriceUsdc_ == 0) {
            revert GoldPriceDeviation(poolPriceUsdc_, oraclePriceUsdc, maxDeviationBps);
        }
    }

    /// @dev Called after every successful oracle read to cache the last known good price.
    function _updateLastGoodPrice(uint256 price, uint256 observedAt) internal {
        lastGoodPrice   = price;
        lastGoodPriceAt = observedAt;
        emit LastGoodPriceUpdated(price, observedAt);
    }

    /// @notice Refresh the cache only from a fresh, complete oracle observation.
    function pokePrice() external {
        (uint256 oraclePrice, bool ok, uint256 observedAt) = _getOraclePriceSafe();
        if (!ok) return;
        _updateLastGoodPrice(oraclePrice, observedAt);
    }

    function isPriceSane() public view returns (bool) {
        try this._checkPriceSanity() {
            return true;
        } catch {
            return false;
        }
    }

    function _checkPriceSanity() external view {
        (uint256 oraclePrice,) = _getOraclePrice();
        uint256 poolPrice = _getPoolPrice(oraclePrice);
        uint256 diff = oraclePrice > poolPrice ? oraclePrice - poolPrice : poolPrice - oraclePrice;
        uint256 deviation = (diff * 10_000) / oraclePrice;
        if (deviation > maxDeviationBps) revert GoldPriceDeviation(poolPrice, oraclePrice, maxDeviationBps);
    }

    /// @notice Error emitted when a new deploy is attempted while the oracle is not sane.
    /// @dev    Deposits are blocked when price is stale/deviated; recalls remain open (G1).
    error OracleNotSane();

    function deploy(uint256 usdcAmount) external onlyVault returns (uint256 xautReceived) {
        if (usdcAmount == 0) revert ZeroAmount();
        // Block new gold buys when oracle is not sane (G1: deposits paused on insane price).
        if (!isPriceSane()) revert OracleNotSane();

        (uint256 oraclePrice, uint256 observedAt) = _getOraclePrice();
        uint256 poolPrice = _getPoolPrice(oraclePrice);

        uint256 diff = oraclePrice > poolPrice ? oraclePrice - poolPrice : poolPrice - oraclePrice;
        if ((diff * 10_000) / oraclePrice > maxDeviationBps) {
            revert GoldPriceDeviation(poolPrice, oraclePrice, maxDeviationBps);
        }

        uint256 expectedXautOut = (usdcAmount * _pow10(xautDecimals)) / oraclePrice;
        uint256 minOut = (expectedXautOut * (10_000 - maxSlippageBps)) / 10_000;
        if (minOut == 0) minOut = 1;

        usdc.forceApprove(address(swapRouter), usdcAmount);

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn: address(usdc),
            tokenOut: address(xaut),
            fee: poolFee,
            recipient: address(this),
            deadline: block.timestamp,
            amountIn: usdcAmount,
            amountOutMinimum: minOut,
            sqrtPriceLimitX96: 0
        });

        xautReceived = swapRouter.exactInputSingle(params);

        if (xautReceived < minOut) revert SlippageExceeded(xautReceived, minOut);

        usdc.forceApprove(address(swapRouter), 0);

        xautHeld += xautReceived;
        totalDeployed += usdcAmount;

        _updateLastGoodPrice(oraclePrice, observedAt);
        emit GoldBought(usdcAmount, xautReceived, oraclePrice);
    }

    /// @notice Sell all held XAUT back to USDC and return proceeds to vault.
    /// @dev Fresh oracle floors never depend on spot pool state. During outages,
    ///      cached price, stale haircut and emergency slippage bound the exit.
    function recall(uint256 usdcAmount) external onlyVault returns (uint256 usdcReturned) {
        if (usdcAmount == 0) revert ZeroAmount();
        if (xautHeld == 0) return 0;

        (uint256 oraclePrice, bool oracleOk, uint256 observedAt) = _getOraclePriceSafe();

        uint256 xautToSell = xautHeld;
        uint256 minUsdcOut;

        if (oracleOk) {
            _updateLastGoodPrice(oraclePrice, observedAt);
            uint256 expectedOut = Math.mulDiv(xautToSell, oraclePrice, _pow10(xautDecimals));
            minUsdcOut = Math.mulDiv(expectedOut, 10_000 - maxSlippageBps, 10_000);
        } else {
            if (lastGoodPrice == 0) revert StaleGoldPrice();
            uint256 expectedOut = Math.mulDiv(xautToSell, lastGoodPrice, _pow10(xautDecimals));
            uint256 haircutValue = Math.mulDiv(expectedOut, 10_000 - staleHaircutBps, 10_000);
            minUsdcOut = Math.mulDiv(haircutValue, 10_000 - emergencySlippageBps, 10_000);
        }

        if (minUsdcOut == 0) minUsdcOut = 1;

        xaut.forceApprove(address(swapRouter), xautToSell);

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn: address(xaut),
            tokenOut: address(usdc),
            fee: poolFee,
            recipient: vault,
            deadline: block.timestamp,
            amountIn: xautToSell,
            amountOutMinimum: minUsdcOut,
            sqrtPriceLimitX96: 0
        });

        usdcReturned = swapRouter.exactInputSingle(params);

        if (usdcReturned < minUsdcOut) revert SlippageExceeded(usdcReturned, minUsdcOut);

        xaut.forceApprove(address(swapRouter), 0);

        xautHeld = 0;
        totalDeployed = 0;

        emit GoldSold(xautToSell, usdcReturned, oraclePrice);
    }

    /// @notice Oracle-only position value; stale/invalid observations use the cached price with haircut.
    /// @dev Pool spot is reserved for execution sanity, never NAV. Read/math failures return zero.
    function currentValue() external view returns (uint256) {
        try this.positionValueUsdc() returns (uint256 value) {
            return value;
        } catch {
            return 0;
        }
    }

    /// @dev Read-only boundary so malformed observations and unrepresentable values cannot revert NAV reads.
    function positionValueUsdc() external view returns (uint256) {
        if (xautHeld == 0) return 0;
        (uint256 oraclePrice, bool oracleOk,) = _getOraclePriceSafe();
        if (oracleOk) return Math.mulDiv(xautHeld, oraclePrice, _pow10(xautDecimals));
        if (lastGoodPrice == 0) return 0;
        uint256 grossValue = Math.mulDiv(xautHeld, lastGoodPrice, _pow10(xautDecimals));
        return Math.mulDiv(grossValue, 10_000 - staleHaircutBps, 10_000);
    }

    function isGoldStrategy() external pure returns (bool) {
        return true;
    }

    function protocolName() external pure returns (string memory) {
        return "GoldAllocationAdapter: USDC/XAUT spot allocation (S6-H, yad bi yad, board-pending SR-008)";
    }

    function proposeParamChange(bytes32 paramId, uint256 newValue) external onlyOwner {
        if (paramId == PARAM_MAX_SLIPPAGE && newValue > MAX_SLIPPAGE_BPS) {
            revert ParamAboveHardCap("maxSlippageBps", newValue, MAX_SLIPPAGE_BPS);
        }

        if (paramId == PARAM_MAX_DEVIATION && newValue > MAX_DEVIATION_BPS) {
            revert ParamAboveHardCap("maxDeviationBps", newValue, MAX_DEVIATION_BPS);
        }

        if (paramId == PARAM_MAX_STALENESS && newValue == 0) {
            revert ParamAboveHardCap("maxStalenessSecs", newValue, 0);
        }

        if (paramId == PARAM_POOL_FEE && newValue > type(uint24).max) {
            revert ParamAboveHardCap("poolFee", newValue, type(uint24).max);
        }

        if (paramId == PARAM_STALE_HAIRCUT && newValue > MAX_STALE_HAIRCUT_BPS) {
            revert ParamAboveHardCap("staleHaircutBps", newValue, MAX_STALE_HAIRCUT_BPS);
        }

        if (paramId == PARAM_EMERGENCY_SLIPPAGE && newValue > MAX_EMERGENCY_SLIPPAGE_BPS) {
            revert ParamAboveHardCap("emergencySlippageBps", newValue, MAX_EMERGENCY_SLIPPAGE_BPS);
        }

        uint256 executeAfter = block.timestamp + TIMELOCK_DELAY;
        pendingChanges[paramId] = PendingChange({newValue: newValue, executeAfter: executeAfter, pending: true});

        emit ParamChangeProposed(paramId, newValue, executeAfter);
    }

    function executeParamChange(bytes32 paramId) external onlyOwner {
        PendingChange memory pc = pendingChanges[paramId];
        if (!pc.pending) revert NoProposalPending();
        if (block.timestamp < pc.executeAfter) revert TimelockNotElapsed(pc.executeAfter, block.timestamp);

        delete pendingChanges[paramId];

        if (paramId == PARAM_MAX_STALENESS) maxStalenessSecs = pc.newValue;
        else if (paramId == PARAM_MAX_SLIPPAGE) maxSlippageBps = pc.newValue;
        else if (paramId == PARAM_MAX_DEVIATION) maxDeviationBps = pc.newValue;
        else if (paramId == PARAM_POOL_FEE) poolFee = uint24(pc.newValue);
        else if (paramId == PARAM_STALE_HAIRCUT) staleHaircutBps = pc.newValue;
        else if (paramId == PARAM_EMERGENCY_SLIPPAGE) {
            uint256 previous = emergencySlippageBps;
            emergencySlippageBps = pc.newValue;
            emit EmergencySlippageBpsUpdated(previous, pc.newValue);
        }

        emit ParamChangeExecuted(paramId, pc.newValue);
    }

    function cancelParamChange(bytes32 paramId) external onlyOwner {
        if (!pendingChanges[paramId].pending) revert NoProposalPending();
        delete pendingChanges[paramId];
        emit ParamChangeCancelled(paramId);
    }

    function proposeAddressParamChange(bytes32 paramId, address newValue) external onlyOwner {
        uint256 executeAfter = block.timestamp + TIMELOCK_DELAY;
        pendingAddressChanges[paramId] = PendingAddressChange({newValue: newValue, executeAfter: executeAfter, pending: true});

        emit ParamChangeProposed(paramId, uint256(uint160(newValue)), executeAfter);
    }

    function executeAddressParamChange(bytes32 paramId) external onlyOwner {
        PendingAddressChange memory pc = pendingAddressChanges[paramId];
        if (!pc.pending) revert NoProposalPending();
        if (block.timestamp < pc.executeAfter) revert TimelockNotElapsed(pc.executeAfter, block.timestamp);

        delete pendingAddressChanges[paramId];

        if (paramId == PARAM_SWAP_ROUTER) {
            swapRouter = ISwapRouter(pc.newValue);
        } else if (paramId == PARAM_GOLD_ORACLE) {
            goldOracle = AggregatorV3Interface(pc.newValue);
            // Update cached decimals atomically to avoid price mispricing with new oracle.
            oracleDecimals = AggregatorV3Interface(pc.newValue).decimals();
        }

        emit ParamChangeExecuted(paramId, uint256(uint160(pc.newValue)));
    }

    event PoolProposed(address indexed proposed, uint256 executeAfter);
    event PoolExecuted(address indexed previous, address indexed updated);
    event PoolProposalCancelled();

    PendingAddressChange public pendingPool;

    /// @dev Retained ABI: this setter now proposes rather than immediately updating.
    function setPool(address pool_) external onlyOwner {
        _proposePool(pool_);
    }

    function proposePool(address pool_) external onlyOwner {
        _proposePool(pool_);
    }

    function _proposePool(address pool_) internal {
        uint256 executeAfter = block.timestamp + TIMELOCK_DELAY;
        pendingPool = PendingAddressChange({newValue: pool_, executeAfter: executeAfter, pending: true});
        emit PoolProposed(pool_, executeAfter);
    }

    function executePool() external onlyOwner {
        PendingAddressChange memory pc = pendingPool;
        if (!pc.pending) revert NoProposalPending();
        if (block.timestamp < pc.executeAfter) revert TimelockNotElapsed(pc.executeAfter, block.timestamp);
        delete pendingPool;
        address previous = pool;
        pool = pc.newValue;
        emit PoolExecuted(previous, pc.newValue);
    }

    function cancelPool() external onlyOwner {
        if (!pendingPool.pending) revert NoProposalPending();
        delete pendingPool;
        emit PoolProposalCancelled();
    }

    /// @dev renounceOwnership disabled — owner controls gold capital allocation.
    function renounceOwnership() public override(Ownable) onlyOwner {
        revert("GoldAllocationAdapter: renouncing ownership is disabled");
    }
}

contracts/adapters/GoldExchangeAdapter.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";

/// @notice Minimal Chainlink-style oracle interface (same shape as AggregatorV3Interface).
interface IAggregatorV3 {
    function latestRoundData() external view returns (
        uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound
    );
    function decimals() external view returns (uint8);
}

/// @notice Uniswap V3 interface (minimal — only exactInputSingle needed)
interface ISwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }
    function exactInputSingle(ExactInputSingleParams calldata params)
        external returns (uint256 amountOut);
}

/// @title  GoldExchangeAdapter
/// @notice Deploys vault USDC into PAXG via an atomic Uniswap V3 swap on the same chain.
/// @dev    Shariah requirement: the exchange must be simultaneous (yad bi yad).
///         This adapter satisfies that by completing the USDC-to-PAXG conversion in
///         a SINGLE transaction with no pending state. Cross-chain routing for GOLD_SPREAD
///         is explicitly blocked via the `NonAtomicGoldExchange` error in ShariahVault.
///
///         Board ruling pending: SR-005 (atomic swap satisfies yad bi yad),
///         SR-006 (PAXG custody terms). See docs/agents/SHARIAH_REVIEW.md.
///
///         On testnet, deploy a MockAllocatedGold in place of PAXG.
///
/// @custom:security-contact board-review-required
contract GoldExchangeAdapter is IStrategyAdapter, Ownable2Step {
    using SafeERC20 for IERC20;

    error SlippageExceeded(uint256 amountOut, uint256 minOut);
    error ZeroAmount();
    error DeadlineExceeded();
    error StalePrice(uint256 paxgBalance, uint256 usdcSpent);
    /// @notice Thrown when the stale-haircut BPS exceeds the hard cap.
    error HaircutAboveCap(uint256 proposed, uint256 cap);
    /// @notice Thrown when the constructor is called without a non-zero gold oracle address (K2).
    error OracleRequired();
    error StaleGoldPrice();

    event GoldAcquired(uint256 usdcIn, uint256 paxgOut, uint256 spotPrice);
    event GoldReturned(uint256 paxgIn, uint256 usdcOut);
    event MinOutBpsUpdated(uint256 previousBps, uint256 newBps);
    /// @notice Emitted whenever lastGoodPrice is refreshed from an executed swap (PR1 parity).
    event LastGoodPriceUpdated(uint256 price, uint256 timestamp);
    event StaleHaircutBpsUpdated(uint256 previous, uint256 updated);
    event MaxStalenessBpsUpdated(uint256 previous, uint256 updated);
    event GoldOracleUpdated(address indexed previous, address indexed updated);

    IERC20  public immutable usdc;
    IERC20  public immutable paxg;
    ISwapRouter public immutable swapRouter;
    uint24  public immutable poolFee;
    address public immutable vault;

    uint256 public totalDeployed;
    uint256 public paxgHeld;

    /// @notice Minimum output as a fraction of expected PAXG out.
    ///         Default: 9900 = 99% (1% max slippage).
    uint256 public minOutBps;

    uint256 public emergencySlippageBps = 1000;
    uint256 public constant MAX_EMERGENCY_SLIPPAGE_BPS = 2500;
    uint256 public constant TIMELOCK_DELAY = 30 days;
    bytes32 public constant PARAM_EMERGENCY_SLIPPAGE = keccak256("emergencySlippageBps");

    struct PendingChange {
        uint256 newValue;
        uint256 executeAfter;
        bool pending;
    }
    mapping(bytes32 => PendingChange) public pendingChanges;

    event ParamChangeProposed(bytes32 indexed paramId, uint256 newValue, uint256 executeAfter);
    event ParamChangeExecuted(bytes32 indexed paramId, uint256 newValue);
    event ParamChangeCancelled(bytes32 indexed paramId);
    event EmergencySlippageBpsUpdated(uint256 previous, uint256 updated);

    // ── PR1 parity — stale-price valuation (I2) ─────────────────────────────
    /// @notice Last USDC-per-PAXG price recorded at swap execution (USDC units, 6 dec).
    ///         Equivalent to GoldAllocationAdapter.lastGoodPrice. Set on every deploy/recall.
    uint256 public lastGoodPrice;
    /// @notice Timestamp of the last executed swap (deploy or recall).
    uint256 public lastGoodPriceAt;
    /// @notice Haircut applied to lastGoodPrice when price is stale (bps, default 500 = 5%).
    ///         Settable by owner, hard cap MAX_STALE_HAIRCUT_BPS.
    uint256 public staleHaircutBps;
    /// @notice Hard cap for staleHaircutBps (matches GoldAllocationAdapter).
    uint256 public constant MAX_STALE_HAIRCUT_BPS = 2000;
    /// @notice Seconds after the last swap before isPriceSane() returns false.
    ///         Default: 1 day. Settable by owner. S2-H has no external oracle;
    ///         staleness is measured from the last executed trade.
    uint256 public maxStalenessSecs;
    /// @notice Hard cap for maxStalenessSecs: 7 days.
    uint256 public constant MAX_STALENESS_SECS = 7 days;

    /// @notice Mandatory XAU/USD Chainlink oracle (K2 — address(0) reverts OracleRequired).
    ///         isPriceSane() uses the oracle's `updatedAt` heartbeat for the freshness check,
    ///         so a 3-day idle S2-H with a fresh oracle stays sane.
    ///         pokePrice() updates lastGoodPrice from the oracle.
    ///         On testnet, pass MockXauUsdAggregator.
    IAggregatorV3 public goldOracle;

    constructor(
        address usdc_,
        address paxg_,
        address swapRouter_,
        uint24  poolFee_,
        address vault_,
        address initialOwner,
        address goldOracle_ // K2: mandatory — pass the XAU/USD feed (or MockXauUsdAggregator on testnet)
    ) Ownable(initialOwner) {
        if (goldOracle_ == address(0)) revert OracleRequired();
        usdc      = IERC20(usdc_);
        paxg      = IERC20(paxg_);
        swapRouter = ISwapRouter(swapRouter_);
        poolFee   = poolFee_;
        vault     = vault_;
        goldOracle       = IAggregatorV3(goldOracle_);
        minOutBps        = 9900;  // 99% default (1% max slippage)
        staleHaircutBps  = 500;   // 5% default stale haircut (matches GoldAllocationAdapter)
        maxStalenessSecs = 1 days; // oracle heartbeat window (max 7 days)
    }

    modifier onlyVault() {
        require(msg.sender == vault, "GoldExchangeAdapter: caller is not the vault");
        _;
    }

    /// @notice Atomic USDC-to-PAXG swap. Called by the vault once per execution cycle.
    ///         The entire amount is swapped in one transaction — no state persists between call and return.
    function deploy(uint256 amount) external onlyVault returns (uint256 paxgOut) {
        if (amount == 0) revert ZeroAmount();

        // Vault has already transferred USDC to this adapter via deployCapital().
        // We work with the balance already held here — no pull needed.
        usdc.forceApprove(address(swapRouter), amount);

        (uint256 oraclePrice,) = _freshOraclePrice();
        if (oraclePrice == 0) revert StaleGoldPrice();
        uint256 minOut = ((amount * 1e18 / oraclePrice) * minOutBps) / 10_000;
        if (minOut == 0) minOut = 1;

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn:           address(usdc),
            tokenOut:          address(paxg),
            fee:               poolFee,
            recipient:         address(this),
            deadline:          block.timestamp,
            amountIn:          amount,
            amountOutMinimum:  minOut,
            sqrtPriceLimitX96: 0
        });

        paxgOut = swapRouter.exactInputSingle(params);

        if (paxgOut < minOut) revert SlippageExceeded(paxgOut, minOut);

        // Clear any dust approval
        usdc.forceApprove(address(swapRouter), 0);

        paxgHeld      += paxgOut;
        totalDeployed += amount;

        // Price is 6-dec USDC per whole PAXG (1e18 token units), matching pokePrice().
        uint256 spotPrice = (amount * 1e18) / paxgOut;
        // PR1: Record lastGoodPrice in USDC units (6 dec) — USDC paid per 1e18 PAXG.
        lastGoodPrice    = spotPrice;
        lastGoodPriceAt  = block.timestamp;
        emit LastGoodPriceUpdated(lastGoodPrice, block.timestamp);
        emit GoldAcquired(amount, paxgOut, spotPrice);
    }

    /// @notice Return PAXG to the swap router, receive USDC back for the vault.
    ///         Also atomic — full exit in one transaction.
    function recall(uint256 amount) external onlyVault returns (uint256 usdcReturned) {
        if (amount == 0) revert ZeroAmount();

        uint256 paxgToSell = paxgHeld;
        if (paxgToSell == 0) {
            return 0;
        }

        paxg.forceApprove(address(swapRouter), paxgToSell);

        (uint256 oraclePrice,) = _freshOraclePrice();
        uint256 minUsdcOut;
        if (oraclePrice > 0) {
            minUsdcOut = Math.mulDiv(Math.mulDiv(paxgToSell, oraclePrice, 1e18), minOutBps, 10_000);
        } else {
            if (lastGoodPrice == 0) revert StaleGoldPrice();
            uint256 cachedValue = Math.mulDiv(paxgToSell, lastGoodPrice, 1e18);
            uint256 haircutValue = Math.mulDiv(cachedValue, 10_000 - staleHaircutBps, 10_000);
            minUsdcOut = Math.mulDiv(haircutValue, 10_000 - emergencySlippageBps, 10_000);
        }
        if (minUsdcOut == 0) minUsdcOut = 1;

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn:           address(paxg),
            tokenOut:          address(usdc),
            fee:               poolFee,
            recipient:         vault,
            deadline:          block.timestamp,
            amountIn:          paxgToSell,
            amountOutMinimum:  minUsdcOut,
            sqrtPriceLimitX96: 0
        });

        usdcReturned = swapRouter.exactInputSingle(params);
        if (usdcReturned < minUsdcOut) revert SlippageExceeded(usdcReturned, minUsdcOut);

        paxg.forceApprove(address(swapRouter), 0);

        // PR1: Compute exit price and update lastGoodPrice/At so currentValue() stays accurate
        //      after the position is closed and before a new one is opened.
        if (paxgToSell > 0 && usdcReturned > 0) {
            uint256 exitSpotPrice = (usdcReturned * 1e18) / paxgToSell;
            // Exit price uses the same 6-dec USDC per whole PAXG unit as entry/oracle prices.
            lastGoodPrice   = exitSpotPrice;
            lastGoodPriceAt = block.timestamp;
            emit LastGoodPriceUpdated(lastGoodPrice, block.timestamp);
        }

        paxgHeld       = 0;
        // On full exit, always clear deployed principal regardless of PAXG/USDC price at exit.
        // This prevents stale totalDeployed from inflating vault NAV after position is closed.
        totalDeployed  = 0;

        emit GoldReturned(paxgToSell, usdcReturned);
    }

    /// @notice Live fresh oracle valuation; otherwise cached price, haircutted after its observation expires.
    /// @dev pokePrice maintains the fallback cache but is not required for fresh-price NAV correctness.
    function currentValue() external view returns (uint256) {
        try this.positionValueUsdc() returns (uint256 value) {
            return value;
        } catch {
            return 0;
        }
    }

    /// @dev Read-only boundary catches malformed observations and unrepresentable valuation arithmetic.
    function positionValueUsdc() external view returns (uint256) {
        if (paxgHeld == 0) return 0;
        (uint256 oraclePrice,) = _freshOraclePrice();
        if (oraclePrice > 0) return Math.mulDiv(paxgHeld, oraclePrice, 1e18);
        if (lastGoodPrice == 0) return 0;
        uint256 grossValue = Math.mulDiv(paxgHeld, lastGoodPrice, 1e18);
        bool fresh = lastGoodPriceAt > 0 && lastGoodPriceAt <= block.timestamp
            && block.timestamp - lastGoodPriceAt <= maxStalenessSecs;
        if (fresh) return grossValue;
        return Math.mulDiv(grossValue, 10_000 - staleHaircutBps, 10_000);
    }

    /// @notice Returns false when the XAU/USD oracle is stale or unhealthy (K2 update).
    ///         The oracle is now mandatory — the last-swap-age fallback has been removed.
    ///         Uses the oracle's `updatedAt` field for the freshness check, independent of
    ///         when the last atomic PAXG swap was executed. A 3-day idle S2-H adapter with a
    ///         fresh oracle heartbeat stays sane. Returns true when no position is open
    ///         (lastGoodPriceAt == 0 means no swap has been executed yet).
    function isPriceSane() external view returns (bool) {
        if (lastGoodPriceAt == 0) return true; // no position open — no oracle concern
        (uint256 price,) = _freshOraclePrice();
        return price > 0;
    }

    /// @dev Returns zero for an unavailable, incomplete, invalid or stale observation.
    ///      Price is 6-dec USDC per whole 18-dec PAXG, as used by pokePrice().
    function _freshOraclePrice() internal view returns (uint256 price, uint256 observedAt) {
        try goldOracle.latestRoundData() returns (
            uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound
        ) {
            if (startedAt == 0 || answeredInRound < roundId || answer <= 0) return (0, 0);
            if (updatedAt == 0 || updatedAt > block.timestamp) return (0, 0);
            if (block.timestamp - updatedAt > maxStalenessSecs) return (0, 0);
            try goldOracle.decimals() returns (uint8 oracDec) {
                // Reject unrepresentable scaling rather than reverting during an exit.
                if (oracDec > 83) return (0, 0);
                if (oracDec < 6 && uint256(answer) > type(uint256).max / (10 ** uint256(6 - oracDec))) {
                    return (0, 0);
                }
                price = oracDec >= 6
                    ? uint256(answer) / (10 ** uint256(oracDec - 6))
                    : uint256(answer) * (10 ** uint256(6 - oracDec));
                observedAt = updatedAt;
            } catch {}
        } catch {}
    }

    /// @notice Refresh the cache only from a fresh, complete oracle observation.
    function pokePrice() external {
        (uint256 price, uint256 observedAt) = _freshOraclePrice();
        if (price == 0) return;
        lastGoodPrice = price;
        lastGoodPriceAt = observedAt;
        emit LastGoodPriceUpdated(price, observedAt);
    }

    /// @notice Owner updates the XAU/USD oracle (K2 — must be non-zero; reverts OracleRequired).
    ///         Use this to rotate the oracle feed without redeploying the adapter.
    function setGoldOracle(address oracle) external onlyOwner {
        if (oracle == address(0)) revert OracleRequired();
        address previous = address(goldOracle);
        goldOracle = IAggregatorV3(oracle);
        emit GoldOracleUpdated(previous, oracle);
    }

    function isGoldStrategy() external pure returns (bool) {
        return true;
    }

    function protocolName() external pure returns (string memory) {
        return "GoldExchangeAdapter: USDC/PAXG atomic swap (yad bi yad)";
    }

    function setMinOutBps(uint256 newBps) external onlyOwner {
        require(newBps >= 9000 && newBps <= 10_000, "GoldExchangeAdapter: bps out of range (9000-10000)");
        uint256 prev = minOutBps;
        minOutBps = newBps;
        emit MinOutBpsUpdated(prev, newBps);
    }

    /// @notice Set the stale-price haircut (bps, max MAX_STALE_HAIRCUT_BPS = 2000).
    function setStaleHaircutBps(uint256 bps) external onlyOwner {
        if (bps > MAX_STALE_HAIRCUT_BPS) revert HaircutAboveCap(bps, MAX_STALE_HAIRCUT_BPS);
        uint256 prev = staleHaircutBps;
        staleHaircutBps = bps;
        emit StaleHaircutBpsUpdated(prev, bps);
    }

    /// @notice Set the max staleness window (seconds, max MAX_STALENESS_SECS = 7 days).
    function setMaxStalenessSecs(uint256 secs) external onlyOwner {
        require(secs > 0 && secs <= MAX_STALENESS_SECS, "GoldExchangeAdapter: staleness out of range");
        uint256 prev = maxStalenessSecs;
        maxStalenessSecs = secs;
        emit MaxStalenessBpsUpdated(prev, secs);
    }

    /// @notice Emergency exit tolerance changes take effect only after 30 days.
    function proposeParamChange(bytes32 paramId, uint256 newValue) external onlyOwner {
        require(paramId == PARAM_EMERGENCY_SLIPPAGE, "GoldExchangeAdapter: unknown param");
        if (newValue > MAX_EMERGENCY_SLIPPAGE_BPS) {
            revert HaircutAboveCap(newValue, MAX_EMERGENCY_SLIPPAGE_BPS);
        }
        uint256 executeAfter = block.timestamp + TIMELOCK_DELAY;
        pendingChanges[paramId] = PendingChange(newValue, executeAfter, true);
        emit ParamChangeProposed(paramId, newValue, executeAfter);
    }

    function executeParamChange(bytes32 paramId) external onlyOwner {
        PendingChange memory pc = pendingChanges[paramId];
        require(pc.pending, "GoldExchangeAdapter: no proposal pending");
        require(block.timestamp >= pc.executeAfter, "GoldExchangeAdapter: timelock not elapsed");
        delete pendingChanges[paramId];
        uint256 previous = emergencySlippageBps;
        emergencySlippageBps = pc.newValue;
        emit EmergencySlippageBpsUpdated(previous, pc.newValue);
        emit ParamChangeExecuted(paramId, pc.newValue);
    }

    function cancelParamChange(bytes32 paramId) external onlyOwner {
        require(pendingChanges[paramId].pending, "GoldExchangeAdapter: no proposal pending");
        delete pendingChanges[paramId];
        emit ParamChangeCancelled(paramId);
    }

    function renounceOwnership() public override(Ownable) onlyOwner {
        revert("GoldExchangeAdapter: renouncing ownership is disabled");
    }
}

