// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Script, console} from "forge-std/Script.sol";
import {ShariahScoreAggregator} from "../ShariahScoreAggregator.sol";
import {RiskTieredExecutor} from "../RiskTieredExecutor.sol";

/// @notice Operator script: deploy a fresh 6-enum ShariahScoreAggregator and re-point both executors.
/// @dev    Required because ShariahScoreAggregator is not upgradeable.
///         Run after Task F to activate GOLD_ALLOCATION (index 5).
///
///         WARNING: The old aggregator's score history is NOT migrated.
///         After running this script, the agent must re-score all strategies.
///
///         Environment variables:
///           DEPLOYER            — address that will own the new aggregator
///           OLD_AGGREGATOR      — address of the old ShariahScoreAggregator (for reference)
///           EXECUTOR_CONSERVATIVE — address of the SHARIAH_CONSERVATIVE RiskTieredExecutor
///           EXECUTOR_DYNAMIC      — address of the SHARIAH_DYNAMIC RiskTieredExecutor
///           AGENT_ORACLE          — address of the agent wallet (set as oracle on new aggregator)
///
///         Usage:
///           forge script contracts/script/RedeployShariahAggregator.s.sol \
///             --rpc-url $RPC_URL --broadcast --private-key $PRIVATE_KEY
contract RedeployShariahAggregator is Script {
    function run() external {
        address deployer           = vm.envAddress("DEPLOYER");
        address oldAggregator      = vm.envAddress("OLD_AGGREGATOR");
        address executorConservative = vm.envAddress("EXECUTOR_CONSERVATIVE");
        address executorDynamic    = vm.envAddress("EXECUTOR_DYNAMIC");
        address agentOracle        = vm.envAddress("AGENT_ORACLE");

        console.log("Deploying new 6-enum ShariahScoreAggregator...");
        console.log("  Old aggregator (DEPRECATED - history lost):", oldAggregator);

        vm.startBroadcast();

        // 1. Deploy fresh aggregator with 6-enum build
        ShariahScoreAggregator newAggregator = new ShariahScoreAggregator(deployer);
        console.log("  New aggregator deployed:", address(newAggregator));

        // 2. Re-apply certified flags:
        //    indices 0,1,2,3 = true  (ETH_SPREAD, GOLD_SPREAD, HALAL_LP, MURABAHA)
        //    index 4 = false         (RESERVED_4 / RWA_SUKUK — blocked per SR-001)
        //    index 5 = false         (GOLD_ALLOCATION — pending board acceptance SR-008)
        newAggregator.setCertified(ShariahScoreAggregator.ShariahStrategy.ETH_SPREAD, true);
        newAggregator.setCertified(ShariahScoreAggregator.ShariahStrategy.GOLD_SPREAD, true);
        newAggregator.setCertified(ShariahScoreAggregator.ShariahStrategy.HALAL_LP, true);
        newAggregator.setCertified(ShariahScoreAggregator.ShariahStrategy.MURABAHA, true);
        // RESERVED_4 (index 4): stays false — no setCertified needed
        // GOLD_ALLOCATION (index 5): stays false — pending SR-008 board acceptance
        console.log("  Certified flags applied: [0..3]=true, [4,5]=false");

        // 3. Set agent as oracle
        newAggregator.setOracle(agentOracle);
        console.log("  Oracle set to agent:", agentOracle);

        // 4. Re-point both executors to the new aggregator
        RiskTieredExecutor(executorConservative).setShariahAggregator(address(newAggregator));
        RiskTieredExecutor(executorDynamic).setShariahAggregator(address(newAggregator));
        console.log("  Conservative executor re-pointed:", executorConservative);
        console.log("  Dynamic executor re-pointed:", executorDynamic);

        vm.stopBroadcast();

        console.log("");
        console.log("=== Update docs/agents/deployed-addresses.md ===");
        console.log("DEPRECATED_ShariahScoreAggregator_v1:", oldAggregator);
        console.log("ShariahScoreAggregator_v2:", address(newAggregator));
        console.log("");
        console.log("IMPORTANT: Agent must re-score all strategies after this deploy.");
        console.log("IMPORTANT: Index 5 (GOLD_ALLOCATION) remains uncertified until SR-008 board acceptance.");
    }
}

contracts/script/Rehearsal.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Script, console}            from "forge-std/Script.sol";
import {IERC20}                     from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ShariahAdapterRegistry}     from "../ShariahAdapterRegistry.sol";
import {ShariahVaultV2}             from "../ShariahVaultV2.sol";
import {ShariahVault}               from "../ShariahVault.sol";
import {TreasuryModule}             from "../TreasuryModule.sol";
import {ZakatModule}                from "../ZakatModule.sol";
import {CharityModule}              from "../CharityModule.sol";
import {PurificationEscrow}         from "../PurificationEscrow.sol";
import {GoldExchangeAdapter}        from "../adapters/GoldExchangeAdapter.sol";
import {GoldAllocationAdapter}      from "../adapters/GoldAllocationAdapter.sol";
import {MockAllocatedGold}          from "../test-helpers/MockAllocatedGold.sol";
import {MockXAUT}                   from "../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}       from "../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT}      from "../test-helpers/MockUniswapV3PoolXAUT.sol";
import {RiskTieredExecutor}         from "../RiskTieredExecutor.sol";
import {ShariahScoreAggregator}     from "../ShariahScoreAggregator.sol";

/**
 * @title  TestnetRegistryShortTimelock
 * @notice TESTNET ONLY — a minimal ShariahAdapterRegistry variant that allows
 *         immediate screening execution (no 30-day wait) via a 2-minute
 *         `TESTNET_TIMELOCK_PERIOD` constant.  Uses its own proposal and execution
 *         functions that read the testnet constant rather than the 30-day constant.
 *
 * !! WARNING: NEVER deploy this contract on mainnet. !!
 * Identified by name — any production deploy pipeline MUST reject this contract.
 *
 * Implementation note: Solidity does not allow overriding `constant` values.
 * This contract replicates only the screening proposal+execution logic with the
 * short timelock and delegates to the parent for all other functions.
 */
contract TestnetRegistryShortTimelock is ShariahAdapterRegistry {
    /// @notice 2-minute timelock for rehearsal scripts.
    uint256 public constant TESTNET_TIMELOCK_PERIOD = 2 minutes;

    /// @notice Separate proposal store keyed by adapter — holds the 2-minute executeAfter.
    mapping(address => uint256) public testnetExecuteAfter;
    mapping(address => bytes32) public testnetPronouncementHash;
    mapping(address => uint256) public testnetExpiresAt;

    constructor(address initialOwner, address initialBoardMember)
        ShariahAdapterRegistry(initialOwner, initialBoardMember)
    {
        require(block.chainid != 5042, "mainnet forbidden");
    }

    /// @notice Propose screening with the 2-minute testnet timelock.
    /// After 2 minutes call executeScreeningTestnet(adapter).
    function proposeScreeningTestnet(
        address adapter,
        bytes32 pronouncementHash,
        uint256 expiresAt
    ) external {
        require(block.chainid != 5042, "mainnet forbidden");
        require(boardRole[msg.sender], "TestnetReg: not board");
        require(pronouncementHash != bytes32(0), "TestnetReg: zero hash");
        require(expiresAt > block.timestamp, "TestnetReg: expiresAt in past");
        testnetExecuteAfter[adapter]    = block.timestamp + TESTNET_TIMELOCK_PERIOD;
        testnetPronouncementHash[adapter] = pronouncementHash;
        testnetExpiresAt[adapter]       = expiresAt;
    }

    /// @notice Execute screening after the 2-minute testnet timelock has elapsed.
    /// Writes directly to the parent's `screenings` mapping so the vault sees it.
    function executeScreeningTestnet(address adapter) external {
        require(block.chainid != 5042, "mainnet forbidden");
        require(boardRole[msg.sender], "TestnetReg: not board");
        uint256 executeAfter = testnetExecuteAfter[adapter];
        require(executeAfter != 0, "TestnetReg: not proposed");
        require(block.timestamp >= executeAfter, "TestnetReg: timelock not elapsed");
        bytes32 pHash  = testnetPronouncementHash[adapter];
        uint256 expiry = testnetExpiresAt[adapter];
        // Clear testnet proposal.
        delete testnetExecuteAfter[adapter];
        delete testnetPronouncementHash[adapter];
        delete testnetExpiresAt[adapter];
        // Write to parent's screenings storage.
        screenings[adapter] = Screening({
            pronouncementHash: pHash,
            expiresAt: expiry,
            setAt: block.timestamp
        });
    }
}

/**
 * @title  Rehearsal
 * @notice Task K PR4 — Full testnet rehearsal on Arc Testnet (chain 5042002).
 *
 * Steps:
 *   1. Deploy full stack from scratch with BOARD_MULTISIG set to a separate test address.
 *   2. Three test wallets (WALLET_A, WALLET_B, WALLET_C) deposit into Conservative V2.
 *   3. Board screens S3-H via 2-minute short timelock (TESTNET_SHORT_TIMELOCK=true).
 *   4. Agent server runs 2+ hours against deployment; captures ExecutionTriggered events.
 *      (This step is off-chain; the script records the wiring needed.)
 *   5. One cross-chain round trip via CCTP to ETH-SEPOLIA (domain 0), settled with
 *      settleCrossChainWithMessage including feeExecuted handling.
 *   6. Force stale gold oracle: confirm deposits pause only when gold position > dustThreshold.
 *   7. Claim profit: waterfall amounts and 3-day unlock recorded on-chain.
 *   8. All three wallets redeem fully.
 *
 * Environment variables required:
 *   DEPLOYER_PK          — private key of deployer / owner
 *   BOARD_MULTISIG       — address for board role (separate from deployer)
 *   WALLET_A             — first test depositor address
 *   WALLET_B             — second test depositor address
 *   WALLET_C             — third test depositor address
 *   WALLET_A_PK          — private key of WALLET_A
 *   WALLET_B_PK          — private key of WALLET_B
 *   WALLET_C_PK          — private key of WALLET_C
 *
 * Run (on a fork of Arc Testnet with vm.warp for time jumps):
 *   forge script contracts/script/Rehearsal.s.sol \
 *     --rpc-url $ARC_TESTNET_RPC \
 *     --broadcast \
 *     --private-key $DEPLOYER_PK \
 *     -vvvv
 *
 * On a live chain (real time): run each step as a separate script invocation after the
 * required time delays have elapsed (screening: 2 minutes for testnet short timelock).
 */
contract Rehearsal is Script {

    // ── Arc Testnet constants ─────────────────────────────────────────────────
    address constant USDC            = 0x3600000000000000000000000000000000000000;
    uint32  constant ARC_DOMAIN      = 26;
    uint32  constant ETH_SEP_DOMAIN  = 0;  // Ethereum Sepolia CCTP domain
    address constant CCTP_MESSENGER  = 0x8FE6B999Dc680CcFDD5Bf7EB0974218be2542DAA;
    // NOTE: Arc Testnet MessageTransmitter address — verify from Circle docs before use.
    // Placeholder; replace with actual address from Circle developer docs.
    address constant MSG_TRANSMITTER = address(0); // TODO: fill from Circle Arc Testnet docs

    // ── Rehearsal config ─────────────────────────────────────────────────────
    uint256 constant DEPOSIT_AMOUNT  = 100e6;  // 100 USDC per depositor
    uint256 constant PROFIT_CLAIM    = 10e6;   // 10 USDC synthetic profit for waterfall test
    uint256 constant CCTP_AMOUNT     = 20e6;   // 20 USDC cross-chain round trip
    uint256 constant DUST_THRESHOLD  = 1e6;    // matches vault default

    struct RehearsalAddresses {
        address registry;
        address treasury;
        address zakatModule;
        address vault;
        address charityModule;
        address escrow;
        address mockPaxg;
        address mockXaut;
        address xauOracle;
        address xautPool;
        address goldSpreadAdap;
        address goldAllocAdap;
        address halalLpAdap;
        address shariahAgg;
        address executor;
    }

    RehearsalAddresses internal _addrs;

    // ── Address loader: reads from env vars, falls back to step-1 deployed values ──
    // Add REHEARSAL_* vars to .env after step1_deploy() so steps 2-8 find the contracts.

    function _loadAddrs() internal {
        // Defaults are the step-1 deploy from 2026-10-28 (Arc Testnet, second run).
        _addrs.registry      = vm.envOr("REHEARSAL_REGISTRY",       address(0x23836611FDF05fAc07a12416e9c8C250F9cdF671));
        _addrs.mockPaxg      = vm.envOr("REHEARSAL_MOCK_PAXG",      address(0x90476D68572E615a1E1447928c8c5d8AABaC6B51));
        _addrs.mockXaut      = vm.envOr("REHEARSAL_MOCK_XAUT",      address(0xC57b6125d2a15C09E3624eb78df06e407F6A9912));
        _addrs.xauOracle     = vm.envOr("REHEARSAL_XAU_ORACLE",     address(0x214a54F86B84589068Cf459749344b1F637A60f7));
        _addrs.xautPool      = vm.envOr("REHEARSAL_XAUT_POOL",      address(0x6A46a3A9608437e832510EfD16a21898dA02dc66));
        _addrs.zakatModule   = vm.envOr("REHEARSAL_ZAKAT_MODULE",   address(0xB3fC6A662196EE2c424B6bdfBf9343d96d29569c));
        _addrs.treasury      = vm.envOr("REHEARSAL_TREASURY",       address(0xF5B550B87476a4359f1307AeFC425cCC6E2530f5));
        _addrs.vault         = vm.envOr("REHEARSAL_VAULT",          address(0xba094D5B01F4fd245EA345Be6B8ac833488c81B0));
        _addrs.charityModule = vm.envOr("REHEARSAL_CHARITY_MODULE", address(0x1D05a0010C78B984b0De2735A6E868E9c9f5d99F));
        _addrs.escrow        = vm.envOr("REHEARSAL_ESCROW",         address(0xcC58b11c3Cd251a44989fEf1f05BdcB0e16375ff));
        _addrs.goldSpreadAdap= vm.envOr("REHEARSAL_GOLD_SPREAD",    address(0x55907Fc4E60A5353D9afD17D56F229192Fd9c3ED));
        _addrs.goldAllocAdap = vm.envOr("REHEARSAL_GOLD_ALLOC",     address(0x04FdFd46F0c93569F3b592C106dDc292fc2f975C));
        _addrs.shariahAgg    = vm.envOr("REHEARSAL_SHARIAH_AGG",    address(0x13340E36E59F8b504faD9B1b731D51fde1697C8A));
        _addrs.executor      = vm.envOr("REHEARSAL_EXECUTOR",       address(0xA800540A029120C475c15345d5D65FB9C898d85c));
    }

    // ── Step 1: Deploy full stack ─────────────────────────────────────────────

    function step1_deploy() public returns (RehearsalAddresses memory) {
        uint256 deployerPk    = vm.envUint("DEPLOYER_PK");
        address deployer      = vm.addr(deployerPk);
        address boardMultisig = vm.envOr("BOARD_MULTISIG", deployer);
        address agentWallet   = vm.envOr("AGENT_WALLET", deployer);

        console.log("=== STEP 1: Deploying full stack ===");
        console.log("Deployer       :", deployer);
        console.log("Board multisig :", boardMultisig);

        // Pass the private key so every broadcasted call originates from the deployer EOA.
        // vm.startBroadcast() with no arg uses msg.sender (the script contract), which has
        // no USDC balance and causes transferFrom to revert on the USDC predeploy.
        vm.startBroadcast(deployerPk);
        _step1a_registry(deployer, boardMultisig);
        _step1b_tokens(deployer);
        _step1c_vaultStack(deployer);
        _step1d_adapters(deployer);
        _step1e_executor(deployer, agentWallet);
        vm.stopBroadcast();

        _logAddresses();
        return _addrs;
    }

    function _step1a_registry(address deployer, address boardMultisig) internal {
        TestnetRegistryShortTimelock reg = new TestnetRegistryShortTimelock(deployer, boardMultisig);
        _addrs.registry = address(reg);
        console.log("TestnetRegistryShortTimelock:", _addrs.registry);
    }

    function _step1b_tokens(address deployer) internal {
        MockAllocatedGold paxg = new MockAllocatedGold();
        _addrs.mockPaxg = address(paxg);

        MockXAUT xaut = new MockXAUT();
        _addrs.mockXaut = address(xaut);

        MockXauUsdAggregator oracle = new MockXauUsdAggregator();
        _addrs.xauOracle = address(oracle);

        MockUniswapV3PoolXAUT pool = new MockUniswapV3PoolXAUT(
            USDC, _addrs.mockXaut, 3_300_000_000
        );
        _addrs.xautPool = address(pool);

        xaut.mint(deployer, 5_000e6);
        // Transfer tokens directly to the pool (avoids Arc Testnet USDC transferFrom
        // delegatecall stack depth issue). Then call fundPoolDirect to validate.
        // Seed with MockXAUT only (no USDC transfer — Arc Testnet USDC predeploy
        // triggers a delegatecall stack overflow on any ERC-20 call from a broadcast
        // script). The vault swaps USDC→XAUT so only XAUT needs to be pre-loaded on
        // the output side. USDC flows into the pool naturally during swaps.
        uint256 poolXautSeed = vm.envOr("POOL_XAUT_SEED", uint256(100e6)); // 100 XAUT (6 dec)
        xaut.transfer(_addrs.xautPool, poolXautSeed);
        pool.fundPoolDirect(0, poolXautSeed);
        paxg.mint(deployer, 5_000e18);
    }

    function _step1c_vaultStack(address deployer) internal {
        ZakatModule zakat = new ZakatModule(deployer, USDC, deployer, deployer);
        _addrs.zakatModule = address(zakat);

        TreasuryModule treasury = new TreasuryModule(
            "Shariah",
            deployer, // temporary feeSource — redeploy with vault addr before live use
            USDC, 50, 1000, 400, deployer
        );
        _addrs.treasury = address(treasury);

        ShariahVaultV2 vault = new ShariahVaultV2(
            IERC20(USDC), deployer, ARC_DOMAIN,
            _addrs.treasury, _addrs.zakatModule, _addrs.registry
        );
        _addrs.vault = address(vault);
        console.log("ShariahVaultV2:", _addrs.vault);

        vault.setTokenMessenger(CCTP_MESSENGER);
        if (MSG_TRANSMITTER != address(0)) {
            vault.setMessageTransmitter(MSG_TRANSMITTER);
        }
        vault.setMaxPendingCrossChainBps(2000);
        vault.setPermittedAsset(USDC, true);

        CharityModule charity = new CharityModule(
            deployer, USDC, _addrs.vault, deployer, _addrs.registry
        );
        _addrs.charityModule = address(charity);

        PurificationEscrow escrow = new PurificationEscrow(
            _addrs.vault, USDC, _addrs.charityModule, _addrs.treasury, deployer, _addrs.registry
        );
        _addrs.escrow = address(escrow);
        vault.setPurificationEscrow(_addrs.escrow);
        // Escrow books the manager's Musharakah share in the vault's treasury.
        TreasuryModule(_addrs.treasury).setProfitRecorder(_addrs.escrow);
        // Wire escrow back into CharityModule so distributeCharity() accepts the
        // escrow as caller (the waterfall path is: vault → escrow → charityModule).
        CharityModule(_addrs.charityModule).setEscrow(_addrs.escrow);
    }

    function _step1d_adapters(address deployer) internal {
        // S2-H GoldExchangeAdapter — K2: oracle mandatory
        GoldExchangeAdapter goldSpread = new GoldExchangeAdapter(
            USDC, _addrs.mockPaxg,
            _addrs.xautPool,   // pool shim for testnet router
            3000, _addrs.vault, deployer, _addrs.xauOracle
        );
        _addrs.goldSpreadAdap = address(goldSpread);

        // S6-H GoldAllocationAdapter
        GoldAllocationAdapter goldAlloc = new GoldAllocationAdapter(
            USDC, _addrs.mockXaut, _addrs.xautPool, 3000,
            _addrs.xauOracle, _addrs.vault, 30 days, deployer
        );
        _addrs.goldAllocAdap = address(goldAlloc);

        ShariahVaultV2 vault = ShariahVaultV2(_addrs.vault);
        vault.setGoldSpreadAdapter(_addrs.goldSpreadAdap);
        vault.setGoldAllocationAdapter(_addrs.goldAllocAdap);

        console.log("GoldExchangeAdapter   :", _addrs.goldSpreadAdap);
        console.log("GoldAllocationAdapter :", _addrs.goldAllocAdap);
    }

    function _step1e_executor(address deployer, address agentWallet) internal {
        ShariahScoreAggregator sagg = new ShariahScoreAggregator(deployer);
        _addrs.shariahAgg = address(sagg);

        RiskTieredExecutor exec = new RiskTieredExecutor(
            _addrs.vault, _addrs.shariahAgg,
            RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE,
            deployer
        );
        _addrs.executor = address(exec);
        ShariahVaultV2(_addrs.vault).setManager(_addrs.executor);
        sagg.setOracle(agentWallet);

        console.log("ShariahScoreAggregator:", _addrs.shariahAgg);
        console.log("RiskTieredExecutor    :", _addrs.executor);
    }

    // ── Step 2: Three wallets deposit ─────────────────────────────────────────

    function step2_deposits() public {
        _loadAddrs();
        console.log("=== STEP 2: Three wallets deposit 100 USDC each ===");
        console.log("Vault:", _addrs.vault);
        console.log("NOTE: Run each broadcast separately with each wallet's private key:");
        console.log("  forge script ... --sig 'step2_deposits()' --private-key $WALLET_A_PK");
        console.log("  (repeat for WALLET_B_PK and WALLET_C_PK)");
        console.log("Or supply via WALLET_A_PK / WALLET_B_PK / WALLET_C_PK env vars.");

        // Each wallet: approve + deposit 100 USDC
        // NOTE: Each wallet must hold USDC before calling this step.
        // Fund wallets via 'Get test USDC' in Arc Studio sidebar.
        uint256[3] memory pks;
        pks[0] = vm.envOr("WALLET_A_PK", uint256(0));
        pks[1] = vm.envOr("WALLET_B_PK", uint256(0));
        pks[2] = vm.envOr("WALLET_C_PK", uint256(0));

        for (uint256 i = 0; i < 3; i++) {
            if (pks[i] == 0) {
                console.log("WALLET pk not set, skipping index:", i);
                continue;
            }
            address wallet = vm.addr(pks[i]);
            vm.startBroadcast(pks[i]);
            IERC20(USDC).approve(_addrs.vault, DEPOSIT_AMOUNT);
            ShariahVaultV2(_addrs.vault).deposit(DEPOSIT_AMOUNT, wallet);
            console.log("Deposited 100 USDC from wallet:", wallet);
            vm.stopBroadcast();
        }
    }

    // ── Step 3: Board screens S3-H (HalalLPAdapter) via short timelock ────────

    function step3_screenS3H(address halalLpAdapter) public {
        _loadAddrs();
        uint256 boardPk       = vm.envUint("BOARD_PK");
        address boardMultisig = vm.addr(boardPk);

        console.log("=== STEP 3: Screen S3-H (HalalLP) via 2-minute testnet timelock ===");
        console.log("NOTE: TestnetRegistryShortTimelock TIMELOCK_PERIOD = 2 minutes.");
        console.log("NEVER use this contract on mainnet.");
        console.log("Board address:", boardMultisig);

        bytes32 pronouncementHash = keccak256("SR-011-REHEARSAL-TESTNET-ONLY");
        uint256 expiresAt         = block.timestamp + 365 days;

        vm.startBroadcast(boardPk);
        TestnetRegistryShortTimelock reg = TestnetRegistryShortTimelock(_addrs.registry);
        reg.proposeScreeningTestnet(halalLpAdapter, pronouncementHash, expiresAt);
        console.log("Proposed screening for adapter:", halalLpAdapter);
        console.log("Wait 2 minutes, then call step3b_executeScreening()");
        vm.stopBroadcast();
    }

    function step3b_executeScreening(address halalLpAdapter) public {
        _loadAddrs();
        uint256 boardPk = vm.envUint("BOARD_PK");
        console.log("=== STEP 3b: Execute S3-H screening after 2-minute delay ===");
        vm.startBroadcast(boardPk);
        TestnetRegistryShortTimelock(_addrs.registry).executeScreeningTestnet(halalLpAdapter);
        ShariahVaultV2(_addrs.vault).setScreened(halalLpAdapter, true);
        console.log("S3-H screening executed. HalalLPAdapter is now screened.");
        vm.stopBroadcast();
    }

    // ── Step 4: Agent wiring (off-chain instructions) ─────────────────────────
    // The agent server (bun run agent) connects to the deployed contracts and runs
    // its scoring loop. This step documents the wiring; execution is off-chain.

    function step4_agentWiring() public pure {
        console.log("=== STEP 4: Agent server instructions ===");
        console.log("Set in .env:");
        console.log("  VITE_SHARIAH_VAULT_ADDRESS=<vault>");
        console.log("  VITE_SHARIAH_AGG_ADDRESS=<sagg>");
        console.log("  VITE_EXECUTOR_CONSERVATIVE=<executor>");
        console.log("Then run: bun run agent");
        console.log("Monitor ExecutionTriggered events for >= 2 hours.");
        console.log("Capture tx hashes and gas used for rehearsal.md.");
    }

    // ── Step 5: Cross-chain round trip ────────────────────────────────────────

    // Task M: this step requires a Task-M vault; return its local position ID, not a CCTP nonce.
    function step5_deployCrossChain() public returns (uint64 positionId) {
        _loadAddrs();
        uint256 deployerPk = vm.envUint("DEPLOYER_PK");
        address deployer   = vm.addr(deployerPk);
        bytes32 recipient  = bytes32(uint256(uint160(deployer))); // return to deployer

        // Live board: run step5_proposeRemoteRecipient first, let 30 days elapse,
        // then run step5_confirmRemoteRecipient. No live-chain time warp is possible.
        require(ShariahVault(_addrs.vault).approvedRemoteRecipient(ETH_SEP_DOMAIN, recipient), "remote approval required");
        console.log("=== STEP 5: Cross-chain deploy to ETH-SEPOLIA ===");
        vm.startBroadcast(deployerPk);
        ShariahVault(_addrs.vault).deployCrossChain(ETH_SEP_DOMAIN, recipient, CCTP_AMOUNT);
        positionId = ShariahVault(_addrs.vault).crossChainPositionCounter();
        console.log("Local position ID:", positionId);
        console.log("CCTP amount:      ", CCTP_AMOUNT);
        console.log("Wait for CCTP attestation, then call step5b_settle(positionId, message, attestation)");
        vm.stopBroadcast();
    }

    /// @notice Board proposal helper; on a live board the full 30 days must elapse first.
    function step5_proposeRemoteRecipient(bytes32 recipient) public {
        _loadAddrs();
        vm.startBroadcast(vm.envUint("BOARD_PK"));
        ShariahVault(_addrs.vault).proposeRemoteRecipient(ETH_SEP_DOMAIN, recipient, true);
        vm.stopBroadcast();
    }

    function step5_confirmRemoteRecipient(bytes32 recipient) public {
        _loadAddrs();
        vm.startBroadcast(vm.envUint("BOARD_PK"));
        ShariahVault(_addrs.vault).confirmRemoteRecipient(ETH_SEP_DOMAIN, recipient);
        vm.stopBroadcast();
    }

    function step5b_settle(
        uint64 positionId,
        bytes calldata message,
        bytes calldata attestation
    ) public {
        _loadAddrs();
        uint256 deployerPk = vm.envUint("DEPLOYER_PK");
        console.log("=== STEP 5b: Settle cross-chain return ===");
        console.log("Local position ID:", positionId);
        // Task M: supply native Circle V2 bytes (148-byte header plus >=228-byte body).
        // The owner must first register the remote TokenMessenger for the return source domain.
        vm.startBroadcast(deployerPk);
        ShariahVault(_addrs.vault).settleCrossChainWithMessage(positionId, message, attestation);
        console.log("settleCrossChainWithMessage succeeded. NAV updated, feeExecuted absorbed.");
        vm.stopBroadcast();
    }

    // ── Step 6: Force stale oracle ────────────────────────────────────────────

    function step6_forceStaleOracle() public {
        _loadAddrs();
        console.log("=== STEP 6: Force stale gold oracle ===");
        console.log("Advancing time past maxStalenessSecs (1 day) WITHOUT updating oracle.");
        console.log("On a live chain, just wait > 1 day without poking the oracle.");
        console.log("On a fork: vm.warp(block.timestamp + 1 days + 1);");

        // Check current state
        GoldExchangeAdapter spread = GoldExchangeAdapter(_addrs.goldSpreadAdap);
        GoldAllocationAdapter alloc = GoldAllocationAdapter(_addrs.goldAllocAdap);

        console.log("goldSpread.isPriceSane():", spread.isPriceSane() ? "true" : "false");
        console.log("goldAlloc.isPriceSane():", alloc.isPriceSane() ? "true" : "false");

        ShariahVaultV2 vault = ShariahVaultV2(_addrs.vault);
        uint256 maxDep = vault.maxDeposit(address(0));
        console.log("maxDeposit(0):", maxDep);
        if (spread.currentValue() > vault.effectiveDustThreshold()) {
            console.log("Gold position > dustThreshold: deposits BLOCKED when stale. OK.");
        } else {
            console.log("Gold position <= dustThreshold: deposits NOT blocked (dust rule). OK.");
        }
        console.log("Redemptions remain open at all times (verify separately).");
    }

    // ── Step 7: Claim profit ──────────────────────────────────────────────────

    function step7_claimProfit() public {
        _loadAddrs();
        uint256 deployerPk = vm.envUint("DEPLOYER_PK");
        console.log("=== STEP 7: Claim profit - waterfall + 3-day unlock ===");
        vm.startBroadcast(deployerPk);
        // Transfer synthetic profit rather than depositing principal; the checkpoint requires realized profit.
        require(IERC20(USDC).transfer(_addrs.vault, PROFIT_CLAIM), "profit funding failed");
        require(ShariahVault(_addrs.vault).realizedProfit() >= PROFIT_CLAIM, "insufficient realized profit");
        ShariahVault(_addrs.vault).claimMusharakahProfit(PROFIT_CLAIM);
        console.log("claimMusharakahProfit(", PROFIT_CLAIM, ")");
        console.log("Waterfall executed. Check WaterfallExecuted + MusharakahProfitClaimed events.");
        console.log("lockedProfit will decay over 3 days (profitUnlockPeriod).");
        vm.stopBroadcast();
    }

    // ── Step 8: All three wallets redeem ──────────────────────────────────────

    function step8_redeemAll() public {
        _loadAddrs();
        console.log("=== STEP 8: All three wallets redeem fully ===");

        uint256[3] memory pks;
        pks[0] = vm.envOr("WALLET_A_PK", uint256(0));
        pks[1] = vm.envOr("WALLET_B_PK", uint256(0));
        pks[2] = vm.envOr("WALLET_C_PK", uint256(0));

        ShariahVaultV2 vault = ShariahVaultV2(_addrs.vault);

        for (uint256 i = 0; i < 3; i++) {
            if (pks[i] == 0) { continue; }
            address wallet = vm.addr(pks[i]);
            uint256 maxShares = vault.maxRedeem(wallet);
            if (maxShares == 0) {
                console.log("Wallet has no shares:", wallet);
                continue;
            }
            vm.startBroadcast(pks[i]);
            vault.redeem(maxShares, wallet, wallet);
            console.log("Redeemed all shares for wallet:", wallet);
            vm.stopBroadcast();
        }
    }

    // ── Convenience: run all steps in sequence (fork only) ───────────────────

    function run() external {
        console.log("=== Rehearsal.s.sol - Task K PR4 ===");
        console.log("Run each step separately in production.");
        console.log("Use 'forge script --sig step1_deploy()' etc.");
        step4_agentWiring();
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    function _logAddresses() internal view {
        console.log("\n=== Rehearsal Deployment Summary ===");
        console.log("TestnetRegistryShortTimelock:", _addrs.registry);
        console.log("ShariahTreasury (redeploy needed for feeSource):", _addrs.treasury);
        console.log("ZakatModule (deprecated):", _addrs.zakatModule);
        console.log("ShariahVaultV2 (Conservative):", _addrs.vault);
        console.log("CharityModule:", _addrs.charityModule);
        console.log("PurificationEscrow:", _addrs.escrow);
        console.log("MockAllocatedGold (PAXG):", _addrs.mockPaxg);
        console.log("MockXAUT:", _addrs.mockXaut);
        console.log("MockXauUsdAggregator:", _addrs.xauOracle);
        console.log("MockUniswapV3PoolXAUT:", _addrs.xautPool);
        console.log("GoldExchangeAdapter (S2-H):", _addrs.goldSpreadAdap);
        console.log("GoldAllocationAdapter (S6-H):", _addrs.goldAllocAdap);
        console.log("ShariahScoreAggregator:", _addrs.shariahAgg);
        console.log("RiskTieredExecutor (Conservative):", _addrs.executor);
        console.log("\nRecording in docs/agents/deployed-addresses.md required.");
    }
}

contracts/test/AutonomousVaultTest.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {AutonomousVaultHarness} from "../test-helpers/AutonomousVaultHarness.sol";
import {ConventionalVault} from "../ConventionalVault.sol";
import {TreasuryModule} from "../TreasuryModule.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

// ---------------------------------------------------------------------------
// Mock token messenger — records native V2 burn calls without a return value
// ---------------------------------------------------------------------------
contract MockTokenMessenger {
    // Task M: V2 burns return no nonce; record all seven arguments instead.
    bytes public lastCall;
    function depositForBurn(uint256 amount, uint32 domain, bytes32 recipient, address token,
        bytes32 caller, uint256 maxFee, uint32 finality) external {
        lastCall = abi.encode(amount, domain, recipient, token, caller, maxFee, finality);
    }
}

// ---------------------------------------------------------------------------
// Mock MessageTransmitter — mints a fixed amount of USDC to the vault on receiveMessage (J1)
// ---------------------------------------------------------------------------
contract MockMessageTransmitterAVT {
    address public usdc;
    address public vault;
    uint256 public mintAmount;
    constructor(address usdc_, address vault_, uint256 amount_) { usdc = usdc_; vault = vault_; mintAmount = amount_; }
    function receiveMessage(bytes calldata, bytes calldata) external returns (bool) {
        MockERC20(usdc).mint(vault, mintAmount);
        return true;
    }
}

// Helper to build a minimal CCTP message for tests (matches CctpMessageDecoder offsets)
library TestCctpMsg {
    function build(uint64 nonce_, uint256 amount_, address recipient_) internal view returns (bytes memory) {
        AutonomousVault target = AutonomousVault(recipient_);
        // Task M: native 148-byte V2 header, bytes32 nonce and registered remote sender.
        uint32 remote = target.pendingCrossChainDestinationDomain(1);
        bytes memory header = abi.encodePacked(
            uint32(1), remote, target.localDomain(), bytes32(uint256(nonce_)),
            target.remoteTokenMessenger(remote), bytes32(uint256(uint160(target.tokenMessenger()))),
            bytes32(uint256(uint160(recipient_))), uint32(2000), uint32(2000) // destinationCaller = vault
        );
        // BurnMessageV2 body: 228 bytes (version+burnToken+mintRecipient+amount+
        //   messageSender+maxFee+feeExecuted+expirationBlock = 4+32+32+32+32+32+32+32).
        bytes memory body = new bytes(228);
        body[3] = 0x01; // Task M: native BurnMessageV2 version.
        bytes32 rw = bytes32(uint256(uint160(recipient_)));
        for (uint256 i = 0; i < 32; i++) body[36 + i] = rw[i];
        bytes32 aw = bytes32(amount_);
        for (uint256 i = 0; i < 32; i++) body[68 + i] = aw[i];
        // maxFee at [132..163], feeExecuted at [164..195] — both zero (Standard Transfer)
        return abi.encodePacked(header, body);
    }
}

// ---------------------------------------------------------------------------
// Mock adapter that holds USDC and can be recalled
// ---------------------------------------------------------------------------
contract MockAdapter is IStrategyAdapter {
    address public override vault;
    address public usdc;

    constructor(address vault_, address usdc_) {
        vault = vault_;
        usdc = usdc_;
    }

    function deploy(uint256 amount) external override returns (uint256) {
        // tokens are sent by the vault via deployCapital; just accept them
        return amount;
    }

    function recall(uint256 amount) external override returns (uint256) {
        // transfer back to vault
        IERC20(usdc).transfer(vault, amount);
        return amount;
    }

    function currentValue() external view override returns (uint256) {
        return IERC20(usdc).balanceOf(address(this));
    }

    function protocolName() external pure override returns (string memory) {
        return "MockAdapter";
    }
}

// ---------------------------------------------------------------------------
// Test contract
// ---------------------------------------------------------------------------
contract AutonomousVaultTest is Test {
    MockERC20 internal usdc;
    AutonomousVault internal vault;
    MockTokenMessenger internal messenger;

    address internal owner = makeAddr("owner");
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal random = makeAddr("random");

    uint32 internal constant SOURCE_DOMAIN = 1;
    uint32 internal constant DEST_DOMAIN = 6; // different from 1

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        vm.prank(owner);
        vault = new AutonomousVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        messenger = new MockTokenMessenger();
    }

    // -----------------------------------------------------------------------
    // Helper: give `who` `amount` USDC and approve vault
    // -----------------------------------------------------------------------
    function _fund(address who, uint256 amount) internal {
        usdc.mint(who, amount);
        vm.prank(who);
        usdc.approve(address(vault), amount);
    }

    // Shortening an active schedule must checkpoint remaining profit instead of moving its start into the future.
    function test_profitStreaming_shortenActivePeriod_keepsNavAndDepositsLive() public {
        AutonomousVaultHarness harness = new AutonomousVaultHarness(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        usdc.mint(address(harness), 300e6);
        vm.prank(owner);
        harness.lockProfit(300e6);
        skip(1 days);
        assertEq(harness.totalAssets(), 100e6);
        vm.prank(owner);
        harness.setProfitUnlockPeriod(1 days);
        assertEq(harness.lockedProfit(), 200e6);
        assertEq(harness.unlockedAt(), block.timestamp + 1 days);
        assertEq(harness.totalAssets(), 100e6);
        usdc.mint(alice, 10e6);
        vm.startPrank(alice);
        usdc.approve(address(harness), 10e6);
        harness.deposit(10e6, alice);
        vm.stopPrank();
        assertEq(harness.totalAssets(), 110e6);
        skip(12 hours);
        assertEq(harness.totalAssets(), 210e6);
        skip(12 hours);
        assertEq(harness.totalAssets(), 310e6);
    }

    // N-15 preserves streaming coverage via a test-only subclass, never a production base entry point.
    function test_profitStreaming_harnessOnly() public {
        AutonomousVaultHarness harness = new AutonomousVaultHarness(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        usdc.mint(address(harness), 300e6);
        vm.prank(owner);
        harness.lockProfit(300e6);
        assertEq(harness.totalAssets(), 0);
        skip(1.5 days);
        assertEq(harness.totalAssets(), 150e6);
        skip(1.5 days);
        assertEq(harness.totalAssets(), 300e6);
        vm.prank(owner);
        (bool ok,) = address(vault).call(abi.encodeWithSignature("lockProfit(uint256)", 1));
        assertFalse(ok, "plain base has no external lockProfit");
    }

    // N-15 preserves ConventionalVault's former inherited locking and proceeds-based recall semantics.
    function test_conventionalBaseSemantics_unchanged() public {
        TreasuryModule treasury = new TreasuryModule("Conventional", address(0), address(usdc), 0, 0, 0, owner);
        ConventionalVault conventional = new ConventionalVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury));
        usdc.mint(address(conventional), 1_000e6);
        vm.prank(owner);
        conventional.lockProfit(100e6);
        assertEq(conventional.totalAssets(), 900e6);
        skip(3 days);
        MockAdapter adapter = new MockAdapter(address(conventional), address(usdc));
        vm.prank(owner);
        conventional.deployCapital(address(adapter), 500e6, "");
        vm.prank(owner);
        conventional.recallCapital(address(adapter), 400e6);
        assertEq(conventional.totalDeployed(), 100e6);
        assertEq(conventional.totalAssets(), 1_000e6);
    }

    // -----------------------------------------------------------------------
    // test_deposit_and_withdraw
    // -----------------------------------------------------------------------
    function test_deposit_and_withdraw() public {
        _fund(alice, 1_000e6);

        vm.prank(alice);
        uint256 shares = vault.deposit(1_000e6, alice);
        assertGt(shares, 0, "shares should be nonzero");
        assertEq(usdc.balanceOf(address(vault)), 1_000e6);

        vm.prank(alice);
        vault.approve(address(vault), shares);

        vm.prank(alice);
        uint256 assets = vault.redeem(shares, alice, alice);
        assertEq(assets, 1_000e6, "should get back 1000e6");
        assertEq(usdc.balanceOf(alice), 1_000e6);
    }

    // -----------------------------------------------------------------------
    // test_deployCapital_basic
    // -----------------------------------------------------------------------
    function test_deployCapital_basic() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        address strategy = makeAddr("strategy");
        vm.prank(owner);
        vault.deployCapital(strategy, 800e6, "");

        assertEq(vault.totalDeployed(), 800e6, "totalDeployed should be 800e6");
        assertEq(usdc.balanceOf(strategy), 800e6);
    }

    // -----------------------------------------------------------------------
    // test_deployCapital_exceeds_cap (80% of 1000e6 = 800e6; 810e6 reverts)
    // -----------------------------------------------------------------------
    function test_deployCapital_exceeds_cap() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        address strategy = makeAddr("strategy");
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.deployCapital(strategy, 810e6, "");
    }

    // -----------------------------------------------------------------------
    // test_deployCapital_only_manager_or_owner
    // -----------------------------------------------------------------------
    function test_deployCapital_only_manager_or_owner() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(random);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.deployCapital(makeAddr("strat"), 100e6, "");
    }

    // -----------------------------------------------------------------------
    // test_returnCapital
    // -----------------------------------------------------------------------
    function test_returnCapital() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        address strategy = makeAddr("strategy");
        vm.prank(owner);
        vault.deployCapital(strategy, 800e6, "");
        assertEq(vault.totalDeployed(), 800e6);

        // strategy approves vault to pull back
        vm.prank(strategy);
        usdc.approve(address(vault), 800e6);

        vm.prank(owner);
        vault.returnCapital(strategy, 800e6);

        assertEq(vault.totalDeployed(), 0, "totalDeployed should be 0");
        assertEq(usdc.balanceOf(address(vault)), 1_000e6, "vault should have all USDC back");
    }

    // -----------------------------------------------------------------------
    // test_recallCapital_via_adapter
    // -----------------------------------------------------------------------
    function test_recallCapital_via_adapter() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        MockAdapter adapter = new MockAdapter(address(vault), address(usdc));

        vm.prank(owner);
        vault.deployCapital(address(adapter), 800e6, "");
        assertEq(vault.totalDeployed(), 800e6);

        // Adapter now holds 800e6 USDC; recallCapital triggers adapter.recall()
        vm.prank(owner);
        vault.recallCapital(address(adapter), 800e6);

        assertEq(vault.totalDeployed(), 0, "totalDeployed should be 0 after recall");
        assertEq(usdc.balanceOf(address(vault)), 1_000e6, "vault should have all USDC back");
    }

    // -----------------------------------------------------------------------
    // test_deployCrossChain_basic
    // -----------------------------------------------------------------------
    function test_deployCrossChain_basic() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(owner);
        vault.setTokenMessenger(address(messenger));

        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remoteVault"))));
        vm.prank(owner);
        // PR3.3: maxPendingCrossChainBps = 2000 (20% of 1000e6 = 200e6 cap).
        // Use 150e6 which is within the 20% cap.
        vault.deployCrossChain(DEST_DOMAIN, recipient, 150e6);

        assertEq(vault.totalDeployed(), 150e6, "totalDeployed should be 150e6");
        // nonce 1 was used by the messenger
        assertEq(vault.pendingCrossChain(1), 150e6, "pendingCrossChain[1] should be 150e6");
    }

    // -----------------------------------------------------------------------
    // test_deployCrossChain_same_domain_reverts
    // -----------------------------------------------------------------------
    function test_deployCrossChain_same_domain_reverts() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(owner);
        vault.setTokenMessenger(address(messenger));

        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remoteVault"))));
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.SameDomainDeploy.selector);
        vault.deployCrossChain(SOURCE_DOMAIN, recipient, 500e6);
    }

    // -----------------------------------------------------------------------
    // test_deployCrossChain_not_configured
    // -----------------------------------------------------------------------
    function test_deployCrossChain_not_configured() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        // tokenMessenger is still address(0)
        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remoteVault"))));
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.CrossChainNotConfigured.selector);
        vault.deployCrossChain(DEST_DOMAIN, recipient, 500e6);
    }

    // -----------------------------------------------------------------------
    // test_settleCrossChain — J1: uses settleCrossChainWithMessage (atomic path)
    // -----------------------------------------------------------------------
    function test_settleCrossChain() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(owner);
        vault.setTokenMessenger(address(messenger));

        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remoteVault"))));
        vm.prank(owner);
        // PR3.3: use 150e6 (within 20% cap of 1000e6)
        vault.deployCrossChain(DEST_DOMAIN, recipient, 150e6);
        assertEq(vault.totalDeployed(), 150e6);

        // J1: deploy a mock transmitter that mints 150e6 on receiveMessage.
        MockMessageTransmitterAVT transmitter =
            new MockMessageTransmitterAVT(address(usdc), address(vault), 150e6);
        vm.prank(owner);
        vault.setMessageTransmitter(address(transmitter));
        vm.prank(owner);
        vault.setRemoteTokenMessenger(DEST_DOMAIN, bytes32(uint256(0xCC7)));

        bytes memory msg_  = TestCctpMsg.build(99, 150e6, address(vault));
        vm.prank(owner);
        vault.settleCrossChainWithMessage(1, msg_, "");

        assertEq(vault.pendingCrossChain(1), 0, "pending should be cleared");
    }

    // -----------------------------------------------------------------------
    // test_settleCrossChain_wrong_nonce — J1: write-off path with wrong nonce
    // -----------------------------------------------------------------------
    function test_settleCrossChain_wrong_nonce() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(owner);
        vault.setTokenMessenger(address(messenger));

        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remoteVault"))));
        vm.prank(owner);
        // PR3.3: use 150e6 (within 20% cap of 1000e6)
        vault.deployCrossChain(DEST_DOMAIN, recipient, 150e6);

        // Write-off with unused nonce 99 reverts NonceMismatch.
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(99), uint64(0)));
        vault.settleCrossChain(99, 0); // J1: write-off only; received must be 0
    }

    // -----------------------------------------------------------------------
    // test_paused_deposit_reverts
    // -----------------------------------------------------------------------
    function test_paused_deposit_reverts() public {
        vm.prank(owner);
        vault.setPaused(true);

        usdc.mint(alice, 1_000e6);
        vm.prank(alice);
        usdc.approve(address(vault), 1_000e6);

        vm.prank(alice);
        vm.expectRevert(AutonomousVault.Paused.selector);
        vault.deposit(1_000e6, alice);
    }

    // -----------------------------------------------------------------------
    // test_setMaxAllocationBps_over_9500_reverts
    // -----------------------------------------------------------------------
    function test_setMaxAllocationBps_over_9500_reverts() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.InvalidBps.selector);
        vault.setMaxAllocationBps(9_501);
    }

    // -----------------------------------------------------------------------
    // test_decimals_offset — share decimals = asset.decimals() + 6
    // -----------------------------------------------------------------------
    function test_decimals_offset() public view {
        // USDC has 6 decimals; offset is 6 → share decimals = 12
        assertEq(vault.decimals(), 12, "vault share decimals should be 12");
    }

    // -----------------------------------------------------------------------
    // test_inflation_attack_protection
    // -----------------------------------------------------------------------
    function test_inflation_attack_protection() public {
        // Attacker donates 1e6-1 USDC directly to vault BEFORE first deposit
        usdc.mint(address(vault), 1e6 - 1);

        // Second depositor deposits 1e6 USDC
        _fund(bob, 1e6);
        vm.prank(bob);
        uint256 bobShares = vault.deposit(1e6, bob);

        // First depositor (alice) deposits 1e6 USDC after donation
        _fund(alice, 1e6);
        vm.prank(alice);
        uint256 aliceShares = vault.deposit(1e6, alice);

        // Alice should get at least 99% of what bob got (fair shares)
        // With _decimalsOffset=6, the virtual shares make the attack ineffective
        assertGt(aliceShares, (bobShares * 99) / 100, "alice should receive fair shares");
    }

    // -----------------------------------------------------------------------
    // test_max_allocation_boundary — exactly at 80% succeeds, 80%+1 reverts
    // -----------------------------------------------------------------------
    function test_max_allocation_boundary() public {
        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        address strategy = makeAddr("strategy");

        // 801e6 = 80.1% of 1000e6 → should revert
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.deployCapital(strategy, 801e6, "");

        // 800e6 = exactly 80% → should succeed
        vm.prank(owner);
        vault.deployCapital(strategy, 800e6, "");
        assertEq(vault.totalDeployed(), 800e6);
    }

    // -----------------------------------------------------------------------
    // test_manager_can_deploy
    // -----------------------------------------------------------------------
    function test_manager_can_deploy() public {
        address mgr = makeAddr("manager");
        vm.prank(owner);
        vault.setManager(mgr);

        _fund(alice, 1_000e6);
        vm.prank(alice);
        vault.deposit(1_000e6, alice);

        vm.prank(mgr);
        vault.deployCapital(makeAddr("strategy"), 500e6, "");
        assertEq(vault.totalDeployed(), 500e6);
    }
}

contracts/test/CharityModuleTest.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {CharityModule} from "../CharityModule.sol";
import {MockERC20}     from "../test-helpers/MockERC20.sol";

/// @dev Minimal registry mock for J3: always returns isBoard=true for the configured member.
contract MockRegistryCMT {
    address public board;
    constructor(address board_) { board = board_; }
    function isBoard(address a) external view returns (bool) { return a == board; }
}

/**
 * @title  CharityModuleTest
 * @notice Unit tests for CharityModule — 20+ tests covering distribution,
 *         wallet timelock, and rate timelock.
 *
 * Setup: test contract IS the vault (address(this) == vault).
 *        Owner is a separate EOA to keep onlyOwner / onlyVault orthogonal.
 */
contract CharityModuleTest is Test {

    // ── actors ────────────────────────────────────────────────────────────────
    address internal owner        = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");
    address internal other        = makeAddr("other");

    // ── contracts ─────────────────────────────────────────────────────────────
    MockERC20         internal usdc;
    CharityModule     internal module;
    MockRegistryCMT   internal registry;

    // ── helpers ───────────────────────────────────────────────────────────────
    uint256 internal constant INITIAL_BALANCE = 1_000_000e6;

    function setUp() public {
        usdc     = new MockERC20("Mock USDC", "mUSDC", 6);
        registry = new MockRegistryCMT(owner); // J3: owner is also board member

        // address(this) is vault; owner is the Ownable owner
        vm.prank(owner);
        module = new CharityModule(charityWallet, address(usdc), address(this), owner, address(registry));

        // Fund this contract (acting as vault) with USDC
        usdc.mint(address(this), INITIAL_BALANCE);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 1. Basic distribution
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice distributeCharity(1000e6) → charityAmount = 25e6 (2.5%), remaining = 975e6
    function test_distributeCharity_basic() public {
        uint256 gross = 1_000e6;
        usdc.approve(address(module), gross);

        (uint256 charityAmount, uint256 remaining) = module.distributeCharity(gross);

        assertEq(charityAmount, 25e6,    "charityAmount should be 2.5% of gross");
        assertEq(remaining,     975e6,   "remaining should be gross - charity");
        assertEq(usdc.balanceOf(charityWallet), 25e6, "charityWallet should receive 25e6");
    }

    /// @notice distributeCharity(0) must revert ZeroAmount
    function test_distributeCharity_zero_reverts() public {
        vm.expectRevert(CharityModule.ZeroAmount.selector);
        module.distributeCharity(0);
    }

    /// @notice Non-vault caller must revert NotVault
    function test_distributeCharity_not_vault_reverts() public {
        vm.prank(other);
        vm.expectRevert(CharityModule.NotVault.selector);
        module.distributeCharity(1e6);
    }

    /// @notice totalCharityDistributed accumulates across two calls
    function test_totalCharityDistributed_accumulates() public {
        uint256 gross1 = 1_000e6;
        uint256 gross2 = 2_000e6;

        usdc.approve(address(module), gross1 + gross2);

        (uint256 c1,) = module.distributeCharity(gross1);
        (uint256 c2,) = module.distributeCharity(gross2);

        assertEq(module.totalCharityDistributed(), c1 + c2, "totalCharityDistributed should sum both calls");
    }

    /// @notice Default charityBps is 250
    function test_default_charityBps_is_250() public view {
        assertEq(module.charityBps(), 250);
    }

    /// @notice MAX_CHARITY_BPS constant is 500
    function test_MAX_CHARITY_BPS_is_500() public view {
        assertEq(module.MAX_CHARITY_BPS(), 500);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 2. Wallet timelock
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice proposeCharityWalletChange sets pendingCharityWallet
    function test_proposeWalletChange_sets_pending() public {
        address newWallet = makeAddr("newWallet");
        vm.prank(owner);
        module.proposeCharityWalletChange(newWallet);
        assertEq(module.pendingCharityWallet(), newWallet, "pendingCharityWallet should be set");
    }

    /// @notice Confirming immediately after proposal reverts TimelockNotElapsed
    function test_confirmWalletChange_before_timelock_reverts() public {
        address newWallet = makeAddr("newWallet");
        vm.startPrank(owner);
        module.proposeCharityWalletChange(newWallet);
        vm.expectRevert(); // TimelockNotElapsed(remaining)
        module.confirmCharityWalletChange();
        vm.stopPrank();
    }

    /// @notice Confirming after 30 days updates charityWallet
    function test_confirmWalletChange_after_30_days_succeeds() public {
        address newWallet = makeAddr("newWallet");
        vm.startPrank(owner);
        module.proposeCharityWalletChange(newWallet);
        vm.warp(block.timestamp + 30 days);
        module.confirmCharityWalletChange();
        vm.stopPrank();
        assertEq(module.charityWallet(), newWallet, "charityWallet should be updated");
        assertEq(module.pendingCharityWallet(), address(0), "pendingCharityWallet should be cleared");
    }

    /// @notice cancelCharityWalletChange clears pendingCharityWallet
    function test_cancelWalletChange_clears_pending() public {
        address newWallet = makeAddr("newWallet");
        vm.startPrank(owner);
        module.proposeCharityWalletChange(newWallet);
        module.cancelCharityWalletChange();
        vm.stopPrank();
        assertEq(module.pendingCharityWallet(), address(0), "pendingCharityWallet should be cleared");
    }

    /// @notice Confirming with no pending proposal reverts NoPendingChange
    function test_confirmWalletChange_no_pending_reverts() public {
        vm.prank(owner);
        vm.expectRevert(CharityModule.NoPendingChange.selector);
        module.confirmCharityWalletChange();
    }

    /// @notice proposeCharityWalletChange(address(0)) reverts ZeroWallet
    function test_proposeWalletChange_zero_reverts() public {
        vm.prank(owner);
        vm.expectRevert(CharityModule.ZeroWallet.selector);
        module.proposeCharityWalletChange(address(0));
    }

    /// @notice Non-owner cannot propose wallet change — reverts OwnableUnauthorizedAccount
    function test_proposeWalletChange_nonOwner_reverts() public {
        // proposeCharityWalletChange uses onlyBoardOrOwner — a non-board, non-owner caller
        // receives NotBoardOrOwner, not OwnableUnauthorizedAccount.
        vm.prank(other);
        vm.expectRevert(
            abi.encodeWithSelector(CharityModule.NotBoardOrOwner.selector, other)
        );
        module.proposeCharityWalletChange(makeAddr("x"));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 3. Rate timelock
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice proposeCharityRateChange(501) reverts CharityRateAboveCap(501, 500)
    function test_proposeRateChange_above_cap_reverts() public {
        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(CharityModule.CharityRateAboveCap.selector, 501, 500)
        );
        module.proposeCharityRateChange(501);
    }

    /// @notice proposeCharityRateChange(500) succeeds and sets hasPendingRateChange
    function test_proposeRateChange_at_cap_succeeds() public {
        vm.prank(owner);
        module.proposeCharityRateChange(500);
        assertTrue(module.hasPendingRateChange(), "hasPendingRateChange should be true");
        assertEq(module.pendingCharityBps(), 500);
    }

    /// @notice Confirming rate change immediately reverts TimelockNotElapsed
    function test_confirmRateChange_before_timelock_reverts() public {
        vm.startPrank(owner);
        module.proposeCharityRateChange(300);
        vm.expectRevert(); // TimelockNotElapsed(remaining)
        module.confirmCharityRateChange();
        vm.stopPrank();
    }

    /// @notice Confirming rate change after 30 days updates charityBps
    function test_confirmRateChange_after_30_days_succeeds() public {
        vm.startPrank(owner);
        module.proposeCharityRateChange(100);
        vm.warp(block.timestamp + 30 days);
        module.confirmCharityRateChange();
        vm.stopPrank();
        assertEq(module.charityBps(), 100, "charityBps should be 100 after confirmation");
        assertFalse(module.hasPendingRateChange(), "hasPendingRateChange should be cleared");
    }

    /// @notice cancelCharityRateChange clears hasPendingRateChange
    function test_cancelRateChange() public {
        vm.startPrank(owner);
        module.proposeCharityRateChange(300);
        module.cancelCharityRateChange();
        vm.stopPrank();
        assertFalse(module.hasPendingRateChange(), "hasPendingRateChange should be false after cancel");
        assertEq(module.pendingCharityBps(), 0, "pendingCharityBps should be cleared");
    }

    /// @notice Confirming rate change with no pending reverts NoPendingChange
    function test_confirmRateChange_no_pending_reverts() public {
        vm.prank(owner);
        vm.expectRevert(CharityModule.NoPendingChange.selector);
        module.confirmCharityRateChange();
    }

    /// @notice After rate change to 100 bps, distributeCharity uses updated rate
    function test_distributeCharity_uses_updated_rate() public {
        // Propose and confirm a rate of 100 bps
        vm.startPrank(owner);
        module.proposeCharityRateChange(100);
        vm.warp(block.timestamp + 30 days);
        module.confirmCharityRateChange();
        vm.stopPrank();

        uint256 gross = 1_000e6;
        usdc.approve(address(module), gross);
        (uint256 charityAmount, uint256 remaining) = module.distributeCharity(gross);

        // 100 bps = 1% of 1000e6 = 10e6
        assertEq(charityAmount, 10e6,   "charityAmount should reflect updated rate of 100 bps");
        assertEq(remaining,     990e6,  "remaining should be gross - charityAmount");
    }
}

contracts/test/CommodityMurabahaAdapterT.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {CommodityMurabahaAdapter} from "../adapters/CommodityMurabahaAdapter.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

contract CommodityMurabahaAdapterTest is Test {
    MockERC20 internal usdc;
    CommodityMurabahaAdapter internal adapter;

    address internal owner = makeAddr("owner");
    address internal vault = makeAddr("vault");   // acts as vault for deploy/recall
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal random = makeAddr("random");

    uint256 internal constant SETTLEMENT_WINDOW = 7 days;

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        vm.prank(owner);
        adapter = new CommodityMurabahaAdapter(address(usdc), vault, owner);
    }

    // -----------------------------------------------------------------------
    // test_requestMurabaha_basic
    // amount=1000e6, markupBps=200 (2%) → salePrice=1020e6
    // -----------------------------------------------------------------------
    function test_requestMurabaha_basic() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        assertEq(tradeId, 1, "first trade id should be 1");

        (
            uint256 id,
            address buyer,
            uint256 costAmount,
            uint256 markupBps,
            uint256 salePrice,
            ,,,
            ,
            CommodityMurabahaAdapter.TradeStatus status
        ) = adapter.trades(tradeId);

        assertEq(id, 1);
        assertEq(buyer, alice);
        assertEq(costAmount, 1_000e6);
        assertEq(markupBps, 200);
        assertEq(salePrice, 1_020e6, "salePrice should be 1020e6");
        assertEq(uint8(status), uint8(CommodityMurabahaAdapter.TradeStatus.PENDING));
    }

    // -----------------------------------------------------------------------
    // test_requestMurabaha_zero_markup_reverts
    // -----------------------------------------------------------------------
    function test_requestMurabaha_zero_markup_reverts() public {
        vm.expectRevert(CommodityMurabahaAdapter.InvalidMarkup.selector);
        adapter.requestMurabaha(alice, 1_000e6, 0, SETTLEMENT_WINDOW);
    }

    // -----------------------------------------------------------------------
    // test_requestMurabaha_over_5000bps_reverts
    // -----------------------------------------------------------------------
    function test_requestMurabaha_over_5000bps_reverts() public {
        vm.expectRevert(CommodityMurabahaAdapter.InvalidMarkup.selector);
        adapter.requestMurabaha(alice, 1_000e6, 5001, SETTLEMENT_WINDOW);
    }

    // -----------------------------------------------------------------------
    // test_requestMurabaha_zero_amount_reverts
    // -----------------------------------------------------------------------
    function test_requestMurabaha_zero_amount_reverts() public {
        vm.expectRevert(CommodityMurabahaAdapter.InvalidAmount.selector);
        adapter.requestMurabaha(alice, 0, 200, SETTLEMENT_WINDOW);
    }

    // -----------------------------------------------------------------------
    // test_executeMurabaha_by_owner
    // -----------------------------------------------------------------------
    function test_executeMurabaha_by_owner() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        (,,,,,,uint256 executeTime,,, CommodityMurabahaAdapter.TradeStatus status) = adapter.trades(tradeId);
        assertEq(uint8(status), uint8(CommodityMurabahaAdapter.TradeStatus.EXECUTED));
        assertGt(executeTime, 0);
    }

    // -----------------------------------------------------------------------
    // test_executeMurabaha_wrong_status_reverts (execute twice)
    // -----------------------------------------------------------------------
    function test_executeMurabaha_wrong_status_reverts() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(
                CommodityMurabahaAdapter.InvalidTradeStatus.selector,
                CommodityMurabahaAdapter.TradeStatus.EXECUTED,
                CommodityMurabahaAdapter.TradeStatus.PENDING
            )
        );
        adapter.executeMurabaha(tradeId);
    }

    // -----------------------------------------------------------------------
    // test_settleMurabaha_happy_path
    // -----------------------------------------------------------------------
    function test_settleMurabaha_happy_path() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        // Alice approves salePrice (1020e6) and settles
        usdc.mint(alice, 1_020e6);
        vm.prank(alice);
        usdc.approve(address(adapter), 1_020e6);

        vm.prank(alice);
        adapter.settleMurabaha(tradeId);

        (,,,,,,,,, CommodityMurabahaAdapter.TradeStatus status) = adapter.trades(tradeId);
        assertEq(uint8(status), uint8(CommodityMurabahaAdapter.TradeStatus.SETTLED));
        assertEq(usdc.balanceOf(vault), 1_020e6, "vault should receive salePrice");
        assertEq(adapter.totalProfitRealized(), 20e6, "profit should be 20e6");
    }

    // -----------------------------------------------------------------------
    // test_settleMurabaha_non_buyer_reverts
    // -----------------------------------------------------------------------
    function test_settleMurabaha_non_buyer_reverts() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        vm.prank(bob);
        vm.expectRevert(CommodityMurabahaAdapter.BuyerOnly.selector);
        adapter.settleMurabaha(tradeId);
    }

    // -----------------------------------------------------------------------
    // test_settleMurabaha_after_deadline_reverts
    // -----------------------------------------------------------------------
    function test_settleMurabaha_after_deadline_reverts() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        skip(SETTLEMENT_WINDOW + 1);

        usdc.mint(alice, 1_020e6);
        vm.prank(alice);
        usdc.approve(address(adapter), 1_020e6);

        vm.prank(alice);
        vm.expectRevert(CommodityMurabahaAdapter.DeadlinePassed.selector);
        adapter.settleMurabaha(tradeId);
    }

    // -----------------------------------------------------------------------
    // test_expireTrade_after_deadline
    // -----------------------------------------------------------------------
    function test_expireTrade_after_deadline() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        skip(SETTLEMENT_WINDOW + 1);

        vm.prank(owner);
        adapter.expireTrade(tradeId);

        (,,,,,,,,, CommodityMurabahaAdapter.TradeStatus status) = adapter.trades(tradeId);
        assertEq(uint8(status), uint8(CommodityMurabahaAdapter.TradeStatus.EXPIRED));
    }

    // -----------------------------------------------------------------------
    // test_expireTrade_before_deadline_reverts
    // -----------------------------------------------------------------------
    function test_expireTrade_before_deadline_reverts() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        vm.prank(owner);
        vm.expectRevert(CommodityMurabahaAdapter.DeadlinePassed.selector);
        adapter.expireTrade(tradeId);
    }

    // -----------------------------------------------------------------------
    // test_max_active_trades_dos_guard — 51st request reverts
    // -----------------------------------------------------------------------
    function test_max_active_trades_dos_guard() public {
        for (uint256 i = 0; i < 50; i++) {
            adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);
        }

        vm.expectRevert(CommodityMurabahaAdapter.InvalidAmount.selector);
        adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);
    }

    // -----------------------------------------------------------------------
    // test_active_trade_removal_o1
    // Request and settle two trades, verifying activeTrades stays consistent
    // -----------------------------------------------------------------------
    function test_active_trade_removal_o1() public {
        uint256 id1 = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);
        uint256 id2 = adapter.requestMurabaha(bob, 500e6, 100, SETTLEMENT_WINDOW);

        // Execute and settle id1
        vm.prank(owner);
        adapter.executeMurabaha(id1);
        usdc.mint(alice, 1_020e6);
        vm.prank(alice);
        usdc.approve(address(adapter), 1_020e6);
        vm.prank(alice);
        adapter.settleMurabaha(id1);

        // Only id2 should remain active
        CommodityMurabahaAdapter.MurabahaTrade[] memory active = adapter.getActiveTrades();
        assertEq(active.length, 1, "only 1 trade should remain active");
        assertEq(active[0].id, id2, "remaining active trade should be id2");

        // Execute and settle id2
        vm.prank(owner);
        adapter.executeMurabaha(id2);
        usdc.mint(bob, 505e6); // 500e6 * 100/10000 = 5e6 markup
        vm.prank(bob);
        usdc.approve(address(adapter), 505e6);
        vm.prank(bob);
        adapter.settleMurabaha(id2);

        active = adapter.getActiveTrades();
        assertEq(active.length, 0, "no active trades should remain");
    }

    // -----------------------------------------------------------------------
    // test_deploy_and_recall
    // -----------------------------------------------------------------------
    function test_deploy_and_recall() public {
        // Mint USDC to vault so it can transfer to adapter via deploy
        usdc.mint(vault, 500e6);

        // vault calls deploy (adapter just records totalDeployed)
        vm.prank(vault);
        adapter.deploy(500e6);
        assertEq(adapter.totalDeployed(), 500e6, "totalDeployed should be 500e6");

        // Mint the USDC to adapter so recall can actually transfer
        usdc.mint(address(adapter), 500e6);

        vm.prank(vault);
        adapter.recall(500e6);
        assertEq(adapter.totalDeployed(), 0, "totalDeployed should be 0 after recall");
        assertEq(usdc.balanceOf(vault), 1_000e6, "vault should receive recalled USDC (500 original + 500 recalled)");
    }

    // -----------------------------------------------------------------------
    // test_getActiveTrades_returns_correct_list
    // -----------------------------------------------------------------------
    function test_getActiveTrades_returns_correct_list() public {
        uint256 id1 = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);
        uint256 id2 = adapter.requestMurabaha(bob, 500e6, 100, SETTLEMENT_WINDOW);
        uint256 id3 = adapter.requestMurabaha(random, 2_000e6, 300, SETTLEMENT_WINDOW);

        CommodityMurabahaAdapter.MurabahaTrade[] memory active = adapter.getActiveTrades();
        assertEq(active.length, 3, "should return 3 active trades");
        assertEq(active[0].id, id1);
        assertEq(active[1].id, id2);
        assertEq(active[2].id, id3);
    }

    // -----------------------------------------------------------------------
    // test_o1_removal_middle_trade — request 3 trades, settle middle one (id=2)
    // After swap-and-pop, activeTrades should contain [1,3] in some order
    // -----------------------------------------------------------------------
    function test_o1_removal_middle_trade() public {
        uint256 id1 = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);
        uint256 id2 = adapter.requestMurabaha(bob, 500e6, 100, SETTLEMENT_WINDOW);
        uint256 id3 = adapter.requestMurabaha(random, 2_000e6, 300, SETTLEMENT_WINDOW);

        // Execute id2
        vm.prank(owner);
        adapter.executeMurabaha(id2);

        // Settle id2
        uint256 salePrice2 = 500e6 + (500e6 * 100) / 10_000; // 505e6
        usdc.mint(bob, salePrice2);
        vm.prank(bob);
        usdc.approve(address(adapter), salePrice2);
        vm.prank(bob);
        adapter.settleMurabaha(id2);

        // activeTrades should have 2 elements: id1 and id3
        CommodityMurabahaAdapter.MurabahaTrade[] memory active = adapter.getActiveTrades();
        assertEq(active.length, 2, "two trades should remain");

        bool foundId1;
        bool foundId3;
        for (uint256 i = 0; i < active.length; i++) {
            if (active[i].id == id1) foundId1 = true;
            if (active[i].id == id3) foundId3 = true;
        }
        assertTrue(foundId1, "id1 should still be active");
        assertTrue(foundId3, "id3 should still be active");
    }

    // -----------------------------------------------------------------------
    // test_executeMurabaha_after_deadline_reverts
    // -----------------------------------------------------------------------
    function test_executeMurabaha_after_deadline_reverts() public {
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, SETTLEMENT_WINDOW);

        skip(SETTLEMENT_WINDOW + 1);

        vm.prank(owner);
        vm.expectRevert(CommodityMurabahaAdapter.DeadlinePassed.selector);
        adapter.executeMurabaha(tradeId);
    }

    // -----------------------------------------------------------------------
    // test_markup_boundary — exactly 5000 bps is valid, 5001 reverts
    // -----------------------------------------------------------------------
    function test_markup_boundary() public {
        // 5000 bps should succeed
        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 5000, SETTLEMENT_WINDOW);
        assertEq(tradeId, 1);

        // 5001 bps should revert
        vm.expectRevert(CommodityMurabahaAdapter.InvalidMarkup.selector);
        adapter.requestMurabaha(alice, 1_000e6, 5001, SETTLEMENT_WINDOW);
    }
}

contracts/test/ForkRehearsalSteps5And7.t.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test, console, Vm} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

// Task M: local legacy ABIs, messenger and 116-byte fixtures intentionally target deployed pre-Task-M bytecode.
// ─── Minimal contract interfaces (deployed on Arc Testnet) ────────────────────

interface IShariahVaultV2 {
    function deposit(uint256 assets, address receiver) external returns (uint256);
    function redeem(uint256 shares, address receiver, address owner_) external returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function totalAssets() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function lockedProfit() external view returns (uint256);
    function claimMusharakahProfit(uint256 grossProfit) external;
    function setTokenMessenger(address messenger) external;
    function setMessageTransmitter(address transmitter) external;
    function deployCrossChain(uint32 destDomain, bytes32 recipient, uint256 amount) external;
    function settleCrossChainWithMessage(uint64 nonce, bytes calldata message, bytes calldata attestation) external;
    function tokenMessenger() external view returns (address);
    function messageTransmitter() external view returns (address);
    function sourceDomain() external view returns (uint32);
    function maxPendingCrossChainBps() external view returns (uint256);
    function pendingCrossChain(uint64 nonce) external view returns (uint256);
    function owner() external view returns (address);
    function profitUnlockPeriod() external view returns (uint256);
    function hurdlePrincipal() external view returns (uint256);
    function purificationEscrow() external view returns (address);
    function setMaxPendingCrossChainBps(uint256 bps) external;
}

// ─── Mock token messenger (replaces real CCTP messenger in Test 1) ────────────
//     depositForBurnWithCaller: does NOT actually burn — just mints dummy USDC
//     to the caller and returns an incrementing nonce.
contract MinimalMockMessenger {
    address public usdc;
    uint64 public nextNonce = 1_000;

    constructor(address usdc_) {
        usdc = usdc_;
    }

    /// @dev Called by vault.deployCrossChain. Returns nonce; leaves vault's USDC balance
    ///      unchanged (no real burn needed on the fork — we just need the nonce registered).
    function depositForBurnWithCaller(
        uint256,       /* amount */
        uint32,        /* destinationDomain */
        bytes32,       /* mintRecipient */
        address,       /* burnToken */
        bytes32        /* destinationCaller */
    ) external returns (uint64 nonce) {
        nonce = nextNonce++;
    }
}

// ─── Mock message transmitter (replaces real CCTP transmitter in Test 1) ─────
//     receiveMessage: mints a fixed `mintAmount` of USDC to `vault` and returns true.
//     This simulates the transmitter minting (amount - feeExecuted) to mintRecipient.
contract MinimalMockTransmitter {
    address public usdc;
    address public vault;
    uint256 public mintAmount;

    constructor(address usdc_, address vault_, uint256 mintAmount_) {
        usdc     = usdc_;
        vault    = vault_;
        mintAmount = mintAmount_;
    }

    function receiveMessage(bytes calldata, bytes calldata) external returns (bool) {
        // Mint net settled USDC (amount - feeExecuted) directly to vault.
        IMintableERC20(usdc).mint(vault, mintAmount);
        return true;
    }
}

interface IMintableERC20 {
    function mint(address to, uint256 amount) external;
    function balanceOf(address) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner_, address spender) external view returns (uint256);
    function decimals() external view returns (uint8);
    function totalSupply() external view returns (uint256);
}

// ─── Minimal MockERC20 deployed inline for etch ───────────────────────────────
//     Etched at the USDC predeploy address so vault calls hit real EVM storage.
contract EtchableUSDC {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    uint256 private _totalSupply;

    string  public constant name     = "USD Coin";
    string  public constant symbol   = "USDC";
    uint8   public constant decimals = 6;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner_, address indexed spender, uint256 value);

    function totalSupply() external view returns (uint256) { return _totalSupply; }
    function balanceOf(address a) external view returns (uint256) { return _balances[a]; }
    function allowance(address o, address s) external view returns (uint256) { return _allowances[o][s]; }

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
        _totalSupply  += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(_balances[msg.sender] >= amount, "ERC20: insufficient balance");
        _balances[msg.sender] -= amount;
        _balances[to]         += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(_balances[from] >= amount, "ERC20: insufficient balance");
        uint256 allowed = _allowances[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "ERC20: insufficient allowance");
            _allowances[from][msg.sender] = allowed - amount;
        }
        _balances[from] -= amount;
        _balances[to]   += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    /// @dev forceApprove (SafeERC20 uses this via IERC20.approve with no prior check)
    function forceApprove(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
}

// ─── CCTP V2 message builder library ─────────────────────────────────────────
//
//  Outer MessageV2 header (116 bytes, big-endian):
//    [0..3]    version       uint32
//    [4..7]    sourceDomain  uint32
//    [8..11]   destDomain    uint32
//    [12..19]  nonce         uint64
//    [20..51]  sender        bytes32
//    [52..83]  recipient     bytes32  (local token messenger)
//    [84..115] destCaller    bytes32
//
//  BurnMessageV2 body (228 bytes, body offset = header offset + field offset):
//    body[0..3]     version          uint32   (4 bytes)
//    body[4..35]    burnToken        bytes32  (32 bytes)
//    body[36..67]   mintRecipient    bytes32  (32 bytes)  ← vault address
//    body[68..99]   amount           uint256  (32 bytes)  ← gross amount
//    body[100..131] messageSender    bytes32  (32 bytes)
//    body[132..163] maxFee           uint256  (32 bytes)  ← fee ceiling
//    body[164..195] feeExecuted      uint256  (32 bytes)  ← ACTUAL fee (offset fix under test)
//    body[196..227] expirationBlock  uint256  (32 bytes)
//
//  Total: 116 + 228 = 344 bytes.
library CctpV2MsgBuilder {
    function build(
        uint32  sourceDomain_,
        uint32  destDomain_,
        uint64  nonce_,
        address mintRecipient_,
        uint256 amount_,
        uint256 maxFee_,
        uint256 feeExecuted_
    ) internal view returns (bytes memory msg_) {
        // ── Header (116 bytes) ─────────────────────────────────────────────
        bytes memory header = new bytes(116);

        // version = 2 at [0..3]
        header[3] = bytes1(uint8(2));

        // sourceDomain at [4..7]
        header[4] = bytes1(uint8(sourceDomain_ >> 24));
        header[5] = bytes1(uint8(sourceDomain_ >> 16));
        header[6] = bytes1(uint8(sourceDomain_ >> 8));
        header[7] = bytes1(uint8(sourceDomain_));

        // destDomain at [8..11]
        header[8]  = bytes1(uint8(destDomain_ >> 24));
        header[9]  = bytes1(uint8(destDomain_ >> 16));
        header[10] = bytes1(uint8(destDomain_ >> 8));
        header[11] = bytes1(uint8(destDomain_));

        // nonce at [12..19] (uint64, big-endian)
        for (uint256 i = 0; i < 8; i++) {
            header[19 - i] = bytes1(uint8(nonce_ >> (i * 8)));
        }

        // sender (bytes32) at [20..51] — leave zero (not checked by vault)
        // Outer recipient is the local messenger; body mintRecipient is the vault.
        bytes32 messengerWord = bytes32(uint256(uint160(IShariahVaultV2(mintRecipient_).tokenMessenger())));
        for (uint256 i = 0; i < 32; i++) header[52 + i] = messengerWord[i];
        // destCaller (bytes32) at [84..115] — leave zero

        // ── Body (228 bytes) ──────────────────────────────────────────────
        bytes memory body = new bytes(228);

        // body[0..3] version = 2
        body[3] = bytes1(uint8(2));

        // body[4..35] burnToken — leave zero (not validated by vault in settle path)

        // body[36..67] mintRecipient (the vault address, left-padded to bytes32)
        bytes32 recip = bytes32(uint256(uint160(mintRecipient_)));
        for (uint256 i = 0; i < 32; i++) {
            body[36 + i] = recip[i];
        }

        // body[68..99] amount (uint256)
        bytes32 amt = bytes32(amount_);
        for (uint256 i = 0; i < 32; i++) {
            body[68 + i] = amt[i];
        }

        // body[100..131] messageSender — leave zero

        // body[132..163] maxFee (uint256)
        bytes32 mf = bytes32(maxFee_);
        for (uint256 i = 0; i < 32; i++) {
            body[132 + i] = mf[i];
        }

        // body[164..195] feeExecuted (uint256) — THIS is the offset the L1 fix targets
        bytes32 fe = bytes32(feeExecuted_);
        for (uint256 i = 0; i < 32; i++) {
            body[164 + i] = fe[i];
        }

        // body[196..227] expirationBlock — leave zero

        msg_ = abi.encodePacked(header, body);
        // Confirm length exactly 344 bytes
        assert(msg_.length == 344);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Test contract
// ─────────────────────────────────────────────────────────────────────────────
contract ForkRehearsalSteps5And7 is Test {

    // ── Deployed contract addresses ───────────────────────────────────────
    address constant VAULT         = 0xba094D5B01F4fd245EA345Be6B8ac833488c81B0;
    address constant ESCROW        = 0xcC58b11c3Cd251a44989fEf1f05BdcB0e16375ff;
    address constant CHARITY_MOD   = 0x1D05a0010C78B984b0De2735A6E868E9c9f5d99F;
    address constant TREASURY_MOD  = 0xF5B550B87476a4359f1307AeFC425cCC6E2530f5;
    address constant USDC_ADDR     = 0x3600000000000000000000000000000000000000;
    address constant OWNER         = 0x3D23214d59CA3582628FffFE44D0Df1CC73D98f9;

    IShariahVaultV2 vault;
    IMintableERC20  usdc;

    // ── setUp: etch MockERC20 at USDC predeploy, fund owner ───────────────
    function setUp() public {
        // Fork Arc Testnet
        vm.createSelectFork("arc_testnet");

        vault = IShariahVaultV2(VAULT);
        usdc  = IMintableERC20(USDC_ADDR);

        // Replace the Arc-native USDC predeploy with a standard EVM ERC20.
        // The vault's stored `asset()` still points to USDC_ADDR, but all
        // ERC20 calls now hit our in-process implementation (no StackUnderflow).
        EtchableUSDC mock = new EtchableUSDC();
        vm.etch(USDC_ADDR, address(mock).code);

        // Confirm etch worked
        assertEq(usdc.decimals(), 6, "USDC etch: wrong decimals");
    }

    // ─────────────────────────────────────────────────────────────────────
    // TEST 1: settleCrossChainWithMessage with feeExecuted < maxFee
    //
    // Verifies: the decoder reads feeExecuted at body[164], NOT body[132].
    // ─────────────────────────────────────────────────────────────────────
    function test_settleCrossChain_feeOffset_fix() public {
        // ── Step 1: fund and deposit ─────────────────────────────────────
        vm.prank(OWNER);
        usdc.mint(OWNER, 1_000e6);

        vm.startPrank(OWNER);
        usdc.approve(VAULT, 500e6);
        vault.deposit(500e6, OWNER);
        vm.stopPrank();

        uint256 assetsAfterDeposit = vault.totalAssets();
        assertGe(assetsAfterDeposit, 500e6, "T1: deposit didn't increase totalAssets");

        // ── Step 2: deploy mock messenger + transmitter, wire them up ────
        //    The transmitter will mint exactly 98e6 (amount=100e6 minus feeExecuted=2e6).
        MinimalMockMessenger   messenger   = new MinimalMockMessenger(USDC_ADDR);
        MinimalMockTransmitter transmitter = new MinimalMockTransmitter(USDC_ADDR, VAULT, 98e6);

        vm.startPrank(OWNER);
        vault.setTokenMessenger(address(messenger));
        vault.setMessageTransmitter(address(transmitter));

        _unblockLegacyFlag();

        // Raise maxPendingCrossChainBps to allow a 100e6 deployment from ~500e6 assets.
        // Default 2000 bps = 20% of totalAssets (~100e6 of 500e6 is exactly 20%).
        // Use 2500 bps to give comfortable headroom.
        vault.setMaxPendingCrossChainBps(2_500);
        vm.stopPrank();

        // ── Step 3: deployCrossChain to register nonce ───────────────────
        uint32  destDomain = 0;   // Ethereum; not sourceDomain (26=Arc)
        bytes32 recipient  = bytes32(uint256(uint160(VAULT))); // vault as mintRecipient

        // Approve messenger to pull from vault (vault will forceApprove internally, but
        // we need vault to have approved messenger). Actually vault calls forceApprove
        // on USDC for the messenger before the depositForBurnWithCaller call.
        // The mock messenger doesn't actually pull tokens, so no pre-approval needed.

        vm.recordLogs();
        vm.prank(OWNER);
        vault.deployCrossChain(destDomain, recipient, 100e6);

        // Extract emitted nonce from CapitalDeployedCrossChain event
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint64 emittedNonce;
        bytes32 eventSig = keccak256("CapitalDeployedCrossChain(uint32,bytes32,uint256,uint64)");
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == eventSig) {
                // nonce is the last non-indexed param; decode from data
                // event: (uint32 indexed dest, bytes32 indexed recipient, uint256 amount, uint64 nonce)
                // data contains: amount (uint256) + nonce (uint64, packed as uint256)
                (, uint64 n) = abi.decode(logs[i].data, (uint256, uint64));
                emittedNonce = n;
                break;
            }
        }
        assertGt(emittedNonce, 0, "T1: failed to capture nonce from event");
        console.log("T1: emitted nonce =", emittedNonce);

        // Confirm nonce registered
        uint256 pendingAmt = vault.pendingCrossChain(emittedNonce);
        assertEq(pendingAmt, 100e6, "T1: pendingCrossChain not registered");

        // ── Step 4: build 344-byte CCTP V2 message ───────────────────────
        //   amount=100e6, maxFee=5e6 at body[132], feeExecuted=2e6 at body[164].
        //   Return source matches the outbound destination; return nonce is independent.
        uint32 srcDomain = vault.sourceDomain(); // 26 = Arc Testnet
        bytes memory message = CctpV2MsgBuilder.build(
            destDomain,         // return source is the outbound destination
            srcDomain,          // return destination is the local domain
            emittedNonce + 1,   // independent return nonce
            VAULT,              // mintRecipient (must equal vault address)
            100e6,              // gross amount
            5e6,                // maxFee  — at body offset 132
            2e6                 // feeExecuted — at body offset 164 (the fix under test)
        );
        assertEq(message.length, 344, "T1: message must be exactly 344 bytes");

        // The transmitter will mint 98e6 to vault when receiveMessage is called.
        // The vault's decoder reads feeExecuted=2e6, computes expectedNet=98e6,
        // and then checks expectedNet == received (98e6 == 98e6). Should NOT revert.

        // ── Step 5: call settleCrossChainWithMessage ──────────────────────
        uint256 assetsBefore = vault.totalAssets();
        bytes memory fakeAttestation = hex""; // transmitter mock ignores attestation

        // Check for CrossChainFeeDeducted and CrossChainSettled events
        vm.expectEmit(true, false, false, true, VAULT);
        emit CrossChainFeeDeducted(emittedNonce, 2e6);

        vm.prank(OWNER);
        vault.settleCrossChainWithMessage(emittedNonce, message, fakeAttestation);

        // ── Step 6: assert totalAssets increased by 98e6 ─────────────────
        uint256 assetsAfter = vault.totalAssets();
        // deployCrossChain incremented totalDeployed by 100e6 and deducted from liquid balance.
        // _doSettle decrements totalDeployed by 100e6 (sent).
        // receiveMessage minted 98e6 to vault (net received).
        // Net change vs assetsBefore: +98e6 - 100e6 = -2e6 (fee cost absorbed).
        // But assetsBefore included the locked 100e6 in totalDeployed.
        // After settle: totalDeployed -= 100e6, liquid balance += 98e6.
        // So assetsAfter = assetsAfterDeposit - 100e6(deployed gone) + 98e6(received) 
        //                  + remaining_deployed = assetsAfterDeposit - 2e6
        // Simpler: assetsAfter = assetsBefore - 2e6 (fee absorbed as loss).
        assertApproxEqAbs(
            assetsAfter,
            assetsBefore - 2e6,
            1e4, // 0.01 USDC tolerance for rounding
            "T1: totalAssets should have decreased by exactly feeExecuted=2e6"
        );

        // Specifically: it is NOT assetsBefore-5e6 (maxFee) and NOT assetsBefore (no loss)
        assertTrue(assetsAfter < assetsBefore - 1e6,  "T1: fee must have been deducted (>1e6)");
        assertTrue(assetsAfter > assetsBefore - 5e6,  "T1: fee must NOT be 5e6 (maxFee, not feeExecuted)");

        // ── Step 7: assert nonce cleared (settled) ────────────────────────
        assertEq(vault.pendingCrossChain(emittedNonce), 0, "T1: nonce should be cleared after settle");

        console.log("T1 PASS: settleCrossChainWithMessage correctly used feeExecuted=2e6 (not maxFee=5e6)");
        console.log("  assetsBefore:", assetsBefore);
        console.log("  assetsAfter: ", assetsAfter);
        console.log("  delta:       ", assetsBefore - assetsAfter);
    }

    // Event declarations for vm.expectEmit
    event CrossChainFeeDeducted(uint64 indexed nonce, uint256 feeExecuted);
    event CrossChainSettled(uint64 indexed nonce, uint256 amount, uint256 shortfall);

    // ─────────────────────────────────────────────────────────────────────
    // TEST 1b: Wrong fee offset causes revert — regression guard
    //
    // If the decoder mistakenly read body[132] (maxFee=5e6) as feeExecuted,
    // it would compute expectedNet = 95e6, but transmitter mints 98e6.
    // settleCrossChainWithMessage would revert MessageAmountMismatch.
    //
    // This test confirms the FIX is correct: a message with feeExecuted=2e6
    // at body[164] does NOT trigger MessageAmountMismatch.
    // ─────────────────────────────────────────────────────────────────────
    function test_wrongFeeOffset_wouldCauseMismatch() public {
        // Re-run setup in isolation (each test gets a fresh fork snapshot via setUp)
        vm.prank(OWNER);
        usdc.mint(OWNER, 500e6);

        vm.startPrank(OWNER);
        usdc.approve(VAULT, 500e6);
        vault.deposit(500e6, OWNER);

        MinimalMockMessenger   messenger   = new MinimalMockMessenger(USDC_ADDR);
        // Transmitter mints 98e6 (simulates feeExecuted=2e6 being actually deducted)
        MinimalMockTransmitter transmitter = new MinimalMockTransmitter(USDC_ADDR, VAULT, 98e6);

        vault.setTokenMessenger(address(messenger));
        vault.setMessageTransmitter(address(transmitter));
        vault.setMaxPendingCrossChainBps(2_500);
        _unblockLegacyFlag();

        vm.recordLogs();
        vault.deployCrossChain(0, bytes32(uint256(uint160(VAULT))), 100e6);
        vm.stopPrank();

        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint64 emittedNonce;
        bytes32 eventSig = keccak256("CapitalDeployedCrossChain(uint32,bytes32,uint256,uint64)");
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == eventSig) {
                (, uint64 n) = abi.decode(logs[i].data, (uint256, uint64));
                emittedNonce = n;
                break;
            }
        }

        // Build a CORRECTLY-encoded message (feeExecuted=2e6 at body[164]).
        // The decoder MUST read body[164] and get 2e6.
        // expectedNet = 100e6 - 2e6 = 98e6 == transmitter mint. No revert.
        bytes memory goodMessage = CctpV2MsgBuilder.build(
            0, vault.sourceDomain(), emittedNonce, VAULT,
            100e6, 5e6 /* maxFee at body[132] */, 2e6 /* feeExecuted at body[164] */
        );

        // Should succeed (no revert)
        vm.prank(OWNER);
        vault.settleCrossChainWithMessage(emittedNonce, goodMessage, hex"");
        console.log("T1b PASS: correct offset message settled without MessageAmountMismatch");
    }

    // ─────────────────────────────────────────────────────────────────────
    // TEST 2: PurificationEscrow.executeWaterfall + claimMusharakahProfit
    //
    // Confirms the profit waterfall runs end-to-end on the fork.
    // Exposes a contract integration bug: CharityModule.distributeCharity
    // checks msg.sender == vault (ShariahVaultV2), but it is called by
    // PurificationEscrow — causing a NotVault revert.
    // ─────────────────────────────────────────────────────────────────────
    function test_claimMusharakahProfit_waterfall() public {
        address depositor = makeAddr("depositor");

        // ── Step 1: fund deployer and depositor ──────────────────────────
        vm.prank(OWNER);
        usdc.mint(OWNER, 400e6);
        vm.prank(OWNER);
        usdc.mint(depositor, 100e6);

        // ── Step 2a: depositor deposits 100e6 ────────────────────────────
        vm.startPrank(depositor);
        usdc.approve(VAULT, 100e6);
        uint256 depositorShares = vault.deposit(100e6, depositor);
        vm.stopPrank();

        assertGt(depositorShares, 0, "T2: depositor should have received shares");
        console.log("T2: depositor shares:", depositorShares);

        // ── Step 2b: deployer deposits 100e6 (establishes share baseline) ─
        vm.startPrank(OWNER);
        usdc.approve(VAULT, 100e6);
        uint256 ownerShares = vault.deposit(100e6, OWNER);
        vm.stopPrank();

        uint256 assetsAfterDeposits = vault.totalAssets();
        console.log("T2: totalAssets after deposits:", assetsAfterDeposits);
        assertApproxEqAbs(assetsAfterDeposits, 200e6, 1e4, "T2: expected ~200e6 after both deposits");

        // ── Step 3: inject 10e6 synthetic profit into vault ──────────────
        // vm.deal / direct mint bypasses the Arc predeploy StackUnderflow.
        vm.prank(OWNER);
        usdc.mint(VAULT, 10e6);

        uint256 assetsWithProfit = vault.totalAssets();
        console.log("T2: totalAssets with synthetic profit:", assetsWithProfit);
        assertApproxEqAbs(assetsWithProfit, 210e6, 1e4, "T2: expected ~210e6 after profit injection");

        // ── Step 4: call claimMusharakahProfit(10e6) as owner ────────────
        //
        // KNOWN CONTRACT BUG: CharityModule.distributeCharity() checks
        //   msg.sender == vault (ShariahVaultV2 = 0xba094D...)
        // but it is called by PurificationEscrow (0xcC58b11c...)
        // This will revert with CharityModule.NotVault().
        //
        // We test the revert here to confirm the bug is present on the
        // deployed contracts, and report it as a contract bug below.
        //
        // The escrow's executeWaterfall step 3:
        //   charityModule.distributeCharity(afterPurification)  <- msg.sender = escrow
        // CharityModule:
        //   if (msg.sender != vault) revert NotVault()          <- vault = ShariahVaultV2
        //
        // Therefore claimMusharakahProfit always reverts on the current deployment.

        vm.expectRevert(); // CharityModule.NotVault
        vm.prank(OWNER);
        vault.claimMusharakahProfit(10e6);

        console.log("T2: claimMusharakahProfit correctly reverted (CharityModule NotVault bug confirmed)");

        // ── Step 4b: verify deposits and redemptions still work ──────────
        // The waterfall bug does not block deposits or redemptions.
        uint256 depositorBalanceBefore = usdc.balanceOf(depositor);

        vm.startPrank(depositor);
        // ERC4626 redeem: need vault to check allowance for depositor burning own shares
        // shares owned by depositor; redeem all
        uint256 received = vault.redeem(depositorShares, depositor, depositor);
        vm.stopPrank();

        uint256 depositorBalanceAfter = usdc.balanceOf(depositor);
        console.log("T2: depositor redeemed, received:", received);
        console.log("T2: depositor USDC after redeem:", depositorBalanceAfter);

        // Depositor should receive at least their original 100e6 (no loss to depositor).
        // Since profit is not locked (claimMusharakahProfit reverted, no lockProfit),
        // the extra 10e6 minted to vault IS reflected in totalAssets and thus in share price.
        // Depositor owns ~50% of shares (deposited 100e6 of 200e6 total).
        // They should get back ~100e6 + ~5e6 (their pro-rata share of the 10e6 profit).
        assertGe(received, 100e6, "T2: depositor should receive >= their deposit (no principal loss)");

        console.log("T2 PASS: deposits and redemptions work; waterfall bug recorded");
    }

    // ─────────────────────────────────────────────────────────────────────
    // TEST 2b: Verify escrow.executeWaterfall can be called directly
    //          (bypassing the CharityModule NotVault check by calling
    //          executeWaterfall with the vault impersonated)
    //
    // This simulates what a FIXED deployment would look like:
    // If CharityModule.vault were set to PurificationEscrow, the waterfall
    // would succeed. We test that premise by directly pranking the vault address.
    // ─────────────────────────────────────────────────────────────────────
    function test_escrow_executeWaterfall_charityNotVault_revert() public {
        // Fund the escrow with profit to distribute
        vm.prank(OWNER);
        usdc.mint(VAULT, 100e6);

        // Vault must approve escrow for grossProfit pull
        // (ShariahVault.claimMusharakahProfit does forceApprove before calling escrow)
        vm.prank(VAULT);
        usdc.approve(ESCROW, 10e6);

        // Call executeWaterfall directly as the vault (msg.sender == vault passes in escrow)
        // This simulates the escrow being called correctly.
        // The escrow then calls charityModule.distributeCharity -- which checks
        // msg.sender == CharityModule.vault (ShariahVaultV2).
        // msg.sender here is ESCROW, not ShariahVaultV2 -> REVERT NotVault.
        vm.expectRevert();
        vm.prank(VAULT);
        (bool success,) = ESCROW.call(
            abi.encodeWithSignature("executeWaterfall(uint256,uint256,uint256)", 10e6, 365 days, 100e6)
        );
        // If expectRevert was triggered, success is irrelevant.
        // The revert proves: CharityModule.vault must be PurificationEscrow, not ShariahVaultV2.
        (success); // suppress unused variable warning
        console.log("T2b PASS: executeWaterfall reverts with NotVault as expected (CharityModule wired to wrong caller)");
    }

    /// @dev The live Arc Testnet vault was deployed before Task N1 and still carries the old
    ///      `goldCrossChainBlocked` flag (set true). N1 removes the flag from the source, so a
    ///      fresh deployment has nothing to clear. Call it by raw selector if it exists; a
    ///      redeployed vault simply has no such function and the call is a no-op.
    ///      Remove this helper once the testnet vault is redeployed from the N1 source.
    function _unblockLegacyFlag() internal {
        (bool ok,) = VAULT.call(abi.encodeWithSignature("setGoldCrossChainBlocked(bool)", false));
        ok;
    }
}

contracts/test/FuzzAutonomousVault.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

// Minimal passthrough adapter — recall sends USDC back to vault
contract FuzzMockAdapter is IStrategyAdapter {
    address public override vault;
    address public usdc;
    constructor(address v, address u) { vault = v; usdc = u; }
    function deploy(uint256 a) external override returns (uint256) { return a; }
    function recall(uint256 a) external override returns (uint256) {
        IERC20(usdc).transfer(vault, a);
        return a;
    }
    function currentValue() external view override returns (uint256) {
        return IERC20(usdc).balanceOf(address(this));
    }
    function protocolName() external pure override returns (string memory) { return "FuzzMock"; }
}

contract FuzzAutonomousVault is Test {
    MockERC20 internal usdc;
    AutonomousVault internal vault;

    address internal owner = makeAddr("owner");
    address internal alice = makeAddr("alice");
    uint32 internal constant SRC = 1;

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        vm.prank(owner);
        vault = new AutonomousVault(IERC20(address(usdc)), owner, SRC);
    }

    // -----------------------------------------------------------------------
    // Invariant: depositor always redeems ≥ their deposited amount (no loss)
    // -----------------------------------------------------------------------
    function testFuzz_deposit_redeem_roundtrip(uint96 amount) public {
        vm.assume(amount > 0 && amount <= 1_000_000e6); // up to $1B
        usdc.mint(alice, amount);
        vm.prank(alice);
        usdc.approve(address(vault), amount);

        vm.prank(alice);
        uint256 shares = vault.deposit(amount, alice);

        vm.prank(alice);
        vault.approve(address(vault), shares);
        vm.prank(alice);
        uint256 returned = vault.redeem(shares, alice, alice);

        // Due to rounding (virtual shares offset), returned may be amount or amount-1
        assertGe(returned + 1, amount, "must get back at least amount-1");
    }

    // -----------------------------------------------------------------------
    // Invariant: totalAssets = vault balance + totalDeployed at all times
    // -----------------------------------------------------------------------
    function testFuzz_totalAssets_accounting(uint96 deposit_, uint96 deploy_) public {
        uint256 depositAmt = bound(deposit_, 1e6, 10_000_000e6);
        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        uint256 maxDeploy = (depositAmt * 8_000) / 10_000;
        uint256 deployAmt = bound(deploy_, 0, maxDeploy);

        if (deployAmt > 0) {
            address strat = makeAddr("strat");
            vm.prank(owner);
            vault.deployCapital(strat, deployAmt, "");
        }

        uint256 vaultBalance = usdc.balanceOf(address(vault));
        assertEq(
            vault.totalAssets(),
            vaultBalance + vault.totalDeployed(),
            "totalAssets must equal balance + deployed"
        );
    }

    // -----------------------------------------------------------------------
    // Invariant: deployCapital always rejects amounts that exceed bps cap
    // -----------------------------------------------------------------------
    function testFuzz_deploy_cap_enforced(uint96 depositAmt_, uint96 deployAmt_) public {
        uint256 depositAmt = bound(depositAmt_, 1e6, 100_000e6);
        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        address strat = makeAddr("strat");
        uint256 maxAllowed = (vault.totalAssets() * vault.maxAllocationBps()) / 10_000;
        uint256 deployAmt = bound(deployAmt_, maxAllowed + 1, maxAllowed + 10_000e6);

        vm.prank(owner);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.deployCapital(strat, deployAmt, "");
    }

    // -----------------------------------------------------------------------
    // Invariant: deployCapital within cap always succeeds + totalDeployed correct
    // -----------------------------------------------------------------------
    function testFuzz_deploy_within_cap_succeeds(uint96 depositAmt_, uint16 bpsFraction) public {
        uint256 depositAmt = bound(depositAmt_, 100e6, 10_000_000e6);
        // bpsFraction from 1 to 8000 of totalAssets
        uint256 fraction = bound(bpsFraction, 1, 8_000);

        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        uint256 deployAmt = (depositAmt * fraction) / 10_000;
        if (deployAmt == 0) return;

        address strat = makeAddr("strat");
        vm.prank(owner);
        vault.deployCapital(strat, deployAmt, "");

        assertEq(vault.totalDeployed(), deployAmt);
    }

    // -----------------------------------------------------------------------
    // Invariant: after returnCapital, totalDeployed decrements correctly
    // -----------------------------------------------------------------------
    function testFuzz_returnCapital_decrements(uint96 depositAmt_, uint16 bpsFraction) public {
        uint256 depositAmt = bound(depositAmt_, 100e6, 10_000_000e6);
        uint256 fraction = bound(bpsFraction, 1, 7_999);

        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        uint256 deployAmt = (depositAmt * fraction) / 10_000;
        if (deployAmt == 0) return;

        address strat = makeAddr("strat");
        vm.prank(owner);
        vault.deployCapital(strat, deployAmt, "");

        // Strategy returns capital
        vm.prank(strat);
        usdc.approve(address(vault), deployAmt);
        vm.prank(owner);
        vault.returnCapital(strat, deployAmt);

        assertEq(vault.totalDeployed(), 0);
    }

    // -----------------------------------------------------------------------
    // Fuzz: setMaxAllocationBps only accepts 0–9500
    // -----------------------------------------------------------------------
    function testFuzz_setMaxAllocationBps(uint256 bps) public {
        if (bps > 9_500) {
            vm.prank(owner);
            vm.expectRevert(AutonomousVault.InvalidBps.selector);
            vault.setMaxAllocationBps(bps);
        } else {
            vm.prank(owner);
            vault.setMaxAllocationBps(bps);
            assertEq(vault.maxAllocationBps(), bps);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: cross-chain deploy tracks pendingCrossChain[nonce] correctly
    // -----------------------------------------------------------------------
    function testFuzz_deployCrossChain_pending(uint96 depositAmt_, uint96 crossAmt_) public {
        uint256 depositAmt = bound(depositAmt_, 1_000e6, 50_000e6);
        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        // Deploy a minimal mock messenger inline
        MockTokenMessenger messenger = new MockTokenMessenger();
        vm.prank(owner);
        vault.setTokenMessenger(address(messenger));

        // PR3.3: cap cross-chain to both maxAllocationBps and maxPendingCrossChainBps
        uint256 maxByAlloc  = (depositAmt * vault.maxAllocationBps()) / 10_000;
        uint256 maxByPending = (depositAmt * vault.maxPendingCrossChainBps()) / 10_000;
        uint256 maxCross = maxByAlloc < maxByPending ? maxByAlloc : maxByPending;
        if (maxCross < 1e6) return; // not enough to cross
        uint256 crossAmt = bound(crossAmt_, 1e6, maxCross);

        bytes32 recipient = bytes32(uint256(uint160(makeAddr("remote"))));
        vm.prank(owner);
        vault.deployCrossChain(2, recipient, crossAmt); // domain 2 != SRC=1

        // Task M: pending keys come from the vault's local counter.
        assertEq(vault.crossChainPositionCounter(), 1);
        assertEq(vault.pendingCrossChain(vault.crossChainPositionCounter()), crossAmt);
        assertEq(vault.totalDeployed(), crossAmt);
    }

    // -----------------------------------------------------------------------
    // Fuzz: paused=true blocks all deposits regardless of amount
    // -----------------------------------------------------------------------
    function testFuzz_paused_blocks_all_deposits(uint96 amount) public {
        vm.assume(amount > 0);
        vm.prank(owner);
        vault.setPaused(true);

        usdc.mint(alice, amount);
        vm.prank(alice);
        usdc.approve(address(vault), amount);

        vm.prank(alice);
        vm.expectRevert(AutonomousVault.Paused.selector);
        vault.deposit(amount, alice);
    }

    // -----------------------------------------------------------------------
    // Fuzz: recallCapital via adapter — totalDeployed decrements by actual return
    // -----------------------------------------------------------------------
    function testFuzz_recallCapital_accounting(uint96 depositAmt_, uint16 bpsFrac) public {
        uint256 depositAmt = bound(depositAmt_, 100e6, 5_000_000e6);
        uint256 fraction = bound(bpsFrac, 100, 7_000);

        usdc.mint(alice, depositAmt);
        vm.prank(alice);
        usdc.approve(address(vault), depositAmt);
        vm.prank(alice);
        vault.deposit(depositAmt, alice);

        uint256 deployAmt = (depositAmt * fraction) / 10_000;
        if (deployAmt == 0) return;

        FuzzMockAdapter adapter = new FuzzMockAdapter(address(vault), address(usdc));
        vm.prank(owner);
        vault.deployCapital(address(adapter), deployAmt, "");
        assertEq(vault.totalDeployed(), deployAmt);

        vm.prank(owner);
        vault.recallCapital(address(adapter), deployAmt);

        assertEq(vault.totalDeployed(), 0);
        assertEq(usdc.balanceOf(address(vault)), depositAmt);
    }

    // -----------------------------------------------------------------------
    // Fuzz: multiple sequential deposits from different users preserve NAV
    // -----------------------------------------------------------------------
    function testFuzz_multi_depositor_fair_shares(uint64 a1, uint64 a2) public {
        uint256 amt1 = bound(a1, 1e6, 1_000_000e6);
        uint256 amt2 = bound(a2, 1e6, 1_000_000e6);
        address bob = makeAddr("bob");

        usdc.mint(alice, amt1);
        vm.prank(alice);
        usdc.approve(address(vault), amt1);
        vm.prank(alice);
        uint256 sharesA = vault.deposit(amt1, alice);

        usdc.mint(bob, amt2);
        vm.prank(bob);
        usdc.approve(address(vault), amt2);
        vm.prank(bob);
        uint256 sharesB = vault.deposit(amt2, bob);

        // Both should get shares proportional to their deposits (with at most 1-unit rounding)
        if (amt1 > 0 && amt2 > 0) {
            // ratio check: sharesA/sharesB ≈ amt1/amt2 within 1%
            // expressed as cross-multiply to avoid division: sharesA * amt2 ≈ sharesB * amt1
            uint256 lhs = sharesA * amt2;
            uint256 rhs = sharesB * amt1;
            // allow 1% deviation
            uint256 tolerance = rhs / 100 + 1;
            assertApproxEqAbs(lhs, rhs, tolerance, "share ratio must match deposit ratio");
        }
    }
}

// Inline mock messenger for cross-chain fuzz tests
contract MockTokenMessenger {
    // Task M: record the V2 burn arguments without manufacturing a Circle nonce.
    bytes public lastCall;
    function depositForBurn(uint256 amount, uint32 domain, bytes32 recipient, address token,
        bytes32 caller, uint256 maxFee, uint32 finality) external {
        lastCall = abi.encode(amount, domain, recipient, token, caller, maxFee, finality);
    }
}

contracts/test/FuzzCharityModule.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// forge-config: default.fuzz.runs = 512

import {Test} from "forge-std/Test.sol";

import {CharityModule} from "../CharityModule.sol";
import {MockERC20}     from "../test-helpers/MockERC20.sol";

contract MockRegistryFCM {
    address public board;
    constructor(address b) { board = b; }
    function isBoard(address a) external view returns (bool) { return a == board; }
}

/**
 * @title  FuzzCharityModule
 * @notice Fuzz / property tests for CharityModule.
 *         Invariants: exact arithmetic, cap enforcement, timelock enforcement,
 *         and accumulator monotonicity.
 *
 * forge-config: default.fuzz.runs = 512
 */
contract FuzzCharityModule is Test {

    // ── actors ────────────────────────────────────────────────────────────────
    address internal owner         = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");

    // ── contracts ─────────────────────────────────────────────────────────────
    MockERC20     internal usdc;
    CharityModule internal module;

    // address(this) is vault
    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        MockRegistryFCM registry = new MockRegistryFCM(owner);

        vm.prank(owner);
        module = new CharityModule(charityWallet, address(usdc), address(this), owner, address(registry));

        // Large balance so any fuzz amount can be approved
        usdc.mint(address(this), type(uint96).max);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 1. charityAmount is exactly grossProfit * 250 / 10_000
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_charityAmount_exact(uint96 grossProfit) public {
        grossProfit = uint96(bound(uint256(grossProfit), 1e6, 10_000e6));

        usdc.approve(address(module), grossProfit);
        (uint256 charityAmount,) = module.distributeCharity(grossProfit);

        uint256 expected = (uint256(grossProfit) * 250) / 10_000;
        assertEq(charityAmount, expected, "charityAmount must equal grossProfit * 250 / 10_000");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 2. charityAmount + remaining == grossProfit (exact conservation)
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_remaining_plus_charity_equals_gross(uint96 grossProfit) public {
        grossProfit = uint96(bound(uint256(grossProfit), 1e6, 10_000e6));

        usdc.approve(address(module), grossProfit);
        (uint256 charityAmount, uint256 remaining) = module.distributeCharity(grossProfit);

        assertEq(charityAmount + remaining, uint256(grossProfit),
            "charityAmount + remaining must equal grossProfit");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 3. Any bps > 500 always reverts CharityRateAboveCap
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_charity_above_cap_always_reverts(uint256 bps) public {
        bps = bound(bps, 501, 1_000_000);

        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(CharityModule.CharityRateAboveCap.selector, bps, 500)
        );
        module.proposeCharityRateChange(bps);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 4. Wallet timelock enforced for any warp < 30 days
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_timelock_enforced_wallet(uint256 warpTime) public {
        warpTime = bound(warpTime, 0, 30 days - 1);

        address newWallet = makeAddr("newWallet");
        vm.startPrank(owner);
        module.proposeCharityWalletChange(newWallet);
        vm.warp(block.timestamp + warpTime);
        vm.expectRevert(); // TimelockNotElapsed
        module.confirmCharityWalletChange();
        vm.stopPrank();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 5. Rate timelock enforced for any warp < 30 days
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_timelock_enforced_rate(uint256 warpTime) public {
        warpTime = bound(warpTime, 0, 30 days - 1);

        vm.startPrank(owner);
        module.proposeCharityRateChange(300);
        vm.warp(block.timestamp + warpTime);
        vm.expectRevert(); // TimelockNotElapsed
        module.confirmCharityRateChange();
        vm.stopPrank();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 6. totalCharityDistributed accumulates correctly over two calls
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_totalDistributed_accumulates(uint64 a, uint64 b) public {
        uint256 gross1 = bound(uint256(a), 1e6, 100_000e6);
        uint256 gross2 = bound(uint256(b), 1e6, 100_000e6);

        usdc.approve(address(module), gross1 + gross2);

        (uint256 c1,) = module.distributeCharity(gross1);
        (uint256 c2,) = module.distributeCharity(gross2);

        assertEq(
            module.totalCharityDistributed(),
            c1 + c2,
            "totalCharityDistributed should equal sum of both charity amounts"
        );
    }
}

contracts/test/FuzzCommodityMurabaha.t.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {CommodityMurabahaAdapter} from "../adapters/CommodityMurabahaAdapter.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

contract FuzzCommodityMurabaha is Test {
    MockERC20 internal usdc;
    CommodityMurabahaAdapter internal adapter;

    address internal owner = makeAddr("owner");
    address internal vault = makeAddr("vault");
    address internal alice = makeAddr("alice");

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        vm.prank(owner);
        adapter = new CommodityMurabahaAdapter(address(usdc), vault, owner);
    }

    // -----------------------------------------------------------------------
    // Fuzz: salePrice = costAmount + (costAmount * markupBps / 10_000) — no overflow
    // -----------------------------------------------------------------------
    function testFuzz_salePrice_math(uint64 amount_, uint16 markupBps_) public {
        // Minimum amount=10_000e6 so that even 1 bps markup produces at least 1 unit of profit
        // (1 bps of 10_000e6 = 1_000_000 which rounds to 1_000_000 > 0)
        uint256 amount    = bound(amount_,    10_000e6, 100_000_000e6);
        uint256 markupBps = bound(markupBps_, 1, 5_000);

        uint256 tradeId = adapter.requestMurabaha(alice, amount, markupBps, 7 days);

        (,, uint256 costAmount,, uint256 salePrice,,,,, ) = adapter.trades(tradeId);

        uint256 expectedSalePrice = amount + (amount * markupBps) / 10_000;
        assertEq(salePrice, expectedSalePrice, "salePrice must match formula");
        assertEq(costAmount, amount);
        assertGt(salePrice, costAmount, "salePrice must exceed costAmount");
    }

    // -----------------------------------------------------------------------
    // Fuzz: markup boundaries — [1, 5000] always succeed; 0 and >5000 revert
    // -----------------------------------------------------------------------
    function testFuzz_markup_boundary(uint16 markup) public {
        if (markup == 0 || markup > 5_000) {
            vm.expectRevert(CommodityMurabahaAdapter.InvalidMarkup.selector);
            adapter.requestMurabaha(alice, 1_000e6, markup, 7 days);
        } else {
            uint256 id = adapter.requestMurabaha(alice, 1_000e6, markup, 7 days);
            assertGt(id, 0);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: settlement window stored as deadline = block.timestamp + window
    // -----------------------------------------------------------------------
    function testFuzz_deadline_stored_correctly(uint32 window) public {
        window = uint32(bound(window, 1, 365 days));
        uint256 before = block.timestamp;

        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, window);

        (,,,,,,,, uint256 deadline,) = adapter.trades(tradeId);
        assertEq(deadline, before + window, "deadline must be timestamp + window");
    }

    // -----------------------------------------------------------------------
    // Fuzz: expired trade can always be expired after deadline
    // -----------------------------------------------------------------------
    function testFuzz_expire_always_works_after_deadline(uint32 window, uint32 extra) public {
        window = uint32(bound(window, 1, 30 days));
        extra  = uint32(bound(extra,  1, 30 days));

        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, window);

        skip(uint256(window) + extra);

        vm.prank(owner);
        adapter.expireTrade(tradeId);

        (,,,,,,,,, CommodityMurabahaAdapter.TradeStatus status) = adapter.trades(tradeId);
        assertEq(uint8(status), uint8(CommodityMurabahaAdapter.TradeStatus.EXPIRED));
    }

    // -----------------------------------------------------------------------
    // Fuzz: non-buyer can never settle
    // -----------------------------------------------------------------------
    function testFuzz_only_buyer_settles(address nonBuyer) public {
        vm.assume(nonBuyer != alice && nonBuyer != address(0));

        uint256 tradeId = adapter.requestMurabaha(alice, 1_000e6, 200, 7 days);
        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        vm.prank(nonBuyer);
        vm.expectRevert(CommodityMurabahaAdapter.BuyerOnly.selector);
        adapter.settleMurabaha(tradeId);
    }

    // -----------------------------------------------------------------------
    // Fuzz: full happy-path settle — vault receives exact salePrice, profit exact
    // -----------------------------------------------------------------------
    function testFuzz_settle_full_roundtrip(uint64 amount_, uint16 markupBps_) public {
        uint256 amount    = bound(amount_,    1_000e6, 10_000_000e6);
        uint256 markupBps = bound(markupBps_, 1, 5_000);

        uint256 salePrice = amount + (amount * markupBps) / 10_000;
        uint256 profit    = salePrice - amount;

        uint256 tradeId = adapter.requestMurabaha(alice, amount, markupBps, 7 days);
        vm.prank(owner);
        adapter.executeMurabaha(tradeId);

        usdc.mint(alice, salePrice);
        vm.prank(alice);
        usdc.approve(address(adapter), salePrice);
        vm.prank(alice);
        adapter.settleMurabaha(tradeId);

        assertEq(usdc.balanceOf(vault), salePrice, "vault must receive full salePrice");
        assertEq(adapter.totalProfitRealized(), profit, "profit must match markup amount");
        assertEq(adapter.totalDeployed(), 0, "totalDeployed must be 0 after settle");
    }

    // -----------------------------------------------------------------------
    // Fuzz: activeTrades.length never exceeds MAX_ACTIVE_TRADES
    // -----------------------------------------------------------------------
    function testFuzz_active_trades_capped(uint8 n) public {
        // Fill to max (50), then verify 51st reverts
        n = uint8(bound(n, 1, 50));
        for (uint256 i = 0; i < n; i++) {
            adapter.requestMurabaha(alice, 1_000e6, 200, 7 days);
        }
        assertLe(adapter.getActiveTrades().length, 50, "active trades must not exceed 50");
    }

    // -----------------------------------------------------------------------
    // Fuzz: deploy + recall roundtrip — totalDeployed always returns to 0
    // -----------------------------------------------------------------------
    function testFuzz_deploy_recall_roundtrip(uint64 amount_) public {
        uint256 amount = bound(amount_, 1e6, 10_000_000e6);

        usdc.mint(vault, amount);

        vm.prank(vault);
        adapter.deploy(amount);
        assertEq(adapter.totalDeployed(), amount);

        // Give adapter the USDC to recall
        usdc.mint(address(adapter), amount);
        vm.prank(vault);
        adapter.recall(amount);

        assertEq(adapter.totalDeployed(), 0, "totalDeployed must be 0 after full recall");
        assertEq(usdc.balanceOf(vault), amount * 2, "vault gets original + recalled");
    }

    // -----------------------------------------------------------------------
    // Invariant: tradeCount monotonically increases, never resets
    // -----------------------------------------------------------------------
    function testFuzz_tradeCount_monotonic(uint8 n) public {
        n = uint8(bound(n, 1, 20));
        for (uint8 i = 0; i < n; i++) {
            adapter.requestMurabaha(alice, 1_000e6, 200, 7 days);
        }
        assertEq(adapter.tradeCount(), n, "tradeCount must equal total requests");
    }
}

contracts/test/FuzzGoldAllocationAdapter.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// forge-config: default.fuzz.runs = 512

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {GoldAllocationAdapter}   from "../adapters/GoldAllocationAdapter.sol";
import {ShariahVault}            from "../ShariahVault.sol";
import {TreasuryModule}          from "../TreasuryModule.sol";
import {MockERC20}               from "../test-helpers/MockERC20.sol";
import {MockXAUT}                from "../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}    from "../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT}   from "../test-helpers/MockUniswapV3PoolXAUT.sol";

/// @title  FuzzGoldAllocationAdapter
/// @notice Property-based tests for GoldAllocationAdapter (Task F).
///
/// Fuzz runs: 512 (set via inline forge-config above and --fuzz-runs flag).
///
/// Price setup (same as unit tests):
///   Oracle answer:  330_000_000_000  (8-dec, = $3300)
///   oraclePriceUsdc = answer / 100 = 3_300_000_000
///   Pool usdcPerXaut = 3_300_000_000 (matching oracle)
contract FuzzGoldAllocationAdapter is Test {

    // ── Actors ─────────────────────────────────────────────────────────────
    address internal owner   = makeAddr("owner");
    address internal alice   = makeAddr("alice");

    // ── Tokens ─────────────────────────────────────────────────────────────
    MockERC20             internal usdc;
    MockXAUT              internal xaut;
    MockXauUsdAggregator  internal oracle;
    MockUniswapV3PoolXAUT internal pool;

    // ── Protocol ───────────────────────────────────────────────────────────
    TreasuryModule        internal treasury;
    ShariahVault          internal vault;
    GoldAllocationAdapter internal adapter;

    // ── Constants ──────────────────────────────────────────────────────────
    uint32  internal constant SOURCE_DOMAIN       = 26;
    uint256 internal constant MAX_STALENESS       = 3600;
    int256  internal constant DEFAULT_ORACLE_PRICE = 330_000_000_000;   // $3300 × 10^8
    uint256 internal constant DEFAULT_ORACLE_USDC  = 3_300_000_000;     // 3300 USDC (6-dec)
    uint256 internal constant DEFAULT_POOL_PRICE   = 3_300_000_000;

    // ── Pool liquidity budget ───────────────────────────────────────────────
    // Pool must hold enough for all swap scenarios. Fund generously.
    uint256 internal constant POOL_USDC_SEED = 500_000_000e6;   // 500M USDC
    uint256 internal constant POOL_XAUT_SEED = 200_000e6;       // 200k XAUT

    function setUp() public {
        // Warp to a realistic timestamp so staleness math (block.timestamp - updatedAt) doesn't underflow
        vm.warp(1_700_000_000);

        usdc   = new MockERC20("Mock USDC", "mUSDC", 6);
        xaut   = new MockXAUT();
        oracle = new MockXauUsdAggregator();
        pool   = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), DEFAULT_POOL_PRICE);

        vm.startPrank(owner);
        treasury = new TreasuryModule(
            "Shariah",
            address(0),
            address(usdc),
            50, 1000, 400,
            owner
        );
        vault = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(treasury),
            address(0)
        );
        adapter = new GoldAllocationAdapter(
            address(usdc),
            address(xaut),
            address(pool),
            3000,
            address(oracle),
            address(vault),
            MAX_STALENESS,
            owner
        );
        vault.setScreened(address(adapter), true);
        vault.setGoldAllocationAdapter(address(adapter));
        vm.stopPrank();

        // Fund pool
        usdc.mint(address(this), POOL_USDC_SEED);
        xaut.mint(address(this), POOL_XAUT_SEED);
        usdc.approve(address(pool), POOL_USDC_SEED);
        xaut.approve(address(pool), POOL_XAUT_SEED);
        pool.fundPool(POOL_USDC_SEED, POOL_XAUT_SEED);
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Helpers
    // ─────────────────────────────────────────────────────────────────────

    /// @dev Fund vault from alice, returns shares minted.
    function _fund(uint256 usdcAmount) internal {
        usdc.mint(alice, usdcAmount);
        vm.startPrank(alice);
        usdc.approve(address(vault), usdcAmount);
        vault.deposit(usdcAmount, alice);
        vm.stopPrank();
    }

    /// @dev Fund and execute the adapter in one vault call.
    function _deploy(uint256 amount) internal {
        vm.prank(owner);
        vault.deployCapitalAndExecute(address(adapter), amount, "");
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Fuzz 1: currentValue within 1 unit of expected
    // ─────────────────────────────────────────────────────────────────────

    /// @notice currentValue() = xautHeld * oraclePrice / 10^xautDecimals.
    ///         We test the formula directly: deploy a fixed USDC amount at varying oracle
    ///         prices and verify |currentValue() - expected| <= 1 (integer division rounding).
    ///         Strategy: fund vault → deploy → check formula.
    function testFuzz_currentValue_within_1_unit(
        uint128 usdcAmount,
        uint128 priceAnswer
    ) public {
        // Bound: 1 USDC to 1_000 USDC (6-dec), small enough to fit in pool and cap
        usdcAmount = uint128(bound(usdcAmount, 1e6, 1_000e6));
        // Bound: 8-dec oracle price $100–$10_000/oz
        priceAnswer = uint128(bound(priceAnswer, 100e8, 10_000e8));

        // Compute expected oraclePriceUsdc (6-dec USDC per 1 XAUT unit in raw units)
        // oraclePriceUsdc = priceAnswer * 1e6 / 1e8 = priceAnswer / 100
        uint256 oraclePriceUsdc = uint256(priceAnswer) / 100;
        vm.assume(oraclePriceUsdc > 0);

        // Set oracle and pool to the same price (no deviation)
        oracle.setPrice(int256(uint256(priceAnswer)));
        pool.setPrice(oraclePriceUsdc);

        // Fund vault with 10x usdcAmount so allocation cap isn't a problem
        _fund(uint256(usdcAmount) * 10);

        // Check allocation room
        uint256 ta = vault.totalAssets();
        uint256 maxD = (ta * vault.maxAllocationBps()) / 10_000;
        if (uint256(usdcAmount) > maxD) return; // skip if still too constrained

        _deploy(usdcAmount);

        uint256 xHeld = adapter.xautHeld();
        uint256 expected = (xHeld * oraclePriceUsdc) / 1e6; // xautDecimals = 6
        uint256 actual = adapter.currentValue();

        assertApproxEqAbs(actual, expected, 1, "currentValue must be within 1 unit of expected");
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Fuzz 2: deploy → recall roundtrip loss within 2x slippage budget
    // ─────────────────────────────────────────────────────────────────────

    /// @notice After deploy then recall, the USDC returned is at least
    ///         amount * (10_000 - 2 * maxSlippageBps) / 10_000.
    ///         The pool charges swapFeeBps on each leg (default 9980/10000 = 0.2%),
    ///         maxSlippageBps defaults to 50 (0.5%), so 2x allowance covers both legs.
    function testFuzz_deploy_recall_roundtrip(uint128 amount) public {
        // Bound: 1 USDC to 1_000 USDC (6-dec)
        amount = uint128(bound(amount, 1e6, 1_000e6));

        _fund(uint256(amount) * 10); // fund 10x for safety

        uint256 maxSlippageBps = adapter.maxSlippageBps();

        _deploy(amount);

        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));

        vm.prank(address(vault));
        adapter.recall(uint256(amount));

        uint256 vaultUsdcAfter = usdc.balanceOf(address(vault));
        uint256 returned = vaultUsdcAfter - vaultUsdcBefore;

        // Minimum expected: amount * (10_000 - 2 * maxSlippageBps) / 10_000
        uint256 minExpected = (uint256(amount) * (10_000 - 2 * maxSlippageBps)) / 10_000;

        assertGe(returned, minExpected, "USDC returned must be >= amount * (1 - 2*slippage)");
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Fuzz 3: combined gold weight never exceeds cap
    // ─────────────────────────────────────────────────────────────────────

    /// @notice At every step after a deploy to goldAllocationAdapter,
    ///         goldSpreadValue + goldAllocationValue <= MAX_GOLD_BPS * totalAssets / 10_000.
    function testFuzz_combined_gold_weight_never_exceeds_cap(
        uint128 depositAmount,
        uint128 spreadValue,
        uint128 deployAmount
    ) public {
        // Bound all inputs
        depositAmount = uint128(bound(depositAmount, 1_000e6, 10_000e6));  // 1k–10k USDC
        spreadValue   = uint128(bound(spreadValue,   0,       1_000e6));   // 0–1k USDC
        deployAmount  = uint128(bound(deployAmount,  1e6,     500e6));     // 1–500 USDC

        _fund(depositAmount);

        uint256 totalAssets_ = vault.totalAssets();
        uint256 goldCap = (totalAssets_ * vault.MAX_GOLD_BPS()) / 10_000;

        // Set up mock spread adapter
        MockGoldSpreadFuzz spreadAdapter = new MockGoldSpreadFuzz(spreadValue);
        vm.startPrank(owner);
        vault.setGoldSpreadAdapter(address(spreadAdapter));
        vm.stopPrank();

        // G-1 includes the newly tracked spread appreciation in the entry-time NAV cap.
        totalAssets_ = vault.totalAssets();
        goldCap = (totalAssets_ * vault.MAX_GOLD_BPS()) / 10_000;

        // Determine if deploying `deployAmount` would exceed cap
        // combined = spreadValue + currentXautValue(=0) + deployAmount
        uint256 combined = uint256(spreadValue) + 0 + uint256(deployAmount);

        if (combined > goldCap) {
            // Expect revert GoldCapExceeded
            vm.prank(owner);
            vm.expectRevert();
            vault.deployCapitalAndExecute(address(adapter), deployAmount, "");
            // Cap is preserved — no deployment happened
        } else {
            // Deploy should succeed
            uint256 room = goldCap - uint256(spreadValue);
            if (deployAmount > room) return; // would exceed, skip

            // Check allocation cap as well
            uint256 maxAlloc = (totalAssets_ * vault.maxAllocationBps()) / 10_000;
            uint256 alreadyDeployed = vault.totalDeployed();
            if (deployAmount > maxAlloc - alreadyDeployed) return;

            vm.prank(owner);
            vault.deployCapitalAndExecute(address(adapter), deployAmount, "");

            // Invariant: spread + allocation <= cap
            uint256 xautVal = adapter.currentValue();
            uint256 combinedAfter = uint256(spreadValue) + xautVal;
            assertLe(combinedAfter, goldCap, "Combined gold value must not exceed MAX_GOLD_BPS cap");
        }
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Fuzz 4: timelock enforced for any sub-30-day warp
    // ─────────────────────────────────────────────────────────────────────

    /// @notice For any warpTime in [0, 29 days], executing a proposed param change
    ///         before 30 days must revert TimelockNotElapsed.
    /// @dev    Cache param IDs before vm.prank to avoid staticcall consuming the prank.
    function testFuzz_timelock_enforced_for_any_timestamp(uint256 warpTime) public {
        warpTime = bound(warpTime, 0, 30 days - 1);

        // Cache param ID before prank — staticcall must NOT consume the prank
        bytes32 paramId = adapter.PARAM_MAX_SLIPPAGE();
        uint256 proposeTime = block.timestamp;

        vm.prank(owner);
        adapter.proposeParamChange(paramId, 100);

        vm.warp(proposeTime + warpTime);

        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(
                GoldAllocationAdapter.TimelockNotElapsed.selector,
                proposeTime + 30 days,
                proposeTime + warpTime
            )
        );
        adapter.executeParamChange(paramId);
    }

    // ─────────────────────────────────────────────────────────────────────
    //  Fuzz 5: no XAUT stranded after recall
    // ─────────────────────────────────────────────────────────────────────

    /// @notice After deploy then recall, adapter holds 0 XAUT regardless of price.
    function testFuzz_no_xaut_stranded_after_recall(
        uint128 amount,
        uint32  priceSeed
    ) public {
        // Bound amount: 1 USDC to 1000 USDC (6-dec)
        amount = uint128(bound(amount, 1e6, 1_000e6));

        // Derive a valid oracle price from priceSeed: map to [100e8, 10_000e8]
        uint256 rawPrice = bound(priceSeed, 100e8, 10_000e8);
        // Ensure oraclePriceUsdc is representable
        uint256 oraclePriceUsdc = (rawPrice * 1e6) / 1e8;
        vm.assume(oraclePriceUsdc > 0);

        oracle.setPrice(int256(rawPrice));
        pool.setPrice(oraclePriceUsdc);

        _fund(uint256(amount) * 10);

        // Check there's room in allocation cap
        uint256 ta = vault.totalAssets();
        uint256 maxD = (ta * vault.maxAllocationBps()) / 10_000;
        uint256 ad = vault.totalDeployed();
        if (uint256(amount) > maxD - ad) return;

        _deploy(amount);

        vm.prank(address(vault));
        adapter.recall(uint256(amount));

        assertEq(xaut.balanceOf(address(adapter)), 0, "No XAUT must be stranded in adapter after recall");
        assertEq(adapter.xautHeld(), 0, "xautHeld must be 0 after recall");
    }
}

// ─────────────────────────────────────────────────────────────────────────────
//  Mock helper for fuzz: minimal IGoldAdapter stub
// ─────────────────────────────────────────────────────────────────────────────
contract MockGoldSpreadFuzz {
    function isGoldStrategy() external pure returns (bool) { return true; }
    uint256 private _value;
    constructor(uint256 value_) { _value = value_; }
    function currentValue() external view returns (uint256) { return _value; }
    function isPriceSane() external pure returns (bool) { return true; }
}

contracts/test/FuzzGoldExchangeAdapter.t.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {GoldExchangeAdapter}    from "../adapters/GoldExchangeAdapter.sol";
import {ShariahVault}           from "../ShariahVault.sol";
import {AutonomousVault}        from "../AutonomousVault.sol";
import {TreasuryModule}         from "../TreasuryModule.sol";
import {MockERC20}              from "../test-helpers/MockERC20.sol";
import {MockAllocatedGold}      from "../test-helpers/MockAllocatedGold.sol";
import {MockXauUsdAggregator}   from "../test-helpers/MockXauUsdAggregator.sol";

/// @title  FuzzGoldExchangeAdapter
/// @notice Property-based tests for GoldExchangeAdapter and ShariahVault Task C guard.
///
/// Execution model (same as unit tests):
///   vault.deployCapitalAndExecute(adapter, amount, "") — funds and swaps atomically.
///   vault.recallCapital(adapter, amount)      — calls adapter.recall().

// ─── Ratio-configurable mock swap router ─────────────────────────────────────
// outputRatioBps: output = input * ratio / 10_000
// Lets fuzz tests drive gain/loss exit scenarios.

contract RatioSwapRouter {
    uint256 public outputRatioBps;
    uint256 public lastMinOut;
    uint256 public priceUsdc = 3_300e6;

    function setPrice(uint256 price) external { priceUsdc = price; }

    constructor(uint256 ratio) { outputRatioBps = ratio; }

    function setOutputRatioBps(uint256 bps) external { outputRatioBps = bps; }

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata p)
        external returns (uint256 amountOut)
    {
        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        lastMinOut = p.amountOutMinimum;
        uint256 expected = MockERC20(p.tokenIn).decimals() == 6
            ? p.amountIn * 1e18 / priceUsdc
            : p.amountIn * priceUsdc / 1e18;
        amountOut = (expected * outputRatioBps) / 10_000;
        if (amountOut < p.amountOutMinimum) revert("RatioSwapRouter: slippage");
        if (amountOut > 0) IERC20(p.tokenOut).transfer(p.recipient, amountOut);
    }
}

// ─── Fuzz test contract ───────────────────────────────────────────────────────

contract FuzzGoldExchangeAdapter is Test {

    address internal owner   = makeAddr("owner");
    address internal manager = makeAddr("manager");
    address internal alice   = makeAddr("alice");

    MockERC20              internal usdc;
    MockAllocatedGold      internal mag;
    RatioSwapRouter        internal router;
    MockXauUsdAggregator   internal xauOracle;
    ShariahVault           internal vault;
    TreasuryModule         internal treasury;
    GoldExchangeAdapter    internal adapter;

    uint32 internal constant SRC = 26;

    function setUp() public {
        usdc      = new MockERC20("Mock USDC", "mUSDC", 6);
        mag       = new MockAllocatedGold();
        router    = new RatioSwapRouter(10_000); // 1:1 default
        xauOracle = new MockXauUsdAggregator(); // K2: mandatory oracle

        vm.startPrank(owner);
        treasury = new TreasuryModule(
            "Shariah", address(0), address(usdc), 50, 1000, 400, owner
        );
        vault = new ShariahVault(
            IERC20(address(usdc)), owner, SRC, address(treasury), address(0)
        );
        vault.setManager(manager);
        adapter = new GoldExchangeAdapter(
            address(usdc), address(mag), address(router), 3000,
            address(vault), owner, address(xauOracle)
        );
        vault.setScreened(address(adapter), true);
        // N-23: swap properties must exercise a tracked position and its gold cap.
        vault.setGoldSpreadAdapter(address(adapter));
        // Widen slippage floor so ratio router variations still pass the 99% check
        adapter.setMinOutBps(9000);
        vm.stopPrank();

        // Large MAG reserve so any fuzz amount up to 10M USDC can be served 1:1
        mag.mint(address(this), 200_000_000e18);
        IERC20(address(mag)).transfer(address(router), 200_000_000e18);
    }

    function testFuzz_minOut_neverBelowOracleBound(uint64 rawAmount, uint32 rawPrice, uint16 rawBps) public {
        uint256 amount = bound(rawAmount, 1, 1_000_000e6);
        uint256 price = bound(rawPrice, 100e6, 20_000e6);
        uint256 bps = bound(rawBps, 9000, 10_000);
        xauOracle.setPrice(int256(price * 100));
        router.setPrice(price);
        vm.prank(owner);
        adapter.setMinOutBps(bps);
        usdc.mint(address(adapter), amount);
        vm.prank(address(vault));
        adapter.deploy(amount);
        uint256 minimum = ((amount * 1e18 / price) * bps) / 10_000;
        if (minimum == 0) minimum = 1;
        assertEq(router.lastMinOut(), minimum);
    }

    // ── Two-step deploy helper ──────────────────────────────────────────────

    function _pushAndSwap(uint256 amount) internal {
        vm.prank(manager);
        // Exercise atomic funding and the real onlyVault caller for all swap properties.
        vault.deployCapitalAndExecute(address(adapter), amount, "");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 1: No USDC stranded in adapter after adapter.deploy()
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_deploy_no_usdc_stranded(uint64 rawAmount) public {
        uint256 depositAmt = bound(rawAmount, 1_000e6, 10_000_000e6);
        // N-23: retain swap/recall properties within the enforced 30% gold cap.
        uint256 deployAmt  = (depositAmt * 2_000) / 10_000;

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        _pushAndSwap(deployAmt);

        assertEq(usdc.balanceOf(address(adapter)), 0,
            "Invariant: no USDC stranded in adapter after deploy");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 2: No MAG stranded in adapter after recallCapital()
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_recall_no_mag_stranded(uint64 rawAmount) public {
        uint256 depositAmt = bound(rawAmount, 1_000e6, 10_000_000e6);
        // N-23: retain swap/recall properties within the enforced 30% gold cap.
        uint256 deployAmt  = (depositAmt * 2_000) / 10_000;

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        _pushAndSwap(deployAmt);
        assertGt(adapter.paxgHeld(), 0);

        // Seed router with USDC for reverse swap
        usdc.mint(address(router), 50_000_000e6);

        vm.prank(manager);
        vault.recallCapital(address(adapter), deployAmt);

        assertEq(mag.balanceOf(address(adapter)), 0,
            "Invariant: no MAG stranded in adapter after recall");
        assertEq(adapter.paxgHeld(), 0,
            "Invariant: paxgHeld must be zero after full recall");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 3: totalDeployed zeros on full recall regardless of exit price
    //              (test with varied gain/loss ratios)
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_totalDeployed_zeros_on_recall(uint64 rawAmount, uint16 exitRatioBps_) public {
        uint256 depositAmt = bound(rawAmount, 1_000e6, 5_000_000e6);
        // N-23: keep gain/loss exit coverage within the linked gold allocation limit.
        uint256 deployAmt  = (depositAmt * 2_000) / 10_000;
        // Simulate exit ratio 90%–110% (loss or gain)
        uint256 exitRatio  = bound(exitRatioBps_, 9000, 11_000);

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        _pushAndSwap(deployAmt);
        assertGt(adapter.totalDeployed(), 0);

        // Change router ratio to simulate price movement
        router.setOutputRatioBps(exitRatio);
        // Supply USDC liquidity for MAG->USDC recall swap
        usdc.mint(address(router), 50_000_000e6);

        vm.prank(manager);
        vault.recallCapital(address(adapter), deployAmt);

        assertEq(adapter.totalDeployed(), 0,
            "Invariant: totalDeployed must zero on full exit regardless of exit price");
        // N-06 must retire vault principal too, including loss-making exits.
        assertEq(vault.totalDeployed(), 0);
        assertEq(vault.principalOf(address(adapter)), 0);
        assertEq(vault.totalAssets(), usdc.balanceOf(address(vault)));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 4: paxgHeld always equals adapter's MAG balance after any swap
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_paxgHeld_equals_balance(uint64 rawAmt1, uint16 splitBps) public {
        uint256 total  = bound(rawAmt1, 10_000e6, 5_000_000e6);
        // N-23: reserve room for the second 10% buy under the combined gold cap.
        uint256 frac   = bound(splitBps, 1000, 1900);
        uint256 d1     = (total * frac) / 10_000;
        uint256 d2     = (total * 1000) / 10_000;
        vm.assume(d1 + d2 <= (total * 7_500) / 10_000);

        usdc.mint(alice, total);
        vm.startPrank(alice);
        usdc.approve(address(vault), total);
        vault.deposit(total, alice);
        vm.stopPrank();

        _pushAndSwap(d1);
        assertEq(adapter.paxgHeld(), mag.balanceOf(address(adapter)),
            "paxgHeld must equal MAG balance after first swap");

        _pushAndSwap(d2);
        assertEq(adapter.paxgHeld(), mag.balanceOf(address(adapter)),
            "paxgHeld must equal MAG balance after second swap");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 5: totalAssets = vaultBalance + totalDeployed at all times
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_totalAssets_invariant(uint64 rawDeposit, uint16 deployFrac) public {
        uint256 depositAmt = bound(rawDeposit, 100e6, 10_000_000e6);
        // N-23: the accounting property now runs inside the tracked gold cap.
        uint256 fraction   = bound(deployFrac, 0, 3_000);

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        uint256 deployAmt = (depositAmt * fraction) / 10_000;
        if (deployAmt >= 1e6) {
            _pushAndSwap(deployAmt);
        }

        // N-23: tracked gold marks the one-unit swap rounding loss instead of treating cost as exact value.
        assertApproxEqAbs(
            vault.totalAssets(),
            usdc.balanceOf(address(vault)) + vault.totalDeployed(),
            1,
            "totalAssets matches funded cost within swap rounding"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 6: Both gold indices reject every nonzero domain, recipient and amount.
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_deployCrossChain_gold_strategies_blocked(
        uint32 domain,
        bytes32 recipient,
        uint256 amount
    ) public {
        vm.assume(domain != 0);

        vm.prank(manager);
        vm.expectRevert(ShariahVault.NonAtomicGoldExchange.selector);
        vault.deployCrossChainForStrategy(1, domain, recipient, amount);

        vm.prank(manager);
        vm.expectRevert(ShariahVault.NonAtomicGoldExchange.selector);
        vault.deployCrossChainForStrategy(5, domain, recipient, amount);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 7: setMinOutBps only accepts 9000–10000
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_setMinOutBps_range(uint256 bps) public {
        vm.prank(owner);
        if (bps < 9000 || bps > 10_000) {
            vm.expectRevert(bytes("GoldExchangeAdapter: bps out of range (9000-10000)"));
            adapter.setMinOutBps(bps);
        } else {
            adapter.setMinOutBps(bps);
            assertEq(adapter.minOutBps(), bps);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 8: deploy within 80% cap always succeeds
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_deploy_within_cap_succeeds(uint64 rawDeposit, uint16 allocFrac) public {
        uint256 depositAmt = bound(rawDeposit, 1_000e6, 50_000_000e6);
        // N-23: successful gold funding must satisfy the 30% gold cap as well as the base cap.
        uint256 fraction   = bound(allocFrac, 100, 3_000); // 1%–30%

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        uint256 deployAmt = (depositAmt * fraction) / 10_000;
        if (deployAmt == 0) return;

        // Both steps should succeed
        vm.prank(manager);
        vault.deployCapitalAndExecute(address(adapter), deployAmt, "");

        assertGt(vault.totalDeployed(), 0);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 9: deployCapital reverts AllocationExceedsLimit above cap
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_deploy_above_cap_reverts(uint64 rawDeposit) public {
        uint256 depositAmt = bound(rawDeposit, 1_000e6, 50_000_000e6);

        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        uint256 maxAllowed = (vault.totalAssets() * vault.maxAllocationBps()) / 10_000;

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.deployCapitalAndExecute(address(adapter), maxAllowed + 1e6, "");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 10: pause blocks deployCapital for any amount
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_pause_blocks_deployCapital(uint64 rawAmount) public {
        uint256 amount = bound(rawAmount, 1e6, 1_000_000e6);

        usdc.mint(alice, amount);
        vm.startPrank(alice);
        usdc.approve(address(vault), amount);
        vault.deposit(amount, alice);
        vm.stopPrank();

        vm.prank(owner);
        vault.setPaused(true);

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.Paused.selector);
        vault.deployCapitalAndExecute(address(adapter), (amount * 5_000) / 10_000, "");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 11: round-trip deposit → pushAndSwap → recall → redeem
    //               depositor recovers at least amount - 1 (rounding only)
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_round_trip_preserves_value(uint64 rawAmount) public {
        uint256 amount = bound(rawAmount, 1_000e6, 5_000_000e6);

        usdc.mint(alice, amount);
        vm.startPrank(alice);
        usdc.approve(address(vault), amount);
        uint256 shares = vault.deposit(amount, alice);
        vm.stopPrank();

        // N-23: retain the complete round trip without exceeding the tracked gold cap.
        uint256 deployAmt = (amount * 2_000) / 10_000; // 20%
        if (deployAmt < 1e6) return;

        _pushAndSwap(deployAmt);

        // Seed router with USDC for recall
        usdc.mint(address(router), 50_000_000e6);

        vm.prank(manager);
        vault.recallCapital(address(adapter), deployAmt);

        // N-06 retires full principal on exit, so rounding losses no longer require capping redeemed shares.
        assertEq(vault.principalOf(address(adapter)), 0);
        assertEq(vault.totalDeployed(), 0);
        vm.startPrank(alice);
        vault.approve(address(vault), shares);
        uint256 redeemed = vault.redeem(shares, alice, alice);
        vm.stopPrank();

        assertGe(redeemed + 2, amount,
            "Invariant: depositor must recover at least amount-2 after round-trip");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 12: adapter.deploy() always reverts for non-vault caller
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_deploy_only_vault_caller(address caller, uint64 rawAmount) public {
        vm.assume(caller != address(vault));
        vm.assume(caller != address(0));
        uint256 amount = bound(rawAmount, 1e6, 1_000_000e6);

        vm.prank(caller);
        vm.expectRevert(bytes("GoldExchangeAdapter: caller is not the vault"));
        adapter.deploy(amount);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INVARIANT 13: adapter.recall() always reverts for non-vault caller
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_recall_only_vault_caller(address caller, uint64 rawAmount) public {
        vm.assume(caller != address(vault));
        vm.assume(caller != address(0));
        uint256 amount = bound(rawAmount, 1e6, 1_000_000e6);

        vm.prank(caller);
        vm.expectRevert(bytes("GoldExchangeAdapter: caller is not the vault"));
        adapter.recall(amount);
    }
}

contracts/test/FuzzPurificationEscrow.t..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// forge-config: default.fuzz.runs = 512

import {Test} from "forge-std/Test.sol";

import {PurificationEscrow} from "../PurificationEscrow.sol";
import {CharityModule}      from "../CharityModule.sol";
import {TreasuryModule}     from "../TreasuryModule.sol";
import {MockERC20}          from "../test-helpers/MockERC20.sol";

contract MockRegistryFPE {
    address public board;
    constructor(address b) { board = b; }
    function isBoard(address a) external view returns (bool) { return a == board; }
}

/**
 * @title  FuzzPurificationEscrow
 * @notice Fuzz / property tests for PurificationEscrow.
 *
 * Invariants checked:
 *   1. purified + charity + vaultShare + depositorShare == grossProfit ALWAYS
 *   2. When purificationBps==0, purified==0 always
 *   3. charityAmount proportional to afterPurification * charityBps / 10_000
 *   4. depositorShare >= 0 always (no negative returns)
 *
 * forge-config: default.fuzz.runs = 512
 */
contract FuzzPurificationEscrow is Test {

    // ── Shariah params ────────────────────────────────────────────────────────
    uint256 internal constant ADMIN_FEE_BPS        = 50;
    uint256 internal constant MUSHARAKAH_SHARE_BPS = 1000;
    uint256 internal constant HURDLE_RATE_BPS       = 400;

    // ── actors ────────────────────────────────────────────────────────────────
    address internal owner         = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");

    // ── contracts ─────────────────────────────────────────────────────────────
    MockERC20          internal usdc;
    TreasuryModule     internal treasury;
    CharityModule      internal charityModule;
    PurificationEscrow internal escrow;

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        MockRegistryFPE reg = new MockRegistryFPE(owner); // J3

        // Pre-compute escrow address to wire feeSource correctly.
        // Deployment order from address(this):
        //   nonce+0 → treasury (deployed by address(this))
        //   charityModule is deployed by owner via vm.prank → does NOT consume test-contract nonce
        //   nonce+1 → escrow (deployed by address(this))
        uint256 nonce = vm.getNonce(address(this));
        address expectedEscrowAddr = vm.computeCreateAddress(address(this), nonce + 1);

        treasury = new TreasuryModule(
            "Shariah",
            expectedEscrowAddr,      // feeSource = escrow
            address(usdc),
            ADMIN_FEE_BPS,
            MUSHARAKAH_SHARE_BPS,
            HURDLE_RATE_BPS,
            owner
        );

        vm.prank(owner);
        charityModule = new CharityModule(
            charityWallet,
            address(usdc),
            expectedEscrowAddr,      // vault = escrow (escrow calls distributeCharity)
            owner,
            address(reg)             // J3: registry required
        );

        escrow = new PurificationEscrow(
            address(this),           // vault = test contract
            address(usdc),
            address(charityModule),
            address(treasury),
            owner,
            address(reg)             // J3: registry required
        );

        assertEq(address(escrow), expectedEscrowAddr, "escrow address mismatch");

        // Large balance for fuzz runs
        usdc.mint(address(this), type(uint128).max);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 1. Waterfall invariant: sum of parts always equals grossProfit
    // ─────────────────────────────────────────────────────────────────────────
    // N-07: retain conservation coverage while varying the loss-recovery reserve.
    function testFuzz_waterfall_invariant(
        uint96 grossProfit,
        uint32 elapsed,
        uint96 principal,
        uint96 deficit
    ) public {
        uint256 gross     = bound(uint256(grossProfit), 1e6, 100_000e6);
        uint256 elapsedSec = bound(uint256(elapsed), 0, 5 * 365 days);
        uint256 princ      = bound(uint256(principal), 1e6, 1_000_000e6);

        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) =
            escrow.executeWaterfallHWM(gross, elapsedSec, princ, bound(uint256(deficit), 0, 200_000e6));

        assertEq(
            purified + charity + vaultShare + depositorShare,
            gross,
            "invariant: components must sum to grossProfit"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 2. purificationBps==0 → purified==0 always
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_purification_rate_zero_means_zero_purified(uint96 grossProfit) public {
        uint256 gross = bound(uint256(grossProfit), 1e6, 100_000e6);

        // Confirm default purificationBps is 0
        assertEq(escrow.purificationBps(), 0);

        usdc.approve(address(escrow), gross);
        (uint256 purified,,,) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        assertEq(purified, 0, "purified must be 0 when purificationBps==0");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 3. charityAmount proportional to afterPurification * rate / 10_000
    //    (within 1 due to integer truncation)
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_charityAmount_proportional(uint96 grossProfit, uint8 rateSeed) public {
        uint256 gross = bound(uint256(grossProfit), 1e6, 100_000e6);
        // Rate must be <= MAX_CHARITY_BPS (500)
        uint256 rate  = bound(uint256(rateSeed), 0, 500);

        // Set charity rate via timelock
        vm.startPrank(owner);
        charityModule.proposeCharityRateChange(rate);
        vm.warp(block.timestamp + 30 days);
        charityModule.confirmCharityRateChange();
        vm.stopPrank();

        assertEq(charityModule.charityBps(), rate);

        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity,,) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        uint256 afterPurification = gross - purified; // purificationBps=0 → afterPurification=gross
        uint256 expectedCharity   = (afterPurification * rate) / 10_000;

        // Integer division can differ by at most 1
        uint256 diff = charity > expectedCharity ? charity - expectedCharity : expectedCharity - charity;
        assertLe(diff, 1, "charityAmount should match rate * afterPurification / 10_000 within 1");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 4. depositorShare is always >= 0 (uint256 invariant — never underflows)
    //    Combined with invariant #1 this proves no component goes negative.
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_depositorShare_gte_zero(
        uint96 grossProfit,
        uint32 elapsed,
        uint96 principal
    ) public {
        uint256 gross      = bound(uint256(grossProfit), 1e6, 100_000e6);
        uint256 elapsedSec = bound(uint256(elapsed), 0, 5 * 365 days);
        uint256 princ      = bound(uint256(principal), 1e6, 1_000_000e6);

        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) =
            escrow.executeWaterfall(gross, elapsedSec, princ);

        // uint256 cannot be negative; also assert vaultShare <= gross (no overflow)
        assertLe(vaultShare,     gross, "vaultShare must not exceed grossProfit");
        assertLe(depositorShare, gross, "depositorShare must not exceed grossProfit");
        // Redundant but explicit
        assertGe(depositorShare, 0,    "depositorShare must be >= 0");

        // Also verify the invariant holds in this run
        assertEq(purified + charity + vaultShare + depositorShare, gross,
            "invariant must hold for all inputs");
    }
}

contracts/test/FuzzRiskTieredExecutor.t..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {ScoreAggregator} from "../ScoreAggregator.sol";
import {RiskTieredExecutor} from "../RiskTieredExecutor.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

contract FuzzExecAdapter is IStrategyAdapter {
    address public override vault;
    address public usdc;
    constructor(address v, address u) { vault = v; usdc = u; }
    function deploy(uint256 a) external override returns (uint256) { return a; }
    function recall(uint256 a) external override returns (uint256) {
        IERC20(usdc).transfer(vault, a);
        return a;
    }
    function currentValue() external view override returns (uint256) {
        return IERC20(usdc).balanceOf(address(this));
    }
    function protocolName() external pure override returns (string memory) { return "Fuzz"; }
}

contract FuzzRiskTieredExecutor is Test {
    MockERC20 internal usdc;
    AutonomousVault internal vault;
    ScoreAggregator internal aggregator;
    RiskTieredExecutor internal executor; // PASSIVE
    FuzzExecAdapter internal adapter;

    address internal owner = makeAddr("owner");
    address internal alice = makeAddr("alice");

    ScoreAggregator.Strategy internal constant S0 = ScoreAggregator.Strategy.STABLECOIN_SPREAD;
    ScoreAggregator.Strategy internal constant S3 = ScoreAggregator.Strategy.LIQUIDATION_RWA;

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);

        vm.startPrank(owner);
        vault      = new AutonomousVault(IERC20(address(usdc)), owner, 1);
        aggregator = new ScoreAggregator(owner);
        executor   = new RiskTieredExecutor(
            address(vault), address(aggregator),
            RiskTieredExecutor.RiskTier.PASSIVE, owner
        );
        vm.stopPrank();

        adapter = new FuzzExecAdapter(address(vault), address(usdc));

        // Fund vault
        usdc.mint(alice, 100_000e6);
        vm.prank(alice);
        usdc.approve(address(vault), 100_000e6);
        vm.prank(alice);
        vault.deposit(100_000e6, alice);

        vm.prank(owner);
        vault.setManager(address(executor));

        vm.prank(owner);
        executor.setMaxGasPrice(1_000 gwei); // never hit in tests

        // Configure S0 (bit 0, in PASSIVE mask=9)
        vm.prank(owner);
        executor.setStrategyConfig(S0, address(adapter), bytes32(0), true, 1e6, 50_000e6);

        // Skip initial cooldown
        skip(2 hours + 1);
    }

    // -----------------------------------------------------------------------
    // Fuzz: any score below minScoreToExecute reverts ScoreTooLow
    // -----------------------------------------------------------------------
    function testFuzz_score_too_low_always_reverts(uint8 score) public {
        // score=0 is treated as "no score written" by ScoreAggregator — winner selection
        // reverts NoValidScores before the ScoreTooLow check can fire.
        // Constrain to 1–79 so a valid-but-low score is always written.
        score = uint8(bound(score, 1, 79)); // PASSIVE min = 80

        vm.prank(owner);
        aggregator.writeScore(S0, score, bytes32(0), 0);

        vm.txGasPrice(1 gwei);
        vm.expectRevert(
            abi.encodeWithSelector(RiskTieredExecutor.ScoreTooLow.selector, score, uint8(80))
        );
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // Fuzz: any score ≥ minScoreToExecute succeeds (assuming cooldown elapsed)
    // -----------------------------------------------------------------------
    function testFuzz_score_sufficient_executes(uint8 score) public {
        score = uint8(bound(score, 80, 100)); // PASSIVE min = 80

        vm.prank(owner);
        aggregator.writeScore(S0, score, bytes32(0), 0);

        vm.txGasPrice(1 gwei);
        executor.executeWinner();

        assertGt(vault.totalDeployed(), 0, "capital should be deployed");
    }

    // -----------------------------------------------------------------------
    // Fuzz: gas price above maxGasPrice always reverts
    // -----------------------------------------------------------------------
    function testFuzz_gas_price_too_high(uint256 gasPrice) public {
        uint256 max = executor.maxGasPrice();
        gasPrice = bound(gasPrice, max + 1, type(uint64).max);

        vm.prank(owner);
        aggregator.writeScore(S0, 90, bytes32(0), 0);

        vm.txGasPrice(gasPrice);
        vm.expectRevert(RiskTieredExecutor.GasPriceTooHigh.selector);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // Fuzz: any gas price ≤ maxGasPrice does not trigger gas-price revert
    // -----------------------------------------------------------------------
    function testFuzz_gas_price_within_limit(uint256 gasPrice) public {
        uint256 max = executor.maxGasPrice();
        gasPrice = bound(gasPrice, 0, max);

        vm.prank(owner);
        aggregator.writeScore(S0, 90, bytes32(0), 0);

        vm.txGasPrice(gasPrice);
        // Must not revert with GasPriceTooHigh — may revert for other reasons (none here)
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // Fuzz: cooldown guard — any elapsed < cooldown reverts CooldownNotElapsed
    // -----------------------------------------------------------------------
    function testFuzz_cooldown_guard(uint32 shortElapsed) public {
        // First execution to set lastExecutionTime
        vm.prank(owner);
        aggregator.writeScore(S0, 90, bytes32(0), 0);
        vm.txGasPrice(1 gwei);
        executor.executeWinner();

        // Return capital
        uint256 deployed = vault.totalDeployed();
        vm.prank(address(adapter));
        usdc.approve(address(vault), deployed);
        vm.prank(owner);
        vault.returnCapital(address(adapter), deployed);

        uint256 cd = executor.executionCooldown();
        shortElapsed = uint32(bound(shortElapsed, 0, cd > 1 ? cd - 1 : 0));
        skip(shortElapsed);

        // Write fresh score
        vm.prank(owner);
        aggregator.writeScore(S0, 90, bytes32(0), 0);

        vm.txGasPrice(1 gwei);
        if (shortElapsed < cd) {
            vm.expectRevert(); // CooldownNotElapsed
            executor.executeWinner();
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: strategy not in mask always reverts StrategyNotAllowedForTier
    //   PASSIVE mask = 9 = 0b00001001 (bits 0 and 3 only)
    //   strategies 1 and 2 are NOT in mask
    // -----------------------------------------------------------------------
    function testFuzz_strategy_not_in_mask_reverts(uint8 stratIdx) public {
        // Strategies with bit NOT in PASSIVE mask=9 → bits 1 and 2
        stratIdx = uint8(bound(stratIdx, 1, 2));
        ScoreAggregator.Strategy strat = ScoreAggregator.Strategy(stratIdx);

        // Configure that strategy's adapter (enabled) but mask excludes it
        vm.prank(owner);
        executor.setStrategyConfig(strat, address(adapter), bytes32(0), true, 1e6, 50_000e6);

        // Write a very high score for this strategy and 0 for the others
        // so it would win — then the mask check must block it
        vm.prank(owner);
        aggregator.writeScore(strat, 99, bytes32(0), 0);

        vm.txGasPrice(1 gwei);
        // Winner will be this out-of-mask strategy; must revert
        vm.expectRevert(
            abi.encodeWithSelector(
                RiskTieredExecutor.StrategyNotAllowedForTier.selector,
                stratIdx,
                uint8(9)
            )
        );
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // Fuzz: setMinScore enforces 0–100 range
    // -----------------------------------------------------------------------
    function testFuzz_setMinScore(uint256 score) public {
        if (score > 100) {
            vm.prank(owner);
            vm.expectRevert(); // "Score too high"
            executor.setMinScore(uint8(score > 255 ? 255 : score));
        } else {
            vm.prank(owner);
            executor.setMinScore(uint8(score));
            assertEq(executor.minScoreToExecute(), uint8(score));
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: setCooldown rejects > 24 hours
    // -----------------------------------------------------------------------
    function testFuzz_setCooldown(uint256 cd) public {
        if (cd > 24 hours) {
            vm.prank(owner);
            vm.expectRevert(); // "Cooldown too long"
            executor.setCooldown(cd);
        } else {
            vm.prank(owner);
            executor.setCooldown(cd);
            assertEq(executor.executionCooldown(), cd);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: setMaxGasPrice always accepted (no explicit bound in contract)
    // -----------------------------------------------------------------------
    function testFuzz_setMaxGasPrice(uint256 gp) public {
        vm.prank(owner);
        executor.setMaxGasPrice(gp);
        assertEq(executor.maxGasPrice(), gp);
    }

    // -----------------------------------------------------------------------
    // Fuzz: isStrategyAllowed matches bitmask logic
    // -----------------------------------------------------------------------
    function testFuzz_isStrategyAllowed_matches_mask(uint8 stratIdx) public view {
        stratIdx = uint8(bound(stratIdx, 0, 3));
        ScoreAggregator.Strategy strat = ScoreAggregator.Strategy(stratIdx);

        bool expected = ((executor.strategyMask() >> stratIdx) & 1) == 1;
        assertEq(executor.isStrategyAllowed(strat), expected, "isStrategyAllowed must match mask bit");
    }
}

contracts/test/FuzzScoreAggregator.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {ScoreAggregator} from "../ScoreAggregator.sol";

contract FuzzScoreAggregator is Test {
    ScoreAggregator internal agg;

    address internal owner = makeAddr("owner");
    address internal oracle = makeAddr("oracle");

    ScoreAggregator.Strategy internal constant S0 = ScoreAggregator.Strategy.STABLECOIN_SPREAD;
    ScoreAggregator.Strategy internal constant S1 = ScoreAggregator.Strategy.FUNDING_RATE_ARB;
    ScoreAggregator.Strategy internal constant S2 = ScoreAggregator.Strategy.BRIDGE_FLOW;
    ScoreAggregator.Strategy internal constant S3 = ScoreAggregator.Strategy.LIQUIDATION_RWA;

    function setUp() public {
        vm.prank(owner);
        agg = new ScoreAggregator(owner);
        vm.prank(owner);
        agg.setOracle(oracle);
    }

    // -----------------------------------------------------------------------
    // Fuzz: any score 0–100 must store and retrieve correctly; >100 must revert
    // -----------------------------------------------------------------------
    function testFuzz_writeScore_value_range(uint8 score) public {
        if (score > 100) {
            vm.prank(oracle);
            vm.expectRevert(ScoreAggregator.InvalidScore.selector);
            agg.writeScore(S0, score, bytes32(0), 0);
        } else {
            vm.prank(oracle);
            agg.writeScore(S0, score, bytes32(0), 0);
            (uint8 stored,,,) = agg.scores(S0);
            assertEq(stored, score);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: any score written → getWinningStrategy returns it if it's the only valid one
    // -----------------------------------------------------------------------
    function testFuzz_singleScore_always_wins(uint8 score, uint8 stratIdx) public {
        score = uint8(bound(score, 1, 100));
        stratIdx = uint8(bound(stratIdx, 0, 3));
        ScoreAggregator.Strategy strat = ScoreAggregator.Strategy(stratIdx);

        vm.prank(oracle);
        agg.writeScore(strat, score, bytes32(0), 0);

        (ScoreAggregator.Strategy winner, uint8 winScore,) = agg.getWinningStrategy();
        assertEq(uint8(winner), stratIdx);
        assertEq(winScore, score);
    }

    // -----------------------------------------------------------------------
    // Fuzz: getWinningStrategy always returns the highest score among 4 strategies
    // -----------------------------------------------------------------------
    function testFuzz_winning_strategy_is_highest(
        uint8 s0, uint8 s1, uint8 s2, uint8 s3
    ) public {
        s0 = uint8(bound(s0, 1, 100));
        s1 = uint8(bound(s1, 1, 100));
        s2 = uint8(bound(s2, 1, 100));
        s3 = uint8(bound(s3, 1, 100));

        vm.startPrank(oracle);
        agg.writeScore(S0, s0, bytes32(0), 0);
        agg.writeScore(S1, s1, bytes32(0), 0);
        agg.writeScore(S2, s2, bytes32(0), 0);
        agg.writeScore(S3, s3, bytes32(0), 0);
        vm.stopPrank();

        (, uint8 winScore,) = agg.getWinningStrategy();

        uint8 expectedMax = s0;
        if (s1 > expectedMax) expectedMax = s1;
        if (s2 > expectedMax) expectedMax = s2;
        if (s3 > expectedMax) expectedMax = s3;

        assertEq(winScore, expectedMax, "winner must have the highest score");
    }

    // -----------------------------------------------------------------------
    // Fuzz: staleness — any score written more than 5 min ago is stale
    // -----------------------------------------------------------------------
    function testFuzz_staleness(uint32 elapsed) public {
        vm.prank(oracle);
        agg.writeScore(S0, 80, bytes32(0), 0);

        if (elapsed > 5 minutes) {
            skip(elapsed);
            vm.expectRevert(); // StaleScore
            agg.getWinningStrategy();
        } else {
            skip(elapsed);
            // Should still succeed (not stale)
            (,uint8 winScore,) = agg.getWinningStrategy();
            assertEq(winScore, 80);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: destinationDomain stored and retrieved accurately
    // -----------------------------------------------------------------------
    function testFuzz_destinationDomain_roundtrip(uint32 domain, uint8 stratIdx) public {
        stratIdx = uint8(bound(stratIdx, 0, 3));
        ScoreAggregator.Strategy strat = ScoreAggregator.Strategy(stratIdx);

        vm.prank(oracle);
        agg.writeScore(strat, 50, bytes32(0), domain);

        (,, uint32[4] memory domains) = agg.getAllScores();
        assertEq(domains[stratIdx], domain);
    }

    // -----------------------------------------------------------------------
    // Fuzz: ring-buffer never corrupts — write N scores, all 10 history slots valid
    // -----------------------------------------------------------------------
    function testFuzz_ringBuffer_no_corruption(uint8 n) public {
        n = uint8(bound(n, 1, 50));

        vm.startPrank(oracle);
        for (uint8 i = 0; i < n; i++) {
            uint8 score = uint8((i % 100) + 1);
            agg.writeScore(S0, score, keccak256(abi.encode(i)), 0);
        }
        vm.stopPrank();

        ScoreAggregator.Score[10] memory history = agg.getScoreHistory(S0);
        uint256 expectedSlots = n < 10 ? n : 10;
        uint256 nonZero;
        for (uint256 i = 0; i < 10; i++) {
            if (history[i].value > 0) nonZero++;
        }
        assertEq(nonZero, expectedSlots, "ring buffer slot count must match min(n, 10)");
    }

    // -----------------------------------------------------------------------
    // Fuzz: only oracle or owner can write; any other address must revert
    // -----------------------------------------------------------------------
    function testFuzz_access_control(address caller) public {
        vm.assume(caller != oracle && caller != owner);

        vm.prank(caller);
        vm.expectRevert(ScoreAggregator.NotOracle.selector);
        agg.writeScore(S0, 50, bytes32(0), 0);
    }

    // -----------------------------------------------------------------------
    // Fuzz: batch write — any equal-length arrays succeed; mismatched reverts
    // -----------------------------------------------------------------------
    function testFuzz_batchWrite_length_invariant(uint8 len1, uint8 len2) public {
        len1 = uint8(bound(len1, 1, 4));
        len2 = uint8(bound(len2, 0, 4));

        ScoreAggregator.Strategy[] memory strats = new ScoreAggregator.Strategy[](len1);
        uint8[] memory vals = new uint8[](len1);
        bytes32[] memory hashes = new bytes32[](len1);
        uint32[] memory domains = new uint32[](len2); // potentially different length

        for (uint8 i = 0; i < len1; i++) {
            strats[i] = ScoreAggregator.Strategy(i % 4);
            vals[i] = 50;
            hashes[i] = bytes32(0);
        }

        if (len1 != len2) {
            vm.prank(oracle);
            vm.expectRevert(ScoreAggregator.InvalidScore.selector);
            agg.writeBatchScores(strats, vals, hashes, domains);
        } else {
            // Equal lengths — should succeed (all scores are valid ≤100)
            vm.prank(oracle);
            agg.writeBatchScores(strats, vals, hashes, domains);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: score of exactly 0 is stored but treated as "no score" by winner
    // -----------------------------------------------------------------------
    function testFuzz_zero_score_not_counted_as_winner(uint8 nonzeroScore) public {
        nonzeroScore = uint8(bound(nonzeroScore, 1, 100));

        vm.startPrank(oracle);
        agg.writeScore(S0, 0, bytes32(0), 0);  // zero — should be skipped
        agg.writeScore(S1, nonzeroScore, bytes32(0), 0);
        vm.stopPrank();

        (ScoreAggregator.Strategy winner, uint8 score,) = agg.getWinningStrategy();
        assertEq(uint8(winner), uint8(S1), "S0 with score=0 must not win");
        assertEq(score, nonzeroScore);
    }
}

contracts/test/FuzzShariahVaultV2.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// forge-config: default.fuzz.runs = 512

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {AutonomousVault}        from "../AutonomousVault.sol";
import {ShariahVault}           from "../ShariahVault.sol";
import {ShariahVaultV2}         from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TreasuryModule}         from "../TreasuryModule.sol";
import {ZakatModule}            from "../ZakatModule.sol";
import {MockERC20}              from "../test-helpers/MockERC20.sol";

/// @title FuzzShariahVaultV2
/// @notice Fuzz tests for ShariahVaultV2 and ShariahAdapterRegistry — Task E
contract FuzzShariahVaultV2 is Test {

    // ── actors ────────────────────────────────────────────────────
    address internal owner         = makeAddr("owner");
    address internal alice         = makeAddr("alice");
    address internal charityWallet = makeAddr("charity");

    // ── constants ─────────────────────────────────────────────────
    uint32  internal constant SOURCE_DOMAIN       = 26;
    bytes32 internal constant HASH                = keccak256("SR-005");
    uint256 internal constant TIMELOCK            = 30 days;
    uint256 internal constant VALID_EXPIRY_OFFSET = 365 days;
    uint256 internal constant MAX_EXPIRY_PERIOD   = 730 days;

    // ── contracts ─────────────────────────────────────────────────
    MockERC20              internal usdc;
    TreasuryModule         internal treasury;
    ZakatModule            internal zakatModule;
    ShariahAdapterRegistry internal registry;
    ShariahVaultV2         internal vault;
    ShariahVault           internal vaultV1;

    // ── adapter ───────────────────────────────────────────────────
    address internal adapter = makeAddr("mockAdapter");

    // ─────────────────────────────────────────────────────────────
    // setUp — runs before every fuzz test
    // ─────────────────────────────────────────────────────────────

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);

        vm.startPrank(owner);

        treasury = new TreasuryModule(
            "Shariah",
            address(0), // feeSource: no fee accrual when adminFeeBps=0
            address(usdc),
            0,  // adminFeeBps = 0 → fee=0 → skip accrue() call
            0,
            0,
            owner
        );

        zakatModule = new ZakatModule(charityWallet, address(usdc), address(0), owner);

        registry = new ShariahAdapterRegistry(owner, owner);

        vault = new ShariahVaultV2(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(treasury),
            address(zakatModule),
            address(registry)
        );

        vaultV1 = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(treasury),
            address(zakatModule)
        );

        vm.stopPrank();
    }

    // ─────────────────────────────────────────────────────────────
    // Internal helpers
    // ─────────────────────────────────────────────────────────────

    function _screenAdapter(address _adapter, uint256 expiryOffset) internal {
        // expiresAt must be after the post-warp block.timestamp to be valid.
        // Compute it relative to the timestamp AFTER the timelock warp.
        uint256 expiresAt = block.timestamp + TIMELOCK + expiryOffset;
        vm.prank(owner);
        registry.proposeScreening(_adapter, HASH, expiresAt);
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(owner);
        registry.executeScreening(_adapter);
    }

    // ─────────────────────────────────────────────────────────────
    // 1. testFuzz_migration_roundtrip
    //    Deposit `amount` to V1, redeem all, deposit to V2.
    //    V2 shares NAV >= 99.9% of USDC redeemed.
    // ─────────────────────────────────────────────────────────────

    function testFuzz_migration_roundtrip(uint96 amount) public {
        uint256 amt = bound(uint256(amount), 1e6, 100_000e6);

        // ── V1 deposit ────────────────────────────────────────────
        usdc.mint(alice, amt);
        vm.startPrank(alice);
        usdc.approve(address(vaultV1), amt);
        uint256 v1Shares = vaultV1.deposit(amt, alice);
        vm.stopPrank();

        // ── Redeem from V1 immediately (no deployment, no fee) ────
        vm.startPrank(alice);
        uint256 usdcReceived = vaultV1.redeem(v1Shares, alice, alice);
        vm.stopPrank();

        // usdcReceived should be non-zero
        assertGt(usdcReceived, 0, "must receive USDC from V1 redeem");

        // ── V2 deposit ────────────────────────────────────────────
        vm.startPrank(alice);
        usdc.approve(address(vault), usdcReceived);
        uint256 v2Shares = vault.deposit(usdcReceived, alice);
        vm.stopPrank();

        // ── 99.9% invariant ───────────────────────────────────────
        uint256 v2Nav = vault.convertToAssets(v2Shares);
        assertGe(v2Nav, (usdcReceived * 999) / 1000, "V2 NAV must be >= 99.9% of redeemed USDC");
    }

    // ─────────────────────────────────────────────────────────────
    // 2. testFuzz_timelock_enforced
    //    For any warpTime in [0, 29 days), propose + warp + execute
    //    must revert TimelockNotElapsed.
    // ─────────────────────────────────────────────────────────────

    function testFuzz_timelock_enforced(uint256 warpTime) public {
        warpTime = bound(warpTime, 0, TIMELOCK - 1);

        uint256 expiresAt = block.timestamp + VALID_EXPIRY_OFFSET;

        vm.prank(owner);
        registry.proposeScreening(adapter, HASH, expiresAt);

        uint256 executeAfter = block.timestamp + TIMELOCK;
        vm.warp(block.timestamp + warpTime);

        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(
                ShariahAdapterRegistry.TimelockNotElapsed.selector,
                executeAfter,
                block.timestamp
            )
        );
        registry.executeScreening(adapter);
    }

    // ─────────────────────────────────────────────────────────────
    // 3. testFuzz_screened_expires
    //    Screen adapter with expiresAt = now + validitySeconds.
    //    Immediately: isScreened == true.
    //    After warp past expiresAt: isScreened == false.
    // ─────────────────────────────────────────────────────────────

    function testFuzz_screened_expires(uint256 validitySeconds) public {
        // Bound to [1 day, 730 days] — within MAX_EXPIRY_PERIOD, above zero
        // expiresAt = block.timestamp + TIMELOCK + validitySeconds in _screenAdapter.
        // Registry cap: expiresAt <= block.timestamp + MAX_EXPIRY_PERIOD.
        // After warp: block.timestamp' = block.timestamp + TIMELOCK.
        // So validitySeconds must be <= MAX_EXPIRY_PERIOD - TIMELOCK.
        uint256 maxValidity = MAX_EXPIRY_PERIOD > TIMELOCK ? MAX_EXPIRY_PERIOD - TIMELOCK : 1 days;
        validitySeconds = bound(validitySeconds, 1 days, maxValidity);

        _screenAdapter(adapter, validitySeconds);

        // Right after execute: should be screened (we are still before expiresAt)
        assertTrue(registry.isScreened(adapter), "should be screened immediately after execute");

        // Warp to exactly expiresAt — isScreened checks block.timestamp < expiresAt
        ShariahAdapterRegistry.Screening memory s = registry.getScreening(adapter);
        vm.warp(s.expiresAt);
        assertFalse(registry.isScreened(adapter), "should not be screened at expiresAt");

        // Warp one second further — still not screened
        vm.warp(s.expiresAt + 1);
        assertFalse(registry.isScreened(adapter), "should not be screened past expiresAt");
    }

    // ─────────────────────────────────────────────────────────────
    // 4. testFuzz_deployCapital_cap_respected
    //    Deploy `amount` to adapter. Sum deployed must not exceed
    //    maxAllocationBps * totalAssets / 10_000.
    //    Over-limit amounts revert AllocationExceedsLimit.
    // ─────────────────────────────────────────────────────────────

    function testFuzz_deployCapital_cap_respected(uint96 amount) public {
        uint256 amt = bound(uint256(amount), 1e6, 500e6);

        // Fund the V2 vault so totalAssets is non-trivial
        uint256 depositAmt = 1_000e6;
        usdc.mint(alice, depositAmt);
        vm.startPrank(alice);
        usdc.approve(address(vault), depositAmt);
        vault.deposit(depositAmt, alice);
        vm.stopPrank();

        // Screen the adapter
        _screenAdapter(adapter, VALID_EXPIRY_OFFSET);

        uint256 maxAllocationBps = vault.maxAllocationBps();         // default 8000
        uint256 currentAssets    = vault.totalAssets();               // = depositAmt (nothing deployed yet)
        uint256 maxDeployable    = (currentAssets * maxAllocationBps) / 10_000;

        if (amt <= maxDeployable) {
            // Should succeed
            vm.prank(owner);
            vault.deployCapital(adapter, amt, "");
            assertGe(vault.totalDeployed(), amt, "totalDeployed should reflect deployment");
        } else {
            // Should revert AllocationExceedsLimit
            vm.prank(owner);
            vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
            vault.deployCapital(adapter, amt, "");
        }
    }
}

contracts/test/FuzzTreasuryModule.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {TreasuryModule} from "../TreasuryModule.sol";

contract FuzzTreasuryModule is Test {
    TreasuryModule internal treasury;
    TreasuryModule internal shariahTreasury;

    address internal owner     = makeAddr("owner");
    address internal feeSource = makeAddr("feeSource");
    address internal asset     = makeAddr("asset");
    address internal receiver  = makeAddr("receiver");

    function setUp() public {
        vm.prank(owner);
        treasury = new TreasuryModule("Conventional", feeSource, asset, 75, 0, 0, owner);

        vm.prank(owner);
        shariahTreasury = new TreasuryModule("Shariah", feeSource, asset, 50, 1000, 400, owner);
    }

    // -----------------------------------------------------------------------
    // Fuzz: accrue any amount — pendingFees accumulates correctly
    // -----------------------------------------------------------------------
    function testFuzz_accrue_accumulates(uint96 a1, uint96 a2) public {
        uint256 amt1 = bound(a1, 0, 1e18);
        uint256 amt2 = bound(a2, 0, 1e18);

        vm.startPrank(feeSource);
        treasury.accrue(amt1);
        treasury.accrue(amt2);
        vm.stopPrank();

        assertEq(treasury.pendingFees(), amt1 + amt2);
        assertEq(treasury.totalAumAccrued(), amt1 + amt2);
    }

    // -----------------------------------------------------------------------
    // Fuzz: claimFees can never claim more than pendingFees
    // -----------------------------------------------------------------------
    function testFuzz_claimFees_never_exceeds_pending(uint96 accrued_, uint96 claim_) public {
        uint256 accrued = bound(accrued_, 1, 1e18);
        uint256 claim   = bound(claim_,   1, 2e18);

        vm.prank(feeSource);
        treasury.accrue(accrued);

        if (claim > accrued) {
            vm.prank(owner);
            vm.expectRevert(
                abi.encodeWithSelector(TreasuryModule.InsufficientPending.selector, claim, accrued)
            );
            treasury.claimFees(receiver, claim);
        } else {
            vm.prank(owner);
            treasury.claimFees(receiver, claim);
            assertEq(treasury.pendingFees(), accrued - claim);
            assertEq(treasury.totalFeesCollected(), claim);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: adminFeeBps setter enforces 0–500 range
    // -----------------------------------------------------------------------
    function testFuzz_setAdminFeeBps_range(uint256 bps) public {
        if (bps > 500) {
            vm.prank(owner);
            vm.expectRevert(TreasuryModule.InvalidBps.selector);
            treasury.setAdminFeeBps(bps);
        } else {
            vm.prank(owner);
            treasury.setAdminFeeBps(bps);
            assertEq(treasury.adminFeeBps(), bps);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: musharakah split math — depositorShare + vaultShare == grossProfit always
    // -----------------------------------------------------------------------
    function testFuzz_musharakah_split_conservation(
        uint96 grossProfit_,
        uint32 elapsed_,
        uint96 principal_
    ) public view {
        uint256 grossProfit = bound(grossProfit_, 0, 1_000_000e6);
        uint256 elapsed     = bound(elapsed_,     0, 10 * 365 days);
        uint256 principal   = bound(principal_,   0, 1_000_000_000e6);

        (,uint256 vaultShare, uint256 depositorShare) =
            shariahTreasury.calculateMusharakahSplit(grossProfit, elapsed, principal);

        assertEq(
            vaultShare + depositorShare,
            grossProfit,
            "vaultShare + depositorShare must always equal grossProfit"
        );
    }

    // -----------------------------------------------------------------------
    // Fuzz: vaultShare is always ≤ grossProfit (no over-extraction)
    // -----------------------------------------------------------------------
    function testFuzz_musharakah_vault_share_bounded(
        uint96 gross,
        uint32 elapsed,
        uint96 principal
    ) public view {
        uint256 grossProfit = bound(gross,     0, 1_000_000e6);
        uint256 el          = bound(elapsed,   0, 5 * 365 days);
        uint256 prin        = bound(principal, 0, 1_000_000_000e6);

        (, uint256 vaultShare,) = shariahTreasury.calculateMusharakahSplit(grossProfit, el, prin);
        assertLe(vaultShare, grossProfit, "vault share must never exceed gross profit");
    }

    // -----------------------------------------------------------------------
    // Fuzz: depositorShare is always ≥ hurdleAmount (hurdle goes to depositor, not vault)
    // -----------------------------------------------------------------------
    function testFuzz_musharakah_depositor_gets_hurdle(
        uint96 gross,
        uint32 elapsed,
        uint96 principal
    ) public view {
        uint256 grossProfit = bound(gross,     0, 1_000_000e6);
        uint256 el          = bound(elapsed,   0, 5 * 365 days);
        uint256 prin        = bound(principal, 0, 1_000_000_000e6);

        (uint256 hurdleAmt, , uint256 depositorShare) =
            shariahTreasury.calculateMusharakahSplit(grossProfit, el, prin);

        if (grossProfit >= hurdleAmt) {
            // depositorShare must include at least the hurdle portion
            assertGe(depositorShare, hurdleAmt, "depositor must receive at least hurdle amount");
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: setMusharakahParams enforces share ≤ 3000, hurdle ≤ 2000
    // -----------------------------------------------------------------------
    function testFuzz_setMusharakahParams_bounds(uint256 shareBps, uint256 hurdleBps) public {
        bool valid = shareBps <= 3_000 && hurdleBps <= 2_000;

        if (!valid) {
            vm.prank(owner);
            vm.expectRevert(TreasuryModule.InvalidBps.selector);
            shariahTreasury.setMusharakahParams(shareBps, hurdleBps);
        } else {
            vm.prank(owner);
            shariahTreasury.setMusharakahParams(shareBps, hurdleBps);
            assertEq(shariahTreasury.musharakahShareBps(), shareBps);
            assertEq(shariahTreasury.hurdleRateBps(), hurdleBps);
        }
    }

    // -----------------------------------------------------------------------
    // Fuzz: recordMusharakahProfit increments pendingFees by exact amount
    // -----------------------------------------------------------------------
    function testFuzz_recordMusharakahProfit(uint96 a1, uint96 a2) public {
        uint256 amt1 = bound(a1, 0, 1e18);
        uint256 amt2 = bound(a2, 0, 1e18);

        vm.startPrank(feeSource);
        shariahTreasury.recordMusharakahProfit(amt1);
        shariahTreasury.recordMusharakahProfit(amt2);
        vm.stopPrank();

        assertEq(shariahTreasury.pendingFees(), amt1 + amt2);
    }

    // -----------------------------------------------------------------------
    // Fuzz: constructor rejects any adminFeeBps > 500
    // -----------------------------------------------------------------------
    function testFuzz_constructor_adminBps_guard(uint256 bps) public {
        vm.assume(bps > 500 && bps < type(uint128).max);
        vm.prank(owner);
        vm.expectRevert(TreasuryModule.InvalidBps.selector);
        new TreasuryModule("T", feeSource, asset, bps, 0, 0, owner);
    }

    // -----------------------------------------------------------------------
    // Fuzz: constructor rejects musharakahShareBps > 3000
    // -----------------------------------------------------------------------
    function testFuzz_constructor_musharakahBps_guard(uint256 shareBps) public {
        vm.assume(shareBps > 3_000 && shareBps < type(uint128).max);
        vm.prank(owner);
        vm.expectRevert(TreasuryModule.InvalidBps.selector);
        new TreasuryModule("T", feeSource, asset, 50, shareBps, 0, owner);
    }
}

contracts/test/FuzzZakatModule.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {ZakatModule} from "../ZakatModule.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

contract FuzzZakatModule is Test {
    MockERC20 internal usdc;
    ZakatModule internal zakatModule;

    address internal owner        = makeAddr("owner");
    address internal charityWallet = makeAddr("charity");
    // The test contract itself is the vault
    address internal vault;

    function setUp() public {
        vault = address(this);
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        vm.prank(owner);
        zakatModule = new ZakatModule(charityWallet, address(usdc), vault, owner);
    }

    function _fund(uint256 amount) internal {
        usdc.mint(vault, amount);
        usdc.approve(address(zakatModule), amount);
    }

    // -----------------------------------------------------------------------
    // Fuzz: zakat amount is always exactly 2.5% of grossProfit
    // -----------------------------------------------------------------------
    function testFuzz_zakat_amount_exact(uint96 grossProfit_) public {
        uint256 grossProfit = bound(grossProfit_, 1, 1_000_000_000e6);
        _fund(grossProfit);

        (uint256 zakatAmount, uint256 remaining) = zakatModule.distributeZakat(grossProfit);

        uint256 expectedZakat = (grossProfit * 250) / 10_000;
        assertEq(zakatAmount, expectedZakat, "zakat must be exactly 2.5%");
        assertEq(remaining, grossProfit - expectedZakat, "remaining must be grossProfit - zakat");
        assertEq(zakatAmount + remaining, grossProfit, "zakat + remaining must equal gross");
    }

    // -----------------------------------------------------------------------
    // Fuzz: charity wallet receives exact zakat amount
    // -----------------------------------------------------------------------
    function testFuzz_charity_receives_correct_amount(uint96 grossProfit_) public {
        uint256 grossProfit = bound(grossProfit_, 1, 100_000_000e6);
        _fund(grossProfit);

        uint256 beforeBalance = usdc.balanceOf(charityWallet);
        (uint256 zakatAmount,) = zakatModule.distributeZakat(grossProfit);

        assertEq(
            usdc.balanceOf(charityWallet) - beforeBalance,
            zakatAmount,
            "charity balance delta must equal zakatAmount"
        );
    }

    // -----------------------------------------------------------------------
    // Fuzz: totalZakatDistributed accumulates correctly across N calls
    // -----------------------------------------------------------------------
    function testFuzz_totalZakat_accumulates(uint64 a, uint64 b, uint64 c) public {
        uint256 g1 = bound(a, 1, 1_000_000e6);
        uint256 g2 = bound(b, 1, 1_000_000e6);
        uint256 g3 = bound(c, 1, 1_000_000e6);
        uint256 totalGross = g1 + g2 + g3;

        _fund(totalGross);
        // Need to approve in batches since _fund sets one approval
        usdc.approve(address(zakatModule), totalGross);

        zakatModule.distributeZakat(g1);
        zakatModule.distributeZakat(g2);
        zakatModule.distributeZakat(g3);

        uint256 expectedTotal = (g1 * 250 / 10_000) + (g2 * 250 / 10_000) + (g3 * 250 / 10_000);
        // allow off-by-one rounding across 3 divisions
        assertApproxEqAbs(zakatModule.totalZakatDistributed(), expectedTotal, 3);
    }

    // -----------------------------------------------------------------------
    // Fuzz: non-vault caller always reverts regardless of amount
    // -----------------------------------------------------------------------
    function testFuzz_only_vault_can_distribute(address caller, uint96 amount) public {
        vm.assume(caller != vault && amount > 0);

        vm.prank(caller);
        vm.expectRevert(ZakatModule.NotVault.selector);
        zakatModule.distributeZakat(amount);
    }

    // -----------------------------------------------------------------------
    // Fuzz: zero amount always reverts
    // -----------------------------------------------------------------------
    function testFuzz_zero_amount_always_reverts() public {
        vm.expectRevert(ZakatModule.ZeroAmount.selector);
        zakatModule.distributeZakat(0);
    }

    // -----------------------------------------------------------------------
    // Fuzz: timelock confirmation — elapsed < 30 days always reverts
    // -----------------------------------------------------------------------
    function testFuzz_timelock_not_elapsed(uint32 elapsed) public {
        vm.assume(elapsed < 30 days);

        address newWallet = makeAddr("newWallet");
        vm.prank(owner);
        zakatModule.proposeZakatWalletChange(newWallet);

        skip(elapsed);

        vm.prank(owner);
        vm.expectRevert(); // TimelockNotElapsed
        zakatModule.confirmZakatWalletChange();
    }

    // -----------------------------------------------------------------------
    // Fuzz: timelock confirmation — elapsed ≥ 30 days always succeeds
    // -----------------------------------------------------------------------
    function testFuzz_timelock_elapsed_succeeds(uint32 extra) public {
        extra = uint32(bound(extra, 0, 365 days));
        address newWallet = makeAddr("newWallet");

        vm.prank(owner);
        zakatModule.proposeZakatWalletChange(newWallet);

        skip(30 days + extra);

        vm.prank(owner);
        zakatModule.confirmZakatWalletChange();

        assertEq(zakatModule.zakatWallet(), newWallet);
        assertEq(zakatModule.pendingZakatWallet(), address(0));
    }

    // -----------------------------------------------------------------------
    // Fuzz: propose rejects address(0) always
    // -----------------------------------------------------------------------
    function testFuzz_propose_zero_always_reverts() public {
        vm.prank(owner);
        vm.expectRevert(ZakatModule.ZeroWallet.selector);
        zakatModule.proposeZakatWalletChange(address(0));
    }

    // -----------------------------------------------------------------------
    // Fuzz: cancel clears state regardless of how much time elapsed
    // -----------------------------------------------------------------------
    function testFuzz_cancel_clears_state(uint32 elapsed) public {
        elapsed = uint32(bound(elapsed, 0, 365 days));
        address newWallet = makeAddr("newWallet");

        vm.prank(owner);
        zakatModule.proposeZakatWalletChange(newWallet);
        skip(elapsed);

        vm.prank(owner);
        zakatModule.cancelZakatWalletChange();

        assertEq(zakatModule.pendingZakatWallet(), address(0));
        assertEq(zakatModule.walletChangeRequestTime(), 0);
        // zakatWallet should be unchanged
        assertEq(zakatModule.zakatWallet(), charityWallet);
    }
}

contracts/test/GoldAllocationAdapterTest.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {stdStorage, StdStorage} from "forge-std/StdStorage.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {GoldAllocationAdapter}   from "../adapters/GoldAllocationAdapter.sol";
import {ShariahVault}            from "../ShariahVault.sol";
import {ShariahScoreAggregator}  from "../ShariahScoreAggregator.sol";
import {RiskTieredExecutor}      from "../RiskTieredExecutor.sol";
import {ScoreAggregator}         from "../ScoreAggregator.sol";
import {TreasuryModule}          from "../TreasuryModule.sol";
import {ZakatModule}             from "../ZakatModule.sol";
import {MockERC20}               from "../test-helpers/MockERC20.sol";
import {MockXAUT}                from "../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}    from "../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT}   from "../test-helpers/MockUniswapV3PoolXAUT.sol";

/// @title  GoldAllocationAdapterTest
/// @notice Full unit test suite for Task F: GoldAllocationAdapter, ShariahScoreAggregator
///         (index 5), RiskTieredExecutor mask changes, and ShariahVault combined gold cap.
///
/// Price constants (both tokens 6-dec, oracle 8-dec):
///   Oracle price:  int256(330_000_000_000)  = $3300 × 10^8 (8-dec feed)
///   oraclePriceUsdc = oracle_answer * 10^6 / 10^8 = oracle_answer / 100 = 3_300_000_000
///   Pool usdcPerXaut: 3_300_000_000 (raw USDC-units per raw XAUT-unit; both 6-dec)
///   After _updateSqrtPrice fix: poolPriceUsdc = usdcPerXaut = 3_300_000_000 ✓
contract GoldAllocationAdapterTest is Test {
    using stdStorage for StdStorage;

    // ── Actors ────────────────────────────────────────────────────────────────
    address internal owner        = makeAddr("owner");
    address internal alice        = makeAddr("alice");
    address internal charityWallet = makeAddr("charity");
    address internal attacker     = makeAddr("attacker");

    // ── Token mocks ───────────────────────────────────────────────────────────
    MockERC20              internal usdc;
    MockXAUT               internal xaut;
    MockXauUsdAggregator   internal oracle;
    MockUniswapV3PoolXAUT  internal pool;

    // ── Protocol contracts ────────────────────────────────────────────────────
    TreasuryModule          internal treasury;
    ZakatModule             internal zakatModule;
    ShariahVault            internal vault;
    GoldAllocationAdapter   internal adapter;
    ShariahScoreAggregator  internal aggregator;
    ScoreAggregator         internal conventionalAgg;
    RiskTieredExecutor      internal conservativeExecutor;
    RiskTieredExecutor      internal dynamicExecutor;

    // ── Constants ─────────────────────────────────────────────────────────────
    uint32  internal constant SOURCE_DOMAIN   = 26;
    uint256 internal constant MAX_STALENESS   = 3600;  // 1 hour

    /// Oracle answer: $3300 in 8-dec feed units
    int256  internal constant ORACLE_PRICE    = 330_000_000_000;
    /// Derived: oraclePriceUsdc = 330_000_000_000 / 100 = 3_300_000_000
    uint256 internal constant ORACLE_USDC     = 3_300_000_000;
    /// Pool set to same price (raw USDC-units per raw XAUT-unit, 6-dec each)
    uint256 internal constant POOL_USDC_PER_XAUT = 3_300_000_000;

    // ─────────────────────────────────────────────────────────────────────────
    //  setUp — fresh state for every test
    // ─────────────────────────────────────────────────────────────────────────

    function setUp() public {
        // Warp to a realistic timestamp so staleness math doesn't underflow
        vm.warp(1_700_000_000);

        // 1. Tokens
        usdc  = new MockERC20("Mock USDC", "mUSDC", 6);
        xaut  = new MockXAUT();
        oracle = new MockXauUsdAggregator();
        pool   = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), POOL_USDC_PER_XAUT);

        vm.startPrank(owner);

        // 2. Treasury — Shariah params
        treasury = new TreasuryModule(
            "Shariah",
            address(0),   // feeSource set to vault after deploy in production; 0 ok for tests
            address(usdc),
            50,           // wakalaFeeBps  0.5%
            1000,         // musharakahShareBps 10%
            400,          // hurdleRateBps 4%
            owner
        );

        // 3. Vault
        vault = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(treasury),
            address(0)   // zakatModule not needed for these tests
        );

        // 4. ZakatModule (needed for completeness if claimMusharakahProfit is called)
        zakatModule = new ZakatModule(charityWallet, address(usdc), address(vault), owner);

        // 5. Aggregators
        conventionalAgg = new ScoreAggregator(owner);
        aggregator = new ShariahScoreAggregator(owner);

        // 6. GoldAllocationAdapter — pool is both swapRouter and pool address
        adapter = new GoldAllocationAdapter(
            address(usdc),
            address(xaut),
            address(pool),     // swapRouter_
            3000,              // poolFee_ (0.3%)
            address(oracle),   // goldOracle_
            address(vault),    // vault_
            MAX_STALENESS,     // initialMaxStalenessSecs
            owner              // initialOwner
        );
