        }
    }

    function test_poolPrice_differentDecimals_bothOrderings() public {
        MockERC20 gold18 = new MockERC20("Gold18", "G18", 18);
        MockUniswapV3PoolXAUT pool18 = new MockUniswapV3PoolXAUT(address(usdc), address(gold18), ORACLE_USDC);
        GoldAllocationAdapter adapter18 = new GoldAllocationAdapter(
            address(usdc), address(gold18), address(pool18), 3000, address(oracle), address(this), 3600, owner
        );
        for (uint256 i; i < 2; ++i) {
            pool18.setTokenOrder(i == 0);
            assertApproxEqRel(adapter18.poolPriceUsdc(), ORACLE_USDC, 1e12);
            assertTrue(adapter18.isPriceSane());
        }
        gold18.mint(address(pool18), 100e18);
        usdc.mint(address(adapter18), 3_300e6);
        adapter18.deploy(3_300e6);
        assertEq(adapter18.currentValue(), adapter18.xautHeld() * ORACLE_USDC / 1e18);
        assertGt(adapter18.recall(3_300e6), 0);
    }

    function test_poolPrice_inverseHighPrice_doesNotTruncateToZero() public {
        uint256 price = 100_000e6;
        pool.setTokenOrder(false);
        pool.setPrice(price);
        oracle.setPrice(int256(price * 100));
        // rounded sqrtPriceX96 encoding: 1e-6 relative tolerance
        assertApproxEqRel(adapter.poolPriceUsdc(), price, 1e12);
        assertTrue(adapter.isPriceSane());
    }

    function test_currentValue_ignoresDepressedInversePoolPrice() public {
        _deployCapital(3_300e6);
        uint256 nav = vault.totalAssets();
        uint256 preview = vault.previewDeposit(100e6);
        pool.setTokenOrder(false);
        pool.setPrice(2_640e6);
        assertEq(vault.totalAssets(), nav, "spot cannot write down oracle-valued NAV");
        assertEq(vault.previewDeposit(100e6), preview);
        assertEq(vault.maxDeposit(alice), 0, "deviating spot still blocks material new deposits");
        // Spot deviations still gate entry, but cannot change fresh or fallback NAV.
        assertFalse(adapter.isPriceSane());
        uint256 expected = adapter.xautHeld() * ORACLE_USDC / 1e6;
        assertEq(adapter.currentValue(), expected);
        oracle.setUpdatedAt(0);
        assertEq(adapter.currentValue(), expected * 9500 / 10_000);
    }

    function test_poolPrice_usdc18_xaut6_bothOrderings() public {
        MockERC20 quote18 = new MockERC20("Quote18", "Q18", 18);
        MockUniswapV3PoolXAUT pool18 = new MockUniswapV3PoolXAUT(address(quote18), address(xaut), 3_300e18);
        GoldAllocationAdapter adapter18 = new GoldAllocationAdapter(
            address(quote18), address(xaut), address(pool18), 3000, address(oracle), address(this), 3600, owner
        );
        for (uint256 i; i < 2; ++i) {
            pool18.setTokenOrder(i == 0);
            assertApproxEqRel(adapter18.poolPriceUsdc(), 3_300e18, 1e6);
            assertTrue(adapter18.isPriceSane());
        }
    }

    function test_poolPrice_largeSqrt_usesFullPrecisionProduct() public {
        uint160 sqrtP = uint160(1 << 140);
        vm.mockCall(address(pool), abi.encodeWithSignature("slot0()"),
            abi.encode(sqrtP, int24(0), uint16(0), uint16(1), uint16(1), uint8(0), true));
        assertEq(adapter.poolPriceUsdc(), uint256(1 << 88) * 1e6);
    }

    function test_poolPrice_fractionalRawRatio_keepsPrecision() public {
        pool.setPrice(500_000); // Half a USDC per whole 6-dec token: raw ratio is below one.
        oracle.setPrice(50_000_000);
        assertApproxEqAbs(adapter.poolPriceUsdc(), 500_000, 1);
        assertTrue(adapter.isPriceSane());
    }

    function test_recall_staleWithoutCachedPrice_reverts() public {
        _deployCapital(3_300e6);
        vm.mockCall(address(oracle), abi.encodeWithSignature("latestRoundData()"),
            abi.encode(uint80(1), int256(0), block.timestamp, block.timestamp, uint80(1)));
        // Simulate a legacy position without a populated cache; never substitute its principal.
        stdstore.target(address(adapter)).sig("lastGoodPrice()").checked_write(uint256(0));
        vm.prank(address(vault));
        vm.expectRevert(GoldAllocationAdapter.StaleGoldPrice.selector);
        adapter.recall(3_300e6);
    }

    function test_unreadablePool_blocksDeposits_notRecall() public {
        _deployCapital(3_300e6);
        vm.mockCallRevert(address(pool), abi.encodeWithSignature("token0()"), "unreadable");
        assertFalse(adapter.isPriceSane());
        assertGt(adapter.currentValue(), 0);
        vm.prank(address(vault));
        vm.expectRevert(GoldAllocationAdapter.OracleNotSane.selector);
        adapter.deploy(1e6);
        vm.prank(address(vault));
        assertGt(adapter.recall(3_300e6), 0);
    }

    function test_wrongPoolPair_isUnreadable_andNavFallsBack() public {
        _deployCapital(3_300e6);
        vm.mockCall(address(pool), abi.encodeWithSignature("token1()"), abi.encode(address(0x1234)));
        assertEq(adapter.poolPriceUsdc(), 0);
        assertFalse(adapter.isPriceSane());
        assertEq(adapter.currentValue(), adapter.xautHeld() * ORACLE_USDC / 1e6);
        oracle.setUpdatedAt(0);
        uint256 gross = adapter.xautHeld() * adapter.lastGoodPrice() / 1e6;
        assertEq(adapter.currentValue(), gross * 9500 / 10_000);
        vm.prank(address(vault));
        assertGt(adapter.recall(3_300e6), 0);
    }

    function test_emergencySlippage_timelock_cap_cancel_ownerOnly() public {
        bytes32 id = adapter.PARAM_EMERGENCY_SLIPPAGE();
        assertEq(adapter.emergencySlippageBps(), 1000);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(GoldAllocationAdapter.ParamAboveHardCap.selector,
            "emergencySlippageBps", uint256(2501), uint256(2500)));
        adapter.proposeParamChange(id, 2501);
        adapter.proposeParamChange(id, 2500);
        assertEq(adapter.emergencySlippageBps(), 1000);
        uint256 deadline = block.timestamp + 30 days;
        vm.expectRevert(abi.encodeWithSelector(GoldAllocationAdapter.TimelockNotElapsed.selector, deadline, block.timestamp));
        adapter.executeParamChange(id);
        vm.warp(deadline);
        vm.expectEmit(false, false, false, true, address(adapter));
        emit GoldAllocationAdapter.EmergencySlippageBpsUpdated(1000, 2500);
        adapter.executeParamChange(id);
        assertEq(adapter.emergencySlippageBps(), 2500);
        adapter.proposeParamChange(id, 0);
        adapter.cancelParamChange(id);
        vm.expectRevert(GoldAllocationAdapter.NoProposalPending.selector);
        adapter.executeParamChange(id);
        vm.stopPrank();
        vm.startPrank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.proposeParamChange(id, 100);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.executeParamChange(id);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.cancelParamChange(id);
        vm.stopPrank();
    }

    /// @notice protocolName() returns expected string.
    function test_protocolName_returns_expected() public view {
        string memory name = adapter.protocolName();
        assertGt(bytes(name).length, 0, "protocolName must be non-empty");
    }

    /// @notice setGoldAllocationAdapter emits GoldAllocationAdapterUpdated.
    function test_setGoldAllocationAdapter_emits_event() public {
        address newAdapter = makeAddr("newAdapter");

        vm.prank(owner);
        vm.expectEmit(true, false, false, false, address(vault));
        emit ShariahVault.GoldAllocationAdapterUpdated(newAdapter);
        vault.setGoldAllocationAdapter(newAdapter);
    }

    /// @notice setGoldSpreadAdapter emits GoldSpreadAdapterUpdated.
    function test_setGoldSpreadAdapter_emits_event() public {
        address newSpread = makeAddr("newSpread");

        vm.prank(owner);
        vm.expectEmit(true, false, false, false, address(vault));
        emit ShariahVault.GoldSpreadAdapterUpdated(newSpread);
        vault.setGoldSpreadAdapter(newSpread);
    }

    /// @notice currentValue() returns oracle-priced value when sanity passes.
    function test_currentValue_oracle_priced_when_sane() public {
        uint256 amount = 3_300e6; // $3300 USDC
        _deployCapital(amount);

        // xautHeld ~ 1e6 (1 XAUT at 0.2% pool fee so slightly less)
        // currentValue = xautHeld * oraclePriceUsdc / 10^xautDecimals
        uint256 xautHeld = adapter.xautHeld();
        uint256 expected = (xautHeld * ORACLE_USDC) / 1e6;
        uint256 actual = adapter.currentValue();

        // Allow 1 unit rounding error
        assertApproxEqAbs(actual, expected, 1, "currentValue must match oracle valuation");
    }
}

// ─────────────────────────────────────────────────────────────────────────────
//  Mock helper: minimal IGoldAdapter stub returning a fixed currentValue
// ─────────────────────────────────────────────────────────────────────────────
contract MockGoldSpread {
    function isGoldStrategy() external pure returns (bool) { return true; }
    uint256 private _value;
    constructor(uint256 value_) { _value = value_; }
    function currentValue() external view returns (uint256) { return _value; }
    function isPriceSane() external pure returns (bool) { return true; }
    function setValue(uint256 v) external { _value = v; }
}

contracts/test/GoldExchangeAdapterTest.t.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {RemoteRecipientFixture} from "./TaskITest.Base.t.sol";
import {Test} from "forge-std/Test.sol";
import {stdStorage, StdStorage} from "forge-std/StdStorage.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {GoldExchangeAdapter}    from "../adapters/GoldExchangeAdapter.sol";
import {ShariahVault}           from "../ShariahVault.sol";
import {AutonomousVault}        from "../AutonomousVault.sol";
import {TreasuryModule}         from "../TreasuryModule.sol";
import {MockERC20}              from "../test-helpers/MockERC20.sol";
import {MockAllocatedGold}      from "../test-helpers/MockAllocatedGold.sol";
import {MockXauUsdAggregator}   from "../test-helpers/MockXauUsdAggregator.sol";
import {GoldAllocationAdapter} from "../adapters/GoldAllocationAdapter.sol";
import {MockXAUT} from "../test-helpers/MockXAUT.sol";
import {MockUniswapV3PoolXAUT} from "../test-helpers/MockUniswapV3PoolXAUT.sol";

/// @title  GoldExchangeAdapterTest
/// @notice Comprehensive unit tests for Task C: GoldExchangeAdapter + ShariahVault guard.
///
/// Execution model (important):
///   vault.deployCapitalAndExecute(adapter, amount, "") — funds and executes the swap atomically.
///   vault.recallCapital(adapter, amount)     — calls adapter.recall() which reverses the swap.
///
/// Swap helpers and failure cases use deployCapitalAndExecute throughout.
///
/// Correctness properties verified:
///   C-1  deploy() is atomic — no USDC stranded in adapter after adapter.deploy() returns
///   C-2  recall() is atomic — no MAG stranded in adapter after recallCapital() returns
///   C-3  SlippageExceeded fires when router returns 0 tokens
///   C-4  setMinOutBps range validation (9000–10000)
///   C-5  setMinOutBps emits MinOutBpsUpdated
///   C-6  Strategy-tagged gold transfers reject nonzero destination domains
///   C-7  Held gold leaves unrelated USDC transfers on the inherited path
///   C-8  Only vault may call deploy/recall
///   C-9  renounceOwnership is disabled
///   C-10 Accounting: totalDeployed/paxgHeld track correctly after deploy + recall
///   C-11 paxgHeld mirrors MAG balance of adapter
///   C-12 GoldAcquired event emitted on deploy with correct values
///   C-13 GoldReturned event emitted on recall
///   C-14 Entry uses a fresh oracle floor; oracle refresh preserves observation time
///   C-15 deploy(0) reverts ZeroAmount
///   C-16 recall(0) reverts ZeroAmount
///   C-17 recall when paxgHeld==0 returns 0 gracefully
///   C-18 Removed: global switch event no longer exists
///   C-19 pause gates deployCapital on ShariahVault
///   C-20 pause gates deployCrossChain on ShariahVault
///   C-21 sequential deploys accumulate paxgHeld
///   C-22 non-owner cannot setMinOutBps
///   C-23 Removed: global switch access-control test no longer applies
///   C-24 protocolName() returns correct string
///   C-25 currentValue() equals totalDeployed

// ─── Mock swap router ─────────────────────────────────────────────────────────
// 1:1 USDC<>MAG swap by default. setReturnZero(true) simulates total slippage.

contract MockSwapRouter {
    bool public returnZero;
    uint256 public payoutBps = 10_000;

    function setReturnZero(bool z) external { returnZero = z; }
    function setPayoutBps(uint256 bps) external { payoutBps = bps; }

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata p)
        external returns (uint256 amountOut)
    {
        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        if (returnZero) { return 0; }
        amountOut = MockERC20(p.tokenIn).decimals() == 6
            ? p.amountIn * 1e18 / 3_300e6
            : p.amountIn * 3_300e6 / 1e18;
        // Deliberately leave enforcement to the adapter to test its own check.
        amountOut = amountOut * payoutBps / 10_000;
        IERC20(p.tokenOut).transfer(p.recipient, amountOut);
    }
}

// ─── Test contract ────────────────────────────────────────────────────────────

contract GoldExchangeAdapterTest is Test {
    using stdStorage for StdStorage;

    address internal owner    = makeAddr("owner");
    address internal manager  = makeAddr("manager");
    address internal alice    = makeAddr("alice");
    address internal attacker = makeAddr("attacker");

    MockERC20              internal usdc;
    MockAllocatedGold      internal mag;
    MockSwapRouter         internal router;
    MockXauUsdAggregator   internal xauOracle;
    ShariahVault           internal vault;
    TreasuryModule         internal treasury;
    GoldExchangeAdapter    internal adapter;

    uint32 internal constant SOURCE_DOMAIN = 26;

    function setUp() public {
        usdc      = new MockERC20("Mock USDC", "mUSDC", 6);
        mag       = new MockAllocatedGold();
        router    = new MockSwapRouter();
        xauOracle = new MockXauUsdAggregator(); // K2: mandatory oracle

        vm.startPrank(owner);
        treasury = new TreasuryModule(
            "Shariah", address(0), address(usdc), 50, 1000, 400, owner
        );
        vault = new ShariahVault(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0)
        );
        vault.setManager(manager);
        adapter = new GoldExchangeAdapter(
            address(usdc), address(mag), address(router), 3000,
            address(vault), owner, address(xauOracle)
        );
        vault.setScreened(address(adapter), true);
        // N-23: keep swap regressions on a tracked gold strategy rather than bypassing vault gold controls.
        vault.setGoldSpreadAdapter(address(adapter));
        vm.stopPrank();

        // Seed router with MAG (stand-in for Uniswap V3 USDC/PAXG pool)
        mag.mint(address(this), 2_000_000e18);
        IERC20(address(mag)).transfer(address(router), 2_000_000e18);

        // Alice deposits 100k USDC
        usdc.mint(alice, 100_000e6);
        vm.startPrank(alice);
        usdc.approve(address(vault), 100_000e6);
        vault.deposit(100_000e6, alice);
        vm.stopPrank();
    }

    /// @dev Push USDC to adapter (vault accounting) then execute the swap (adapter side).
    function _deployAndSwap(uint256 amount) internal {
        vm.prank(manager);
        // Exercise vault-funded execution without impersonating the adapter's onlyVault caller.
        vault.deployCapitalAndExecute(address(adapter), amount, "");
    }

    // ─── C-1: deploy() is atomic ─────────────────────────────────────────────

    function test_C1_deploy_no_usdc_stranded() public {
        _deployAndSwap(10_000e6);

        assertEq(usdc.balanceOf(address(adapter)), 0,
            "No USDC should remain in adapter after atomic swap");
        assertGt(mag.balanceOf(address(adapter)), 0,
            "Adapter must hold MAG after swap");
        assertGt(adapter.paxgHeld(), 0,     "paxgHeld must be updated");
        assertGt(adapter.totalDeployed(), 0, "totalDeployed must be updated");
    }

    // ─── C-2: recall() is atomic ─────────────────────────────────────────────

    function test_C2_recall_no_mag_stranded() public {
        _deployAndSwap(10_000e6);

        assertGt(mag.balanceOf(address(adapter)), 0);

        // Seed router with USDC for the reverse swap
        usdc.mint(address(router), 50_000_000e6);

        vm.prank(manager);
        vault.recallCapital(address(adapter), 10_000e6);

        assertEq(adapter.paxgHeld(), 0,
            "paxgHeld must be zero after full recall");
        assertEq(mag.balanceOf(address(adapter)), 0,
            "No MAG should remain in adapter after recall");
    }

    // ─── C-3: SlippageExceeded when router returns 0 ─────────────────────────

    function test_C3_slippage_exceeded_when_router_returns_zero() public {
        router.setReturnZero(true);
        vm.prank(manager);
        vm.expectRevert(
            abi.encodeWithSelector(GoldExchangeAdapter.SlippageExceeded.selector, uint256(0), ((uint256(5_000e6) * 1e18 / 3_300e6) * 9900 / 10_000))
        );
        vault.deployCapitalAndExecute(address(adapter), 5_000e6, "");
    }

    // ─── C-4: setMinOutBps range validation ──────────────────────────────────

    function test_C4a_setMinOutBps_below_9000_reverts() public {
        vm.prank(owner);
        vm.expectRevert(bytes("GoldExchangeAdapter: bps out of range (9000-10000)"));
        adapter.setMinOutBps(8999);
    }

    function test_C4b_setMinOutBps_above_10000_reverts() public {
        vm.prank(owner);
        vm.expectRevert(bytes("GoldExchangeAdapter: bps out of range (9000-10000)"));
        adapter.setMinOutBps(10_001);
    }

    function test_C4c_setMinOutBps_9000_accepted() public {
        vm.prank(owner);
        adapter.setMinOutBps(9000);
        assertEq(adapter.minOutBps(), 9000);
    }

    function test_C4d_setMinOutBps_10000_accepted() public {
        vm.prank(owner);
        adapter.setMinOutBps(10_000);
        assertEq(adapter.minOutBps(), 10_000);
    }

    // ─── C-5: setMinOutBps emits event ───────────────────────────────────────

    function test_C5_setMinOutBps_emits_event() public {
        vm.prank(owner);
        vm.expectEmit(false, false, false, true);
        emit GoldExchangeAdapter.MinOutBpsUpdated(9900, 9950);
        adapter.setMinOutBps(9950);
        assertEq(adapter.minOutBps(), 9950);
    }

    // ─── C-6: Only gold strategy routing rejects nonzero domains ─────────────

    function test_C6_deployCrossChain_gold_strategies_revert() public {
        vm.prank(manager);
        vm.expectRevert(ShariahVault.NonAtomicGoldExchange.selector);
        vault.deployCrossChainForStrategy(1, 3, bytes32(0), 0);
        vm.prank(manager);
        vm.expectRevert(ShariahVault.NonAtomicGoldExchange.selector);
        vault.deployCrossChainForStrategy(5, 3, bytes32(0), type(uint256).max);
    }

    // ─── C-7: Held gold does not block unrelated USDC transfers ──────────────

    function test_C7_deployCrossChain_with_gold_hits_base_revert() public {
        _deployAndSwap(5_000e6);
        MockXAUT xaut = new MockXAUT();
        MockUniswapV3PoolXAUT pool = new MockUniswapV3PoolXAUT(
            address(usdc), address(xaut), 3_300_000_000
        );
        GoldAllocationAdapter second = new GoldAllocationAdapter(
            address(usdc), address(xaut), address(pool), 3000,
            address(xauOracle), address(vault), 3600, owner
        );
        xaut.mint(address(pool), 100e6);
        vm.startPrank(owner);
        vault.setScreened(address(second), true);
        // N-23: setup already links the funded spread; re-setting it would hit the exposure guard.
        vault.setGoldAllocationAdapter(address(second));
        vm.stopPrank();
        vm.prank(manager);
        vault.deployCapitalAndExecute(address(second), 3_300e6, "");
        assertGt(adapter.paxgHeld(), 0);
        assertGt(second.xautHeld(), 0);

        bytes32 recipient = bytes32(uint256(uint160(alice)));
        RemoteRecipientFixture.approve(vm, vault, owner, 3, recipient);
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.CrossChainNotConfigured.selector);
        vault.deployCrossChain(3, recipient, 1_000e6);
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.CrossChainNotConfigured.selector);
        vault.deployCrossChainForStrategy(0, 3, recipient, 1_000e6);
    }

    // ─── C-8: only vault address can call adapter deploy/recall ───────────────

    function test_C8a_deploy_only_vault() public {
        vm.prank(attacker);
        vm.expectRevert(bytes("GoldExchangeAdapter: caller is not the vault"));
        adapter.deploy(1_000e6);
    }

    function test_C8b_recall_only_vault() public {
        vm.prank(attacker);
        vm.expectRevert(bytes("GoldExchangeAdapter: caller is not the vault"));
        adapter.recall(1_000e6);
    }

    // ─── C-9: renounceOwnership is disabled ──────────────────────────────────

    function test_C9_renounceOwnership_disabled() public {
        vm.prank(owner);
        vm.expectRevert(bytes("GoldExchangeAdapter: renouncing ownership is disabled"));
        adapter.renounceOwnership();
    }

    // ─── C-10: accounting tracks correctly after deploy + recall ─────────────

    function test_C10a_totalDeployed_increments_after_swap() public {
        assertEq(adapter.totalDeployed(), 0);
        _deployAndSwap(8_000e6);
        assertEq(adapter.totalDeployed(), 8_000e6);
    }

    function test_C10b_totalDeployed_zeros_after_recall() public {
        _deployAndSwap(8_000e6);
        assertGt(adapter.totalDeployed(), 0);

        usdc.mint(address(router), 50_000_000e6);
        vm.prank(manager);
        vault.recallCapital(address(adapter), 8_000e6);

        assertEq(adapter.totalDeployed(), 0,
            "totalDeployed must zero on full recall regardless of price");
    }

    // ─── C-11: paxgHeld mirrors adapter MAG balance ───────────────────────────

    function test_C11_paxgHeld_matches_mag_balance() public {
        _deployAndSwap(5_000e6);
        assertEq(adapter.paxgHeld(), mag.balanceOf(address(adapter)));
    }

    // ─── C-12: GoldAcquired event emitted on adapter.deploy() ────────────────

    function test_C12_goldAcquired_event_emitted() public {
        uint256 expectedOut = uint256(10_000e6) * 1e18 / 3_300e6;
        uint256 expectedPrice = uint256(10_000e6) * 1e18 / expectedOut;
        vm.prank(manager);
        vm.expectEmit(false, false, false, true, address(adapter));
        emit GoldExchangeAdapter.GoldAcquired(10_000e6, expectedOut, expectedPrice);
        vault.deployCapitalAndExecute(address(adapter), 10_000e6, "");
    }

    // ─── C-13: GoldReturned event emitted on recall ───────────────────────────

    function test_C13_goldReturned_event_emitted() public {
        _deployAndSwap(10_000e6);
        usdc.mint(address(router), 50_000_000e6);

        vm.prank(manager);
        vm.expectEmit(false, false, false, false); // check event fires, values vary
        emit GoldExchangeAdapter.GoldReturned(0, 0);
        vault.recallCapital(address(adapter), 10_000e6);
    }

    function test_deploy_belowOracleMinimum_reverts() public {
        router.setPayoutBps(9800);
        usdc.mint(address(adapter), 3_300e6);
        vm.prank(address(vault));
        vm.expectRevert(abi.encodeWithSelector(
            GoldExchangeAdapter.SlippageExceeded.selector, uint256(0.98e18), uint256(0.99e18)
        ));
        adapter.deploy(3_300e6);
    }

    function test_deploy_staleOracle_reverts() public {
        vm.warp(block.timestamp + adapter.maxStalenessSecs() + 1);
        usdc.mint(address(adapter), 1_000e6);
        vm.prank(address(vault));
        vm.expectRevert(GoldExchangeAdapter.StaleGoldPrice.selector);
        adapter.deploy(1_000e6);
    }

    function test_pokePrice_keepsObservationTimestamp_andIgnoresStale() public {
        vm.warp(1_700_000_000);
        xauOracle.setPrice(330_000_000_000);
        uint256 observedAt = block.timestamp - 60;
        xauOracle.setUpdatedAt(observedAt);
        adapter.pokePrice();
        assertEq(adapter.lastGoodPriceAt(), observedAt);
        assertEq(adapter.lastGoodPrice(), 3_300e6);
        vm.warp(block.timestamp + adapter.maxStalenessSecs() + 1);
        adapter.pokePrice();
        assertEq(adapter.lastGoodPriceAt(), observedAt);
        xauOracle.setUpdatedAt(block.timestamp + 1);
        adapter.pokePrice();
        assertEq(adapter.lastGoodPriceAt(), observedAt);
        xauOracle.setUpdatedAt(0);
        adapter.pokePrice();
        assertEq(adapter.lastGoodPriceAt(), observedAt);
    }

    // N-09 allows ordinary declines during outages, but never output below the cached-price floor.
    function test_recall_staleOracle_retainsBoundedFloor() public {
        _deployAndSwap(3_300e6);
        vm.warp(block.timestamp + adapter.maxStalenessSecs() + 1);
        uint256 floor = adapter.paxgHeld() * adapter.lastGoodPrice() / 1e18;
        floor = floor * (10_000 - adapter.staleHaircutBps()) / 10_000;
        floor = floor * (10_000 - adapter.emergencySlippageBps()) / 10_000;
        router.setPayoutBps(8549);
        vm.prank(address(vault));
        vm.expectRevert(abi.encodeWithSelector(
            GoldExchangeAdapter.SlippageExceeded.selector, uint256(3_300e6 * 8549 / 10_000), floor
        ));
        adapter.recall(3_300e6);
        router.setPayoutBps(8550);
        vm.prank(address(vault));
        assertEq(adapter.recall(3_300e6), floor);
    }

    function test_recall_staleWithoutCachedPrice_reverts() public {
        _deployAndSwap(3_300e6);
        xauOracle.setUpdatedAt(0);
        // Simulate a legacy position without a populated cache; principal is not an exit-price fallback.
        stdstore.target(address(adapter)).sig("lastGoodPrice()").checked_write(uint256(0));
        vm.prank(address(vault));
        vm.expectRevert(GoldExchangeAdapter.StaleGoldPrice.selector);
        adapter.recall(3_300e6);
    }

    function test_recall_staleOracle_usesRefreshedCache_notEntryCost() public {
        _deployAndSwap(3_300e6);
        xauOracle.setPrice(264_000_000_000);
        adapter.pokePrice();
        xauOracle.setUpdatedAt(0);
        router.setPayoutBps(7000); // Clears the refreshed cache floor, but not the entry-price floor.
        vm.prank(address(vault));
        assertEq(adapter.recall(3_300e6), 2_310e6);
    }

    function test_recall_freshOracle_neverUsesEmergencyTolerance() public {
        _deployAndSwap(3_300e6);
        router.setPayoutBps(9000);
        vm.prank(address(vault));
        vm.expectRevert(abi.encodeWithSelector(
            GoldExchangeAdapter.SlippageExceeded.selector, uint256(2_970e6), uint256(3_267e6)
        ));
        adapter.recall(3_300e6);
    }

    function test_emergencySlippage_timelock_cap_cancel_ownerOnly() public {
        bytes32 id = adapter.PARAM_EMERGENCY_SLIPPAGE();
        assertEq(adapter.emergencySlippageBps(), 1000);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(GoldExchangeAdapter.HaircutAboveCap.selector, uint256(2501), uint256(2500)));
        adapter.proposeParamChange(id, 2501);
        adapter.proposeParamChange(id, 2500);
        assertEq(adapter.emergencySlippageBps(), 1000);
        vm.expectRevert(bytes("GoldExchangeAdapter: timelock not elapsed"));
        adapter.executeParamChange(id);
        vm.warp(block.timestamp + 30 days);
        vm.expectEmit(false, false, false, true, address(adapter));
        emit GoldExchangeAdapter.EmergencySlippageBpsUpdated(1000, 2500);
        adapter.executeParamChange(id);
        assertEq(adapter.emergencySlippageBps(), 2500);
        adapter.proposeParamChange(id, 0);
        adapter.cancelParamChange(id);
        vm.expectRevert(bytes("GoldExchangeAdapter: no proposal pending"));
        adapter.executeParamChange(id);
        vm.stopPrank();
        vm.startPrank(attacker);
        vm.expectRevert();
        adapter.proposeParamChange(id, 100);
        vm.expectRevert();
        adapter.executeParamChange(id);
        vm.expectRevert();
        adapter.cancelParamChange(id);
        vm.stopPrank();
    }

    // ─── C-15: deploy(0) reverts ZeroAmount ──────────────────────────────────

    function test_C15_deploy_zero_reverts() public {
        // Create adapter pointing at address(this) so we can call deploy() directly
        GoldExchangeAdapter da = new GoldExchangeAdapter(
            address(usdc), address(mag), address(router), 3000,
            address(this), owner, address(xauOracle)
        );
        vm.expectRevert(GoldExchangeAdapter.ZeroAmount.selector);
        da.deploy(0);
    }

    // ─── C-16: recall(0) reverts ZeroAmount ──────────────────────────────────

    function test_C16_recall_zero_reverts() public {
        GoldExchangeAdapter da = new GoldExchangeAdapter(
            address(usdc), address(mag), address(router), 3000,
            address(this), owner, address(xauOracle)
        );
        vm.expectRevert(GoldExchangeAdapter.ZeroAmount.selector);
        da.recall(0);
    }

    // ─── C-17: recall when paxgHeld==0 returns 0 gracefully ──────────────────

    function test_C17_recall_with_zero_paxgHeld_returns_zero() public {
        GoldExchangeAdapter da = new GoldExchangeAdapter(
            address(usdc), address(mag), address(router), 3000,
            address(this), owner, address(xauOracle)
        );
        uint256 ret = da.recall(1);
        assertEq(ret, 0, "recall with zero paxgHeld must return 0 gracefully");
    }

    // C-18 removed: the global switch and its event no longer exist; C-6 covers the strategy guard.

    // ─── C-19: pause gates deployCapital on ShariahVault ─────────────────────

    function test_C19_pause_blocks_deployCapital() public {
        vm.prank(owner);
        vault.setPaused(true);

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.Paused.selector);
        vault.deployCapitalAndExecute(address(adapter), 5_000e6, "");
    }

    // ─── C-20: pause gates deployCrossChain on ShariahVault ──────────────────

    function test_C20_pause_blocks_deployCrossChain() public {
        // The inherited transfer path retains the base pause check.
        vm.prank(owner);
        ShariahVault fresh = new ShariahVault(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0)
        );
        vm.prank(owner);
        fresh.setManager(manager);
        vm.prank(owner);
        fresh.setPaused(true);

        RemoteRecipientFixture.approve(vm, fresh, owner, 3, bytes32(uint256(uint160(makeAddr("r")))));
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.Paused.selector);
        fresh.deployCrossChain(3, bytes32(uint256(uint160(makeAddr("r")))), 1_000e6);
    }

    // ─── C-21: sequential deploys accumulate paxgHeld ────────────────────────

    function test_C21_sequential_deploys_accumulate() public {
        _deployAndSwap(5_000e6);
        uint256 held1 = adapter.paxgHeld();
        assertGt(held1, 0);

        _deployAndSwap(5_000e6);
        uint256 held2 = adapter.paxgHeld();
        assertGt(held2, held1, "second deploy must increase paxgHeld");
        assertEq(adapter.totalDeployed(), 10_000e6);
    }

    // ─── C-22: non-owner cannot setMinOutBps ─────────────────────────────────

    function test_C22_setMinOutBps_only_owner() public {
        vm.prank(attacker);
        vm.expectRevert();
        adapter.setMinOutBps(9500);
    }

    // C-23 removed: no owner-controlled global switch remains to exercise.

    // ─── C-24: protocolName() ─────────────────────────────────────────────────

    function test_C24_protocolName() public view {
        assertEq(
            adapter.protocolName(),
            "GoldExchangeAdapter: USDC/PAXG atomic swap (yad bi yad)"
        );
    }

    // ─── C-25: currentValue() == totalDeployed ────────────────────────────────

    // Regression coverage uses the corrected price units rather than accepting a self-consistent zero value.
    function test_entryAndExitPrice_shareUnits() public {
        _deployAndSwap(6_600e6);
        assertEq(adapter.lastGoodPrice(), 3_300e6);
        assertEq(adapter.currentValue(), 6_600e6);
        vm.prank(manager);
        vault.recallCapital(address(adapter), 6_600e6);
        assertEq(adapter.lastGoodPrice(), 3_300e6);
        assertEq(adapter.currentValue(), 0);
    }

    // Adapter failure must roll back funding and vault accounting on the new entry point.
    function test_atomicFailure_rollsBackFunding() public {
        router.setReturnZero(true);
        uint256 balanceBefore = usdc.balanceOf(address(vault));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(GoldExchangeAdapter.SlippageExceeded.selector,
            uint256(0), ((uint256(5_000e6) * 1e18 / 3_300e6) * 9900 / 10_000)));
        vault.deployCapitalAndExecute(address(adapter), 5_000e6, "");
        assertEq(usdc.balanceOf(address(vault)), balanceBefore);
        assertEq(usdc.balanceOf(address(adapter)), 0);
        assertEq(vault.totalDeployed(), 0);
        assertEq(adapter.paxgHeld(), 0);
        router.setReturnZero(false);
        _deployAndSwap(5_000e6);
    }

    // Fresh losses must affect adapter value and vault NAV before any keeper refresh.
    function test_currentValue_freshLossBeforePoke_updatesNav() public {
        vm.prank(owner);
        vault.setGoldSpreadAdapter(address(adapter));
        _deployAndSwap(6_600e6);
        uint256 cached = adapter.lastGoodPrice();
        uint256 beforeNav = vault.totalAssets();
        xauOracle.setPrice(264_000_000_000);
        assertEq(adapter.currentValue(), 5_280e6);
        assertEq(adapter.lastGoodPrice(), cached);
        assertEq(vault.goldWritedown(), 1_320e6);
        assertEq(vault.totalAssets(), beforeNav - 1_320e6);
        uint256 sharesBefore = vault.previewDeposit(100e6);
        adapter.pokePrice();
        assertEq(adapter.currentValue(), 5_280e6);
        assertEq(vault.previewDeposit(100e6), sharesBefore);
        xauOracle.setUpdatedAt(0);
        assertEq(adapter.currentValue(), 5_280e6, "recent cache needs no haircut yet");
        skip(adapter.maxStalenessSecs() + 1);
        assertEq(adapter.currentValue(), 5_016e6);
    }

    function test_C25_currentValue_usesFreshOracle() public {
        _deployAndSwap(7_000e6);
        // Fresh oracle valuation must be independent of the cached execution price.
        uint256 expected = (adapter.paxgHeld() * 3_300e6) / 1e18;
        assertEq(adapter.currentValue(), expected,
            "currentValue should equal paxgHeld * fresh oracle / 1e18");
    }
}

contracts/test/PurificationEscrowTest.t..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test}     from "forge-std/Test.sol";
import {IERC20}   from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable}  from "@openzeppelin/contracts/access/Ownable.sol";

import {PurificationEscrow} from "../PurificationEscrow.sol";
import {CharityModule}      from "../CharityModule.sol";
import {TreasuryModule}     from "../TreasuryModule.sol";
import {ShariahVault}       from "../ShariahVault.sol";
import {MockERC20}          from "../test-helpers/MockERC20.sol";

/// @dev J3: registry mock — owner is board member so all existing tests still work.
contract MockRegistryPET {
    address public board;
    constructor(address b) { board = b; }
    function isBoard(address a) external view returns (bool) { return a == board; }
}

/**
 * @title  PurificationEscrowTest
 * @notice Unit tests for PurificationEscrow — 15+ tests covering the waterfall,
 *         purification rate controls, and ShariahVault integration.
 *
 * ── Deployment topology ────────────────────────────────────────────────────
 *
 *  MockERC20 (USDC, 6 dec)
 *  TreasuryModule  ← feeSource = address(escrow)  (set in setUp after escrow is known)
 *  CharityModule   ← vault = address(this),  owner = owner
 *  PurificationEscrow ← vault = address(this), feeSource = escrow itself
 *
 * For ShariahVault integration sub-tests we deploy a second set wired together.
 *
 * address(this) acts as the "vault" for standalone escrow calls.
 * We approve escrow for grossProfit before each executeWaterfall call.
 */
contract PurificationEscrowTest is Test {

    // ── Shariah params ────────────────────────────────────────────────────────
    uint256 internal constant ADMIN_FEE_BPS       = 50;   // 0.5%
    uint256 internal constant MUSHARAKAH_SHARE_BPS = 1000; // 10%
    uint256 internal constant HURDLE_RATE_BPS      = 400;  // 4%

    // ── actors ────────────────────────────────────────────────────────────────
    address internal owner         = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");
    address internal other         = makeAddr("other");

    // ── CCTP domain ───────────────────────────────────────────────────────────
    uint32 internal constant SOURCE_DOMAIN = 26;

    // ── contracts (standalone waterfall tests — vault = address(this)) ────────
    MockERC20          internal usdc;
    TreasuryModule     internal treasury;
    CharityModule      internal charityModule;
    PurificationEscrow internal escrow;
    MockRegistryPET    internal reg; // J3: single registry instance for all deploys

    // ── contracts (ShariahVault integration tests) ────────────────────────────
    TreasuryModule     internal vaultTreasury;
    CharityModule      internal vaultCharityModule;
    PurificationEscrow internal vaultEscrow;
    ShariahVault       internal vault;

    function setUp() public {
        // ── 1. Shared MockERC20 + registry ──────────────────────────────────
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        reg  = new MockRegistryPET(owner); // J3: owner is board member

        // ── 2. Standalone stack (vault = address(this)) ──────────────────────
        // CharityModule: vault = address(this), owner = owner
        vm.prank(owner);
        charityModule = new CharityModule(
            charityWallet,
            address(usdc),
            address(this), // vault for CharityModule — will be overridden to escrow below
            owner,
            address(reg)   // J3: registry required
        );

        // TreasuryModule placeholder — feeSource must be escrow, deployed next.
        // Use a two-step: deploy treasury with feeSource = address(this), then deploy
        // escrow; treasury's feeSource is immutable so we deploy it with the CORRECT
        // feeSource address. We compute escrow address deterministically using CREATE.
        // Simpler approach: deploy treasury with feeSource = address(this), let
        // escrow use address(this) to call recordMusharakahProfit by pranking.
        //
        // Actually the cleanest approach for unit tests:
        // • Deploy treasury with feeSource = address(this) (test contract).
        // • Deploy CharityModule with vault = address(this).
        // • Deploy PurificationEscrow with vault = address(this).
        // • In executeWaterfall, escrow calls treasury.recordMusharakahProfit —
        //   BUT feeSource=address(this) so that call will revert with NotFeeSource.
        //
        // Correct fix: feeSource must = address(escrow).
        // We pre-compute the escrow address with vm.computeCreateAddress:

        uint256 deployerNonce = vm.getNonce(address(this));
        // CharityModule was just deployed (nonce consumed), treasury is next (+0),
        // then escrow (+1).
        address expectedTreasuryAddr = vm.computeCreateAddress(address(this), deployerNonce);
        address expectedEscrowAddr   = vm.computeCreateAddress(address(this), deployerNonce + 1);

        treasury = new TreasuryModule(
            "Shariah",
            expectedEscrowAddr,  // feeSource = escrow (pre-computed)
            address(usdc),
            ADMIN_FEE_BPS,
            MUSHARAKAH_SHARE_BPS,
            HURDLE_RATE_BPS,
            owner
        );

        // CharityModule vault must also be the escrow so distributeCharity can be called by escrow.
        // Re-deploy charityModule with vault = expectedEscrowAddr.
        vm.prank(owner);
        charityModule = new CharityModule(
            charityWallet,
            address(usdc),
            expectedEscrowAddr,  // vault = escrow
            owner,
            address(reg)         // J3: registry required
        );

        escrow = new PurificationEscrow(
            address(this),    // vault = test contract
            address(usdc),
            address(charityModule),
            address(treasury),
            owner,
            address(reg)      // J3: registry required
        );

        // Sanity: confirm addresses match
        assertEq(address(escrow),  expectedEscrowAddr,  "escrow address mismatch - adjust nonce offset");

        // Fund test contract (acting as vault)
        usdc.mint(address(this), 10_000_000e6);

        // ── 3. ShariahVault integration stack ────────────────────────────────
        vm.startPrank(owner);

        vaultTreasury = new TreasuryModule(
            "ShariahV2",
            address(0), // placeholder — will be replaced below
            address(usdc),
            ADMIN_FEE_BPS,
            MUSHARAKAH_SHARE_BPS,
            HURDLE_RATE_BPS,
            owner
        );

        vault = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(vaultTreasury),
            address(0) // no ZakatModule
        );

        vaultCharityModule = new CharityModule(
            charityWallet,
            address(usdc),
            address(0x1), // placeholder vault — will be redeployed with correct addr below
            owner,
            address(reg)  // J3: registry required
        );

        vm.stopPrank();

        // Pre-compute vaultEscrow address
        uint256 vaultEscrowNonce = vm.getNonce(address(this));
        address expectedVaultEscrowAddr = vm.computeCreateAddress(address(this), vaultEscrowNonce);

        // Re-deploy vaultTreasury and vaultCharityModule with correct feeSource/vault addresses
        vm.startPrank(owner);

        vaultTreasury = new TreasuryModule(
            "ShariahV2",
            expectedVaultEscrowAddr,  // feeSource = vaultEscrow
            address(usdc),
            ADMIN_FEE_BPS,
            MUSHARAKAH_SHARE_BPS,
            HURDLE_RATE_BPS,
            owner
        );

        vaultCharityModule = new CharityModule(
            charityWallet,
            address(usdc),
            expectedVaultEscrowAddr,  // vault = vaultEscrow (escrow calls distributeCharity)
            owner,
            address(reg)              // J3: registry required
        );

        vm.stopPrank();

        // Re-compute after the two re-deploys
        uint256 vaultEscrowNonce2 = vm.getNonce(address(this));
        address expectedVaultEscrowAddr2 = vm.computeCreateAddress(address(this), vaultEscrowNonce2);

        vaultEscrow = new PurificationEscrow(
            address(vault),
            address(usdc),
            address(vaultCharityModule),
            address(vaultTreasury),
            owner,
            address(reg)  // J3: registry required
        );

        assertEq(address(vaultEscrow), expectedVaultEscrowAddr2, "vaultEscrow address mismatch");

        // Wire vault → escrow and fund vault
        vm.prank(owner);
        vault.setPurificationEscrow(address(vaultEscrow));

        usdc.mint(address(vault), 10_000_000e6);
    }

    function test_waterfallHWM_deficitSuppressesManagerShare() public {
        usdc.approve(address(escrow), 100e6);
        uint256 beforeBalance = usdc.balanceOf(address(this));
        (uint256 p, uint256 c, uint256 v, uint256 d) = escrow.executeWaterfallHWM(100e6, 0, 0, 100e6);
        assertEq(v, 0);
        assertEq(p + c + v + d, 100e6);
        assertEq(treasury.pendingFees(), 0);
        assertEq(usdc.balanceOf(address(this)), beforeBalance - p - c);
        assertEq(usdc.balanceOf(address(escrow)), 0);
    }

    function test_waterfallHWM_shareOnlyOnExcessAfterRecoveryAndHurdle() public {
        usdc.approve(address(escrow), 1_000e6);
        uint256 beforeBalance = usdc.balanceOf(address(this));
        (uint256 p, uint256 c, uint256 v, uint256 d) =
            escrow.executeWaterfallHWM(1_000e6, 365 days, 10_000e6, 200e6);
        // 975 after charity, less 200 recovery and 400 hurdle: 10% of 375.
        assertEq(v, 37_500_000);
        assertEq(treasury.pendingFees(), v);
        assertEq(p + c + v + d, 1_000e6);
        assertEq(usdc.balanceOf(address(this)), beforeBalance - 1_000e6 + v + d);
        assertEq(usdc.balanceOf(address(escrow)), 0);
    }

    function test_waterfallHWM_zeroDeficitMatchesLegacyABI() public {
        usdc.approve(address(escrow), 2_000e6);
        (uint256 p, uint256 c, uint256 v, uint256 d) = escrow.executeWaterfall(1_000e6, 365 days, 10_000e6);
        (uint256 hp, uint256 hc, uint256 hv, uint256 hd) = escrow.executeWaterfallHWM(1_000e6, 365 days, 10_000e6, 0);
        assertEq(p, hp);
        assertEq(c, hc);
        assertEq(v, hv);
        assertEq(d, hd);
        assertEq(v, 57_500_000);
    }

    function test_waterfallHWM_preservesAccessAndZeroAmountGuards() public {
        vm.prank(other);
        vm.expectRevert(PurificationEscrow.NotVault.selector);
        escrow.executeWaterfallHWM(100e6, 0, 0, 100e6);
        vm.expectRevert(PurificationEscrow.ZeroAmount.selector);
        escrow.executeWaterfallHWM(0, 0, 0, 100e6);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 1. Waterfall invariant: purified + charity + vaultShare + depositorShare == grossProfit
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_invariant() public {
        uint256 gross     = 1_000e6;
        uint256 elapsed   = 365 days;
        uint256 principal = 10_000e6;

        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity, uint256 vaultShare, uint256 depositorShare) =
            escrow.executeWaterfall(gross, elapsed, principal);

        assertEq(
            purified + charity + vaultShare + depositorShare,
            gross,
            "waterfall invariant: components must sum to grossProfit"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 2. purificationBps=0 → purified==0, charity==25e6 (2.5% of 1000e6)
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_zero_purification() public {
        // Default purificationBps is 0
        assertEq(escrow.purificationBps(), 0);

        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity,,) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        assertEq(purified, 0,    "purified should be 0 when purificationBps=0");
        assertEq(charity,  25e6, "charity should be 2.5% of full gross when purification=0");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 3. proposePurificationRate(100) → purified==10e6 from 1000e6  [PR2 updated]
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_with_purification() public {
        // PR2: board proposes + 30-day timelock + confirm (owner is initial board member)
        vm.prank(owner);
        escrow.proposePurificationRate(100); // 1%
        vm.warp(block.timestamp + 30 days);
        vm.prank(owner);
        escrow.confirmPurificationRate();

        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);
        (uint256 purified, uint256 charity,,) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        // purified = 1000e6 * 100 / 10_000 = 10e6
        assertEq(purified, 10e6, "purified should be 1% of grossProfit");

        // charity = (1000e6 - 10e6) * 250 / 10_000 = 990e6 * 250 / 10_000 = 24.75e6
        uint256 afterPurification = gross - purified;
        uint256 expectedCharity   = (afterPurification * 250) / 10_000;
        assertEq(charity, expectedCharity, "charity should be 2.5% of afterPurification");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 4. Non-vault caller reverts NotVault
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_not_vault_reverts() public {
        vm.prank(other);
        vm.expectRevert(PurificationEscrow.NotVault.selector);
        escrow.executeWaterfall(1_000e6, 365 days, 10_000e6);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 5. grossProfit==0 reverts ZeroAmount
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_zero_amount_reverts() public {
        vm.expectRevert(PurificationEscrow.ZeroAmount.selector);
        escrow.executeWaterfall(0, 365 days, 10_000e6);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 6. WaterfallExecuted event emitted with correct params
    // ─────────────────────────────────────────────────────────────────────────
    function test_waterfall_emits_event() public {
        uint256 gross     = 1_000e6;
        uint256 elapsed   = 365 days;
        uint256 principal = 10_000e6;

        usdc.approve(address(escrow), gross);

        // Pre-compute expected values
        uint256 purified = 0; // purificationBps = 0
        uint256 afterPurification = gross;
        uint256 expectedCharity   = (afterPurification * 250) / 10_000; // 25e6
        uint256 afterCharity      = afterPurification - expectedCharity;

        (uint256 hurdleAmt, uint256 expectedVaultShare, uint256 expectedDepositorShare) =
            treasury.calculateMusharakahSplit(afterCharity, elapsed, principal);
        (hurdleAmt); // suppress unused warning

        vm.expectEmit(false, false, false, true, address(escrow));
        emit PurificationEscrow.WaterfallExecuted(
            gross,
            purified,
            expectedCharity,
            expectedVaultShare,
            expectedDepositorShare
        );

        escrow.executeWaterfall(gross, elapsed, principal);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 7. proposePurificationRate above cap reverts PurificationAboveCap  [PR2 updated]
    // ─────────────────────────────────────────────────────────────────────────
    function test_setPurificationBps_above_cap_reverts() public {
        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(PurificationEscrow.PurificationAboveCap.selector, 1001, 1000)
        );
        escrow.proposePurificationRate(1001);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 8. CombinedDeductionAboveCap is checked in executeWaterfall runtime guard.
    //    Individual caps on setPurificationBps (<=1000) and charityBps (<=500)
    //    make combined<=1500 in normal operation, so the setPurificationBps path
    //    cannot reach the combined cap. We test the executeWaterfall guard by
    //    directly writing purificationBps to a high value via vm.store, bypassing
    //    the setter cap, then confirming executeWaterfall reverts.
    // ─────────────────────────────────────────────────────────────────────────
    function test_setPurificationBps_combined_above_cap_reverts() public {
        // Raise charityBps to 500 via 30-day timelock
        vm.startPrank(owner);
        charityModule.proposeCharityRateChange(500);
        vm.warp(block.timestamp + 30 days);
        charityModule.confirmCharityRateChange();
        vm.stopPrank();
        assertEq(charityModule.charityBps(), 500, "charityBps should be 500");

        // Write purificationBps = 4501 directly (slot 2 of PurificationEscrow storage:
        //   slot 0 = _owner, slot 1 = _pendingOwner, slot 2 = purificationBps)
        // Combined = 4501 + 500 = 5001 > 5000 → CombinedDeductionAboveCap
        vm.store(address(escrow), bytes32(uint256(2)), bytes32(uint256(4501)));
        assertEq(escrow.purificationBps(), 4501, "purificationBps should be 4501 via store");

        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);

        vm.expectRevert(
            abi.encodeWithSelector(
                PurificationEscrow.CombinedDeductionAboveCap.selector,
                5001,
                5000
            )
        );
        escrow.executeWaterfall(gross, 365 days, 10_000e6);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 9. Non-board account cannot call proposePurificationRate  [PR2 updated]
    // ─────────────────────────────────────────────────────────────────────────
    function test_setPurificationBps_nonOwner_reverts() public {
        vm.prank(other);
        vm.expectRevert(
            abi.encodeWithSelector(PurificationEscrow.NotBoardRole.selector, other)
        );
        escrow.proposePurificationRate(100);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 10. charityWallet receives correct purification amount directly
    // ─────────────────────────────────────────────────────────────────────────
    function test_charityWallet_receives_correct_purification() public {
        // PR2: propose + timelock + confirm
        vm.prank(owner);
        escrow.proposePurificationRate(200); // 2%
        vm.warp(block.timestamp + 30 days);
        vm.prank(owner);
        escrow.confirmPurificationRate();

        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);

        uint256 balanceBefore = usdc.balanceOf(charityWallet);
        (uint256 purified,,,) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        // purified = 1000e6 * 200 / 10_000 = 20e6
        assertEq(purified, 20e6, "purified should be 2% of gross");

        // charityWallet receives purification directly PLUS charity via CharityModule
        // But the purification portion goes directly to charityWallet
        uint256 balanceAfterWaterfall = usdc.balanceOf(charityWallet);
        // The total increase includes both purification (direct) and charity (via CharityModule)
        // We check that balance increased by at least the purification amount
        assertGe(
            balanceAfterWaterfall - balanceBefore,
            purified,
            "charityWallet should receive at least the purification amount"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 11. CharityModule.totalCharityDistributed == 25e6 when purificationBps=0
    // ─────────────────────────────────────────────────────────────────────────
    function test_charityModule_receives_correct_charity() public {
        // purificationBps = 0 (default), so afterPurification = gross = 1000e6
        // charity = 1000e6 * 250 / 10_000 = 25e6
        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);
        escrow.executeWaterfall(gross, 365 days, 10_000e6);

        assertEq(
            charityModule.totalCharityDistributed(),
            25e6,
            "totalCharityDistributed should be 25e6 (2.5% of 1000e6)"
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 12. depositorShare is returned to vault (test contract's balance increases)
    // ─────────────────────────────────────────────────────────────────────────
    function test_depositorShare_returned_to_vault() public {
        uint256 gross = 1_000e6;
        usdc.approve(address(escrow), gross);

        uint256 balanceBefore = usdc.balanceOf(address(this));

        (,, uint256 vaultShare, uint256 depositorShare) = escrow.executeWaterfall(gross, 365 days, 10_000e6);

        uint256 balanceAfter = usdc.balanceOf(address(this));
        // F-01 fix: vault sent gross to escrow; escrow returns depositorShare AND the
        // manager's vaultShare tokens so pendingFees stays backed 1:1 at the vault.
        assertEq(
            balanceAfter,
            balanceBefore - gross + depositorShare + vaultShare,
            "vault balance should change by depositorShare + vaultShare - gross"
        );
        assertEq(usdc.balanceOf(address(escrow)), 0, "escrow must hold no residual tokens");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 13. ShariahVault.claimMusharakahProfit reverts if escrow not set
    // ─────────────────────────────────────────────────────────────────────────
    function test_ShariahVault_claimMusharakahProfit_no_escrow_reverts() public {
        // Deploy a standalone vault without setting escrow
        vm.startPrank(owner);

        TreasuryModule standaloneTreasury = new TreasuryModule(
            "ShariahStandalone",
            makeAddr("placeholder"),
            address(usdc),
            ADMIN_FEE_BPS,
            MUSHARAKAH_SHARE_BPS,
            HURDLE_RATE_BPS,
            owner
        );

        ShariahVault standaloneVault = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(standaloneTreasury),
            address(0)
        );

        vm.stopPrank();

        // Fund vault
        usdc.mint(address(standaloneVault), 1_000e6);

        // claimMusharakahProfit without escrow set → PurificationEscrowNotSet
        vm.prank(owner);
        vm.expectRevert(ShariahVault.PurificationEscrowNotSet.selector);
        standaloneVault.claimMusharakahProfit(1_000e6);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 14. ShariahVault.claimMusharakahProfit succeeds when escrow is set
    // ─────────────────────────────────────────────────────────────────────────
    function test_ShariahVault_claimMusharakahProfit_with_escrow_succeeds() public {
        // vault and vaultEscrow are wired together in setUp
        assertEq(
            address(vault.purificationEscrow()),
            address(vaultEscrow),
            "purificationEscrow should be set"
        );

        uint256 gross = 1_000e6;

        // Fund vault with enough USDC (already done in setUp)
        uint256 vaultBalanceBefore = usdc.balanceOf(address(vault));
        assertGe(vaultBalanceBefore, gross, "vault must have enough USDC");

        vm.prank(owner);
        // Should not revert
        vault.claimMusharakahProfit(gross);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // 15. MusharakahProfitClaimed event has 5 parameters
    // ─────────────────────────────────────────────────────────────────────────
    function test_ShariahVault_event_has_5_params() public {
        uint256 gross = 1_000e6;

        // Pre-compute expected waterfall output using vaultEscrow state
        // purificationBps=0, charityBps=250
        uint256 purified = 0;
        uint256 afterPurification = gross;
        uint256 expectedCharity   = (afterPurification * 250) / 10_000; // 25e6
        uint256 afterCharity      = afterPurification - expectedCharity;

        // Calculate Musharakah split (elapsed ≈ 0 for fresh vault, principal=0)
        // elapsed = block.timestamp - hurdleStartTime; hurdleStartTime set in constructor = block.timestamp
        // principal = hurdlePrincipal = 0 (never set)
        (, uint256 expectedVaultShare, uint256 expectedDepositorShare) =
            vaultTreasury.calculateMusharakahSplit(afterCharity, 0, 0);

        vm.expectEmit(false, false, false, true, address(vault));
        emit ShariahVault.MusharakahProfitClaimed(
            gross,
            purified,
            expectedCharity,
            expectedVaultShare,
            expectedDepositorShare
        );

        vm.prank(owner);
        vault.claimMusharakahProfit(gross);
    }
}

contracts/test/RiskTieredExecutorTest.t..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IStrategyAdapter} from "../IStrategyAdapter.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {ScoreAggregator} from "../ScoreAggregator.sol";
import {RiskTieredExecutor} from "../RiskTieredExecutor.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

// ---------------------------------------------------------------------------
// MockAdapter that accepts deploy/recall for the executor tests
// ---------------------------------------------------------------------------
contract ExecMockAdapter is IStrategyAdapter {
    address public override vault;
    address public usdc;

    constructor(address vault_, address usdc_) {
        vault = vault_;
        usdc = usdc_;
    }

    function deploy(uint256 amount) external override returns (uint256) {
        return amount;
    }

    function recall(uint256 amount) external override returns (uint256) {
        IERC20(usdc).transfer(vault, amount);
        return amount;
    }

    function currentValue() external view override returns (uint256) {
        return IERC20(usdc).balanceOf(address(this));
    }

    function protocolName() external pure override returns (string memory) {
        return "ExecMockAdapter";
    }
}

// ---------------------------------------------------------------------------
// RiskTieredExecutorTest
// ---------------------------------------------------------------------------
contract RiskTieredExecutorTest is Test {
    MockERC20 internal usdc;
    AutonomousVault internal vault;
    ScoreAggregator internal aggregator;
    RiskTieredExecutor internal executor;
    ExecMockAdapter internal adapter;

    address internal owner = makeAddr("owner");
    address internal alice = makeAddr("alice");
    address internal random = makeAddr("random");

    uint32 internal constant SOURCE_DOMAIN = 1;

    ScoreAggregator.Strategy internal constant S0 = ScoreAggregator.Strategy.STABLECOIN_SPREAD;  // idx 0
    ScoreAggregator.Strategy internal constant S1 = ScoreAggregator.Strategy.FUNDING_RATE_ARB;   // idx 1
    ScoreAggregator.Strategy internal constant S2 = ScoreAggregator.Strategy.BRIDGE_FLOW;        // idx 2
    ScoreAggregator.Strategy internal constant S3 = ScoreAggregator.Strategy.LIQUIDATION_RWA;    // idx 3

    bytes32 internal constant DATA_HASH = keccak256("test");

    function setUp() public {
        // Deploy stack
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);

        vm.startPrank(owner);
        vault = new AutonomousVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        aggregator = new ScoreAggregator(owner);
        executor = new RiskTieredExecutor(
            address(vault),
            address(aggregator),
            RiskTieredExecutor.RiskTier.PASSIVE,
            owner
        );
        vm.stopPrank();

        // Deploy adapter (vault is owner for adapter purposes)
        adapter = new ExecMockAdapter(address(vault), address(usdc));

        // Fund vault with 10_000e6 so there's allocation room
        usdc.mint(alice, 10_000e6);
        vm.prank(alice);
        usdc.approve(address(vault), 10_000e6);
        vm.prank(alice);
        vault.deposit(10_000e6, alice);

        // Set executor as vault manager
        vm.prank(owner);
        vault.setManager(address(executor));

        // Raise maxGasPrice so default gas doesn't trigger GasPriceTooHigh
        vm.prank(owner);
        executor.setMaxGasPrice(100 gwei);
    }

    // -----------------------------------------------------------------------
    // Helper: configure S0 adapter
    // -----------------------------------------------------------------------
    function _configureS0(uint256 minAmt, uint256 maxAmt) internal {
        vm.prank(owner);
        executor.setStrategyConfig(
            S0,
            address(adapter),
            bytes32(0),
            true,
            minAmt,
            maxAmt
        );
    }

    /// @dev Write a fresh score (always at current block.timestamp so it is not stale).
    function _writeScore(ScoreAggregator.Strategy strat, uint8 score, uint32 domain) internal {
        vm.prank(owner);
        aggregator.writeScore(strat, score, DATA_HASH, domain);
    }

    /// @dev Skip cooldown AND then write a fresh score — score is always current after the skip.
    function _skipCooldownAndWriteScore(ScoreAggregator.Strategy strat, uint8 score, uint32 domain) internal {
        skip(2 hours + 1);
        _writeScore(strat, score, domain);
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_happy_path
    // -----------------------------------------------------------------------
    function test_executeWinner_happy_path() public {
        _configureS0(1e6, 2_000e6);

        // Skip past cooldown, then write a fresh score
        _skipCooldownAndWriteScore(S0, 85, 0);

        vm.txGasPrice(1 gwei);
        vm.expectEmit(true, false, false, false, address(executor));
        emit RiskTieredExecutor.ExecutionTriggered(S0, 85, 0, address(adapter), RiskTieredExecutor.RiskTier.PASSIVE);
        executor.executeWinner();

        assertGt(vault.totalDeployed(), 0, "capital should have been deployed");
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_score_too_low (PASSIVE min=80)
    // -----------------------------------------------------------------------
    function test_executeWinner_score_too_low() public {
        _configureS0(1e6, 2_000e6);

        _skipCooldownAndWriteScore(S0, 70, 0); // 70 < 80

        vm.txGasPrice(1 gwei);
        vm.expectRevert(abi.encodeWithSelector(RiskTieredExecutor.ScoreTooLow.selector, uint8(70), uint8(80)));
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_cooldown_not_elapsed
    // -----------------------------------------------------------------------
    function test_executeWinner_cooldown_not_elapsed() public {
        _configureS0(1e6, 2_000e6);

        _skipCooldownAndWriteScore(S0, 85, 0);

        vm.txGasPrice(1 gwei);
        executor.executeWinner(); // first execution succeeds

        // Re-write fresh score immediately after execution
        _writeScore(S0, 85, 0);

        // Try again without waiting cooldown — should revert CooldownNotElapsed
        vm.txGasPrice(1 gwei);
        vm.expectRevert(); // CooldownNotElapsed
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_cooldown_boundary — exact boundary warp
    // -----------------------------------------------------------------------
    function test_executeWinner_cooldown_boundary() public {
        _configureS0(1e6, 2_000e6);

        // Record current time as lastExecutionTime baseline (it's 0 by default → cooldown already elapsed)
        // First: do an execution to set lastExecutionTime
        _skipCooldownAndWriteScore(S0, 85, 0);
        vm.txGasPrice(1 gwei);
        executor.executeWinner();
        uint256 lastExec = executor.lastExecutionTime();

        // cooldown is 2 hours; warp to exactly lastExec+cooldown-1 → should revert
        vm.warp(lastExec + 2 hours - 1);
        _writeScore(S0, 85, 0);
        vm.txGasPrice(1 gwei);
        vm.expectRevert(); // CooldownNotElapsed
        executor.executeWinner();

        // Return capital so vault has headroom
        _returnAdapterCapital();

        // warp 1 more second → exactly at cooldown → should succeed
        vm.warp(lastExec + 2 hours);
        _writeScore(S0, 85, 0);
        vm.txGasPrice(1 gwei);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_gas_price_too_high
    // -----------------------------------------------------------------------
    function test_executeWinner_gas_price_too_high() public {
        _configureS0(1e6, 2_000e6);

        _skipCooldownAndWriteScore(S0, 85, 0);

        // Set gas price above maxGasPrice (100 gwei in setUp)
        vm.txGasPrice(101 gwei);
        vm.expectRevert(RiskTieredExecutor.GasPriceTooHigh.selector);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_strategy_not_in_mask
    // PASSIVE mask=9 (bits 0+3), BRIDGE_FLOW is bit 2 → not allowed
    // -----------------------------------------------------------------------
    function test_executeWinner_strategy_not_in_mask() public {
        // Configure S2 adapter but PASSIVE mask doesn't include it
        vm.prank(owner);
        executor.setStrategyConfig(S2, address(adapter), bytes32(0), true, 1e6, 2_000e6);

        // Write a score only for S2 (so it wins)
        _skipCooldownAndWriteScore(S2, 85, 0);

        vm.txGasPrice(1 gwei);
        vm.expectRevert(
            abi.encodeWithSelector(RiskTieredExecutor.StrategyNotAllowedForTier.selector, uint8(2), uint8(9))
        );
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_adapter_not_set
    // -----------------------------------------------------------------------
    function test_executeWinner_adapter_not_set() public {
        // S0 is in mask (PASSIVE mask bit 0), but no adapter configured
        _skipCooldownAndWriteScore(S0, 85, 0);

        vm.txGasPrice(1 gwei);
        // StrategyDisabled is checked first (enabled=false, adapter=address(0))
        vm.expectRevert(RiskTieredExecutor.StrategyDisabled.selector);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_strategy_disabled
    // -----------------------------------------------------------------------
    function test_executeWinner_strategy_disabled() public {
        // Set adapter but enabled=false
        vm.prank(owner);
        executor.setStrategyConfig(S0, address(adapter), bytes32(0), false, 1e6, 2_000e6);

        _skipCooldownAndWriteScore(S0, 85, 0);

        vm.txGasPrice(1 gwei);
        vm.expectRevert(RiskTieredExecutor.StrategyDisabled.selector);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_executeWinner_adapter_address_zero_reverts
    // With enabled=true but adapter=address(0) → AdapterNotSet
    // -----------------------------------------------------------------------
    function test_executeWinner_adapter_address_zero_reverts() public {
        // Configure with enabled=true, adapter=address(0)
        vm.prank(owner);
        executor.setStrategyConfig(S0, address(0), bytes32(0), true, 1e6, 2_000e6);

        _skipCooldownAndWriteScore(S0, 85, 0);

        vm.txGasPrice(1 gwei);
        vm.expectRevert(RiskTieredExecutor.AdapterNotSet.selector);
        executor.executeWinner();
    }

    // -----------------------------------------------------------------------
    // test_setStrategyConfig_only_owner
    // -----------------------------------------------------------------------
    function test_setStrategyConfig_only_owner() public {
        vm.prank(random);
        vm.expectRevert();
        executor.setStrategyConfig(S0, address(adapter), bytes32(0), true, 1e6, 2_000e6);
    }

    // -----------------------------------------------------------------------
    // test_aggressive_tier_lower_min_score
    // AGGRESSIVE min=60; write score 65 → should execute
    // -----------------------------------------------------------------------
    function test_aggressive_tier_lower_min_score() public {
        // Deploy a fresh aggressive executor
        vm.prank(owner);
        RiskTieredExecutor aggExec = new RiskTieredExecutor(
            address(vault),
            address(aggregator),
            RiskTieredExecutor.RiskTier.AGGRESSIVE,
            owner
        );
        // AGGRESSIVE mask=15 — all 4 strategies; configure S0
        vm.prank(owner);
        aggExec.setStrategyConfig(S0, address(adapter), bytes32(0), true, 1e6, 2_000e6);

        // Set aggExec as manager
        vm.prank(owner);
        vault.setManager(address(aggExec));

        // Raise gas ceiling
        vm.prank(owner);
        aggExec.setMaxGasPrice(100 gwei);

        // Skip 31 minutes (past 30-min AGGRESSIVE cooldown), then write fresh score
        skip(31 minutes);
        _writeScore(S0, 65, 0); // 65 >= 60 (AGGRESSIVE min)

        vm.txGasPrice(1 gwei);
        aggExec.executeWinner(); // must NOT revert ScoreTooLow
        assertGt(vault.totalDeployed(), 0, "capital should have been deployed");
    }

    // -----------------------------------------------------------------------
    // test_cooldown_resets_after_execution
    // -----------------------------------------------------------------------
    function test_cooldown_resets_after_execution() public {
        _configureS0(1e6, 2_000e6);

        // First execution
        _skipCooldownAndWriteScore(S0, 85, 0);
        vm.txGasPrice(1 gwei);
        executor.executeWinner();
        uint256 firstDeploy = vault.totalDeployed();
        assertGt(firstDeploy, 0, "first deploy should succeed");

        // Return capital so vault has headroom for second deploy
        _returnAdapterCapital();
        assertEq(vault.totalDeployed(), 0);

        // Wait for cooldown again, write fresh score
        skip(2 hours + 1);
        _writeScore(S0, 85, 0);
        vm.txGasPrice(1 gwei);
        executor.executeWinner(); // should succeed again
        assertGt(vault.totalDeployed(), 0, "second deploy should succeed");
    }

    // -----------------------------------------------------------------------
    // Internal helper: return capital from adapter back to vault
    // -----------------------------------------------------------------------
    function _returnAdapterCapital() internal {
        uint256 deployed = vault.totalDeployed();
        if (deployed == 0) return;

        // Adapter holds the USDC; approve vault to pull back
        vm.prank(address(adapter));
        usdc.approve(address(vault), deployed);
        vm.prank(owner);
        vault.returnCapital(address(adapter), deployed);
    }
}

contracts/test/ScoreAggregatorTest.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {ScoreAggregator} from "../ScoreAggregator.sol";

contract ScoreAggregatorTest is Test {
    ScoreAggregator internal agg;

    address internal owner = makeAddr("owner");
    address internal oracle = makeAddr("oracle");
    address internal random = makeAddr("random");

    bytes32 internal constant HASH_A = keccak256("dataA");

    ScoreAggregator.Strategy internal constant S0 = ScoreAggregator.Strategy.STABLECOIN_SPREAD;
    ScoreAggregator.Strategy internal constant S1 = ScoreAggregator.Strategy.FUNDING_RATE_ARB;
    ScoreAggregator.Strategy internal constant S2 = ScoreAggregator.Strategy.BRIDGE_FLOW;
    ScoreAggregator.Strategy internal constant S3 = ScoreAggregator.Strategy.LIQUIDATION_RWA;

    function setUp() public {
        vm.prank(owner);
        agg = new ScoreAggregator(owner);
        vm.prank(owner);
        agg.setOracle(oracle);
    }

    // -----------------------------------------------------------------------
    // test_writeScore_basic
    // -----------------------------------------------------------------------
    function test_writeScore_basic() public {
        vm.prank(oracle);
        agg.writeScore(S0, 85, HASH_A, 0);

        (uint8 val, uint40 ts, bytes32 dh, uint32 dd) = agg.scores(S0);
        assertEq(val, 85, "value should be 85");
        assertEq(ts, uint40(block.timestamp));
        assertEq(dh, HASH_A);
        assertEq(dd, 0);
    }

    // -----------------------------------------------------------------------
    // test_writeScore_invalid_over_100
    // -----------------------------------------------------------------------
    function test_writeScore_invalid_over_100() public {
        vm.prank(oracle);
        vm.expectRevert(ScoreAggregator.InvalidScore.selector);
        agg.writeScore(S0, 101, HASH_A, 0);
    }

    // -----------------------------------------------------------------------
    // test_getWinningStrategy_picks_highest
    // -----------------------------------------------------------------------
    function test_getWinningStrategy_picks_highest() public {
        vm.startPrank(oracle);
        agg.writeScore(S0, 70, HASH_A, 0);
        agg.writeScore(S1, 90, HASH_A, 0);
        agg.writeScore(S2, 60, HASH_A, 0);
        agg.writeScore(S3, 80, HASH_A, 0);
        vm.stopPrank();

        (ScoreAggregator.Strategy winner, uint8 score,) = agg.getWinningStrategy();
        assertEq(uint8(winner), uint8(S1), "FUNDING_RATE_ARB should win with 90");
        assertEq(score, 90);
    }

    // -----------------------------------------------------------------------
    // test_getWinningStrategy_stale_reverts
    // -----------------------------------------------------------------------
    function test_getWinningStrategy_stale_reverts() public {
        vm.prank(oracle);
        agg.writeScore(S0, 85, HASH_A, 0);

        // warp 6 minutes forward → score is stale (> 5 minutes old)
        skip(6 minutes);

        vm.expectRevert(abi.encodeWithSelector(ScoreAggregator.StaleScore.selector, S0));
        agg.getWinningStrategy();
    }

    // -----------------------------------------------------------------------
    // test_getWinningStrategy_no_scores
    // -----------------------------------------------------------------------
    function test_getWinningStrategy_no_scores() public {
        vm.expectRevert(ScoreAggregator.NoValidScores.selector);
        agg.getWinningStrategy();
    }

    // -----------------------------------------------------------------------
    // test_writeBatchScores
    // -----------------------------------------------------------------------
    function test_writeBatchScores() public {
        ScoreAggregator.Strategy[] memory strats = new ScoreAggregator.Strategy[](4);
        strats[0] = S0; strats[1] = S1; strats[2] = S2; strats[3] = S3;

        uint8[] memory vals = new uint8[](4);
        vals[0] = 80; vals[1] = 75; vals[2] = 65; vals[3] = 90;

        bytes32[] memory hashes = new bytes32[](4);
        hashes[0] = HASH_A; hashes[1] = HASH_A; hashes[2] = HASH_A; hashes[3] = HASH_A;

        uint32[] memory domains = new uint32[](4);
        domains[0] = 1; domains[1] = 2; domains[2] = 3; domains[3] = 4;

        vm.prank(oracle);
        agg.writeBatchScores(strats, vals, hashes, domains);

        (uint8 v0,,,) = agg.scores(S0);
        (uint8 v1,,,) = agg.scores(S1);
        (uint8 v2,,,) = agg.scores(S2);
        (uint8 v3,,,) = agg.scores(S3);
        assertEq(v0, 80);
        assertEq(v1, 75);
        assertEq(v2, 65);
        assertEq(v3, 90);
    }

    // -----------------------------------------------------------------------
    // test_writeBatchScores_length_mismatch
    // -----------------------------------------------------------------------
    function test_writeBatchScores_length_mismatch() public {
        ScoreAggregator.Strategy[] memory strats = new ScoreAggregator.Strategy[](2);
        strats[0] = S0; strats[1] = S1;

        uint8[] memory vals = new uint8[](1); // mismatch
        vals[0] = 80;

        bytes32[] memory hashes = new bytes32[](2);
        hashes[0] = HASH_A; hashes[1] = HASH_A;

        uint32[] memory domains = new uint32[](2);
        domains[0] = 0; domains[1] = 0;

        vm.prank(oracle);
        vm.expectRevert(ScoreAggregator.InvalidScore.selector);
        agg.writeBatchScores(strats, vals, hashes, domains);
    }

    // -----------------------------------------------------------------------
    // test_scoreHistory_ring_buffer — write 12 scores, verify only 10 stored
    // -----------------------------------------------------------------------
    function test_scoreHistory_ring_buffer() public {
        // Write 12 scores for STABLECOIN_SPREAD
        vm.startPrank(oracle);
        for (uint8 i = 1; i <= 12; i++) {
            agg.writeScore(S0, i, keccak256(abi.encode(i)), 0);
        }
        vm.stopPrank();

        ScoreAggregator.Score[10] memory history = agg.getScoreHistory(S0);

        // All 10 slots must be filled (no zero-value entries from overflow)
        uint256 nonZero;
        for (uint256 i = 0; i < 10; i++) {
            if (history[i].value != 0) nonZero++;
        }
        assertEq(nonZero, 10, "ring buffer should hold exactly 10 entries");

        // The last written value (12) must appear somewhere in history
        bool foundLast;
        for (uint256 i = 0; i < 10; i++) {
            if (history[i].value == 12) foundLast = true;
        }
        assertTrue(foundLast, "last written value (12) must be in history");

        // Value 2 (written 11th from last) must NOT appear — it was overwritten
        bool foundOldest;
        for (uint256 i = 0; i < 10; i++) {
            if (history[i].value == 2) foundOldest = true;
        }
        assertFalse(foundOldest, "value 2 should have been overwritten in ring buffer");
    }

    // -----------------------------------------------------------------------
    // test_onlyOracle_or_owner — random address reverts NotOracle
    // -----------------------------------------------------------------------
    function test_onlyOracle_or_owner() public {
        vm.prank(random);
        vm.expectRevert(ScoreAggregator.NotOracle.selector);
        agg.writeScore(S0, 85, HASH_A, 0);
    }

    // -----------------------------------------------------------------------
    // test_setOracle
    // -----------------------------------------------------------------------
    function test_setOracle() public {
        address newOracle = makeAddr("newOracle");

        // Owner sets new oracle
        vm.prank(owner);
        agg.setOracle(newOracle);

        // New oracle can write
        vm.prank(newOracle);
        agg.writeScore(S0, 77, HASH_A, 0);
        (uint8 val,,,) = agg.scores(S0);
        assertEq(val, 77);

        // Old oracle can no longer write
        vm.prank(oracle);
        vm.expectRevert(ScoreAggregator.NotOracle.selector);
        agg.writeScore(S0, 50, HASH_A, 0);
    }

    // -----------------------------------------------------------------------
    // test_destinationDomain_stored
    // -----------------------------------------------------------------------
    function test_destinationDomain_stored() public {
        vm.prank(oracle);
        agg.writeScore(S1, 88, HASH_A, 9);

        (,, uint32[4] memory domains) = agg.getAllScores();
        assertEq(domains[uint8(S1)], 9, "destinationDomain should be 9");
    }

    // -----------------------------------------------------------------------
    // test_owner_can_write_score
    // -----------------------------------------------------------------------
    function test_owner_can_write_score() public {
        vm.prank(owner);
        agg.writeScore(S2, 60, HASH_A, 3);
        (uint8 val,,,) = agg.scores(S2);
        assertEq(val, 60);
    }

    // -----------------------------------------------------------------------
    // test_score_100_valid (boundary)
    // -----------------------------------------------------------------------
    function test_score_100_valid() public {
        vm.prank(oracle);
        agg.writeScore(S0, 100, HASH_A, 0);
        (uint8 val,,,) = agg.scores(S0);
        assertEq(val, 100);
    }
}

contracts/test/SecurityReviewFixesTest.t.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {AutonomousVault}       from "../AutonomousVault.sol";
import {ShariahVault}          from "../ShariahVault.sol";
import {ConventionalVault}     from "../ConventionalVault.sol";
import {TreasuryModule}        from "../TreasuryModule.sol";
import {CharityModule}         from "../CharityModule.sol";
import {PurificationEscrow}    from "../PurificationEscrow.sol";
import {HalalLPAdapter}        from "../adapters/HalalLPAdapter.sol";
import {GoldAllocationAdapter} from "../adapters/GoldAllocationAdapter.sol";
import {TestnetRegistryShortTimelock} from "../script/Rehearsal.s.sol";
import {MockERC20}             from "../test-helpers/MockERC20.sol";
import {MockXAUT}              from "../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}  from "../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT} from "../test-helpers/MockUniswapV3PoolXAUT.sol";
import {MockPositionManager}   from "../test-helpers/MockPositionManager.sol";

/*
 * Regression tests for the security-review fixes F-01 .. F-08.
 *
 *  F-01  PurificationEscrow returns vaultShare to the vault; vault sweepFeesToTreasury balance check
 *  F-02/F-04  AutonomousVault.settleCrossChainWithMessage header validation + setLocalDomain
 *  F-03  HalalLPAdapter slippage timelock + non-zero min amounts
 *  F-05  CharityModule.setEscrow one-shot
 *  F-06  TestnetRegistryShortTimelock mainnet guard
 *  F-07  AutonomousVault.setTokenMessenger / setMessageTransmitter zero-address guards
 *  F-08  GoldAllocationAdapter.setPool is propose-only (timelocked)
 */

// ─── Shared mocks ────────────────────────────────────────────────────────────

contract MockRegistrySRF {
    address public board;
    constructor(address b) { board = b; }
    function isBoard(address a) external view returns (bool) { return a == board; }
}

contract MockMessengerSRF {
    // Task M: record V2's seven arguments; Circle assigns its nonce offchain.
    bytes public lastCall;
    function depositForBurn(uint256 amount, uint32 domain, bytes32 recipient, address token,
        bytes32 caller, uint256 maxFee, uint32 finality) external {
        lastCall = abi.encode(amount, domain, recipient, token, caller, maxFee, finality);
    }
}

/// @dev CCTP transmitter stub WITHOUT localDomain(): vault falls back to its stored domain.
contract MockTransmitterSRF {
    MockERC20 public immutable usdc;
    address public mintTo;
    uint256 public mintAmount;
    constructor(MockERC20 usdc_) { usdc = usdc_; }
    function arm(address to, uint256 amount) external { mintTo = to; mintAmount = amount; }
    function receiveMessage(bytes calldata, bytes calldata) external returns (bool) {
        usdc.mint(mintTo, mintAmount);
        return true;
    }
}

/// @dev Same, but reports a localDomain().
contract MockTransmitterDomainSRF is MockTransmitterSRF {
    uint32 public localDomain;
    constructor(MockERC20 usdc_, uint32 d) MockTransmitterSRF(usdc_) { localDomain = d; }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-01  PurificationEscrow → vault token return + sweepFeesToTreasury balance check
// ═════════════════════════════════════════════════════════════════════════════
contract SRF01EscrowAndSweepTest is Test {
    address internal owner         = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");
    address internal feeReceiver   = makeAddr("feeReceiver");
    address internal attacker      = makeAddr("attacker");
    uint32  internal constant DOMAIN = 26;

    MockERC20          internal usdc;
    MockRegistrySRF    internal reg;
    TreasuryModule     internal treasury;
    ShariahVault       internal vault;
    CharityModule      internal charity;
    PurificationEscrow internal escrow;

    TreasuryModule     internal cTreasury;
    ConventionalVault  internal cvault;

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        reg  = new MockRegistrySRF(owner);

        // Shariah stack: treasury(n) → vault(n+1) → charity(n+2) → escrow(n+3)
        uint256 n = vm.getNonce(address(this));
        address escrowAddr = vm.computeCreateAddress(address(this), n + 3);
        // NOTE: sweepFeesToTreasury calls treasury.claimFees (onlyOwner) as msg.sender == vault,
        // so the sweep success path requires the treasury to be OWNED BY THE VAULT.
        address vaultAddr = vm.computeCreateAddress(address(this), n + 1);
        treasury = new TreasuryModule("Shariah", escrowAddr, address(usdc), 50, 1000, 400, vaultAddr);
        vault    = new ShariahVault(IERC20(address(usdc)), owner, DOMAIN, address(treasury), address(0));
        charity  = new CharityModule(charityWallet, address(usdc), escrowAddr, owner, address(reg));
        escrow   = new PurificationEscrow(
            address(vault), address(usdc), address(charity), address(treasury), owner, address(reg)
        );
        assertEq(address(escrow), escrowAddr, "escrow address precompute");
        vm.prank(owner);
        vault.setPurificationEscrow(address(escrow));

        // Conventional stack: treasury(m) → vault(m+1); treasury feeSource = vault
        uint256 m = vm.getNonce(address(this));
        address cvaultAddr = vm.computeCreateAddress(address(this), m + 1);
        cTreasury = new TreasuryModule("Conventional", cvaultAddr, address(usdc), 50, 0, 0, cvaultAddr);
        cvault    = new ConventionalVault(IERC20(address(usdc)), owner, DOMAIN, address(cTreasury));
        assertEq(address(cvault), cvaultAddr, "cvault address precompute");
    }

    // ── executeWaterfall: end-to-end through the real vault ──────────────────

    // Principal checkpoints must reject arbitrary claims while retaining the existing funded waterfall tests.
    function test_profitCheckpoint_depositMintWithdrawRedeem() public {
        usdc.mint(address(this), 2_000e6);
        usdc.approve(address(vault), type(uint256).max);
        vault.deposit(1_000e6, address(this));
        uint256 shares = vault.previewDeposit(500e6);
        uint256 mintedAssets = vault.mint(shares, address(this));
        assertEq(vault.profitBase(), 1_000e6 + mintedAssets);
        assertEq(vault.realizedProfit(), 0);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 1, 0));
        vault.claimMusharakahProfit(1);
        usdc.mint(address(vault), 100e6);
        uint256 base = vault.profitBase();
        uint256 nav = vault.totalAssets();
        vault.withdraw(100e6, address(this), address(this));
        // checkpoint now shrinks by shares burned / supply; allow 1-wei virtual-share rounding
        assertApproxEqAbs(vault.profitBase(), base - base * 100e6 / nav, 2);
        base = vault.profitBase();
        nav = vault.totalAssets();
        uint256 assets = vault.redeem(vault.balanceOf(address(this)), address(this), address(this));
        assertApproxEqAbs(vault.profitBase(), base - base * assets / nav, 2);
    }

    // A successful claim checkpoints post-claim net NAV, including locked profit and pending fees.
    function test_profitCheckpoint_claimAndOverclaim() public {
        usdc.mint(address(this), 1_000e6);
        usdc.approve(address(vault), 1_000e6);
        vault.deposit(1_000e6, address(this));
        usdc.mint(address(vault), 100e6);
        assertEq(vault.realizedProfit(), 100e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 100e6 + 1, 100e6));
        vault.claimMusharakahProfit(100e6 + 1);
        vm.prank(owner);
        vault.claimMusharakahProfit(100e6);
        // checkpoint counts the locked (already distributed) depositor share as well
        assertEq(vault.profitBase(), vault.totalAssets() + vault.lockedProfit());
        assertEq(vault.realizedProfit(), 0);
        assertEq(usdc.allowance(address(vault), address(escrow)), 0);
    }

    // Deployments preserve principal NAV; locks and fee accrual can only reduce available profit.
    function test_profitCheckpoint_principalWithDeploymentLocksAndFees() public {
        usdc.mint(address(this), 1_000e6);
        usdc.approve(address(vault), 1_000e6);
        vault.deposit(1_000e6, address(this));
        vm.startPrank(owner);
        vault.setScreened(attacker, true);
        vault.deployCapital(attacker, 500e6, "");
        assertEq(vault.realizedProfit(), 0);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 100e6, 0));
        vault.lockProfit(100e6);
        vm.stopPrank();
        vm.prank(address(escrow));
        treasury.accrue(10e6);
        assertEq(vault.profitBase(), 1_000e6);
        assertEq(vault.realizedProfit(), 0);
        skip(3 days);
        assertEq(vault.realizedProfit(), 0);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 1, 0));
        vault.claimMusharakahProfit(1);
    }

    function test_F01_claimReturnsVaultShareToVault() public {
        // N-20: isolate the funded waterfall return from the independently tested annual fee.
        vm.prank(address(vault));
        treasury.setAdminFeeBps(0);
        uint256 gross = 1_000e6;
        usdc.mint(address(vault), gross); // vault holds profit only (no depositor capital)
        vm.prank(owner);
        vault.setHurdlePrincipal(10_000e6);
        skip(365 days);

        vm.prank(owner);
        vault.claimMusharakahProfit(gross);

        // hurdle = 10_000e6 * 4% = 400e6; charity 2.5% = 25e6; surplus = 975e6-400e6 = 575e6; fee = 10% = 57.5e6
        assertEq(treasury.pendingFees(), 57_500_000, "pendingFees == vaultShare");
        assertEq(usdc.balanceOf(address(escrow)), 0, "escrow drained");
        assertEq(usdc.balanceOf(charityWallet), 25e6, "charity paid");
        assertEq(usdc.balanceOf(address(vault)), gross - 25e6, "vault keeps vaultShare + depositorShare");
        assertGe(usdc.balanceOf(address(vault)), treasury.pendingFees(), "vault backs pendingFees");
    }

    function test_F01_feesSweepableAfterClaim() public {
        // N-20: retain the manager-fee sweep fixture without introducing annual admin liabilities.
        vm.prank(address(vault));
        treasury.setAdminFeeBps(0);
        usdc.mint(address(vault), 1_000e6);
        vm.prank(owner);
        vault.setHurdlePrincipal(10_000e6);
        skip(365 days);
        vm.prank(owner);
        vault.claimMusharakahProfit(1_000e6);

        uint256 fees = treasury.pendingFees();
        vm.prank(owner);
        vault.sweepFeesToTreasury(feeReceiver, fees);

        assertEq(usdc.balanceOf(feeReceiver), fees);
        assertEq(treasury.pendingFees(), 0);
        assertEq(treasury.totalFeesCollected(), fees);
    }

    function test_F01_escrowForwardsDonatedDust() public {
        usdc.mint(address(escrow), 7); // stray tokens sitting in escrow
        usdc.mint(address(vault), 1_000e6);
        vm.startPrank(address(vault));
        usdc.approve(address(escrow), 1_000e6);
        escrow.executeWaterfall(1_000e6, 365 days, 10_000e6);
        vm.stopPrank();
        assertEq(usdc.balanceOf(address(escrow)), 0);
    }

    /// @dev purified + charity + vaultShare + depositorShare == grossProfit; escrow ends at 0;
    ///      vault balance >= pendingFees.
    function testFuzz_F01_waterfallConservesAndDrainsEscrow(
        uint256 gross,
        uint256 elapsed,
        uint256 principal,
        uint256 purBps
    ) public {
        gross     = bound(gross, 1, 1_000_000_000e6);
        elapsed   = bound(elapsed, 0, 10 * 365 days);
        principal = bound(principal, 0, 1_000_000_000e6);
        purBps    = bound(purBps, 0, 1000);

        if (purBps > 0) {
            vm.prank(owner);
            escrow.proposePurificationRate(purBps);
            skip(30 days);
            vm.prank(owner);
            escrow.confirmPurificationRate();
        }

        usdc.mint(address(vault), gross);
        vm.startPrank(address(vault));
        usdc.approve(address(escrow), gross);
        (uint256 p, uint256 c, uint256 v, uint256 d) = escrow.executeWaterfall(gross, elapsed, principal);
        vm.stopPrank();

        assertEq(p + c + v + d, gross, "components sum to gross");
        assertEq(usdc.balanceOf(address(escrow)), 0, "escrow balance zero");
        assertEq(treasury.pendingFees(), v, "pendingFees == vaultShare");
        assertGe(usdc.balanceOf(address(vault)), treasury.pendingFees(), "vault balance >= pendingFees");
        assertEq(usdc.balanceOf(address(vault)), v + d, "vault received vaultShare + depositorShare");
        assertEq(usdc.balanceOf(charityWallet), p + c, "purification + charity reach charity wallet");
    }

    // ── sweepFeesToTreasury: InsufficientFeeBalance ───────────────────────────

    function test_F01_shariahSweepRevertsWhenVaultBalanceZero() public {
        vm.prank(address(escrow)); // feeSource
        treasury.accrue(100e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.InsufficientFeeBalance.selector, 0, 100e6));
        vault.sweepFeesToTreasury(feeReceiver, 100e6);
    }

    function test_F01_shariahSweepRevertsWhenBalanceBelowAmount() public {
        vm.prank(address(escrow));
        treasury.accrue(100e6);
        usdc.mint(address(vault), 40e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.InsufficientFeeBalance.selector, 40e6, 100e6));
        vault.sweepFeesToTreasury(feeReceiver, 100e6);
        assertEq(treasury.pendingFees(), 100e6, "accounting untouched on revert");
    }

    function test_F01_shariahSweepSucceedsWhenFunded() public {
        vm.prank(address(escrow));
        treasury.accrue(100e6);
        usdc.mint(address(vault), 100e6);
        vm.prank(owner);
        vault.sweepFeesToTreasury(feeReceiver, 100e6);
        assertEq(usdc.balanceOf(feeReceiver), 100e6);
        assertEq(treasury.pendingFees(), 0);
    }

    function test_F01_shariahSweepAbovePendingReverts() public {
        vm.prank(address(escrow));
        treasury.accrue(100e6);
        usdc.mint(address(vault), 500e6);
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.sweepFeesToTreasury(feeReceiver, 100e6 + 1);
    }

    function test_F01_shariahSweepNonOwnerReverts() public {
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        vault.sweepFeesToTreasury(feeReceiver, 0);
    }

    function test_F01_conventionalSweepRevertsWhenVaultBalanceZero() public {
        vm.prank(address(cvault));
        cTreasury.accrue(100e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ConventionalVault.InsufficientFeeBalance.selector, 0, 100e6));
        cvault.sweepFeesToTreasury(feeReceiver, 100e6);
    }

    function test_F01_conventionalSweepRevertsWhenBalanceBelowAmount() public {
        vm.prank(address(cvault));
        cTreasury.accrue(100e6);
        usdc.mint(address(cvault), 99e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ConventionalVault.InsufficientFeeBalance.selector, 99e6, 100e6));
        cvault.sweepFeesToTreasury(feeReceiver, 100e6);
    }

    function test_F01_conventionalSweepSucceedsWhenFunded() public {
        vm.prank(address(cvault));
        cTreasury.accrue(100e6);
        usdc.mint(address(cvault), 100e6);
        vm.prank(owner);
        cvault.sweepFeesToTreasury(feeReceiver, 100e6);
        assertEq(usdc.balanceOf(feeReceiver), 100e6);
        assertEq(cTreasury.pendingFees(), 0);
    }

    function test_R2_conventionalFeesExcludedAndSweepNeutral() public {
        usdc.mint(address(this), 1_000e6);
        vm.startPrank(address(this));
        usdc.approve(address(cvault), 1_000e6);
        uint256 shares = cvault.deposit(1_000e6, address(this));
        vm.stopPrank();
        vm.prank(address(cvault));
        cTreasury.accrue(100e6);
        assertEq(cvault.totalAssets(), 900e6);
        uint256 redeemable = cvault.previewRedeem(shares);
        uint256 depositShares = cvault.previewDeposit(100e6);
        uint256 withdrawalShares = cvault.previewWithdraw(100e6);
        vm.prank(owner);
        cvault.sweepFeesToTreasury(feeReceiver, 100e6);
        assertEq(cvault.totalAssets(), 900e6);
        assertEq(cvault.previewRedeem(shares), redeemable);
        assertEq(cvault.previewDeposit(100e6), depositShares);
        assertEq(cvault.previewWithdraw(100e6), withdrawalShares);
        vm.prank(address(this));
        cvault.redeem(shares, address(this), address(this));
        assertLe(usdc.balanceOf(address(this)), 900e6);
    }

    function test_conventionalDeployment_pauseThenUnpause_preservesFeesAndAccounting() public {
        usdc.mint(address(this), 1_000e6);
        usdc.approve(address(cvault), 1_000e6);
        cvault.deposit(1_000e6, address(this));
        skip(365 days);
        uint256 lastAccrual = cvault.lastFeeAccrualTime();
        vm.startPrank(owner);
        cvault.setPaused(true);
        vm.expectRevert(AutonomousVault.Paused.selector);
        cvault.deployCapitalWithFeeAccrual(attacker, 100e6, "");
        vm.expectRevert(AutonomousVault.Paused.selector);
        cvault.deployCapital(attacker, 100e6, "");
        assertEq(usdc.balanceOf(attacker), 0);
        assertEq(cvault.totalDeployed(), 0);
        assertEq(cvault.lastFeeAccrualTime(), lastAccrual);
        assertEq(cTreasury.pendingFees(), 0);
        cvault.setPaused(false);
        vm.expectEmit(true, false, false, true, address(cvault));
        emit AutonomousVault.CapitalDeployed(attacker, 100e6);
        cvault.deployCapitalWithFeeAccrual(attacker, 100e6, "");
        assertEq(usdc.balanceOf(attacker), 100e6);
        assertEq(cvault.totalDeployed(), 100e6);
        assertEq(cTreasury.pendingFees(), 5e6);
        assertEq(cvault.totalAssets(), 995e6);
        assertEq(cvault.lastFeeAccrualTime(), block.timestamp);
        cvault.deployCapital(attacker, 10e6, "");
        assertEq(cvault.totalDeployed(), 110e6);
        assertEq(cTreasury.pendingFees(), 5e6, "inherited path does not accrue fees");
        cvault.lockProfit(10e6);
        assertEq(cvault.totalAssets(), 985e6, "conventional locking is unchanged");
        cvault.sweepFeesToTreasury(feeReceiver, 5e6);
        assertEq(cvault.totalAssets(), 985e6, "fee sweep remains NAV neutral");
        vm.stopPrank();
    }

    function test_conventionalDeployment_authAndAllocationUnchanged() public {
        usdc.mint(address(cvault), 1_000e6);
        vm.prank(attacker);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        cvault.deployCapitalWithFeeAccrual(attacker, 1e6, "");
        vm.startPrank(owner);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        cvault.deployCapitalWithFeeAccrual(attacker, 800e6 + 1, "");
        cvault.setManager(feeReceiver);
        vm.stopPrank();
        vm.prank(feeReceiver);
        cvault.deployCapitalWithFeeAccrual(attacker, 100e6, "");
        assertEq(cvault.totalDeployed(), 100e6);
    }

    function test_R2_conventionalAssetsFloorAtZero() public {
        usdc.mint(address(cvault), 100e6);
        vm.prank(address(cvault));
        cTreasury.accrue(100e6);
        assertEq(cvault.totalAssets(), 0);
        vm.prank(address(cvault));
        cTreasury.accrue(1);
        assertEq(cvault.totalAssets(), 0);
    }

    function test_F01_conventionalSweepNonOwnerReverts() public {
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        cvault.sweepFeesToTreasury(feeReceiver, 0);
    }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-02 / F-04 / F-07  AutonomousVault CCTP settlement header checks + config guards
// ═════════════════════════════════════════════════════════════════════════════
contract SRF02VaultCctpTest is Test {
    address internal owner    = makeAddr("owner");
    address internal manager  = makeAddr("manager");
    address internal alice    = makeAddr("alice");
    address internal attacker = makeAddr("attacker");

    uint32  internal constant SOURCE_DOMAIN = 26;
    uint32  internal constant BURN_DOMAIN   = 3;
    uint256 internal constant SENT          = 10_000e6;

    MockERC20        internal usdc;
    MockMessengerSRF internal messenger;
    MockTransmitterSRF internal transmitter;
    AutonomousVault  internal vault;
    uint64           internal nonce;

    function setUp() public {
        usdc        = new MockERC20("Mock USDC", "mUSDC", 6);
        messenger   = new MockMessengerSRF();
        transmitter = new MockTransmitterSRF(usdc);

        vm.startPrank(owner);
        vault = new AutonomousVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        vault.setManager(manager);
        vault.setTokenMessenger(address(messenger));
        vault.setRemoteTokenMessenger(BURN_DOMAIN, bytes32(uint256(0xCC7)));
        vault.setMaxAllocationBps(9_000);
        vault.setMaxPendingCrossChainBps(5_000);
        vault.setMessageTransmitter(address(transmitter));
        vm.stopPrank();

        usdc.mint(alice, 100_000e6);
        vm.startPrank(alice);
        usdc.approve(address(vault), 100_000e6);
        vault.deposit(100_000e6, alice);
        vm.stopPrank();

        // Task M: pending accounting uses the next local position ID.
        nonce = vault.crossChainPositionCounter() + 1;
        vm.prank(manager);
        vault.deployCrossChain(BURN_DOMAIN, bytes32(uint256(uint160(alice))), SENT);
        assertEq(vault.pendingCrossChain(nonce), SENT);
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    function _bytes32(address a) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(a)));
    }

    /// 148-byte native header (version, domains, bytes32 nonce, sender, recipient, caller, finality fields)
    /// + 228-byte V2 burn body (version, burnToken, mintRecipient, amount, msgSender, maxFee, feeExecuted, expiry)
    function _msg(uint64 n, uint32 destDomain, bytes32 destCaller, uint256 amount, uint256 fee)
        internal
        view
        returns (bytes memory)
    {
        // Task M: use the native 148-byte header with an independent bytes32 return nonce.
        bytes memory header = abi.encodePacked(
            uint32(1), BURN_DOMAIN, destDomain, bytes32(uint256(n)),
            vault.remoteTokenMessenger(BURN_DOMAIN), _bytes32(address(messenger)), destCaller,
            uint32(2000), uint32(2000)
        );
        bytes memory body = abi.encodePacked(
            uint32(1), bytes32(0), _bytes32(address(vault)), amount, bytes32(0), uint256(0), fee, uint256(0)
        );
        return bytes.concat(header, body);
    }

    function _settle(uint64 n, bytes memory m) internal {
        vm.prank(manager);
        vault.settleCrossChainWithMessage(n, m, hex"");
    }

    // ── F-02: header validation ──────────────────────────────────────────────

    function test_F02_unknownNonceReverts() public {
        bytes memory m = _msg(77, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(77), uint64(0)));
        vault.settleCrossChainWithMessage(77, m, hex"");
    }

    function test_F02_independentReturnNonceSucceeds() public {
        bytes memory m = _msg(99, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        transmitter.arm(address(vault), SENT);
        _settle(nonce, m);
        assertEq(vault.pendingCrossChain(nonce), 0);
        assertTrue(vault.consumedInbound(BURN_DOMAIN, bytes32(uint256(99))));
    }

    function test_R2_wrongMessageRecipientReverts() public {
        bytes memory m = _msg(99, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        bytes32 bad = _bytes32(attacker);
        for (uint256 i = 0; i < 32; i++) m[76 + i] = bad[i];
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.WrongMessageRecipient.selector, bad));
        _settle(nonce, m);
        assertFalse(vault.consumedInbound(BURN_DOMAIN, bytes32(uint256(99))));
    }

    function test_R2_wrongSourceDomainReverts() public {
        bytes memory m = _msg(99, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        m[7] = bytes1(uint8(7));
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.WrongSourceDomain.selector, BURN_DOMAIN, uint32(7)));
        _settle(nonce, m);
    }

    function test_R2_inboundCannotSettleAnotherPendingEntry() public {
        transmitter.arm(address(vault), SENT);
        bytes memory m = _msg(99, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        _settle(nonce, m);
        uint64 second = vault.crossChainPositionCounter() + 1;
        vm.prank(manager);
        vault.deployCrossChain(BURN_DOMAIN, _bytes32(alice), SENT);
        vm.expectRevert(AutonomousVault.InboundAlreadyConsumed.selector);
        _settle(second, m);
        assertEq(vault.pendingCrossChain(second), SENT);
    }

    function test_R2_failedMintDoesNotConsumeInbound() public {
        bytes memory m = _msg(99, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        // Unarmed transmitter mock: the mint fails, so the whole settle must revert and roll back.
        vm.expectRevert();
        _settle(nonce, m);
        assertFalse(vault.consumedInbound(BURN_DOMAIN, bytes32(uint256(99))));
        transmitter.arm(address(vault), SENT);
        _settle(nonce, m);
        assertTrue(vault.consumedInbound(BURN_DOMAIN, bytes32(uint256(99))));
    }

    function test_F02_wrongDestinationDomainReverts() public {
        bytes memory m = _msg(nonce, 7, _bytes32(address(vault)), SENT, 0);
        vm.prank(manager);
        vm.expectRevert(
            abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, SOURCE_DOMAIN, uint32(7))
        );
        vault.settleCrossChainWithMessage(nonce, m, hex"");
    }

    function test_F02_wrongDestinationCallerReverts() public {
        bytes32 bad = _bytes32(attacker);
        bytes memory m = _msg(nonce, SOURCE_DOMAIN, bad, SENT, 0);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, bad));
        vault.settleCrossChainWithMessage(nonce, m, hex"");
    }

    // Remote strategies MUST burn with destinationCaller = this vault so third parties cannot pre-consume the message.
    function test_F02_rejectsZeroDestinationCaller() public {
        transmitter.arm(address(vault), SENT);
        bytes memory m = _msg(nonce, SOURCE_DOMAIN, bytes32(0), SENT, 0);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, bytes32(0)));
        vault.settleCrossChainWithMessage(nonce, m, hex"");
        assertEq(vault.pendingCrossChain(nonce), SENT);
    }

    function test_F02_acceptsVaultDestinationCaller_emitsSettled() public {
        transmitter.arm(address(vault), SENT);
        bytes memory m = _msg(nonce, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);

        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(nonce, SENT, 0);
        _settle(nonce, m);

        assertEq(vault.pendingCrossChain(nonce), 0);
        assertEq(vault.totalPendingCrossChain(), 0);
        assertEq(vault.totalDeployed(), 0);
    }

    function test_F02_acceptsVaultAsDestinationCaller() public {
        transmitter.arm(address(vault), SENT);
        bytes memory m = _msg(nonce, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        _settle(nonce, m);
        assertEq(vault.pendingCrossChain(nonce), 0);
    }

    function test_F02_settleOnlyManagerOrOwner() public {
        bytes memory m = _msg(nonce, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        vm.prank(attacker);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.settleCrossChainWithMessage(nonce, m, hex"");
    }

    function test_F02_transmitterReportedDomainIsEnforced() public {
        MockTransmitterDomainSRF t5 = new MockTransmitterDomainSRF(usdc, 5);
        vm.prank(owner);
        vault.setMessageTransmitter(address(t5));
        assertEq(vault.localDomain(), 5, "vault adopts transmitter-reported domain");

        // Message for the constructor domain (26) is now wrong.
        bytes memory bad = _msg(nonce, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        vm.prank(manager);
        vm.expectRevert(
            abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, uint32(5), SOURCE_DOMAIN)
        );
        vault.settleCrossChainWithMessage(nonce, bad, hex"");

        // Message for domain 5 settles.
        t5.arm(address(vault), SENT);
        _settle(nonce, _msg(nonce, 5, _bytes32(address(vault)), SENT, 0));
        assertEq(vault.pendingCrossChain(nonce), 0);
    }

    // ── F-04: setLocalDomain ─────────────────────────────────────────────────

    function test_F04_setLocalDomainOnlyOwner() public {
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        vault.setLocalDomain(9);

        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setLocalDomain(9);
    }

    function test_F04_ownerSetsLocalDomainAndSettlementFollows() public {
        vm.prank(owner);
        vault.setLocalDomain(9);
        assertEq(vault.localDomain(), 9);

        bytes memory old = _msg(nonce, SOURCE_DOMAIN, _bytes32(address(vault)), SENT, 0);
        vm.prank(manager);
        vm.expectRevert(
            abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, uint32(9), SOURCE_DOMAIN)
        );
        vault.settleCrossChainWithMessage(nonce, old, hex"");

        transmitter.arm(address(vault), SENT);
        _settle(nonce, _msg(nonce, 9, _bytes32(address(vault)), SENT, 0));
        assertEq(vault.pendingCrossChain(nonce), 0);
    }

    function test_F04_domainZeroIsValid() public {
        vm.prank(owner);
        vault.setLocalDomain(0);
        assertEq(vault.localDomain(), 0);
    }

    function test_F04_setLocalDomainWithoutTransmitterReverts() public {
        vm.prank(owner);
        AutonomousVault fresh = new AutonomousVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN);
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        fresh.setLocalDomain(1);
    }

    function test_F04_setLocalDomainMustMatchTransmitterReport() public {
        MockTransmitterDomainSRF t5 = new MockTransmitterDomainSRF(usdc, 5);
        vm.startPrank(owner);
        vault.setMessageTransmitter(address(t5));
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.LocalDomainMismatch.selector, uint32(5), uint32(6)));
        vault.setLocalDomain(6);
        vault.setLocalDomain(5); // matching value accepted
        vm.stopPrank();
        assertEq(vault.localDomain(), 5);
    }

    // ── F-07: zero-address guards ────────────────────────────────────────────

    function test_F07_setTokenMessengerZeroReverts() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        vault.setTokenMessenger(address(0));
        assertEq(vault.tokenMessenger(), address(messenger), "unchanged");
    }

    function test_F07_setMessageTransmitterZeroReverts() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        vault.setMessageTransmitter(address(0));
        assertEq(vault.messageTransmitter(), address(transmitter), "unchanged");
    }

    function test_F07_setTokenMessengerOwnerHappyPath() public {
        address newMessenger = address(new MockMessengerSRF());
        vm.expectEmit(true, true, false, false, address(vault));
        emit AutonomousVault.TokenMessengerUpdated(address(messenger), newMessenger);
        vm.prank(owner);
        vault.setTokenMessenger(newMessenger);
        assertEq(vault.tokenMessenger(), newMessenger);
    }

    function test_F07_setMessageTransmitterOwnerHappyPath() public {
        MockTransmitterSRF t2 = new MockTransmitterSRF(usdc);
        vm.prank(owner);
        vault.setMessageTransmitter(address(t2));
        assertEq(vault.messageTransmitter(), address(t2));
        assertEq(vault.localDomain(), SOURCE_DOMAIN, "falls back to constructor domain");
    }

    function test_F07_settersNonOwnerRevert() public {
        vm.startPrank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        vault.setTokenMessenger(address(1));
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        vault.setMessageTransmitter(address(1));
        vm.stopPrank();
    }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-03  HalalLPAdapter — timelocked slippage + non-zero min amounts
// ═════════════════════════════════════════════════════════════════════════════
contract SRF03HalalLPTest is Test {
    address internal owner    = makeAddr("owner");
    address internal vault    = makeAddr("vault");
    address internal attacker = makeAddr("attacker");

    MockERC20         internal usdc;
    MockERC20         internal pair;
    MockPositionManager internal pm;
    HalalLPAdapter    internal adapter;

    event SlippageProposed(uint256 newBps, uint256 executeAfter);
    event SlippageExecuted(uint256 newBps);
    event SlippageProposalCancelled();

    function setUp() public {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        pair = new MockERC20("Pair", "PAIR", 18);
        pm   = new MockPositionManager(address(usdc), address(pair));
        adapter = new HalalLPAdapter(
            address(pm), address(usdc), address(pair), 3000, address(usdc), vault, owner
        );
        // The mock manager pays out the paired token on collect().
        pair.mint(address(pm), 1_000_000e18);
    }

    function _deploy(uint256 amount) internal {
        usdc.mint(address(adapter), amount);
        vm.prank(vault);
        adapter.deploy(amount);
    }

    // ── timelock ─────────────────────────────────────────────────────────────

    function test_F03_defaultsAndConstants() public view {
        assertEq(adapter.maxSlippageBps(), 100);
        assertEq(adapter.MAX_SLIPPAGE_BPS(), 500);
        assertEq(adapter.TIMELOCK_DELAY(), 30 days);
        assertFalse(adapter.slippageProposalPending());
    }

    function test_F03_proposeDoesNotChangeValueAndEmits() public {
        vm.expectEmit(false, false, false, true, address(adapter));
        emit SlippageProposed(300, block.timestamp + 30 days);
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(300);

        assertEq(adapter.maxSlippageBps(), 100, "unchanged until execute");
        assertEq(adapter.pendingSlippageBps(), 300);
        assertEq(adapter.slippageExecuteAfter(), block.timestamp + 30 days);
        assertTrue(adapter.slippageProposalPending());
    }

    function test_F03_executeBeforeTimelockReverts() public {
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(300);
        uint256 executeAfter = adapter.slippageExecuteAfter();

        skip(30 days - 1);
        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(HalalLPAdapter.TimelockNotElapsed.selector, executeAfter, block.timestamp)
        );
        adapter.executeMaxSlippageBps();
        assertEq(adapter.maxSlippageBps(), 100);
    }

    function test_F03_executeAfterTimelockAppliesAndClears() public {
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(300);
        skip(30 days);

        vm.expectEmit(false, false, false, true, address(adapter));
        emit SlippageExecuted(300);
        vm.prank(owner);
        adapter.executeMaxSlippageBps();

        assertEq(adapter.maxSlippageBps(), 300);
        assertFalse(adapter.slippageProposalPending());
        assertEq(adapter.pendingSlippageBps(), 0);
        assertEq(adapter.slippageExecuteAfter(), 0);

        vm.prank(owner);
        vm.expectRevert(HalalLPAdapter.NoProposalPending.selector);
        adapter.executeMaxSlippageBps();
    }

    function test_F03_executeWithoutProposalReverts() public {
        vm.prank(owner);
        vm.expectRevert(HalalLPAdapter.NoProposalPending.selector);
        adapter.executeMaxSlippageBps();
    }

    function test_F03_cancelClearsProposal() public {
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(300);

        vm.expectEmit(false, false, false, false, address(adapter));
        emit SlippageProposalCancelled();
        vm.prank(owner);
        adapter.cancelMaxSlippageBps();

        assertFalse(adapter.slippageProposalPending());
        assertEq(adapter.maxSlippageBps(), 100);
        skip(30 days);
        vm.prank(owner);
        vm.expectRevert(HalalLPAdapter.NoProposalPending.selector);
        adapter.executeMaxSlippageBps();
    }

    function test_F03_cancelWithoutProposalReverts() public {
        vm.prank(owner);
        vm.expectRevert(HalalLPAdapter.NoProposalPending.selector);
        adapter.cancelMaxSlippageBps();
    }

    function test_F03_capIsInclusive500() public {
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(500);
        assertEq(adapter.pendingSlippageBps(), 500);
    }

    function test_F03_aboveCapReverts() public {
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(HalalLPAdapter.SlippageAboveCap.selector, 501, 500));
        adapter.proposeMaxSlippageBps(501);
        assertFalse(adapter.slippageProposalPending());
    }

    function testFuzz_F03_capEnforced(uint256 bps) public {
        vm.prank(owner);
        if (bps > 500) {
            vm.expectRevert(abi.encodeWithSelector(HalalLPAdapter.SlippageAboveCap.selector, bps, 500));
            adapter.proposeMaxSlippageBps(bps);
        } else {
            adapter.proposeMaxSlippageBps(bps);
            assertEq(adapter.pendingSlippageBps(), bps);
        }
    }

    function test_F03_nonOwnerReverts() public {
        vm.startPrank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.proposeMaxSlippageBps(200);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.executeMaxSlippageBps();
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.cancelMaxSlippageBps();
        vm.stopPrank();
    }

    // ── non-zero min amounts to the position manager ─────────────────────────

    function test_F03_deployPassesNonZeroMinAmount() public {
        _deploy(1_000e6);
        assertEq(pm.mintCount(), 1);
        assertEq(pm.lastMintAmount0Desired(), 1_000e6);
        assertEq(pm.lastMintAmount0Min(), 990e6, "99% of desired at default 100 bps");
        assertEq(pm.lastMintAmount1Min(), 0, "no min on the zero-desired side");
        assertEq(usdc.allowance(address(adapter), address(pm)), 0, "allowance cleared");
        assertEq(adapter.totalDeployed(), 1_000e6);
    }

    function test_F03_deployTinyAmountStillHasMinOfOne() public {
        _deploy(1);
        assertEq(pm.lastMintAmount0Min(), 1);
    }

    function testFuzz_F03_deployMinNeverZero(uint256 amount) public {
        amount = bound(amount, 1, 1e15);
        _deploy(amount);
        uint256 min0 = pm.lastMintAmount0Min();
        assertGt(min0, 0, "min amount must be non-zero");
        assertLe(min0, amount);
    }

    function test_F03_deployRevertsWhenManagerPaysBelowMin() public {
        pm.setPayoutBps(9_000); // 10% shortfall > 1% tolerance
        usdc.mint(address(adapter), 1_000e6);
        vm.prank(vault);
        vm.expectRevert(bytes("Price slippage check"));
        adapter.deploy(1_000e6);
    }

    function test_F03_deployToleratesShortfallWithinSlippage() public {
        pm.setPayoutBps(9_900); // exactly 1%
        _deploy(1_000e6);
        assertEq(adapter.totalDeployed(), 1_000e6);
    }

    function test_F03_recallPassesNonZeroMinAmounts() public {
        _deploy(1_000e6);
        vm.prank(vault);
        uint256 returned = adapter.recall(400e6);

        assertEq(pm.decreaseCount(), 1);
        assertEq(pm.lastDecLiquidity(), 400e6);
        assertGt(pm.lastDecAmount0Min(), 0, "amount0Min non-zero");
        assertGt(pm.lastDecAmount1Min(), 0, "amount1Min non-zero");
        assertLe(pm.lastDecAmount0Min(), 400e6);
        assertEq(returned, 400e6);
        assertEq(usdc.balanceOf(vault), 400e6);
        assertEq(adapter.totalDeployed(), 600e6);
    }

    function test_F03_recallRevertsWhenManagerPaysBelowMin() public {
        _deploy(1_000e6);
        pm.setPayoutBps(9_000);
        vm.prank(vault);
        vm.expectRevert(bytes("Price slippage check"));
        adapter.recall(400e6);
    }

    function test_F03_recallWithNoPositionReturnsZero() public {
        vm.prank(vault);
        assertEq(adapter.recall(1e6), 0);
        assertEq(pm.decreaseCount(), 0);
    }

    function test_F03_executedSlippageWidensMinAmounts() public {
        vm.prank(owner);
        adapter.proposeMaxSlippageBps(500);
        skip(30 days);
        vm.prank(owner);
        adapter.executeMaxSlippageBps();

        pm.setPayoutBps(9_700); // 3% shortfall: would revert at 1%, ok at 5%
        _deploy(1_000e6);
        assertEq(pm.lastMintAmount0Min(), 950e6, "95% of desired at 500 bps");
    }

    function test_R2_secondDeployRevertsWithoutOverwritingPosition() public {
        _deploy(1_000e6);
        uint256 id = adapter.positionTokenId();
        usdc.mint(address(adapter), 1e6);
        vm.prank(vault);
        vm.expectRevert(bytes4(keccak256("PositionAlreadyOpen()")));
        adapter.deploy(1e6);
        assertEq(adapter.positionTokenId(), id);
        assertEq(pm.mintCount(), 1);
    }

    function test_R2_spotDeviationBlocksMintAndRecall() public {
        pm.setTicks(101, 0);
        usdc.mint(address(adapter), 1_000e6);
        vm.prank(vault);
        vm.expectRevert(abi.encodeWithSignature("SpotTwapDeviation(int24,int24)", int24(101), int24(0)));
        adapter.deploy(1_000e6);
        pm.setTicks(100, 0);
        vm.prank(vault);
        adapter.deploy(1_000e6);
        pm.setTicks(-101, 0);
        vm.prank(vault);
        vm.expectRevert(abi.encodeWithSignature("SpotTwapDeviation(int24,int24)", int24(-101), int24(0)));
        adapter.recall(400e6);
        assertEq(pm.decreaseCount(), 0);
    }

    function test_R2_observationFailureBlocksMintAndRecall() public {
        pm.setObserveUnavailable(true);
        usdc.mint(address(adapter), 1_000e6);
        vm.prank(vault);
        vm.expectRevert(bytes4(keccak256("TwapUnavailable()")));
        adapter.deploy(1_000e6);
        pm.setObserveUnavailable(false);
        vm.prank(vault);
        adapter.deploy(1_000e6);
        pm.setObserveUnavailable(true);
        vm.prank(vault);
        vm.expectRevert(bytes4(keccak256("TwapUnavailable()")));
        adapter.recall(400e6);
    }

    function test_R2_negativeAverageRoundsDown() public {
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = 1800;
        int56[] memory cumulatives = new int56[](2);
        cumulatives[1] = -1801;
        uint160[] memory secondsPerLiquidity = new uint160[](2);
        vm.mockCall(address(pm), abi.encodeWithSignature("observe(uint32[])", secondsAgos),
            abi.encode(cumulatives, secondsPerLiquidity));
        pm.setTicks(99, 0);
        usdc.mint(address(adapter), 1_000e6);
        vm.prank(vault);
        vm.expectRevert(abi.encodeWithSignature("SpotTwapDeviation(int24,int24)", int24(99), int24(-2)));
        adapter.deploy(1_000e6);
    }

    function test_R2_minimumAmountsUseAverageNotSpot() public {
        _deploy(1_000e6);
        uint256 snapshot = vm.snapshotState();
        vm.prank(vault);
        adapter.recall(400e6);
        uint256 min0 = pm.lastDecAmount0Min();
        uint256 min1 = pm.lastDecAmount1Min();
        vm.revertToState(snapshot);
        pm.setTicks(100, 0);
        vm.prank(vault);
        adapter.recall(400e6);
        assertEq(pm.lastDecAmount0Min(), min0);
        assertEq(pm.lastDecAmount1Min(), min1);
    }

    function test_R2_windowTimelockAndBounds() public {
        assertEq(adapter.twapWindow(), 1800);
        assertEq(adapter.MIN_TWAP_WINDOW(), 300);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSignature("TwapWindowBelowMinimum(uint32,uint32)", uint32(299), uint32(300)));
        adapter.proposeTwapWindow(299);
        adapter.proposeTwapWindow(300);
        assertEq(adapter.twapWindow(), 1800);
        uint256 executeAfter = adapter.twapWindowExecuteAfter();
        vm.expectRevert(abi.encodeWithSignature("TimelockNotElapsed(uint256,uint256)", executeAfter, block.timestamp));
        adapter.executeTwapWindow();
        skip(30 days);
        adapter.executeTwapWindow();
        assertEq(adapter.twapWindow(), 300);
        assertFalse(adapter.twapWindowProposalPending());
        assertEq(adapter.pendingTwapWindow(), 0);
        assertEq(adapter.twapWindowExecuteAfter(), 0);
        adapter.proposeTwapWindow(3600);
        adapter.cancelTwapWindow();
        vm.expectRevert(bytes4(keccak256("NoProposalPending()")));
        adapter.executeTwapWindow();
        vm.stopPrank();
    }

    function test_R2_deviationTimelockAndBounds() public {
        assertEq(adapter.maxTwapDeviationTicks(), 100);
        assertEq(adapter.MAX_TWAP_DEVIATION_TICKS(), 500);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSignature("TwapDeviationAboveCap(uint24,uint24)", uint24(501), uint24(500)));
        adapter.proposeMaxTwapDeviationTicks(501);
        adapter.proposeMaxTwapDeviationTicks(500);
        assertEq(adapter.maxTwapDeviationTicks(), 100);
        uint256 executeAfter = adapter.twapDeviationExecuteAfter();
        vm.expectRevert(abi.encodeWithSignature("TimelockNotElapsed(uint256,uint256)", executeAfter, block.timestamp));
        adapter.executeMaxTwapDeviationTicks();
        skip(30 days);
        adapter.executeMaxTwapDeviationTicks();
        assertEq(adapter.maxTwapDeviationTicks(), 500);
        assertFalse(adapter.twapDeviationProposalPending());
        assertEq(adapter.pendingMaxTwapDeviationTicks(), 0);
        assertEq(adapter.twapDeviationExecuteAfter(), 0);
        adapter.proposeMaxTwapDeviationTicks(0);
        adapter.cancelMaxTwapDeviationTicks();
        vm.expectRevert(bytes4(keccak256("NoProposalPending()")));
        adapter.executeMaxTwapDeviationTicks();
        vm.stopPrank();
    }

    function test_R2_oracleConfigOnlyOwner() public {
        vm.startPrank(attacker);
        bytes memory err = abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker);
        vm.expectRevert(err);
        adapter.proposeTwapWindow(300);
        vm.expectRevert(err);
        adapter.executeTwapWindow();
        vm.expectRevert(err);
        adapter.cancelTwapWindow();
        vm.expectRevert(err);
        adapter.proposeMaxTwapDeviationTicks(500);
        vm.expectRevert(err);
        adapter.executeMaxTwapDeviationTicks();
        vm.expectRevert(err);
        adapter.cancelMaxTwapDeviationTicks();
        vm.stopPrank();
    }

    function test_F03_deployAndRecallOnlyVault() public {
        vm.startPrank(attacker);
        vm.expectRevert(HalalLPAdapter.OnlyVault.selector);
        adapter.deploy(1);
        vm.expectRevert(HalalLPAdapter.OnlyVault.selector);
        adapter.recall(1);
        vm.stopPrank();
    }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-05  CharityModule.setEscrow — one-shot
// ═════════════════════════════════════════════════════════════════════════════
contract SRF05CharityEscrowOnceTest is Test {
    address internal owner         = makeAddr("owner");
    address internal charityWallet = makeAddr("charityWallet");
    address internal escrowA       = makeAddr("escrowA");
    address internal escrowB       = makeAddr("escrowB");
    address internal attacker      = makeAddr("attacker");

    MockERC20       internal usdc;
    MockRegistrySRF internal reg;
    CharityModule   internal module;

    function setUp() public {
        usdc   = new MockERC20("Mock USDC", "mUSDC", 6);
        reg    = new MockRegistrySRF(owner);
        module = new CharityModule(charityWallet, address(usdc), makeAddr("vault"), owner, address(reg));
    }

    function test_F05_firstSetEscrowSucceedsAndEmits() public {
        vm.expectEmit(true, false, false, false, address(module));
        emit CharityModule.EscrowSet(escrowA);
        vm.prank(owner);
        module.setEscrow(escrowA);
        assertEq(module.escrow(), escrowA);
    }

    function test_F05_secondSetEscrowReverts() public {
        vm.startPrank(owner);
        module.setEscrow(escrowA);
        vm.expectRevert(CharityModule.EscrowAlreadySet.selector);
        module.setEscrow(escrowB);
        vm.expectRevert(CharityModule.EscrowAlreadySet.selector);
        module.setEscrow(escrowA); // even re-setting the same value
        vm.stopPrank();
        assertEq(module.escrow(), escrowA, "escrow immutable once set");
    }

    function test_F05_zeroAddressAfterSetRevertsEscrowAlreadySet() public {
        vm.startPrank(owner);
        module.setEscrow(escrowA);
        vm.expectRevert(CharityModule.EscrowAlreadySet.selector);
        module.setEscrow(address(0));
        vm.stopPrank();
        assertEq(module.escrow(), escrowA, "cannot be cleared");
    }

    /// @dev On a fresh module a zero address is rejected with ZeroWallet (source order:
    ///      EscrowAlreadySet check first, then the zero check) and escrow stays unset.
    function test_F05_zeroAddressOnFreshModuleReverts() public {
        vm.prank(owner);
        vm.expectRevert(CharityModule.ZeroWallet.selector);
        module.setEscrow(address(0));
        assertEq(module.escrow(), address(0));
    }

    function test_F05_nonOwnerReverts() public {
        vm.prank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        module.setEscrow(escrowA);
    }

    function test_F05_escrowCanDistributeOnlyAfterSet() public {
        usdc.mint(escrowA, 1_000e6);
        vm.prank(escrowA);
        usdc.approve(address(module), 1_000e6);

        vm.prank(escrowA);
        vm.expectRevert(CharityModule.NotVault.selector);
        module.distributeCharity(1_000e6);

        vm.prank(owner);
        module.setEscrow(escrowA);
        vm.prank(escrowA);
        (uint256 charityAmt,) = module.distributeCharity(1_000e6);
        assertEq(charityAmt, 25e6);
    }

    function testFuzz_F05_onlyFirstEscrowWins(address a, address b) public {
        vm.assume(a != address(0));
        vm.startPrank(owner);
        module.setEscrow(a);
        vm.expectRevert(CharityModule.EscrowAlreadySet.selector);
        module.setEscrow(b);
        vm.stopPrank();
        assertEq(module.escrow(), a);
    }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-06  Rehearsal.s.sol TestnetRegistryShortTimelock — mainnet chain guard
// ═════════════════════════════════════════════════════════════════════════════
contract SRF06RehearsalGuardTest is Test {
    address internal owner  = makeAddr("owner");
    address internal board  = makeAddr("board");
    address internal adapter = makeAddr("adapter");

    function test_F06_deployRevertsOnArcMainnet5042() public {
        vm.chainId(5042);
        vm.expectRevert(bytes("mainnet forbidden"));
        new TestnetRegistryShortTimelock(owner, board);
    }

    function test_F06_deployWorksOnArcTestnet5042002() public {
        vm.chainId(5042002);
        TestnetRegistryShortTimelock r = new TestnetRegistryShortTimelock(owner, board);
        assertEq(r.owner(), owner);
        assertTrue(r.isBoard(board));
        assertEq(r.TESTNET_TIMELOCK_PERIOD(), 2 minutes);
    }

    function testFuzz_F06_deployWorksOnAnyChainExcept5042(uint64 chainId) public {
        vm.assume(chainId != 5042 && chainId != 0);
        vm.chainId(chainId);
        TestnetRegistryShortTimelock r = new TestnetRegistryShortTimelock(owner, board);
        assertEq(r.owner(), owner);
    }

    function test_F06_screeningFunctionsRevertIfChainBecomes5042() public {
        vm.chainId(5042002);
        TestnetRegistryShortTimelock r = new TestnetRegistryShortTimelock(owner, board);
        vm.chainId(5042);
        vm.startPrank(board);
        vm.expectRevert(bytes("mainnet forbidden"));
        r.proposeScreeningTestnet(adapter, keccak256("ruling"), block.timestamp + 365 days);
        vm.expectRevert(bytes("mainnet forbidden"));
        r.executeScreeningTestnet(adapter);
        vm.stopPrank();
    }

    function test_F06_shortTimelockFlowOnTestnet() public {
        vm.chainId(5042002);
        TestnetRegistryShortTimelock r = new TestnetRegistryShortTimelock(owner, board);
        bytes32 h = keccak256("ruling");
        uint256 expiry = block.timestamp + 365 days;

        vm.startPrank(board);
        r.proposeScreeningTestnet(adapter, h, expiry);
        vm.expectRevert(bytes("TestnetReg: timelock not elapsed"));
        r.executeScreeningTestnet(adapter);
        skip(2 minutes);
        r.executeScreeningTestnet(adapter);
        vm.stopPrank();

        (bytes32 pHash, uint256 exp,) = r.screenings(adapter);
        assertEq(pHash, h);
        assertEq(exp, expiry);
    }
}

// ═════════════════════════════════════════════════════════════════════════════
//  F-08  GoldAllocationAdapter.setPool — propose-only, 30-day timelock
// ═════════════════════════════════════════════════════════════════════════════
contract SRF08GoldPoolTimelockTest is Test {
    address internal owner    = makeAddr("owner");
    address internal vault    = makeAddr("vault");
    address internal attacker = makeAddr("attacker");

    uint256 internal constant POOL_PRICE = 3_300_000_000;
    int256  internal constant ORACLE_PRICE = 330_000_000_000;

    MockERC20             internal usdc;
    MockXAUT              internal xaut;
    MockXauUsdAggregator  internal oracle;
    MockUniswapV3PoolXAUT internal poolA;
    MockUniswapV3PoolXAUT internal poolB;
    GoldAllocationAdapter internal adapter;

    function setUp() public {
        vm.warp(1_700_000_000);
        usdc   = new MockERC20("Mock USDC", "mUSDC", 6);
        xaut   = new MockXAUT();
        oracle = new MockXauUsdAggregator();
        poolA  = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), POOL_PRICE);
        poolB  = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), POOL_PRICE * 2);
        adapter = new GoldAllocationAdapter(
            address(usdc), address(xaut), address(poolA), 3000, address(oracle), vault, 3600, owner
        );
    }

    function test_F08_setPoolOnlyProposes() public {
        assertEq(adapter.pool(), address(poolA));
        vm.expectEmit(true, false, false, true, address(adapter));
        emit GoldAllocationAdapter.PoolProposed(address(poolB), block.timestamp + 30 days);
        vm.prank(owner);
        adapter.setPool(address(poolB));

        assertEq(adapter.pool(), address(poolA), "pool unchanged until executePool");
        (address pending, uint256 executeAfter, bool isPending) = adapter.pendingPool();
        assertEq(pending, address(poolB));
        assertEq(executeAfter, block.timestamp + 30 days);
        assertTrue(isPending);
    }

    function test_F08_executeEarlyReverts() public {
        vm.prank(owner);
        adapter.setPool(address(poolB));
        (, uint256 executeAfter,) = adapter.pendingPool();

        skip(30 days - 1);
        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(GoldAllocationAdapter.TimelockNotElapsed.selector, executeAfter, block.timestamp)
        );
        adapter.executePool();
        assertEq(adapter.pool(), address(poolA));
    }

    function test_F08_executeAfterTimelockSwitchesPool() public {
        vm.prank(owner);
        adapter.setPool(address(poolB));
        skip(30 days);

        vm.expectEmit(true, true, false, false, address(adapter));
        emit GoldAllocationAdapter.PoolExecuted(address(poolA), address(poolB));
        vm.prank(owner);
        adapter.executePool();

        assertEq(adapter.pool(), address(poolB));
        (,, bool isPending) = adapter.pendingPool();
        assertFalse(isPending);

        vm.prank(owner);
        vm.expectRevert(GoldAllocationAdapter.NoProposalPending.selector);
        adapter.executePool();
    }

    function test_F08_proposePoolAliasBehavesTheSame() public {
        vm.prank(owner);
        adapter.proposePool(address(poolB));
        assertEq(adapter.pool(), address(poolA));
        (address pending,, bool isPending) = adapter.pendingPool();
        assertEq(pending, address(poolB));
        assertTrue(isPending);
    }

    function test_F08_cancelPoolWorks() public {
        vm.prank(owner);
        adapter.setPool(address(poolB));

        vm.expectEmit(false, false, false, false, address(adapter));
        emit GoldAllocationAdapter.PoolProposalCancelled();
        vm.prank(owner);
        adapter.cancelPool();

        (,, bool isPending) = adapter.pendingPool();
        assertFalse(isPending);
        skip(30 days);
        vm.prank(owner);
        vm.expectRevert(GoldAllocationAdapter.NoProposalPending.selector);
        adapter.executePool();
        assertEq(adapter.pool(), address(poolA));
    }

    function test_F08_cancelWithoutProposalReverts() public {
        vm.prank(owner);
        vm.expectRevert(GoldAllocationAdapter.NoProposalPending.selector);
        adapter.cancelPool();
    }

    function test_F08_nonOwnerReverts() public {
        vm.startPrank(attacker);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.setPool(address(poolB));
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.proposePool(address(poolB));
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.executePool();
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, attacker));
        adapter.cancelPool();
        vm.stopPrank();
    }

    /// @dev Behavioural: price sanity keeps reading the OLD pool until executePool.
    function test_F08_priceSanityFollowsActivePoolOnly() public {
        oracle.setPrice(ORACLE_PRICE);
        assertTrue(adapter.isPriceSane());
        vm.prank(owner);
        adapter.setPool(address(poolB)); // poolB is 2x the oracle price
        assertTrue(adapter.isPriceSane(), "proposal alone must not change price source");

        skip(30 days);
        oracle.setPrice(ORACLE_PRICE); // refresh staleness
        assertTrue(adapter.isPriceSane(), "still old pool right before execute");

        vm.prank(owner);
        adapter.executePool();
        assertFalse(adapter.isPriceSane(), "deviating pool is live only after execute");
    }
}

contracts/test/ShariahAdapterRegistryTes.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";

/// @title ShariahAdapterRegistryTest
/// @notice Unit tests for ShariahAdapterRegistry — Task E
contract ShariahAdapterRegistryTest is Test {

    // ── actors ────────────────────────────────────────────────────
    address internal deployer = makeAddr("deployer");
    address internal other    = makeAddr("other");

    // ── contract under test ───────────────────────────────────────
    ShariahAdapterRegistry internal registry;

    // ── constants ─────────────────────────────────────────────────
    address internal constant ADAPTER     = address(0x42);
    bytes32 internal constant HASH        = keccak256("SR-005");
    uint256 internal constant TIMELOCK    = 30 days;
    uint256 internal constant VALID_EXPIRY_OFFSET = 365 days;

    // ─────────────────────────────────────────────────────────────
    // setUp — runs before every test
    // ─────────────────────────────────────────────────────────────

    function setUp() public {
        vm.prank(deployer);
        registry = new ShariahAdapterRegistry(deployer, deployer);
        // deployer has boardRole automatically (set in constructor)
    }

    // ─────────────────────────────────────────────────────────────
    // 1. isScreened false by default
    // ─────────────────────────────────────────────────────────────

    function test_isScreened_false_by_default() public view {
        assertFalse(registry.isScreened(ADAPTER));
    }

    // ─────────────────────────────────────────────────────────────
    // 2. isScreened false after propose before execute
    // ─────────────────────────────────────────────────────────────

    function test_isScreened_false_after_propose_before_execute() public {
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);

        // Proposal exists but not executed yet — screening not live
        assertFalse(registry.isScreened(ADAPTER));
    }

    // ─────────────────────────────────────────────────────────────
    // 3. isScreened true after propose + warp + execute
    // ─────────────────────────────────────────────────────────────

    function test_isScreened_true_after_execute() public {
        uint256 expiresAt = block.timestamp + VALID_EXPIRY_OFFSET;

        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, expiresAt);

        vm.warp(block.timestamp + TIMELOCK);

        vm.prank(deployer);
        registry.executeScreening(ADAPTER);

        assertTrue(registry.isScreened(ADAPTER));
    }

    // ─────────────────────────────────────────────────────────────
    // 4. isScreened false after screening expires
    // ─────────────────────────────────────────────────────────────

    function test_isScreened_false_after_expiry() public {
        uint256 expiresAt = block.timestamp + VALID_EXPIRY_OFFSET;

        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, expiresAt);

        vm.warp(block.timestamp + TIMELOCK);

        vm.prank(deployer);
        registry.executeScreening(ADAPTER);

        // Warp to exact expiry — isScreened checks block.timestamp < expiresAt
        vm.warp(expiresAt);
        assertFalse(registry.isScreened(ADAPTER));
    }

    // ─────────────────────────────────────────────────────────────
    // 5. Non-board address cannot propose
    // ─────────────────────────────────────────────────────────────

    function test_nonBoard_propose_reverts() public {
        vm.prank(other);
        vm.expectRevert(abi.encodeWithSelector(ShariahAdapterRegistry.NotBoardRole.selector, other));
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);
    }

    // ─────────────────────────────────────────────────────────────
    // 6. Execute before timelock reverts TimelockNotElapsed
    // ─────────────────────────────────────────────────────────────

    function test_execute_before_timelock_reverts() public {
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);

        uint256 executeAfter = block.timestamp + TIMELOCK;

        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(
                ShariahAdapterRegistry.TimelockNotElapsed.selector,
                executeAfter,
                block.timestamp
            )
        );
        registry.executeScreening(ADAPTER);
    }

    // ─────────────────────────────────────────────────────────────
    // 7. Execute with no pending proposal reverts NoPendingProposal
    // ─────────────────────────────────────────────────────────────

    function test_execute_no_proposal_reverts() public {
        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(ShariahAdapterRegistry.NoPendingProposal.selector, ADAPTER)
        );
        registry.executeScreening(ADAPTER);
    }

    // ─────────────────────────────────────────────────────────────
    // 8. Double propose reverts AlreadyProposed
    // ─────────────────────────────────────────────────────────────

    function test_double_propose_reverts() public {
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);

        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(ShariahAdapterRegistry.AlreadyProposed.selector, ADAPTER)
        );
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);
    }

    // ─────────────────────────────────────────────────────────────
    // 9. Zero hash reverts ZeroHash
    // ─────────────────────────────────────────────────────────────

    function test_zero_hash_reverts() public {
        vm.prank(deployer);
        vm.expectRevert(ShariahAdapterRegistry.ZeroHash.selector);
        registry.proposeScreening(ADAPTER, bytes32(0), block.timestamp + VALID_EXPIRY_OFFSET);
    }

    // ─────────────────────────────────────────────────────────────
    // 10. Zero adapter reverts ZeroAdapter
    // ─────────────────────────────────────────────────────────────

    function test_zero_adapter_reverts() public {
        vm.prank(deployer);
        vm.expectRevert(ShariahAdapterRegistry.ZeroAdapter.selector);
        registry.proposeScreening(address(0), HASH, block.timestamp + VALID_EXPIRY_OFFSET);
    }

    // ─────────────────────────────────────────────────────────────
    // 11. Expiry too far reverts ExpiryTooFar
    // ─────────────────────────────────────────────────────────────

    function test_expiry_too_far_reverts() public {
        uint256 tooFar = block.timestamp + 731 days;
        uint256 maxAllowed = block.timestamp + registry.MAX_EXPIRY_PERIOD();

        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(ShariahAdapterRegistry.ExpiryTooFar.selector, tooFar, maxAllowed)
        );
        registry.proposeScreening(ADAPTER, HASH, tooFar);
    }

    // ─────────────────────────────────────────────────────────────
    // 12. Cancel clears proposal
    // ─────────────────────────────────────────────────────────────

    function test_cancel_clears_proposal() public {
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);

        // Proposal exists before cancel
        (,, , bool existsBefore) = registry.proposals(ADAPTER);
        assertTrue(existsBefore);

        vm.prank(deployer);
        registry.cancelProposal(ADAPTER);

        // Proposal gone after cancel
        (,, , bool existsAfter) = registry.proposals(ADAPTER);
        assertFalse(existsAfter);
    }

    // ─────────────────────────────────────────────────────────────
    // 13. Removal before timelock reverts TimelockNotElapsed
    // ─────────────────────────────────────────────────────────────

    function test_removal_before_timelock_reverts() public {
        // First screen the adapter
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, block.timestamp + VALID_EXPIRY_OFFSET);
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeScreening(ADAPTER);

        // Propose removal
        vm.prank(deployer);
        registry.proposeRemoval(ADAPTER);

        uint256 executeAfter = block.timestamp + TIMELOCK;

        // Try to execute immediately
        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(
                ShariahAdapterRegistry.TimelockNotElapsed.selector,
                executeAfter,
                block.timestamp
            )
        );
        registry.executeRemoval(ADAPTER);
    }

    // ─────────────────────────────────────────────────────────────
    // 14. Removal after timelock succeeds — isScreened false after
    // ─────────────────────────────────────────────────────────────

    function test_removal_after_timelock_succeeds() public {
        // Screen the adapter first
        uint256 expiresAt = block.timestamp + VALID_EXPIRY_OFFSET;
        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, expiresAt);
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeScreening(ADAPTER);
        assertTrue(registry.isScreened(ADAPTER), "should be screened before removal");

        // Propose and execute removal
        vm.prank(deployer);
        registry.proposeRemoval(ADAPTER);
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeRemoval(ADAPTER);

        // Screening entry deleted
        assertFalse(registry.isScreened(ADAPTER), "should not be screened after removal");
        ShariahAdapterRegistry.Screening memory s = registry.getScreening(ADAPTER);
        assertEq(s.pronouncementHash, bytes32(0));
        assertEq(s.expiresAt, 0);
    }

    // ─────────────────────────────────────────────────────────────
    // 15. Grant and revoke board role via propose/timelock/execute (G4)
    // ─────────────────────────────────────────────────────────────

    function test_grant_revoke_board_role() public {
        // Initially `other` has no board role
        assertFalse(registry.boardRole(other));

        // Board member (deployer) proposes granting board role to `other`
        vm.prank(deployer);
        registry.proposeBoardRoleChange(other, true);

        // Proposal exists but not executed yet — board role not granted
        assertFalse(registry.boardRole(other));

        // Warp past the 30-day timelock and execute
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeBoardRoleChange(other);
        assertTrue(registry.boardRole(other));

        // Board member (deployer) proposes revoking board role from `other`
        vm.prank(deployer);
        registry.proposeBoardRoleChange(other, false);

        // Warp past the 30-day timelock and execute
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeBoardRoleChange(other);
        assertFalse(registry.boardRole(other));
    }

    // ─────────────────────────────────────────────────────────────
    // 16. getScreening returns correct struct after execute
    // ─────────────────────────────────────────────────────────────

    function test_getScreening_returns_correct_struct() public {
        uint256 expiresAt = block.timestamp + VALID_EXPIRY_OFFSET;

        vm.prank(deployer);
        registry.proposeScreening(ADAPTER, HASH, expiresAt);
        vm.warp(block.timestamp + TIMELOCK);
        vm.prank(deployer);
        registry.executeScreening(ADAPTER);

        ShariahAdapterRegistry.Screening memory s = registry.getScreening(ADAPTER);
        assertEq(s.pronouncementHash, HASH);
        assertEq(s.expiresAt, expiresAt);
        assertGt(s.setAt, 0);
    }

    // ─────────────────────────────────────────────────────────────
    // 17. Non-board address cannot proposeBoardRoleChange (G4)
    // ─────────────────────────────────────────────────────────────

    function test_board_role_not_nonOwner() public {
        // `other` has no board role — proposeBoardRoleChange reverts NotBoardRole
        vm.prank(other);
        vm.expectRevert(
            abi.encodeWithSelector(ShariahAdapterRegistry.NotBoardRole.selector, other)
        );
        registry.proposeBoardRoleChange(makeAddr("newMember"), true);
    }

    // ─────────────────────────────────────────────────────────────
    // 18. emergencyRevokeBoardRole is owner-only and works instantly (G4)
    // ─────────────────────────────────────────────────────────────

    function test_emergencyRevoke_board_role() public {
        // deployer has board role from constructor
        assertTrue(registry.boardRole(deployer));

        // Owner calls emergencyRevokeBoardRole — instant removal, no timelock
        vm.prank(deployer);
        registry.emergencyRevokeBoardRole(deployer);
        assertFalse(registry.boardRole(deployer));
    }

    // ─────────────────────────────────────────────────────────────
    // 19. cancelBoardRoleChange clears a pending proposal (G4)
    // ─────────────────────────────────────────────────────────────

    function test_cancelBoardRoleChange_clears_proposal() public {
        vm.prank(deployer);
        registry.proposeBoardRoleChange(other, true);

        // Proposal now exists
        (,, bool exists) = registry.boardRoleProposals(other);
        assertTrue(exists, "proposal should exist after propose");

        // Cancel it
        vm.prank(deployer);
        registry.cancelBoardRoleChange(other);

        // Proposal cleared
        (,, bool existsAfter) = registry.boardRoleProposals(other);
        assertFalse(existsAfter, "proposal should be gone after cancel");
    }
}

