    // ─────────────────────────────────────────────────────────────────────────
    // L1 Test 10 — golden fixture: a hand-crafted BurnMessageV2 with known field
    //              values round-trips through settleCrossChainWithMessage and the
    //              emitted events must carry exactly those values.
    //
    //  This test exercises CctpMessageDecoder end-to-end without a shim.
    //
    //  Fixture fields:
    //    amount       = 5_000_000   (5 USDC, 6 dec)
    //    maxFee       = 100_000     (0.1 USDC ceiling — placed at body[132..163])
    //    feeExecuted  = 50_000      (0.05 USDC actual — placed at body[164..195])
    //    mintRecipient = vault address
    //
    //  If the decoder were reading body[132] instead of body[164], feeExecuted would
    //  equal maxFee (100_000) instead of 50_000, and expectedNet would be 4_900_000
    //  instead of 4_950_000 — the transmitter mints 4_950_000, the check fails.
    //  This test therefore fails specifically when the offset is wrong.
    // ─────────────────────────────────────────────────────────────────────────
    function test_L1_golden_fixture_correct_offset() public {
        uint256 fixtureAmount  = 5_000_000;  // 5 USDC
        uint256 fixtureMaxFee  = 100_000;    // 0.1 USDC — must NOT be decoded as feeExecuted
        uint256 fixtureFeeExec = 50_000;     // 0.05 USDC actual fee
        uint256 expectedNet    = fixtureAmount - fixtureFeeExec; // 4_950_000

        // Pre-condition: maxFee != feeExecuted so an offset mix-up is detectable.
        assertTrue(fixtureMaxFee != fixtureFeeExec, "fixture design: maxFee must differ from feeExecuted");

        // Deploy 5 USDC cross-chain so there is a pending nonce.
        uint64 nonce = _deployCrossChainI1(fixtureAmount);

        // Transmitter mints exactly expectedNet (= amount - feeExecuted).
        transmitter.setMintAmount(expectedNet);
        uint256 navBefore = vault.totalAssets();

        bytes memory msg_ = _buildMessageWithFee(
            nonce, fixtureAmount, address(vault), fixtureFeeExec, fixtureMaxFee
        );
        assertEq(msg_.length, 376, "fixture message length must be 376 bytes");

        vm.prank(manager);
        // Expect CrossChainFeeDeducted with the actual feeExecuted (50_000), not maxFee.
        vm.expectEmit(true, false, false, true);
        emit AutonomousVault.CrossChainFeeDeducted(nonce, fixtureFeeExec);
        // Expect CrossChainSettled: received=4_950_000, shortfall=50_000
        vm.expectEmit(true, false, false, true);
        emit AutonomousVault.CrossChainSettled(nonce, expectedNet, fixtureFeeExec);
        vault.settleCrossChainWithMessage(nonce, msg_, "");

        // NAV drops by exactly fixtureFeeExec (not fixtureMaxFee).
        assertEq(vault.totalAssets(), navBefore - fixtureFeeExec,
            "NAV drop must equal feeExecuted, not maxFee");
    }

}

contracts/test/TaskITest.I2.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title  TaskI — Item I2: GoldExchangeAdapter PR1 parity (stale-price valuation)
/// @notice Tests 6-15 from the Task-I specification.

import {TaskITestBase} from "./TaskITest.Base.t.sol";
import {GoldExchangeAdapter} from "../adapters/GoldExchangeAdapter.sol";

contract TaskITest_I2 is TaskITestBase {

    // ─────────────────────────────────────────────────────────────────────────
    // Test 6 — currentValue() uses the live oracle when fresh
    // ─────────────────────────────────────────────────────────────────────────
    // Corrected units make even the raw 1:1 router value its position at the full USDC input.
    function test_I2_currentValue_uses_oracle_when_fresh() public {
        // Use a large deploy to get a non-trivial paxgHeld
        // Fund the svault with more USDC first
        usdc.mint(alice, 1_000_000e6);
        vm.startPrank(alice);
        usdc.approve(address(svault), 1_000_000e6);
        svault.deposit(1_000_000e6, alice);
        vm.stopPrank();

        uint256 deployAmt = 50_000e6;
        _deployAndSwapGold(deployAmt);

        uint256 paxgHeld_     = goldAdapter.paxgHeld();
        // Fresh valuation reads the oracle directly rather than the execution-price cache.
        uint256 expectedGross = (paxgHeld_ * 3_300e6) / 1e18;

        // Must be fresh (just deployed, no warp)
        uint256 cv = goldAdapter.currentValue();
        assertEq(cv, expectedGross, "currentValue != paxgHeld * lastGoodPrice / 1e18 when fresh");
        assertApproxEqAbs(cv, deployAmt, 1, "entry value must not lose a decimal scaling factor");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 7 — currentValue() uses haircut when stale
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_currentValue_uses_haircut_when_stale() public {
        uint256 deployAmt = 50_000e6;
        usdc.mint(alice, 1_000_000e6);
        vm.startPrank(alice);
        usdc.approve(address(svault), 1_000_000e6);
        svault.deposit(1_000_000e6, alice);
        vm.stopPrank();
        _deployAndSwapGold(deployAmt);

        uint256 paxgHeld_     = goldAdapter.paxgHeld();
        uint256 lastGoodPrice_= goldAdapter.lastGoodPrice();
        uint256 grossValue    = (paxgHeld_ * lastGoodPrice_) / 1e18;

        // Advance past maxStalenessSecs (default 1 day)
        uint256 maxStaleness = goldAdapter.maxStalenessSecs();
        vm.warp(block.timestamp + maxStaleness + 1);

        uint256 haircutBps  = goldAdapter.staleHaircutBps(); // default 500
        uint256 expectedValue = (grossValue * (10_000 - haircutBps)) / 10_000;

        assertEq(goldAdapter.currentValue(), expectedValue, "stale currentValue should apply haircut");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 8 — currentValue() == 0 before any deploy
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_currentValue_zero_before_deploy() public view {
        assertEq(goldAdapter.currentValue(), 0, "currentValue must be 0 before any swap");
        assertEq(goldAdapter.paxgHeld(), 0, "paxgHeld must be 0 before swap");
        assertEq(goldAdapter.lastGoodPrice(), 0, "lastGoodPrice must be 0 before swap");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 9 — isPriceSane() == true immediately after deploy
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_isPriceSane_true_when_fresh() public {
        _deployAndSwapGold(1_000e6);
        assertTrue(goldAdapter.isPriceSane(), "isPriceSane should be true right after swap");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 10 — isPriceSane() == false when stale
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_isPriceSane_false_when_stale() public {
        _deployAndSwapGold(1_000e6);

        uint256 maxStaleness = goldAdapter.maxStalenessSecs();
        vm.warp(block.timestamp + maxStaleness + 1);

        assertFalse(goldAdapter.isPriceSane(), "isPriceSane should be false after staleness window");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 11 — isPriceSane() == true when no position open (no swap ever)
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_isPriceSane_true_when_no_position() public view {
        // Fresh adapter: lastGoodPriceAt == 0 → isPriceSane returns true
        assertEq(goldAdapter.lastGoodPriceAt(), 0, "no swap yet");
        assertTrue(goldAdapter.isPriceSane(), "should be sane with no position");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 12 — maxDeposit(alice) == 0 when S2-H (goldSpreadAdapter) is stale
    // ─────────────────────────────────────────────────────────────────────────
    // Retain controllable value/sanity coverage independently of the corrected swap price units.
    function test_I2_maxDeposit_zero_when_S2H_stale() public {
        // Wire goldAllocAdapter as S2-H mock (goldSpreadAdapter) with a non-zero position
        goldAllocAdapter.setValue(10_000e6); // 10 000 USDC equivalent — above dustThreshold
        // Seed cost before slot registration: a value-only mock no longer represents funded exposure.
        vm.prank(owner);
        svault.setScreened(address(goldAllocAdapter), true);
        uint256 seededValue = goldAllocAdapter.value(); // read before pranking so the prank hits deployCapital
        vm.prank(owner);
        svault.setGoldSpreadAdapter(address(goldAllocAdapter)); // N-23: marked gold must be linked before funding
        vm.prank(manager);
        svault.deployCapitalAndExecute(address(goldAllocAdapter), seededValue, "");
        goldAllocAdapter.setSane(false);     // simulate stale S2-H

        assertFalse(goldAllocAdapter.isPriceSane(), "S2-H should be insane");
        assertEq(svault.maxDeposit(alice), 0, "maxDeposit should be 0 when S2-H stale");
        assertEq(svault.maxMint(alice), 0, "maxMint should be 0 when S2-H stale");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 13 — S6-H sane, S2-H stale → maxDeposit still 0
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_maxDeposit_normal_when_S6H_sane_and_S2H_stale() public {
        // goldAdapter (GoldExchangeAdapter) is sane by default (no position open → lastGoodPriceAt=0).
        // Use it as S6-H (goldAllocationAdapter) — it will report isPriceSane=true.
        // Use goldAllocAdapter as S2-H (goldSpreadAdapter) — set stale with a real position.
        goldAllocAdapter.setValue(10_000e6); // above dustThreshold
        // Seed cost before slot registration: a value-only mock no longer represents funded exposure.
        vm.prank(owner);
        svault.setScreened(address(goldAllocAdapter), true);
        uint256 seededValue = goldAllocAdapter.value(); // read before pranking so the prank hits deployCapital
        vm.prank(owner);
        svault.setGoldSpreadAdapter(address(goldAllocAdapter)); // N-23: marked gold must be linked before funding
        vm.prank(manager);
        svault.deployCapitalAndExecute(address(goldAllocAdapter), seededValue, "");
        goldAllocAdapter.setSane(false);     // S2-H stale

        vm.startPrank(owner);
        svault.setGoldAllocationAdapter(address(goldAdapter));  // S6-H sane (no position yet)
        vm.stopPrank();

        assertTrue(goldAdapter.isPriceSane(), "S6-H should be sane (no position open)");
        assertFalse(goldAllocAdapter.isPriceSane(), "S2-H should be stale");

        // S2-H is stale → maxDeposit must still be 0 (either adapter stale blocks deposits)
        assertEq(svault.maxDeposit(alice), 0, "stale S2-H blocks even when S6-H sane");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 14 — same as 13: both adapters needed to be sane for deposits
    // ─────────────────────────────────────────────────────────────────────────
    function test_I2_S6H_sane_S2H_stale_blocks_deposits() public {
        // Same wiring as test 13: S6-H = goldAdapter (sane), S2-H = goldAllocAdapter (stale).
        goldAllocAdapter.setValue(8_000e6); // above dustThreshold
        // Seed cost before slot registration: a value-only mock no longer represents funded exposure.
        vm.prank(owner);
        svault.setScreened(address(goldAllocAdapter), true);
        uint256 seededValue = goldAllocAdapter.value(); // read before pranking so the prank hits deployCapital
        vm.prank(owner);
        svault.setGoldSpreadAdapter(address(goldAllocAdapter)); // N-23: marked gold must be linked before funding
        vm.prank(manager);
        svault.deployCapitalAndExecute(address(goldAllocAdapter), seededValue, "");
        goldAllocAdapter.setSane(false);

        vm.startPrank(owner);
        svault.setGoldAllocationAdapter(address(goldAdapter));
        vm.stopPrank();

        assertFalse(goldAllocAdapter.isPriceSane(), "S2-H stale");
        assertTrue(goldAdapter.isPriceSane(), "S6-H still sane (no position open)");
        assertEq(svault.maxDeposit(alice), 0, "deposits blocked because S2-H stale");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 15 — fuzz: stale value <= fresh value
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_I2_stale_value_leq_fresh_value(
        uint128 paxgHeld,
        uint32  timeSeed
    ) public {
        // Corrected units make the stale-value comparison nonzero for every bounded input.
        uint256 elapsed = bound(uint256(timeSeed), 0, 10 days);
        // The raw 1:1 router gives paxgHeld == deployAmt and lastGoodPrice == 1e18.
        uint256 deployAmt = bound(uint256(paxgHeld), 1e6, 10_000e6);

        // Need svault to have enough USDC
        usdc.mint(alice, deployAmt);
        vm.startPrank(alice);
        usdc.approve(address(svault), deployAmt);
        svault.deposit(deployAmt, alice);
        vm.stopPrank();

        _deployAndSwapGold(deployAmt);

        // Capture fresh value
        uint256 freshValue = goldAdapter.currentValue();
        assertApproxEqAbs(freshValue, deployAmt, 1, "fresh value must equal funded input");

        // Warp by elapsed
        vm.warp(block.timestamp + elapsed);

        uint256 staleness = goldAdapter.maxStalenessSecs();
        uint256 valueAfterWarp = goldAdapter.currentValue();

        if (elapsed > staleness) {
            // Stale — should have haircut applied
            assertLe(valueAfterWarp, freshValue, "stale value must be <= fresh value");
        } else {
            // Still fresh — same value
            assertEq(valueAfterWarp, freshValue, "value unchanged while fresh");
        }
    }
}

contracts/test/TaskITest.I3.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title  TaskI — Item I3: TreasuryModule.calculateMusharakahSplitHWM
/// @notice Tests 16-20 from the Task-I specification.
///
/// calculateMusharakahSplitHWM(grossProfit, elapsedSeconds, principal, hwmDeficit)
///   → (hurdleAmount, vaultShare, depositorShare)
///
/// Formula:
///   hurdleAmount  = principal * hurdleRateBps * elapsed / (10_000 * 365 days)
///   afterRecovery = grossProfit > hwmDeficit ? grossProfit - hwmDeficit : 0
///   surplus       = afterRecovery > hurdleAmount ? afterRecovery - hurdleAmount : 0
///   vaultShare    = surplus * musharakahShareBps / 10_000
///   depositorShare = grossProfit - vaultShare
///   (sum: hurdleAmount + vaultShare + depositorShare == grossProfit + hurdleAmount — not additive)
///   INVARIANT: vaultShare + depositorShare == grossProfit  (hurdleAmount is informational)

import {TaskITestBase} from "./TaskITest.Base.t.sol";
import {TreasuryModule} from "../TreasuryModule.sol";

contract TaskITest_I3 is TaskITestBase {

    // musharakahShareBps = 1000 (10%), hurdleRateBps = 400 (4%)

    // ─────────────────────────────────────────────────────────────────────────
    // Test 16 — deficit=100e6, gross=150e6, elapsed=0, principal=0
    //   hurdleAmount  = 0 (elapsed=0 → 0)
    //   afterRecovery = 150e6 - 100e6 = 50e6
    //   surplus       = 50e6 - 0 = 50e6
    //   vaultShare    = 50e6 * 1000 / 10_000 = 5e6
    //   depositorShare = 150e6 - 5e6 = 145e6
    // ─────────────────────────────────────────────────────────────────────────
    function test_I3_split_on_excess_only_when_deficit_partial() public view {
        uint256 gross    = 150e6;
        uint256 deficit  = 100e6;
        uint256 elapsed  = 0;
        uint256 principal= 0;

        (uint256 hurdle, uint256 vaultShare, uint256 depositorShare) =
            treasury.calculateMusharakahSplitHWM(gross, elapsed, principal, deficit);

        assertEq(hurdle, 0, "hurdle should be 0 with elapsed=0");
        assertEq(vaultShare, 5e6, "vaultShare = 5e6 (10% of 50e6 excess)");
        assertEq(depositorShare, 145e6, "depositorShare = gross - vaultShare");
        // Invariant: vaultShare + depositorShare == gross
        assertEq(vaultShare + depositorShare, gross, "sum invariant");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 17 — deficit=100e6, gross=150e6 → after recovery, vaultShare > 0
    //   afterRecovery = 50e6 > 0, surplus = 50e6, vaultShare = 5e6 > 0
    //   Confirms HWM deficit is fully absorbed before the manager earns.
    // ─────────────────────────────────────────────────────────────────────────
    function test_I3_deficit_fully_cleared_after_recovery() public view {
        uint256 gross   = 150e6;
        uint256 deficit = 100e6;

        (, uint256 vaultShare, uint256 depositorShare) =
            treasury.calculateMusharakahSplitHWM(gross, 0, 0, deficit);

        // afterRecovery = 50e6 > 0 → manager earns something
        assertGt(vaultShare, 0, "vaultShare > 0: recovery absorbed, manager earns on excess");
        assertEq(vaultShare + depositorShare, gross, "sum invariant");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 18 — deficit=200e6 > gross=100e6 → afterRecovery=0, vaultShare=0
    //   depositorShare = gross = 100e6 (manager earns nothing)
    // ─────────────────────────────────────────────────────────────────────────
    function test_I3_vaultShare_zero_when_gross_below_deficit() public view {
        uint256 gross   = 100e6;
        uint256 deficit = 200e6;

        (, uint256 vaultShare, uint256 depositorShare) =
            treasury.calculateMusharakahSplitHWM(gross, 0, 0, deficit);

        assertEq(vaultShare, 0, "vaultShare = 0 when gross < deficit");
        assertEq(depositorShare, gross, "depositorShare = gross when vaultShare = 0");
        assertEq(vaultShare + depositorShare, gross, "sum invariant");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 19 — hurdle on excess, not full gross
    //   deficit=100e6, gross=300e6, principal=1_000_000e6, elapsed=365 days
    //   hurdleAmount = 1_000_000e6 * 400 * 365days / (10_000 * 365days) = 40_000e6
    //   afterRecovery = 300e6 - 100e6 = 200e6
    //   surplus = 200e6 > 40_000e6 ? NO → surplus = 0
    //   vaultShare = 0
    //   depositorShare = 300e6
    // ─────────────────────────────────────────────────────────────────────────
    function test_I3_hurdle_on_excess_not_full_gross() public view {
        uint256 gross     = 300e6;
        uint256 deficit   = 100e6;
        uint256 principal = 1_000_000e6;
        uint256 elapsed   = 365 days;

        (uint256 hurdle, uint256 vaultShare, uint256 depositorShare) =
            treasury.calculateMusharakahSplitHWM(gross, elapsed, principal, deficit);

        // hurdle = principal * 400 * elapsed / (10000 * 365 days)
        //        = 1_000_000e6 * 400 / 10000 = 40_000e6
        assertEq(hurdle, 40_000e6, "hurdleAmount = 40_000e6");
        // afterRecovery = 200e6 < hurdle (40_000e6) → surplus = 0
        assertEq(vaultShare, 0, "vaultShare = 0 when afterRecovery < hurdle");
        assertEq(depositorShare, gross, "depositorShare = gross");
        assertEq(vaultShare + depositorShare, gross, "sum invariant");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Test 20 — fuzz: vaultShare + depositorShare == gross always
    // ─────────────────────────────────────────────────────────────────────────
    function testFuzz_I3_invariant(
        uint96 gross,
        uint96 deficit,
        uint96 principal,
        uint32 elapsed
    ) public view {
        // Bound to avoid absurd values while covering interesting edge cases
        uint256 g = bound(uint256(gross),     0,       100_000_000e6);
        uint256 d = bound(uint256(deficit),   0,       200_000_000e6);
        uint256 p = bound(uint256(principal), 0,       1_000_000_000e6);
        uint256 e = bound(uint256(elapsed),   0,       730 days);

        if (g == 0) return; // calculateMusharakahSplitHWM is view so no revert for 0, but skip trivial

        (, uint256 vaultShare, uint256 depositorShare) =
            treasury.calculateMusharakahSplitHWM(g, e, p, d);

        // Core invariant: the split must cover exactly the gross profit
        assertEq(
            vaultShare + depositorShare,
            g,
            "vaultShare + depositorShare must equal grossProfit"
        );

        // vaultShare must not exceed gross
        assertLe(vaultShare, g, "vaultShare cannot exceed gross");
    }
}

contracts/test/TaskITest.I4I5.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title  TaskI — Items I4 & I5: Single-source board role + Registry constructor board param
/// @notice Tests 21-28 from the Task-I specification.

import {TaskITestBase} from "./TaskITest.Base.t.sol";
import {CharityModule}          from "../CharityModule.sol";
import {PurificationEscrow}     from "../PurificationEscrow.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";

contract TaskITest_I4I5 is TaskITestBase {

    // ─────────────────────────────────────────────────────────────────────────
    // I4 — Test 21: registry board member (not owner) can proposeCharityWalletChange
    // ─────────────────────────────────────────────────────────────────────────
    function test_I4_registry_board_can_propose_charityWallet() public {
        // boardMember is in registry (set at construction in setUp)
        assertTrue(registry.isBoard(boardMember), "boardMember should be in registry");

        address newWallet = makeAddr("newWallet");

        // boardMember (not owner) can propose
        vm.prank(boardMember);
        charity.proposeCharityWalletChange(newWallet);

        assertEq(charity.pendingCharityWallet(), newWallet, "pending wallet should be set");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I4 — Test 22: non-board, non-owner cannot proposeCharityWalletChange
    // ─────────────────────────────────────────────────────────────────────────
    function test_I4_non_board_non_owner_cannot_propose_charity() public {
        address newWallet = makeAddr("newWallet");

        vm.prank(nonBoard);
        vm.expectRevert(
            abi.encodeWithSelector(CharityModule.NotBoardOrOwner.selector, nonBoard)
        );
        charity.proposeCharityWalletChange(newWallet);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I4 — Test 23: board change propagates to CharityModule via registry
    // A new board member granted by registry can propose charity changes.
    // ─────────────────────────────────────────────────────────────────────────
    function test_I4_registry_board_change_propagates_to_charity() public {
        address newBoardMember = makeAddr("newBoardMember");

        // boardMember proposes to grant newBoardMember board role
        vm.prank(boardMember);
        registry.proposeBoardRoleChange(newBoardMember, true);

        // Warp past timelock
        vm.warp(block.timestamp + registry.TIMELOCK_PERIOD() + 1);

        // Execute the proposal
        vm.prank(boardMember);
        registry.executeBoardRoleChange(newBoardMember);

        assertTrue(registry.isBoard(newBoardMember), "newBoardMember should be board after grant");

        // Now newBoardMember can propose charity changes
        address newWallet = makeAddr("newWallet2");
        vm.prank(newBoardMember);
        charity.proposeCharityWalletChange(newWallet);

        assertEq(charity.pendingCharityWallet(), newWallet, "new board member can propose");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I4 — Test 24: registry board member can proposePurificationRate on Escrow
    // ─────────────────────────────────────────────────────────────────────────
    function test_I4_registry_board_can_propose_purification_rate() public {
        // boardMember is in registry → can call proposePurificationRate
        vm.prank(boardMember);
        escrow.proposePurificationRate(100); // 1%

        (uint256 newBps, uint256 executeAfter, bool exists) = escrow.pendingRateChange();
        assertTrue(exists, "pending rate change should exist");
        assertEq(newBps, 100, "newBps should be 100");
        assertGt(executeAfter, 0, "executeAfter should be set");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I4 — Test 25: owner alone cannot propose when registry is set and owner is not board
    // ─────────────────────────────────────────────────────────────────────────
    // setUp: registry = new ShariahAdapterRegistry(owner, boardMember)
    //        → owner does NOT have boardRole (I5 requirement)
    //        → escrow.boardRegistry = registry
    //   onlyBoard checks registry.isBoard(msg.sender) when boardRegistry != 0
    //   registry.isBoard(owner) == false  → revert NotBoardRole
    function test_I4_owner_alone_cannot_propose_when_registry_set_and_not_board() public {
        assertFalse(registry.isBoard(owner), "owner should NOT be board (I5)");

        vm.prank(owner);
        vm.expectRevert(
            abi.encodeWithSelector(PurificationEscrow.NotBoardRole.selector, owner)
        );
        escrow.proposePurificationRate(50);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I5 — Test 26: deployer (owner) does NOT get boardRole; initialBoardMember does
    // ─────────────────────────────────────────────────────────────────────────
    function test_I5_deployer_not_board_by_default() public {
        address deployer      = makeAddr("deployer");
        address boardMultisig = makeAddr("boardMultisig");

        // Deploy a fresh registry where deployer != boardMultisig
        ShariahAdapterRegistry reg = new ShariahAdapterRegistry(deployer, boardMultisig);

        assertFalse(reg.boardRole(deployer),      "deployer must NOT have boardRole");
        assertTrue( reg.boardRole(boardMultisig), "boardMultisig must have boardRole");
        assertEq(reg.owner(), deployer,           "deployer is still the owner");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I5 — Test 27: owner (not board) cannot call proposeBoardRoleChange
    // ─────────────────────────────────────────────────────────────────────────
    function test_I5_owner_cannot_propose_board_change_when_not_board() public {
        address deployer      = makeAddr("deployer2");
        address boardMultisig = makeAddr("boardMultisig2");
        address target        = makeAddr("target");

        ShariahAdapterRegistry reg = new ShariahAdapterRegistry(deployer, boardMultisig);

        // deployer is owner but NOT board → proposeBoardRoleChange must revert
        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(ShariahAdapterRegistry.NotBoardRole.selector, deployer)
        );
        reg.proposeBoardRoleChange(target, true);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // I5 — Test 28: boardMultisig (board member) can call proposeBoardRoleChange
    // ─────────────────────────────────────────────────────────────────────────
    function test_I5_board_multisig_can_propose() public {
        address deployer      = makeAddr("deployer3");
        address boardMultisig = makeAddr("boardMultisig3");
        address target        = makeAddr("target3");

        ShariahAdapterRegistry reg = new ShariahAdapterRegistry(deployer, boardMultisig);

        vm.prank(boardMultisig);
        reg.proposeBoardRoleChange(target, true);

        (bool grant, uint256 executeAfterP, bool exists) = reg.boardRoleProposals(target);
        assertTrue(exists, "proposal should exist");
        assertTrue(grant,  "proposal.grant should be true");
        assertGt(executeAfterP, 0, "executeAfter should be set");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Bonus: I4 — owner of CharityModule CAN propose when registry set if owner IS board
    // (Confirms the onlyBoardOrOwner modifier logic — owner-or-board, not owner-and-board)
    // ─────────────────────────────────────────────────────────────────────────
    function test_I4_owner_who_is_also_board_can_propose() public {
        // Grant owner board role via the existing boardMember
        vm.prank(boardMember);
        registry.proposeBoardRoleChange(owner, true);
        vm.warp(block.timestamp + registry.TIMELOCK_PERIOD() + 1);
        vm.prank(boardMember);
        registry.executeBoardRoleChange(owner);

        assertTrue(registry.isBoard(owner), "owner is now also board");

        // Now owner (who is board) can propose charity change
        address newWallet = makeAddr("ownerWallet");
        vm.prank(owner);
        charity.proposeCharityWalletChange(newWallet);
        assertEq(charity.pendingCharityWallet(), newWallet);
    }
}

contracts/test/TaskMTest.Base.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test, Vm} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {AutonomousVault, CctpMessageDecoder} from "../AutonomousVault.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";

/// @dev Records the seven native CCTP V2 depositForBurn arguments. Optionally burns (pulls) tokens.
contract MockTokenMessengerM {
    struct Call {
        uint256 amount;
        uint32 destinationDomain;
        bytes32 mintRecipient;
        address burnToken;
        bytes32 destinationCaller;
        uint256 maxFee;
        uint32 minFinalityThreshold;
    }

    Call public last;
    uint256 public callCount;
    bool public pull = true;
    bool public partialPull;
    /// @dev Allowance the vault had granted at the moment depositForBurn ran.
    uint256 public allowanceSeen;

    function configure(bool pull_, bool partial_) external {
        pull = pull_;
        partialPull = partial_;
    }

    function depositForBurn(
        uint256 amount,
        uint32 destinationDomain,
        bytes32 mintRecipient,
        address burnToken,
        bytes32 destinationCaller,
        uint256 maxFee,
        uint32 minFinalityThreshold
    ) external {
        last = Call(amount, destinationDomain, mintRecipient, burnToken, destinationCaller, maxFee, minFinalityThreshold);
        ++callCount;
        allowanceSeen = IERC20(burnToken).allowance(msg.sender, address(this));
        if (pull) {
            uint256 a = partialPull ? amount / 2 : amount;
            IERC20(burnToken).transferFrom(msg.sender, address(this), a);
        }
    }
}

/// @dev CCTP transmitter stub WITHOUT localDomain(): the vault must fall back to its stored domain.
contract MockTransmitterM {
    MockERC20 public immutable usdc;
    address public mintTo;
    uint256 public mintAmount;
    bool public ret = true;
    bool public doRevert;
    uint256 public calls;
    bytes32 public lastMsgHash;
    bytes32 public lastAttHash;

    constructor(MockERC20 usdc_) {
        usdc = usdc_;
    }

    function arm(address to, uint256 amount) external {
        mintTo = to;
        mintAmount = amount;
    }

    function setRet(bool r) external {
        ret = r;
    }

    function setRevert(bool r) external {
        doRevert = r;
    }

    function receiveMessage(bytes calldata m, bytes calldata a) external returns (bool) {
        ++calls;
        lastMsgHash = keccak256(m);
        lastAttHash = keccak256(a);
        if (doRevert) revert("transmitter: boom");
        if (mintAmount > 0) usdc.mint(mintTo, mintAmount);
        return ret;
    }
}

/// @dev Same, but reports a localDomain().
contract MockTransmitterDomainM is MockTransmitterM {
    uint32 public localDomain;

    constructor(MockERC20 usdc_, uint32 d) MockTransmitterM(usdc_) {
        localDomain = d;
    }

    function setDomain(uint32 d) external {
        localDomain = d;
    }
}

/// @dev Shared fixture + native MessageV2/BurnMessageV2 encoder. No test functions here.
abstract contract TaskMBase is Test {
    address internal owner = makeAddr("owner");
    address internal manager = makeAddr("manager");
    address internal alice = makeAddr("alice");
    address internal stranger = makeAddr("stranger");
    address internal remoteMessengerAddr = makeAddr("remoteMessenger");
    address internal remoteRecipientAddr = makeAddr("remoteRecipient");

    uint32 internal constant LOCAL_DOMAIN = 26;
    uint32 internal constant REMOTE_DOMAIN = 3;
    uint32 internal constant OTHER_DOMAIN = 7;
    uint256 internal constant DEPOSIT = 100_000e6;
    uint256 internal constant SENT = 10_000e6;
    bytes32 internal constant NONCE = bytes32(uint256(0xC0FFEE));

    MockERC20 internal usdc;
    MockTokenMessengerM internal messenger;
    MockTransmitterDomainM internal transmitter;
    AutonomousVault internal vault;

    struct Msg {
        uint32 headerVersion;
        uint32 sourceDomain;
        uint32 destinationDomain;
        bytes32 nonce;
        bytes32 sender;
        bytes32 recipient;
        bytes32 destinationCaller;
        uint32 minFinality;
        uint32 finalityExecuted;
        uint32 bodyVersion;
        bytes32 burnToken;
        bytes32 mintRecipient;
        uint256 amount;
        bytes32 messageSender;
        uint256 maxFee;
        uint256 feeExecuted;
        uint256 expirationBlock;
        bytes hookData;
    }

    function setUp() public virtual {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        messenger = new MockTokenMessengerM();
        transmitter = new MockTransmitterDomainM(usdc, LOCAL_DOMAIN);

        vm.startPrank(owner);
        vault = new AutonomousVault(IERC20(address(usdc)), owner, LOCAL_DOMAIN);
        vault.setManager(manager);
        vault.setTokenMessenger(address(messenger));
        vault.setMessageTransmitter(address(transmitter));
        vault.setRemoteTokenMessenger(REMOTE_DOMAIN, _b32(remoteMessengerAddr));
        vault.setMaxAllocationBps(9_000);
        vault.setMaxPendingCrossChainBps(5_000);
        vm.stopPrank();

        usdc.mint(alice, DEPOSIT);
        vm.startPrank(alice);
        usdc.approve(address(vault), DEPOSIT);
        vault.deposit(DEPOSIT, alice);
        vm.stopPrank();
    }

    function _b32(address a) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(a)));
    }

    function _deploy(uint32 domain, uint256 amount) internal returns (uint64 id) {
        vm.prank(manager);
        vault.deployCrossChain(domain, _b32(remoteRecipientAddr), amount);
        id = vault.crossChainPositionCounter();
    }

    /// @dev A fully valid message returning `amount` to the vault, from REMOTE_DOMAIN.
    function _msg(uint256 amount, uint256 fee, bytes32 nonce) internal view returns (Msg memory m) {
        m.headerVersion = 1;
        m.sourceDomain = REMOTE_DOMAIN;
        m.destinationDomain = LOCAL_DOMAIN;
        m.nonce = nonce;
        m.sender = _b32(remoteMessengerAddr);
        m.recipient = _b32(address(messenger));
        m.destinationCaller = _b32(address(vault)); // remote strategies MUST burn with destinationCaller = this vault
        m.minFinality = 2000;
        m.finalityExecuted = 2000;
        m.bodyVersion = 1;
        m.burnToken = _b32(address(usdc));
        m.mintRecipient = _b32(address(vault));
        m.amount = amount;
        m.messageSender = _b32(address(vault));
        m.maxFee = fee;
        m.feeExecuted = fee;
        m.expirationBlock = 0;
    }

    function _encode(Msg memory m) internal pure returns (bytes memory) {
        bytes memory header = abi.encodePacked(
            m.headerVersion, m.sourceDomain, m.destinationDomain, m.nonce, m.sender,
            m.recipient, m.destinationCaller, m.minFinality, m.finalityExecuted
        );
        bytes memory body = abi.encodePacked(
            m.bodyVersion, m.burnToken, m.mintRecipient, m.amount, m.messageSender,
            m.maxFee, m.feeExecuted, m.expirationBlock
        );
        return abi.encodePacked(header, body, m.hookData);
    }

    /// @dev Arms the transmitter to mint `minted` to the vault and settles as the manager.
    function _settle(uint64 id, Msg memory m, uint256 minted) internal {
        transmitter.arm(address(vault), minted);
        _settleArmed(id, m);
    }

    /// @dev Settles without touching the transmitter, so vm.expectEmit can precede it directly.
    function _settleArmed(uint64 id, Msg memory m) internal {
        bytes memory message = _encode(m);
        vm.prank(manager);
        vault.settleCrossChainWithMessage(id, message, hex"a77e57");
    }

    /// @dev Count logs emitted by `emitter` whose topic0 matches `sig`.
    function _countLogs(Vm.Log[] memory logs, address emitter, bytes32 sig) internal pure returns (uint256 n) {
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == emitter && logs[i].topics.length > 0 && logs[i].topics[0] == sig) n++;
        }
    }
}

contracts/test/TaskMTest.N01.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {AutonomousVault} from "../AutonomousVault.sol";
import {ShariahVault} from "../ShariahVault.sol";
import {ShariahVaultV2} from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TreasuryModule} from "../TreasuryModule.sol";
import {CharityModule} from "../CharityModule.sol";
import {PurificationEscrow} from "../PurificationEscrow.sol";
import {MockERC20} from "../test-helpers/MockERC20.sol";
import {MockRegistrySRF} from "./SecurityReviewFixesTest.t.sol";
import {PrincipalAdapterM} from "./TaskMTest.N02.t.sol";

/// @dev N-01: claimMusharakahProfit is bounded by realizedProfit(); run against V1 and V2 vaults.
abstract contract TaskMN01Base is Test {
    address internal owner = makeAddr("owner");
    address internal manager = makeAddr("manager");
    address internal alice = makeAddr("alice");
    address internal stranger = makeAddr("stranger");
    address internal charityWallet = makeAddr("charityWallet");
    uint32 internal constant DOM = 26;

    MockERC20 internal usdc;
    MockRegistrySRF internal reg;
    ShariahAdapterRegistry internal registry;
    TreasuryModule internal treasury;
    ShariahVault internal vault;
    CharityModule internal charity;
    PurificationEscrow internal escrow;

    function _newVault() internal virtual returns (ShariahVault);

    function setUp() public virtual {
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);
        reg = new MockRegistrySRF(owner);
        registry = new ShariahAdapterRegistry(owner, owner);

        // treasury(n) -> vault(n+1) -> charity(n+2) -> escrow(n+3); treasury is owned by the vault.
        uint256 n = vm.getNonce(address(this));
        address escrowAddr = vm.computeCreateAddress(address(this), n + 3);
        address vaultAddr = vm.computeCreateAddress(address(this), n + 1);
        treasury = new TreasuryModule("Shariah", escrowAddr, address(usdc), 50, 1000, 400, vaultAddr);
        vault = _newVault();
        charity = new CharityModule(charityWallet, address(usdc), escrowAddr, owner, address(reg));
        escrow = new PurificationEscrow(
            address(vault), address(usdc), address(charity), address(treasury), owner, address(reg)
        );
        assertEq(address(vault), vaultAddr);
        assertEq(address(escrow), escrowAddr);

        vm.startPrank(owner);
        vault.setPurificationEscrow(address(escrow));
        vault.setManager(manager);
        vm.stopPrank();
        // N-20: isolate realized-profit/streaming tests from time-based fees; fee coverage has its own fixture.
        vm.prank(address(vault));
        treasury.setAdminFeeBps(0);

        usdc.mint(alice, 10_000e6);
        vm.prank(alice);
        usdc.approve(address(vault), type(uint256).max);
    }

    function _deposit(uint256 amount) internal {
        vm.prank(alice);
        vault.deposit(amount, alice);
    }

    function _claim(uint256 gross) internal {
        vm.prank(owner);
        vault.claimMusharakahProfit(gross);
    }

    function _expectExceeds(uint256 requested, uint256 available) internal {
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, requested, available));
        vault.claimMusharakahProfit(requested);
    }

    function _appreciatingGold() internal returns (PrincipalAdapterM adapter) {
        _deposit(1_000e6);
        adapter = new PrincipalAdapterM(vault);
        vm.startPrank(owner);
        vault.setGoldSpreadAdapter(address(adapter));
        vault.setScreened(address(adapter), true);
        registry.proposeScreening(address(adapter), keccak256("gold"), block.timestamp + 365 days);
        vm.stopPrank();
        skip(30 days);
        vm.prank(owner);
        registry.executeScreening(address(adapter));
        vm.startPrank(address(vault));
        treasury.setAdminFeeBps(0);
        treasury.setFeeSource(address(vault));
        treasury.setProfitRecorder(address(escrow));
        vm.stopPrank();
        vm.prank(manager);
        vault.deployCapitalAndExecute(address(adapter), 200e6, "");
        adapter.setValue(300e6, true);
        usdc.mint(address(adapter), 100e6);
        adapter.setRecall(300e6, 300e6, 0);
    }

    function test_unrealizedGoldGain_isNeitherClaimableNorLockable() public {
        _appreciatingGold();
        assertEq(vault.goldUnrealizedGain(), 100e6);
        assertEq(vault.totalAssets(), 1_100e6);
        assertEq(vault.realizedProfit(), 0);
        _expectExceeds(1, 0);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 1, 0));
        vault.lockProfit(1);
    }

    function test_goldRecall_realizesGainExactlyOnce_afterEarlierClaim() public {
        PrincipalAdapterM adapter = _appreciatingGold();
        usdc.mint(address(vault), 40e6);
        _claim(40e6);
        uint256 gain = vault.goldUnrealizedGain();
        assertEq(vault.hurdlePrincipal(), vault.totalAssets() - gain);
        assertEq(vault.profitBase(), vault.totalAssets() - gain + vault.lockedProfit());
        // Processed depositor profit raises the high while locked; paper gold still does not.
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 0);
        uint256 nav = vault.totalAssets();
        vm.prank(manager);
        vault.recallCapital(address(adapter), 200e6);
        assertEq(vault.totalAssets(), nav, "recall changes realization, not marked NAV");
        assertEq(vault.goldUnrealizedGain(), 0);
        assertEq(vault.realizedProfit(), gain, "only the recalled appreciation becomes available");
        _claim(gain);
        _expectExceeds(1, 0);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 0, "distributed gain cannot be claimed twice");
        _expectExceeds(1, 0);
    }

    function test_claimHWM_deficitUsesRealizedAssetUnits_notPaperGoldGain() public {
        _appreciatingGold();
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        skip(vault.profitUnlockPeriod());
        uint256 high = vault.highWaterMarkPerShare();
        usdc.burn(address(vault), 200e6);
        _deposit(1_000e6);
        usdc.mint(address(vault), 240e6);
        assertEq(vault.goldUnrealizedGain(), 100e6);
        uint256 deficit = vault.hwmDeficit();
        assertGt(deficit, 40e6);
        uint256 feesBefore = treasury.pendingFees();
        _claim(40e6);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertEq(treasury.pendingFees(), feesBefore, "paper gold cannot erase recovery");
        // Locked processed recovery counts immediately, not only when it unlocks.
        uint256 remaining = vault.hwmDeficit();
        assertLt(remaining, deficit);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.hwmDeficit(), remaining);
        assertEq(usdc.allowance(address(vault), address(escrow)), 0);
        assertEq(usdc.balanceOf(address(escrow)), 0);
    }

    function test_claimHWM_excessPaysOnlyAfterDeficitAndHurdle() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        skip(vault.profitUnlockPeriod());
        usdc.burn(address(vault), 200e6);
        _deposit(1_000e6);
        skip(365 days);
        usdc.mint(address(vault), 600e6);
        // The waterfall now receives the CURRENT capped processed deficit, not NAV minus gross.
        uint256 deficit = vault.hwmDeficit();
        uint256 elapsed = block.timestamp - vault.hurdleStartTime();
        (, uint256 expected,) = treasury.calculateMusharakahSplitHWM(
            400e6 - 400e6 * charity.charityBps() / 10_000, elapsed, vault.hurdlePrincipal(), deficit
        );
        assertGt(deficit, 0);
        assertGt(expected, 0);
        uint256 feesBefore = treasury.pendingFees();
        _claim(400e6);
        assertEq(vault.hwmDeficit(), 0, "processed recovery includes the locked depositor share");
        assertEq(treasury.pendingFees() - feesBefore, expected);
    }

    function test_lockProfit_zeroCannotRestartUnlockSchedule() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        vm.prank(manager);
        vault.lockProfit(100e6);
        uint256 end = vault.unlockedAt();
        skip(vault.profitUnlockPeriod() / 2);
        uint256 nav = vault.totalAssets();
        vm.prank(manager);
        vm.expectRevert(ShariahVault.ZeroAmount.selector);
        vault.lockProfit(0);
        assertEq(vault.unlockedAt(), end);
        assertEq(vault.lockedProfit(), 100e6);
        assertEq(vault.totalAssets(), nav);
        vm.warp(end);
        assertEq(vault.totalAssets(), 1_100e6);
    }

    // N-20/N-21 regressions share the V1/V2 fixture so inherited behavior cannot drift.
    function _enableWakala() internal {
        vm.startPrank(address(vault));
        treasury.setFeeSource(address(vault));
        treasury.setProfitRecorder(address(escrow));
        treasury.setAdminFeeBps(50);
        vm.stopPrank();
    }

    function test_N20_emptyYear_firstDepositHasNoHistoricalFee() public {
        _enableWakala();
        skip(365 days);
        _deposit(1_000e6);
        assertEq(treasury.pendingFees(), 0);
        assertEq(vault.pendingWakalaFee(), 0);
        assertEq(vault.lastFeeAccrualTime(), block.timestamp);
        assertEq(vault.totalAssets(), 1_000e6);
    }

    function test_N20_yearLaterRedeem_previewEqualsActualNetOfFee() public {
        _enableWakala();
        _deposit(1_000e6);
        skip(365 days);
        assertEq(vault.pendingWakalaFee(), 5e6);
        uint256 shares = vault.balanceOf(alice);
        uint256 quoted = vault.previewRedeem(shares);
        uint256 before = usdc.balanceOf(alice);
        vm.prank(alice);
        uint256 received = vault.redeem(shares, alice, alice);
        assertEq(received, quoted);
        assertEq(usdc.balanceOf(alice) - before, quoted);
        assertApproxEqAbs(received, 995e6, 1);
        assertEq(treasury.pendingFees(), 5e6);
        assertEq(vault.pendingWakalaFee(), 0);
    }

    function test_N20_laterDepositor_onlyPaysAfterEntry() public {
        _enableWakala();
        _deposit(1_000e6);
        skip(365 days);
        uint256 quoted = vault.previewDeposit(1_000e6);
        usdc.mint(stranger, 1_000e6);
        vm.startPrank(stranger);
        usdc.approve(address(vault), 1_000e6);
        assertEq(vault.deposit(1_000e6, stranger), quoted);
        vm.stopPrank();
        assertApproxEqAbs(vault.previewRedeem(vault.balanceOf(stranger)), 1_000e6, 1);
        assertEq(treasury.pendingFees(), 5e6, "only existing AUM pays the old year");
        assertEq(vault.totalAssets(), 1_995e6);
        skip(365 days);
        assertEq(vault.pendingWakalaFee(), 9_975_000, "new AUM pays only its next year");
    }

    function test_N20_viewAndBooking_areNavNeutral() public {
        _enableWakala();
        _deposit(1_000e6);
        skip(365 days);
        uint256 nav = vault.totalAssets();
        uint256 fee = vault.pendingWakalaFee();
        uint256 quoted = vault.previewDeposit(1e6);
        _deposit(1e6);
        assertEq(treasury.pendingFees(), fee);
        assertEq(vault.pendingWakalaFee(), 0);
        assertEq(vault.totalAssets(), nav + 1e6);
        // Rebuild the same quote at the booked NAV, with pre-deposit virtual supply.
        assertEq(quoted, Math.mulDiv(1e6, vault.totalSupply() - quoted + 1e6, nav + 1));
    }

    function test_N20_badFeeSource_depositAndRedeemEmitSkip_preserveTimestamp() public {
        _enableWakala();
        _deposit(1_000e6);
        uint256 checkpoint = vault.lastFeeAccrualTime();
        vm.prank(address(vault));
        treasury.setFeeSource(stranger);
        skip(365 days);
        uint256 fee = vault.pendingWakalaFee();
        vm.expectEmit(false, false, false, true, address(vault));
        emit ShariahVault.WakalaAccrualSkipped(fee);
        _deposit(100e6);
        assertEq(vault.lastFeeAccrualTime(), checkpoint);
        uint256 shares = vault.balanceOf(alice) / 2;
        uint256 quoted = vault.previewRedeem(shares);
        fee = vault.pendingWakalaFee();
        vm.expectEmit(false, false, false, true, address(vault));
        emit ShariahVault.WakalaAccrualSkipped(fee);
        vm.prank(alice);
        assertEq(vault.redeem(shares, alice, alice), quoted);
        assertEq(vault.lastFeeAccrualTime(), checkpoint);
        assertEq(treasury.pendingFees(), 0);
    }

    function test_N20_roundedZero_keepsElapsedTime() public {
        _enableWakala();
        _deposit(1);
        uint256 checkpoint = vault.lastFeeAccrualTime();
        skip(1);
        assertEq(vault.pendingWakalaFee(), 0);
        _deposit(1);
        // A fee that rounds to zero must keep its elapsed time, so zero-value calls cannot erase accrual.
        assertEq(vault.lastFeeAccrualTime(), checkpoint);
    }

    function test_N20_frequentZeroCalls_doNotEraseAccrual() public {
        _enableWakala();
        _deposit(1e6); // small AUM so each 6 s slice rounds to zero fee
        uint256 start = block.timestamp;
        for (uint256 i; i < 50; ++i) {
            skip(6);
            vm.prank(alice);
            vault.deposit(0, alice);
        }
        assertEq(vault.lastFeeAccrualTime(), start, "interrupted interval keeps its start");
        skip(365 days);
        assertGt(vault.pendingWakalaFee(), 0);
    }

    function test_N20_claim_booksFeeBeforeProfitBound() public {
        _enableWakala();
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        skip(365 days);
        uint256 fee = vault.pendingWakalaFee();
        uint256 available = vault.realizedProfit();
        _expectExceeds(available + 1, available);
        uint256 before = treasury.pendingFees();
        _claim(available);
        assertGe(treasury.pendingFees() - before, fee);
        assertEq(vault.pendingWakalaFee(), 0);
        assertEq(vault.lastFeeAccrualTime(), block.timestamp);
    }

    function test_N20_claim_badFeeSourceStillDistributes() public {
        _enableWakala();
        _deposit(1_000e6);
        vm.prank(address(vault));
        treasury.setFeeSource(stranger);
        usdc.mint(address(vault), 100e6);
        skip(365 days);
        uint256 checkpoint = vault.lastFeeAccrualTime();
        vm.expectEmit(false, false, false, true, address(vault));
        emit ShariahVault.WakalaAccrualSkipped(vault.pendingWakalaFee());
        _claim(10e6);
        assertEq(vault.lastFeeAccrualTime(), checkpoint);
        assertGt(vault.profitBase(), 1_000e6, "depositor share still checkpointed");
        assertEq(vault.lockedProfit(), 0, "claim does not lock the depositor share");
    }

    function test_N20_strictDeployment_badFeeSourceRollsBack() public {
        PrincipalAdapterM adapter = _appreciatingGold();
        _enableWakala();
        vm.prank(address(vault));
        treasury.setFeeSource(stranger);
        skip(1 days);
        uint256 deployed = vault.totalDeployed();
        uint256 balance = usdc.balanceOf(address(vault));
        vm.prank(manager);
        vm.expectRevert(TreasuryModule.NotFeeSource.selector);
        vault.deployCapitalAndExecute(address(adapter), 1e6, "");
        assertEq(vault.totalDeployed(), deployed);
        assertEq(usdc.balanceOf(address(vault)), balance);
    }

    function test_N21_withdrawalAlone_createsNoDeficit() public {
        _deposit(1_000e6);
        uint256 high = vault.highWaterMarkPerShare();
        vm.prank(alice);
        vault.withdraw(400e6, alice, alice);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertEq(vault.hwmDeficit(), 0);
        assertEq(vault.highWaterMark(), 600e6);
    }

    function test_N21_depositDoesNotEraseGenuineDeficit() public {
        _deposit(1_000e6);
        usdc.burn(address(vault), 200e6);
        uint256 high = vault.highWaterMarkPerShare();
        uint256 deficit = vault.hwmDeficit();
        assertGt(deficit, 0);
        _deposit(1_000e6);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertGe(vault.hwmDeficit(), deficit, "new supply cannot erase the old price gap");
    }

    function test_N21_lossAndPartialRecovery_managerZeroUntilOldHigh() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 300e6);
        // N-21: establish an earned peak with a full claim, not unprocessed yield.
        _claim(300e6);
        skip(vault.profitUnlockPeriod());
        uint256 high = vault.highWaterMarkPerShare();
        usdc.burn(address(vault), 200e6);
        _deposit(1_000e6);
        usdc.mint(address(vault), 250e6);
        uint256 fees = treasury.pendingFees();
        _claim(50e6);
        assertEq(treasury.pendingFees(), fees);
        assertEq(vault.highWaterMarkPerShare(), high);
        skip(vault.profitUnlockPeriod());
        assertGt(vault.hwmDeficit(), 0);
    }

    function test_N21_review1100_loss200_recovery210_noShareBelowHigh() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        // N-21: the earned high includes the FULL claim's locked depositor profit.
        _claim(100e6);
        uint256 high = vault.highWaterMarkPerShare();
        skip(vault.profitUnlockPeriod());
        usdc.burn(address(vault), 200e6);
        _deposit(1_000e6);
        // Recovery of 210 gross less 20 costs is still below the old processed high.
        usdc.mint(address(vault), 210e6);
        usdc.burn(address(vault), 20e6);
        assertGt(vault.hwmDeficit(), 0);
        _expectExceeds(1, 0);
        // Even a later claimable 50 remains recovery after the intervening deposit.
        usdc.mint(address(vault), 60e6);
        uint256 fees = treasury.pendingFees();
        _claim(50e6);
        assertEq(treasury.pendingFees(), fees);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertGt(vault.hwmDeficit(), 0);
    }

    function test_N21_paperGold_neverAdvancesPerShareHigh() public {
        PrincipalAdapterM adapter = _appreciatingGold();
        uint256 high = vault.highWaterMarkPerShare();
        uint256 deficit = vault.hwmDeficit();
        adapter.setValue(400e6, true);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertEq(vault.hwmDeficit(), deficit);
        usdc.mint(address(vault), 10e6);
        _claim(10e6);
        // Only processed cash profit moves the high; the larger paper gain stays excluded.
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
        assertGt(vault.highWaterMarkPerShare(), high);
        uint256 earnedHigh = vault.highWaterMarkPerShare();
        adapter.setValue(500e6, true);
        assertEq(vault.highWaterMarkPerShare(), earnedHigh);
        assertEq(vault.hwmDeficit(), 0);
    }

    function _currentLocked() internal view returns (uint256) {
        uint256 period = vault.profitUnlockPeriod();
        uint256 end = vault.unlockedAt();
        if (period == 0 || block.timestamp >= end || end < period || end - period > block.timestamp) return 0;
        return Math.mulDiv(vault.lockedProfit(), end - block.timestamp, period);
    }

    function _processedPrice() internal view returns (uint256) {
        uint256 nav = vault.totalAssets();
        uint256 gain = vault.goldUnrealizedGain();
        nav = nav > gain ? nav - gain : 0;
        nav = Math.min(nav + _currentLocked(), vault.profitBase());
        return Math.mulDiv(nav + 1, 1e18, vault.totalSupply() + 1e6);
    }

    function _zeroHurdle() internal {
        vm.prank(address(vault));
        treasury.setMusharakahParams(1000, 0);
    }

    function _assertSplitClaimMatchesFull(uint256 first) internal {
        _zeroHurdle(); // Isolate HWM/rounding from the time-dependent hurdle between claims.
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        uint256 snapshot = vm.snapshot();
        _claim(100e6);
        uint256 fullManager = treasury.pendingFees();
        uint256 fullHigh = vault.highWaterMarkPerShare();
        uint256 fullBase = vault.profitBase();
        assertTrue(vm.revertTo(snapshot));
        _claim(first);
        assertEq(vault.hwmDeficit(), 0, "partial claim cannot invent recovery");
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
        skip(vault.profitUnlockPeriod());
        assertEq(vault.hwmDeficit(), 0, "unlock cannot invent recovery");
        assertEq(vault.realizedProfit(), 100e6 - first);
        uint256 firstManager = treasury.pendingFees();
        _claim(100e6 - first);
        assertGt(treasury.pendingFees(), firstManager, "remaining yield still pays manager");
        assertApproxEqAbs(treasury.pendingFees(), fullManager, 1);
        assertApproxEqAbs(vault.profitBase(), fullBase, 2);
        assertApproxEqAbs(vault.highWaterMarkPerShare(), fullHigh, 2000);
        assertEq(vault.hwmDeficit(), 0);
    }

    function test_N21_fullVsOneThenNinetyNine_sameManagerShare() public {
        _assertSplitClaimMatchesFull(1e6);
    }

    function testFuzz_N21_splitClaim_sameManagerShare(uint256 first) public {
        first = bound(first, 1e6, 99e6);
        _assertSplitClaimMatchesFull(first);
    }

    function test_N21_partialClaim_noDeficitThroughoutUnlock() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(1e6);
        uint256 high = vault.highWaterMarkPerShare();
        assertEq(high, _processedPrice());
        assertApproxEqAbs(vault.highWaterMark(), vault.profitBase(), 2);
        assertEq(vault.hwmDeficit(), 0);
        skip(vault.profitUnlockPeriod() / 2);
        assertEq(vault.hwmDeficit(), 0);
        assertEq(_processedPrice(), high);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.hwmDeficit(), 0);
        assertEq(_processedPrice(), high);
    }

    function test_N21_fullClaim_recordsEarnedPeak() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        assertEq(vault.lockedProfit(), 0, "depositor share is not locked");
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
        assertApproxEqAbs(vault.highWaterMark(), vault.totalAssets(), 2);
        uint256 high = vault.highWaterMarkPerShare();
        skip(vault.profitUnlockPeriod());
        assertEq(_processedPrice(), high);
        assertEq(vault.hwmDeficit(), 0);
    }

    function test_N21_fullClaim_lossCashFlows_recoveryThenExcess() public {
        _zeroHurdle();
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        uint256 high = vault.highWaterMarkPerShare();
        assertGt(high, 1e12);
        skip(vault.profitUnlockPeriod());
        usdc.burn(address(vault), 200e6);
        _deposit(1_000e6);
        assertEq(vault.highWaterMarkPerShare(), high);
        vm.prank(alice);
        vault.withdraw(100e6, alice, alice);
        assertEq(vault.highWaterMarkPerShare(), high);
        assertGt(vault.hwmDeficit(), 0);
        // Restore NAV above the checkpoint so a recovery-only claim is available.
        uint256 needed = vault.profitBase() - vault.totalAssets();
        usdc.mint(address(vault), needed + 50e6);
        uint256 deficit = vault.hwmDeficit();
        assertGt(deficit, 50e6);
        uint256 fees = treasury.pendingFees();
        _claim(50e6);
        assertEq(treasury.pendingFees(), fees);
        assertEq(vault.highWaterMarkPerShare(), high);
        uint256 remaining = vault.hwmDeficit();
        assertGt(remaining, 0);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.hwmDeficit(), remaining);
        usdc.mint(address(vault), 500e6);
        uint256 gross = vault.realizedProfit();
        uint256 net = gross - gross * charity.charityBps() / 10_000;
        (, uint256 expected,) = treasury.calculateMusharakahSplitHWM(net, 0, 0, remaining);
        assertGt(expected, 0);
        _claim(gross);
        assertEq(treasury.pendingFees() - fees, expected);
        assertGt(_processedPrice(), high);
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
        assertEq(vault.hwmDeficit(), 0);
    }

    // ───────────── profitBase ─────────────

    function test_profitBase_startsZero_andTracksDepositsAndMints() public {
        assertEq(vault.profitBase(), 0);
        assertEq(vault.realizedProfit(), 0);
        _deposit(1_000e6);
        assertEq(vault.profitBase(), 1_000e6);
        uint256 shares = vault.previewDeposit(500e6);
        vm.prank(alice);
        uint256 assetsIn = vault.mint(shares, alice);
        assertEq(vault.profitBase(), 1_000e6 + assetsIn);
        assertEq(vault.realizedProfit(), 0, "deposits are not profit");
    }

    function test_principalOnlyVault_hasNoClaimableProfit() public {
        _deposit(1_000e6);
        assertEq(vault.realizedProfit(), 0);
        _expectExceeds(1, 0);
        _expectExceeds(1_000e6, 0);
        // Even the manager (non-owner) cannot claim principal.
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 1, 0));
        vault.claimMusharakahProfit(1);
        assertEq(usdc.balanceOf(address(vault)), 1_000e6);
    }

    function test_realizedProfit_equalsDonatedYield() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        assertEq(vault.realizedProfit(), 100e6);
        assertEq(vault.profitBase(), 1_000e6, "base unaffected by yield");
    }

    // ───────────── bound ─────────────

    function test_overLimit_reverts_exactLimit_succeeds() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _expectExceeds(100e6 + 1, 100e6);

        vm.expectEmit(false, false, false, false, address(vault));
        emit ShariahVault.MusharakahProfitClaimed(0, 0, 0, 0, 0);
        _claim(100e6);
        assertEq(usdc.allowance(address(vault), address(escrow)), 0, "escrow allowance cleared");
    }

    function test_partialClaim_leavesRemainderClaimable() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        uint256 baseBefore = vault.profitBase();
        _claim(40e6);
        // N-22: preserve unprocessed yield while checkpointing only the distributed depositor share.
        uint256 firstShare = vault.profitBase() - baseBefore;
        assertGt(firstShare, 0, "waterfall returned a depositor share");
        assertEq(vault.lockedProfit(), 0);
        assertEq(vault.hurdlePrincipal(), vault.totalAssets());
        // The processed price includes the depositor share and excludes the unprocessed remainder.
        assertApproxEqAbs(vault.highWaterMark(), vault.profitBase(), 2);
        // With no lock the unprocessed remainder is claimable immediately and exactly.
        assertEq(vault.realizedProfit(), 60e6);
        _expectExceeds(60e6 + 1, 60e6);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 60e6, "time does not change the remainder");
        _claim(60e6);
        uint256 secondShare = vault.profitBase() - baseBefore - firstShare;
        assertGt(secondShare, 0);
        assertEq(vault.realizedProfit(), 0);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 0, "neither depositor share can be claimed twice");
        _expectExceeds(1, 0);
    }

    function testFuzz_partialClaims_preserveRemainderAndExcludeDistributedShare(uint256 first) public {
        first = bound(first, 1, 100e6 - 1);
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(first);
        uint256 firstShare = vault.profitBase() - 1_000e6;
        assertEq(vault.lockedProfit(), 0);
        uint256 remainder = 100e6 - first;
        assertEq(vault.realizedProfit(), remainder, "remainder claimable immediately");
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), remainder);
        _expectExceeds(remainder + 1, remainder);
        _claim(remainder);
        assertGe(vault.profitBase(), 1_000e6 + firstShare);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 0);
        _expectExceeds(1, 0);
    }

    function test_partialClaims_zeroUnlockPeriod_remainderImmediatelyAvailable() public {
        vm.prank(owner);
        vault.setProfitUnlockPeriod(0);
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(40e6);
        assertEq(vault.realizedProfit(), 60e6);
        _expectExceeds(60e6 + 1, 60e6);
        _claim(60e6);
        assertEq(vault.realizedProfit(), 0);
        _expectExceeds(1, 0);
    }

    function test_postClaim_checkpointIsNetNav_andSecondClaimReverts() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        assertEq(
            vault.profitBase(), vault.totalAssets() + vault.lockedProfit(),
            "checkpoint = post-claim net NAV + locked depositor share"
        );
        assertEq(vault.realizedProfit(), 0);
        assertEq(vault.hurdlePrincipal(), vault.totalAssets());
        _expectExceeds(1, 0);
    }

    function test_claimZero_revertsAtEscrow_notBound() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 10e6);
        vm.prank(owner);
        vm.expectRevert(PurificationEscrow.ZeroAmount.selector);
        vault.claimMusharakahProfit(0);
    }

    function test_escrowUnset_revertsBeforeBoundCheck() public {
        _deposit(1_000e6);
        vm.startPrank(owner);
        vault.setPurificationEscrow(address(0));
        vm.expectRevert(ShariahVault.PurificationEscrowNotSet.selector);
        vault.claimMusharakahProfit(1);
        vm.stopPrank();
    }

    function test_claim_onlyManagerOrOwner() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 10e6);
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.claimMusharakahProfit(1);
        vm.prank(manager);
        vault.claimMusharakahProfit(10e6);
    }

    // ───────────── pro-rata reduction on withdraw / redeem ─────────────

    function test_withdraw_reducesProfitBaseProRata() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6); // NAV 1_100
        uint256 base = vault.profitBase();
        uint256 nav = vault.totalAssets();
        vm.prank(alice);
        vault.withdraw(110e6, alice, alice); // 10% of NAV
        assertEq(vault.profitBase(), base - Math.mulDiv(base, 110e6, nav));
        assertEq(vault.profitBase(), 900e6);
        assertEq(vault.realizedProfit(), 90e6, "profit shrinks pro rata with the exit");
        _expectExceeds(90e6 + 1, 90e6);
    }

    function test_redeem_partialThenAll_baseReachesZero() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        uint256 half = vault.balanceOf(alice) / 2;
        uint256 base = vault.profitBase();
        uint256 nav = vault.totalAssets();
        vm.prank(alice);
        uint256 assets = vault.redeem(half, alice, alice);
        // checkpoint shrinks by shares burned / supply; allow 1-wei virtual-share rounding
        assertApproxEqAbs(vault.profitBase(), base - Math.mulDiv(base, assets, nav), 2);
        uint256 rest = vault.balanceOf(alice);
        vm.prank(alice);
        vault.redeem(rest, alice, alice);
        // Virtual-share rounding can leave a 1-wei residue in both base and NAV.
        assertLe(vault.profitBase(), 1);
        assertApproxEqAbs(vault.realizedProfit(), vault.totalAssets(), 1);
        assertLe(vault.totalAssets(), 2);
    }

    function testFuzz_withdraw_proRata_neverCreatesProfit(uint256 dep, uint256 yield_, uint256 w) public {
        dep = bound(dep, 1e6, 10_000e6);
        yield_ = bound(yield_, 0, 5_000e6);
        _deposit(dep);
        usdc.mint(address(vault), yield_);
        uint256 profitBefore = vault.realizedProfit();
        w = bound(w, 1, vault.maxWithdraw(alice));
        vm.prank(alice);
        vault.withdraw(w, alice, alice);
        assertLe(vault.realizedProfit(), profitBefore + 1, "exits cannot inflate realized profit");
        assertLe(vault.profitBase(), dep);
    }

    // ───────────── fees and locked profit reduce the bound ─────────────

    function test_pendingFees_reduceRealizedProfit() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        vm.prank(address(escrow));
        treasury.accrue(30e6);
        assertEq(vault.realizedProfit(), 70e6);
        _expectExceeds(70e6 + 1, 70e6);
    }

    function test_lockProfit_rejectsPrincipalAndOverlock() public {
        _deposit(1_000e6);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 1, 0));
        vault.lockProfit(1);
        usdc.mint(address(vault), 100e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.ProfitExceedsRealized.selector, 100e6 + 1, 100e6));
        vault.lockProfit(100e6 + 1);
        vm.prank(manager);
        vault.lockProfit(60e6);
        assertEq(vault.realizedProfit(), 40e6);
        vm.prank(owner);
        vault.lockProfit(40e6);
        assertEq(vault.lockedProfit(), 100e6);
        assertEq(vault.realizedProfit(), 0);
    }

    function test_lockProfit_onlyManagerOrOwner() public {
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.lockProfit(0);
    }

    function test_lockedProfit_excludedUntilItUnlocks() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        vm.prank(owner);
        vault.lockProfit(100e6);
        assertEq(vault.realizedProfit(), 0);
        _expectExceeds(1, 0);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 100e6);
    }

    // ───────────── N-11 / N-24 regressions: no claim-time lock ─────────────

    function test_N11_entrantAfterClaim_getsNoUnlockDiscount() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        uint256 sharesNow = vault.previewDeposit(100e6);
        uint256 redeemNow = vault.previewRedeem(sharesNow);
        skip(vault.profitUnlockPeriod());
        // Price does not drift upward after the claim, so a fresh entrant captures nothing from holders.
        assertEq(vault.previewDeposit(100e6), sharesNow, "entry price must not change as time passes");
        assertEq(vault.previewRedeem(sharesNow), redeemNow);
    }

    function test_N24_depositAfterClaim_createsNoDeficit() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        _claim(100e6);
        assertEq(vault.hwmDeficit(), 0);
        _deposit(1_000e6);
        assertEq(vault.hwmDeficit(), 0, "a deposit cannot manufacture a recovery deficit");
        assertEq(vault.highWaterMarkPerShare(), _processedPrice());
    }

    // ───────────── observation: depositor share after a claim ─────────────

    /// @dev The distributed depositor share is counted in the checkpoint and sits in NAV
    ///      immediately, so it is never claimable again.
    function test_depositorShare_doesNotReenterRealizedProfit() public {
        _deposit(1_000e6);
        usdc.mint(address(vault), 100e6);
        uint256 baseBefore = vault.profitBase();
        _claim(100e6);
        assertGt(vault.profitBase(), baseBefore, "waterfall returned a depositor share");
        assertEq(vault.lockedProfit(), 0, "depositor share is not locked");
        assertEq(vault.realizedProfit(), 0);
        skip(vault.profitUnlockPeriod());
        assertEq(vault.realizedProfit(), 0, "depositor share must not be re-claimable");
        // Genuinely new profit is still claimable.
        usdc.mint(address(vault), 40e6);
        assertEq(vault.realizedProfit(), 40e6);
    }
}

contract TaskMN01V1Test is TaskMN01Base {
