// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ShariahVault} from "../ShariahVault.sol";
import {GoldExchangeAdapter} from "../adapters/GoldExchangeAdapter.sol";
import {TaskNBase, MockGoldRouterN} from "./TaskNTest.Base.t.sol";

/// @title TaskMTest.N12 — GoldExchangeAdapter records USDC(6dec)-per-whole-PAXG on deploy (no pokePrice needed).
contract TaskMN12Test is TaskNBase {
    function _fresh(uint256 price) internal returns (GoldExchangeAdapter a) {
        MockGoldRouterN r = new MockGoldRouterN(address(usdc), price);
        paxg.mint(address(r), 1_000_000e18);
        usdc.mint(address(r), 50_000_000e6);
        a = new GoldExchangeAdapter(
            address(usdc), address(paxg), address(r), 3000, address(svault), owner, address(oracle)
        );
        // N-23: close the fixture spread before linking the fresh adapter used by price regressions.
        vm.prank(manager);
        svault.recallCapital(address(goldAdapter), GOLD_BUY);
        vm.startPrank(owner);
        svault.setScreened(address(a), true);
        svault.setGoldSpreadAdapter(address(a));
        vm.stopPrank();
    }

    function _deployVia(GoldExchangeAdapter a, uint256 amount) internal {
        vm.prank(manager);
        svault.deployCapitalAndExecute(address(a), amount, "");
    }

    function test_n12_beforeAnyDeploy_priceAndValueAreZero() public {
        GoldExchangeAdapter a = _fresh(PAXG_PRICE);
        assertEq(a.lastGoodPrice(), 0);
        assertEq(a.lastGoodPriceAt(), 0);
        assertEq(a.currentValue(), 0);
    }

    function test_n12_deploy_setsLastGoodPrice_withoutPokePrice() public {
        // Router price 2_500 differs from the oracle's 3_300, so equality proves the swap price was used.
        GoldExchangeAdapter a = _fresh(2_500e6);
        assertEq(uint256(oracle.price()) / 100, 3_300e6, "oracle price differs from router price");
        uint256 amount = 25_000e6; // buys exactly 10 whole PAXG

        vm.expectEmit(false, false, false, true, address(a));
        emit GoldExchangeAdapter.LastGoodPriceUpdated(2_500e6, block.timestamp);
        _deployVia(a, amount);

        assertEq(a.paxgHeld(), 10e18);
        assertEq(a.lastGoodPrice(), 2_500e6, "USDC (6 dec) per whole PAXG");
        assertEq(a.lastGoodPriceAt(), block.timestamp);
        // Entry-price cache remains observable, but fresh NAV must use the oracle without a poke.
        assertEq(a.currentValue(), (a.paxgHeld() * 3_300e6) / 1e18);
        assertEq(a.currentValue(), 33_000e6);
    }

    function test_n12_priceIsInUsdcUnits_notFixedPointScaled() public {
        GoldExchangeAdapter a = _fresh(PAXG_PRICE);
        _deployVia(a, 33_000e6);
        assertEq(a.paxgHeld(), 10e18);
        assertEq(a.lastGoodPrice(), PAXG_PRICE);
        assertGt(a.lastGoodPrice(), 1e6);
        assertLt(a.lastGoodPrice(), 1e12);
        assertEq(a.currentValue(), 33_000e6);
    }

    function test_n12_nonDivisibleAmount_valueWithinRoundingOfCost() public {
        GoldExchangeAdapter a = _fresh(PAXG_PRICE);
        _deployVia(a, 1_000e6);
        assertApproxEqAbs(a.lastGoodPrice(), PAXG_PRICE, 1);
        assertApproxEqAbs(a.currentValue(), 1_000e6, 1);
        // Fresh NAV uses the exact oracle input rather than a rounded execution-price cache.
        assertEq(a.currentValue(), (a.paxgHeld() * PAXG_PRICE) / 1e18);
    }

    function test_n12_pokePrice_afterDeploy_stillRefreshesFromOracle() public {
        GoldExchangeAdapter a = _fresh(2_500e6);
        _deployVia(a, 25_000e6);
        a.pokePrice();
        assertEq(a.lastGoodPrice(), 3_300e6, "oracle (3300 USD, 8 dec) -> 6 dec");
        assertEq(a.currentValue(), 33_000e6);
    }

    function testFuzz_n12_currentValueTracksCost_andFormulaExact(uint256 amount, uint256 price) public {
        amount = bound(amount, 100e6, 50_000e6); // inside the allocation cap; avoid router rounding at dust sizes
        price = bound(price, 100e6, 3_300e6); // above this the fixture's allocation adapter appreciates past the combined gold cap
        GoldExchangeAdapter a = _fresh(price);
        // N-23: set the oracle after the fixture spread is recalled so the router and oracle agree at deploy time.
        oracle.setPrice(int256(price * 100));
        _deployVia(a, amount);
        uint256 held = a.paxgHeld();
        assertGt(a.lastGoodPrice(), 0);
        assertApproxEqAbs(a.lastGoodPrice(), price, 2);
        // The oracle input is exact; the execution-price cache may have division rounding.
        assertEq(a.currentValue(), (held * price) / 1e18, "exact oracle formula");
        assertApproxEqAbs(a.currentValue(), amount, held / 1e18 + 1);
    }

    function test_n12_valuation_feedsVaultGoldCap() public {
        // Existing fixture holds 200_000 USDC of gold (100k PAXG + 100k XAUT); cap is 30% of NAV (300k).
        vm.prank(manager);
        svault.deployCapitalAndExecute(address(goldAdapter), 50_000e6, "");
        assertApproxEqAbs(goldAdapter.currentValue(), GOLD_BUY + 50_000e6, 2);
        vm.prank(manager);
        vm.expectPartialRevert(ShariahVault.GoldCapExceeded.selector);
        svault.deployCapitalAndExecute(address(goldAdapter), 60_000e6, ""); // 100k alloc + 150k + 60k > 300k
    }
}

contracts/test/TaskMTest.Outbound.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {TaskMBase, MockTransmitterM} from "./TaskMTest.Base.t.sol";

/// @title TaskMTest.Outbound — native depositForBurn arguments plus owner-only configuration setters.
contract TaskMOutboundTest is TaskMBase {
    function _lastCall()
        internal
        view
        returns (uint256 amount, uint32 domain, bytes32 rcpt, address token, bytes32 caller, uint256 maxFee, uint32 fin)
    {
        return messenger.last();
    }

    // ───────────── outbound depositForBurn ─────────────

    function test_outbound_defaults_recordAllSevenArgs() public {
        _deploy(REMOTE_DOMAIN, SENT);
        (uint256 amount, uint32 domain, bytes32 rcpt, address token, bytes32 caller, uint256 maxFee, uint32 fin) =
            _lastCall();
        assertEq(amount, SENT);
        assertEq(domain, REMOTE_DOMAIN);
        assertEq(rcpt, _b32(remoteRecipientAddr));
        assertEq(token, address(usdc), "burnToken = asset");
        assertEq(caller, bytes32(0), "destinationCaller = 0");
        assertEq(maxFee, 0, "default bps 0 -> maxFee 0");
        assertEq(fin, 2000, "default finality = standard");
        assertEq(messenger.callCount(), 1);
    }

    function test_outbound_configuredFeeAndFinality_integerRounding() public {
        vm.startPrank(owner);
        vault.setCrossChainMaxFeeBps(37);
        vault.setCrossChainMinFinality(1000);
        vm.stopPrank();
        uint256 amount = 12_345_678; // 12.345678 USDC: 37 bps = 4567.9 -> rounds down
        _deploy(OTHER_DOMAIN, amount);
        (uint256 a, uint32 domain, bytes32 rcpt, address token, bytes32 caller, uint256 maxFee, uint32 fin) =
            _lastCall();
        assertEq(a, amount);
        assertEq(domain, OTHER_DOMAIN);
        assertEq(rcpt, _b32(remoteRecipientAddr));
        assertEq(token, address(usdc));
        assertEq(caller, bytes32(0));
        assertEq(maxFee, (amount * 37) / 10_000);
        assertEq(maxFee, 45_679);
        assertEq(fin, 1000);
    }

    function test_outbound_tinyAmount_feeRoundsToZero() public {
        vm.prank(owner);
        vault.setCrossChainMaxFeeBps(100);
        _deploy(REMOTE_DOMAIN, 99); // 99 * 100 / 10_000 = 0
        (, , , , , uint256 maxFee,) = _lastCall();
        assertEq(maxFee, 0);
    }

    function test_outbound_maxBps_isOnePercent() public {
        vm.prank(owner);
        vault.setCrossChainMaxFeeBps(100);
        _deploy(REMOTE_DOMAIN, SENT);
        (, , , , , uint256 maxFee,) = _lastCall();
        assertEq(maxFee, SENT / 100);
    }

    function testFuzz_outbound_maxFeeFormula_andAllowanceCleared(uint256 amount, uint256 bps, bool fast) public {
        amount = bound(amount, 1, 40_000e6);
        bps = bound(bps, 0, 100);
        vm.startPrank(owner);
        vault.setCrossChainMaxFeeBps(bps);
        vault.setCrossChainMinFinality(fast ? 1000 : 2000);
        vm.stopPrank();
        _deploy(REMOTE_DOMAIN, amount);
        (uint256 a, , , , , uint256 maxFee, uint32 fin) = _lastCall();
        assertEq(a, amount);
        assertEq(maxFee, (amount * bps) / 10_000);
        assertEq(fin, fast ? 1000 : 2000);
        assertEq(usdc.allowance(address(vault), address(messenger)), 0);
    }

    function test_outbound_exactAllowanceGranted_thenCleared() public {
        _deploy(REMOTE_DOMAIN, SENT);
        assertEq(messenger.allowanceSeen(), SENT, "exact allowance during burn");
        assertEq(usdc.allowance(address(vault), address(messenger)), 0, "cleared afterwards");
        assertEq(usdc.balanceOf(address(messenger)), SENT, "tokens burned/pulled");
    }

    function test_outbound_partialPull_residualAllowanceCleared() public {
        messenger.configure(true, true);
        _deploy(REMOTE_DOMAIN, SENT);
        assertEq(usdc.balanceOf(address(messenger)), SENT / 2);
        assertEq(usdc.allowance(address(vault), address(messenger)), 0, "residual allowance cleared");
    }

    function test_outbound_noPull_allowanceStillCleared() public {
        messenger.configure(false, false);
        _deploy(REMOTE_DOMAIN, SENT);
        assertEq(usdc.allowance(address(vault), address(messenger)), 0);
    }

    function test_outbound_ownerCanAlsoDeploy_andBookkeepingUpdated() public {
        vm.prank(owner);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), SENT);
        assertEq(vault.pendingCrossChain(1), SENT);
        assertEq(vault.totalDeployed(), SENT);
        assertEq(vault.totalPendingCrossChain(), SENT);
    }

    function test_outbound_revertPaths() public {
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), SENT);

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.SameDomainDeploy.selector);
        vault.deployCrossChain(LOCAL_DOMAIN, _b32(alice), SENT);

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.PendingCrossChainCapExceeded.selector);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), 50_000e6 + 1);

        vm.prank(manager);
        vm.expectRevert(AutonomousVault.AllocationExceedsLimit.selector);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), DEPOSIT);

        vm.prank(owner);
        vault.setPaused(true);
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.Paused.selector);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), SENT);
        assertEq(messenger.callCount(), 0);
        assertEq(vault.crossChainPositionCounter(), 0);
    }

    function test_outbound_messengerUnset_revertsNotConfigured() public {
        vm.prank(owner);
        AutonomousVault v2 = new AutonomousVault(IERC20(address(usdc)), owner, LOCAL_DOMAIN);
        vm.prank(owner);
        v2.setManager(manager);
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.CrossChainNotConfigured.selector);
        v2.deployCrossChain(REMOTE_DOMAIN, _b32(alice), 1);
    }

    function test_outbound_capRevert_doesNotAdvanceCounterOrPending() public {
        _deploy(REMOTE_DOMAIN, 45_000e6); // pending cap is 50% of 100_000e6
        uint256 counterBefore = vault.crossChainPositionCounter();
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.PendingCrossChainCapExceeded.selector);
        vault.deployCrossChain(REMOTE_DOMAIN, _b32(alice), 6_000e6);
        assertEq(vault.crossChainPositionCounter(), counterBefore);
        assertEq(vault.totalPendingCrossChain(), 45_000e6);
    }

    // ───────────── setters: crossChainMinFinality ─────────────

    function test_defaults() public view {
        assertEq(vault.crossChainMinFinality(), 2000);
        assertEq(vault.crossChainMaxFeeBps(), 0);
        assertEq(vault.MAX_CROSS_CHAIN_FEE_BPS(), 100);
        assertEq(vault.crossChainPositionCounter(), 0);
    }

    function test_setMinFinality_1000_and_2000_emit() public {
        vm.startPrank(owner);
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.CrossChainMinFinalityUpdated(2000, 1000);
        vault.setCrossChainMinFinality(1000);
        assertEq(vault.crossChainMinFinality(), 1000);
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.CrossChainMinFinalityUpdated(1000, 2000);
        vault.setCrossChainMinFinality(2000);
        assertEq(vault.crossChainMinFinality(), 2000);
        vm.stopPrank();
    }

    function testFuzz_setMinFinality_otherValuesRevert(uint32 f) public {
        vm.assume(f != 1000 && f != 2000);
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.InvalidCrossChainMinFinality.selector);
        vault.setCrossChainMinFinality(f);
        assertEq(vault.crossChainMinFinality(), 2000);
    }

    function test_setMinFinality_boundaryNeighboursRevert() public {
        uint32[6] memory bad = [uint32(0), 1, 999, 1001, 1999, 2001];
        for (uint256 i = 0; i < bad.length; i++) {
            vm.prank(owner);
            vm.expectRevert(AutonomousVault.InvalidCrossChainMinFinality.selector);
            vault.setCrossChainMinFinality(bad[i]);
        }
    }

    function test_setMinFinality_ownerOnly() public {
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setCrossChainMinFinality(1000);
        vm.prank(stranger);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, stranger));
        vault.setCrossChainMinFinality(1000);
    }

    // ───────────── setters: crossChainMaxFeeBps ─────────────

    function test_setMaxFeeBps_bounds_andEvents() public {
        vm.startPrank(owner);
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.CrossChainMaxFeeBpsUpdated(0, 100);
        vault.setCrossChainMaxFeeBps(100);
        assertEq(vault.crossChainMaxFeeBps(), 100);
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.CrossChainMaxFeeBpsUpdated(100, 0);
        vault.setCrossChainMaxFeeBps(0);
        assertEq(vault.crossChainMaxFeeBps(), 0);
        vault.setCrossChainMaxFeeBps(1);
        assertEq(vault.crossChainMaxFeeBps(), 1);
        vm.expectRevert(AutonomousVault.InvalidBps.selector);
        vault.setCrossChainMaxFeeBps(101);
        vm.stopPrank();
        assertEq(vault.crossChainMaxFeeBps(), 1);
    }

    function testFuzz_setMaxFeeBps_aboveCapReverts_belowAccepted(uint256 bps) public {
        vm.prank(owner);
        if (bps > 100) {
            vm.expectRevert(AutonomousVault.InvalidBps.selector);
            vault.setCrossChainMaxFeeBps(bps);
            assertEq(vault.crossChainMaxFeeBps(), 0);
        } else {
            vault.setCrossChainMaxFeeBps(bps);
            assertEq(vault.crossChainMaxFeeBps(), bps);
        }
    }

    function test_setMaxFeeBps_ownerOnly() public {
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setCrossChainMaxFeeBps(1);
    }

    // ───────────── setters: remote messenger / local wiring ─────────────

    function test_setRemoteTokenMessenger_storesAndEmits() public {
        bytes32 m = _b32(makeAddr("anotherRemote"));
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.RemoteTokenMessengerUpdated(OTHER_DOMAIN, m);
        vm.prank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, m);
        assertEq(vault.remoteTokenMessenger(OTHER_DOMAIN), m);
        // overwrite allowed, domain 0 is a real domain
        vm.startPrank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(remoteMessengerAddr));
        vault.setRemoteTokenMessenger(0, m);
        vm.stopPrank();
        assertEq(vault.remoteTokenMessenger(OTHER_DOMAIN), _b32(remoteMessengerAddr));
        assertEq(vault.remoteTokenMessenger(0), m);
    }

    function test_setRemoteTokenMessenger_zeroReverts_ownerOnly() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, bytes32(0));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(alice));
    }

    function test_setTokenMessenger_zeroReverts_updatesAndEmits_ownerOnly() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        vault.setTokenMessenger(address(0));

        address newM = makeAddr("newMessenger");
        vm.expectEmit(true, true, false, false, address(vault));
        emit AutonomousVault.TokenMessengerUpdated(address(messenger), newM);
        vm.prank(owner);
        vault.setTokenMessenger(newM);
        assertEq(vault.tokenMessenger(), newM);

        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setTokenMessenger(newM);
    }

    function test_setMessageTransmitter_zeroReverts_updatesAndEmits_ownerOnly() public {
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        vault.setMessageTransmitter(address(0));

        MockTransmitterM plain = new MockTransmitterM(usdc);
        vm.expectEmit(true, true, false, false, address(vault));
        emit AutonomousVault.MessageTransmitterUpdated(address(transmitter), address(plain));
        vm.prank(owner);
        vault.setMessageTransmitter(address(plain));
        assertEq(vault.messageTransmitter(), address(plain));

        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setMessageTransmitter(address(plain));
    }

    function test_setMessageTransmitter_adoptsReportedDomain_includingZero() public {
        transmitter.setDomain(0);
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.LocalDomainUpdated(0);
        vm.prank(owner);
        vault.setMessageTransmitter(address(transmitter));
        assertEq(vault.localDomain(), 0);
        transmitter.setDomain(77);
        vm.prank(owner);
        vault.setMessageTransmitter(address(transmitter));
        assertEq(vault.localDomain(), 77);
    }

    function test_setLocalDomain_mismatchWithTransmitterReverts() public {
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.LocalDomainMismatch.selector, LOCAL_DOMAIN, uint32(5)));
        vault.setLocalDomain(5);
        vm.prank(owner);
        vault.setLocalDomain(LOCAL_DOMAIN);
        assertEq(vault.localDomain(), LOCAL_DOMAIN);
    }

    function test_setLocalDomain_transmitterWithoutLocalDomain_acceptsAnyIncludingZero() public {
        MockTransmitterM plain = new MockTransmitterM(usdc);
        vm.startPrank(owner);
        vault.setMessageTransmitter(address(plain));
        vm.expectEmit(false, false, false, true, address(vault));
        emit AutonomousVault.LocalDomainUpdated(0);
        vault.setLocalDomain(0);
        assertEq(vault.localDomain(), 0, "domain zero is valid");
        vault.setLocalDomain(123);
        assertEq(vault.localDomain(), 123);
        vm.stopPrank();
    }

    function test_setLocalDomain_noTransmitter_revertsZeroAddress_ownerOnly() public {
        vm.prank(owner);
        AutonomousVault v2 = new AutonomousVault(IERC20(address(usdc)), owner, LOCAL_DOMAIN);
        vm.prank(owner);
        vm.expectRevert(AutonomousVault.ZeroAddress.selector);
        v2.setLocalDomain(1);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.setLocalDomain(LOCAL_DOMAIN);
    }
}

contracts/test/TaskMTest.Settle.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Vm} from "forge-std/Vm.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {AutonomousVault} from "../AutonomousVault.sol";
import {TaskMBase} from "./TaskMTest.Base.t.sol";

/// @title TaskMTest.Settle — atomic settlement accounting, fees, rollback, positions and write-off.
contract TaskMSettleTest is TaskMBase {
    struct Snap {
        uint256 vaultBal;
        uint256 supply;
        uint256 pending;
        uint256 totalPending;
        uint256 totalDeployed;
        uint256 totalAssets;
        bool consumed;
        uint256 transmitterCalls;
    }

    function _snap(uint64 id, uint32 src, bytes32 nonce) internal view returns (Snap memory s) {
        s.vaultBal = usdc.balanceOf(address(vault));
        s.supply = usdc.totalSupply();
        s.pending = vault.pendingCrossChain(id);
        s.totalPending = vault.totalPendingCrossChain();
        s.totalDeployed = vault.totalDeployed();
        s.totalAssets = vault.totalAssets();
        s.consumed = vault.consumedInbound(src, nonce);
        s.transmitterCalls = transmitter.calls();
    }

    function _assertSame(Snap memory a, Snap memory b) internal pure {
        assertEq(a.vaultBal, b.vaultBal, "vault balance rolled back");
        assertEq(a.supply, b.supply, "token supply rolled back");
        assertEq(a.pending, b.pending, "pending rolled back");
        assertEq(a.totalPending, b.totalPending, "totalPending rolled back");
        assertEq(a.totalDeployed, b.totalDeployed, "totalDeployed rolled back");
        assertEq(a.totalAssets, b.totalAssets, "NAV rolled back");
        assertEq(a.consumed, b.consumed, "replay consumption rolled back");
        assertEq(a.transmitterCalls, b.transmitterCalls, "transmitter call rolled back");
    }

    function _settleExpectRevert(uint64 id, Msg memory m, bytes memory err) internal {
        bytes memory message = _encode(m);
        vm.prank(manager);
        vm.expectRevert(err);
        vault.settleCrossChainWithMessage(id, message, hex"a77e57");
    }

    // ───────────── fee cases ─────────────

    function test_settle_zeroFee_booksFullAmount_noFeeEvent() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        uint256 navBefore = vault.totalAssets();
        assertEq(navBefore, DEPOSIT, "NAV neutral while in flight");
        assertEq(usdc.balanceOf(address(vault)), DEPOSIT - SENT);

        vm.recordLogs();
        _settle(id, _msg(SENT, 0, NONCE), SENT);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        assertEq(_countLogs(logs, address(vault), AutonomousVault.CrossChainFeeDeducted.selector), 0);
        assertEq(_countLogs(logs, address(vault), AutonomousVault.CrossChainSettled.selector), 1);

        assertEq(usdc.balanceOf(address(vault)), DEPOSIT);
        assertEq(vault.totalDeployed(), 0);
        assertEq(vault.totalPendingCrossChain(), 0);
        assertEq(vault.pendingCrossChain(id), 0);
        assertEq(vault.pendingCrossChainDestinationDomain(id), 0);
        assertEq(vault.totalAssets(), DEPOSIT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, NONCE));
    }

    function test_settle_zeroFee_emitsSettledWithZeroShortfall() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        transmitter.arm(address(vault), SENT);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, SENT, 0);
        _settleArmed(id, _msg(SENT, 0, NONCE));
    }

    function test_settle_nonzeroFee_emitsFeeThenSettled_andNavDropsByFee() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        uint256 fee = 5e6;
        transmitter.arm(address(vault), SENT - fee);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainFeeDeducted(id, fee);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, SENT - fee, fee);
        _settleArmed(id, _msg(SENT, fee, NONCE));

        assertEq(usdc.balanceOf(address(vault)), DEPOSIT - fee);
        assertEq(vault.totalAssets(), DEPOSIT - fee);
        assertEq(vault.totalDeployed(), 0);
        assertEq(vault.totalPendingCrossChain(), 0);
    }

    function test_settle_maxFeeInMessageDiffersFromFeeExecuted_usesFeeExecuted() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 3e6, NONCE);
        m.maxFee = 20e6; // authorised ceiling, not what was charged
        transmitter.arm(address(vault), SENT - 3e6);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainFeeDeducted(id, 3e6);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, SENT - 3e6, 3e6);
        _settleArmed(id, m);
        assertEq(vault.totalAssets(), DEPOSIT - 3e6);
    }

    function test_settle_strategyLossPlusFee_shortfallIsLossAndFee() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        uint256 returned = 9_000e6; // strategy lost 1_000 on the remote side
        uint256 fee = 4e6;
        transmitter.arm(address(vault), returned - fee);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainFeeDeducted(id, fee);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, returned - fee, SENT - (returned - fee));
        _settleArmed(id, _msg(returned, fee, NONCE));
        assertEq(vault.totalAssets(), DEPOSIT - 1_000e6 - fee);
        assertEq(vault.totalDeployed(), 0);
    }

    function test_settle_gain_zeroShortfall_navRises() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        transmitter.arm(address(vault), 11_000e6);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, 11_000e6, 0);
        _settleArmed(id, _msg(11_000e6, 0, NONCE));
        assertEq(vault.totalAssets(), DEPOSIT + 1_000e6);
    }

    function test_settle_feeExceedsAmount_expectedNetZero_booksFullLoss() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        transmitter.arm(address(vault), 0);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainFeeDeducted(id, 10);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, 0, SENT);
        _settleArmed(id, _msg(5, 10, NONCE));
        assertEq(vault.pendingCrossChain(id), 0);
        assertEq(vault.totalAssets(), DEPOSIT - SENT);
    }

    function testFuzz_settle_netDeltaDrivesAccounting(uint256 returned, uint256 fee) public {
        returned = bound(returned, 1, 1_000_000e6);
        fee = bound(fee, 0, returned);
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        uint256 net = returned - fee;
        _settle(id, _msg(returned, fee, NONCE), net);
        assertEq(usdc.balanceOf(address(vault)), DEPOSIT - SENT + net);
        assertEq(vault.totalAssets(), DEPOSIT - SENT + net);
        assertEq(vault.totalDeployed(), 0);
        assertEq(vault.totalPendingCrossChain(), 0);
    }

    function test_settle_donationBeforeSettle_doesNotAffectDeltaCheck() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        usdc.mint(address(vault), 7e6); // donation: raises balBefore, not the mint delta
        _settle(id, _msg(SENT, 0, NONCE), SENT);
        assertEq(vault.totalAssets(), DEPOSIT + 7e6);
    }

    // ───────────── rollback paths ─────────────

    function test_rollback_mismatch_mintedTooMuch() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Snap memory before_ = _snap(id, REMOTE_DOMAIN, NONCE);
        transmitter.arm(address(vault), SENT + 1);
        _settleExpectRevert(
            id, _msg(SENT, 0, NONCE), abi.encodeWithSelector(AutonomousVault.MessageAmountMismatch.selector, SENT, SENT + 1)
        );
        _assertSame(before_, _snap(id, REMOTE_DOMAIN, NONCE));
    }

    function test_rollback_mismatch_feeIgnoredByTransmitter() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Snap memory before_ = _snap(id, REMOTE_DOMAIN, NONCE);
        transmitter.arm(address(vault), SENT); // minted gross although feeExecuted = 5
        _settleExpectRevert(
            id,
            _msg(SENT, 5e6, NONCE),
            abi.encodeWithSelector(AutonomousVault.MessageAmountMismatch.selector, SENT - 5e6, SENT)
        );
        _assertSame(before_, _snap(id, REMOTE_DOMAIN, NONCE));
    }

    function test_rollback_failedMint_mintedToWrongAddress() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Snap memory before_ = _snap(id, REMOTE_DOMAIN, NONCE);
        transmitter.arm(alice, SENT); // vault never receives
        _settleExpectRevert(
            id, _msg(SENT, 0, NONCE), abi.encodeWithSelector(AutonomousVault.MessageAmountMismatch.selector, SENT, 0)
        );
        _assertSame(before_, _snap(id, REMOTE_DOMAIN, NONCE));
    }

    function test_rollback_falseReceive_afterMint() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Snap memory before_ = _snap(id, REMOTE_DOMAIN, NONCE);
        transmitter.setRet(false);
        transmitter.arm(address(vault), SENT); // would have minted, but receive reports failure
        _settleExpectRevert(id, _msg(SENT, 0, NONCE), abi.encodeWithSelector(AutonomousVault.MessageReceiveFailed.selector));
        _assertSame(before_, _snap(id, REMOTE_DOMAIN, NONCE));
    }

    function test_rollback_transmitterReverts_bubblesAndRollsBack() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Snap memory before_ = _snap(id, REMOTE_DOMAIN, NONCE);
        transmitter.setRevert(true);
        _settleExpectRevert(id, _msg(SENT, 0, NONCE), abi.encodeWithSignature("Error(string)", "transmitter: boom"));
        _assertSame(before_, _snap(id, REMOTE_DOMAIN, NONCE));
    }

    function test_rollback_thenRetrySucceeds_sameNonce() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        transmitter.setRet(false);
        transmitter.arm(address(vault), SENT);
        _settleExpectRevert(id, _msg(SENT, 0, NONCE), abi.encodeWithSelector(AutonomousVault.MessageReceiveFailed.selector));
        assertFalse(vault.consumedInbound(REMOTE_DOMAIN, NONCE));

        transmitter.setRet(true);
        _settle(id, _msg(SENT, 0, NONCE), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, NONCE));
        assertEq(usdc.balanceOf(address(vault)), DEPOSIT);
    }

    function test_receiveMessage_gets_exactMessageAndAttestation() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        _settle(id, m, SENT);
        assertEq(transmitter.lastMsgHash(), keccak256(_encode(m)));
        assertEq(transmitter.lastAttHash(), keccak256(hex"a77e57"));
        assertEq(transmitter.calls(), 1);
    }

    // ───────────── positions ─────────────

    function test_positionIds_sequential_matchCounterAndEvent() public {
        uint256[3] memory amounts = [uint256(1_000e6), 2_000e6, 3_000e6];
        uint32[3] memory domains = [REMOTE_DOMAIN, OTHER_DOMAIN, REMOTE_DOMAIN];
        assertEq(vault.crossChainPositionCounter(), 0);
        uint256 running;
        for (uint64 i = 0; i < 3; i++) {
            vm.expectEmit(true, true, false, true, address(vault));
            emit AutonomousVault.CapitalDeployedCrossChain(
                domains[i], _b32(remoteRecipientAddr), amounts[i], i + 1
            );
            uint64 id = _deploy(domains[i], amounts[i]);
            assertEq(id, i + 1);
            assertEq(vault.crossChainPositionCounter(), i + 1);
            assertEq(vault.pendingCrossChain(id), amounts[i]);
            assertEq(vault.pendingCrossChainDestinationDomain(id), domains[i]);
            running += amounts[i];
            assertEq(vault.totalPendingCrossChain(), running);
            assertEq(vault.totalDeployed(), running);
        }
    }

    function test_settle_oneOfSeveral_leavesOthersUntouched() public {
        uint64 id1 = _deploy(REMOTE_DOMAIN, 1_000e6);
        uint64 id2 = _deploy(OTHER_DOMAIN, 2_000e6);
        uint64 id3 = _deploy(REMOTE_DOMAIN, 3_000e6);
        vm.prank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(remoteMessengerAddr));
        Msg memory m = _msg(2_000e6, 0, NONCE);
        m.sourceDomain = OTHER_DOMAIN;
        _settle(id2, m, 2_000e6);

        assertEq(vault.pendingCrossChain(id1), 1_000e6);
        assertEq(vault.pendingCrossChain(id2), 0);
        assertEq(vault.pendingCrossChain(id3), 3_000e6);
        assertEq(vault.pendingCrossChainDestinationDomain(id1), REMOTE_DOMAIN);
        assertEq(vault.pendingCrossChainDestinationDomain(id3), REMOTE_DOMAIN);
        assertEq(vault.totalPendingCrossChain(), 4_000e6);
        assertEq(vault.totalDeployed(), 4_000e6);
        assertEq(vault.crossChainPositionCounter(), 3, "counter never decrements");
    }

    function test_settle_sameIdTwice_revertsNonceMismatch() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        _settle(id, _msg(SENT, 0, NONCE), SENT);
        bytes memory message = _encode(_msg(SENT, 0, bytes32(uint256(2))));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, id, uint64(0)));
        vault.settleCrossChainWithMessage(id, message, "");
    }

    function test_settle_idNeverDeployed_revertsNonceMismatch() public {
        _deploy(REMOTE_DOMAIN, SENT);
        bytes memory message = _encode(_msg(SENT, 0, NONCE));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(2), uint64(0)));
        vault.settleCrossChainWithMessage(2, message, "");
    }

    // ───────────── owner-only zero-value write-off ─────────────

    function test_writeOff_ownerOnly_booksFullLoss_andEmits() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.expectEmit(true, false, false, true, address(vault));
        emit AutonomousVault.CrossChainSettled(id, 0, SENT);
        vm.prank(owner);
        vault.settleCrossChain(id, 0);
        assertEq(vault.pendingCrossChain(id), 0);
        assertEq(vault.pendingCrossChainDestinationDomain(id), 0);
        assertEq(vault.totalPendingCrossChain(), 0);
        assertEq(vault.totalDeployed(), 0);
        assertEq(vault.totalAssets(), DEPOSIT - SENT);
    }

    function test_writeOff_managerAndStrangerRejected() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        vault.settleCrossChain(id, 0);
        vm.prank(stranger);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, stranger));
        vault.settleCrossChain(id, 0);
        assertEq(vault.pendingCrossChain(id), SENT);
    }

    function test_writeOff_nonZeroReceived_reverts_beforeUnknownIdCheck() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.startPrank(owner);
        vm.expectRevert(AutonomousVault.WriteOffMustBeZero.selector);
        vault.settleCrossChain(id, 1);
        vm.expectRevert(AutonomousVault.WriteOffMustBeZero.selector);
        vault.settleCrossChain(999, 1);
        vm.stopPrank();
    }

    function test_writeOff_unknownOrAlreadySettled_revertsNonceMismatch() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(42), uint64(0)));
        vault.settleCrossChain(42, 0);
        vault.settleCrossChain(id, 0);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, id, uint64(0)));
        vault.settleCrossChain(id, 0);
        vm.stopPrank();
    }

    function test_writeOff_doesNotConsumeAnyInboundKey_andLateMessageCannotSettleIt() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.prank(owner);
        vault.settleCrossChain(id, 0);
        assertFalse(vault.consumedInbound(REMOTE_DOMAIN, NONCE));
        bytes memory message = _encode(_msg(SENT, 0, NONCE));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, id, uint64(0)));
        vault.settleCrossChainWithMessage(id, message, "");
    }
}

contracts/test/TaskMTest.Validation.t.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {AutonomousVault, CctpMessageDecoder} from "../AutonomousVault.sol";
import {TaskMBase, MockTransmitterM} from "./TaskMTest.Base.t.sol";

/// @title TaskMTest.Validation — native CCTP V2 inbound validation order, replay and decoder bounds.
contract TaskMValidationTest is TaskMBase {
    bytes32 internal constant BAD = bytes32(uint256(0xBAD));

    function _expectSettleRevert(uint64 id, Msg memory m, bytes memory err) internal {
        bytes memory message = _encode(m);
        vm.prank(manager);
        vm.expectRevert(err);
        vault.settleCrossChainWithMessage(id, message, "");
    }

    function _truncate(bytes memory b, uint256 n) internal pure returns (bytes memory out) {
        out = new bytes(n);
        for (uint256 i = 0; i < n; i++) out[i] = b[i];
    }

    // ───────────── precedence of pre-message checks ─────────────

    function test_unknownPositionId_revertsNonceMismatch_beforeAnyMessageDecoding() public {
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(99), uint64(0)));
        vault.settleCrossChainWithMessage(99, hex"", hex"");
    }

    function test_positionIdZero_revertsNonceMismatch() public {
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(AutonomousVault.NonceMismatch.selector, uint64(0), uint64(0)));
        vault.settleCrossChainWithMessage(0, hex"", hex"");
    }

    function test_transmitterUnset_revertsCrossChainNotConfigured_beforeDecoding() public {
        vm.startPrank(owner);
        AutonomousVault v2 = new AutonomousVault(IERC20(address(usdc)), owner, LOCAL_DOMAIN);
        v2.setManager(manager);
        v2.setTokenMessenger(address(messenger));
        v2.setMaxAllocationBps(9_000);
        v2.setMaxPendingCrossChainBps(5_000);
        vm.stopPrank();
        usdc.mint(alice, 1_000e6);
        vm.startPrank(alice);
        usdc.approve(address(v2), 1_000e6);
        v2.deposit(1_000e6, alice);
        vm.stopPrank();
        vm.prank(manager);
        v2.deployCrossChain(REMOTE_DOMAIN, _b32(alice), 100e6);
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.CrossChainNotConfigured.selector);
        v2.settleCrossChainWithMessage(1, hex"", hex"");
    }

    function test_onlyManagerOrOwner_canSettle() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        bytes memory message = _encode(_msg(SENT, 0, NONCE));
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        vault.settleCrossChainWithMessage(id, message, "");

        transmitter.arm(address(vault), SENT);
        vm.prank(owner);
        vault.settleCrossChainWithMessage(id, message, "");
        assertEq(vault.pendingCrossChain(id), 0);
    }

    // ───────────── full validation order (each step fixes exactly one field) ─────────────

    function test_validationOrder_headerVersion_destDomain_sourceDomain_recipient_caller_remote_body_mint() public {
        uint64 id = _deploy(OTHER_DOMAIN, SENT); // no remote messenger registered for domain 7
        Msg memory m = _msg(SENT, 0, NONCE);
        m.headerVersion = 2;
        m.destinationDomain = 99;
        m.sourceDomain = 55;
        m.recipient = BAD;
        m.destinationCaller = BAD;
        m.sender = BAD;
        m.bodyVersion = 2;
        m.mintRecipient = BAD;

        // 1. header version
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongHeaderVersion.selector, uint32(2)));
        m.headerVersion = 1;
        // 2. local destination domain
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, LOCAL_DOMAIN, uint32(99)));
        m.destinationDomain = LOCAL_DOMAIN;
        // 3. recorded source domain
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongSourceDomain.selector, OTHER_DOMAIN, uint32(55)));
        m.sourceDomain = OTHER_DOMAIN;
        // 4. local messenger recipient
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongMessageRecipient.selector, BAD));
        m.recipient = _b32(address(messenger));
        // 5. destinationCaller must be exactly the vault
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, BAD));
        m.destinationCaller = _b32(address(vault));
        // 6. remote messenger not registered for the source domain
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.RemoteMessengerNotSet.selector, OTHER_DOMAIN));
        vm.prank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(remoteMessengerAddr));
        // 7. registered remote messenger != message sender
        _expectSettleRevert(
            id, m, abi.encodeWithSelector(AutonomousVault.WrongRemoteSender.selector, _b32(remoteMessengerAddr), BAD)
        );
        m.sender = _b32(remoteMessengerAddr);
        // 8. body version
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongBodyVersion.selector, uint32(2)));
        m.bodyVersion = 1;
        // 9. vault mintRecipient
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongMintRecipient.selector, BAD));
        m.mintRecipient = _b32(address(vault));

        // 10. everything valid -> settles and nothing was consumed by the failed attempts
        assertFalse(vault.consumedInbound(OTHER_DOMAIN, NONCE));
        _settle(id, m, SENT);
        assertTrue(vault.consumedInbound(OTHER_DOMAIN, NONCE));
        assertEq(vault.pendingCrossChain(id), 0);
    }

    // Remote strategies MUST burn with destinationCaller = this vault so third parties cannot pre-consume the message.
    function test_destinationCaller_onlyVaultAccepted_zeroAndOthersRejected() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, bytes32(uint256(1)));

        m.destinationCaller = bytes32(0);
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, bytes32(0)));

        m.destinationCaller = _b32(stranger);
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, _b32(stranger)));

        m.destinationCaller = _b32(address(messenger));
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationCaller.selector, _b32(address(messenger))));

        assertEq(vault.totalPendingCrossChain(), SENT);
        m.destinationCaller = _b32(address(vault));
        _settle(id, m, SENT);
        assertEq(vault.totalPendingCrossChain(), 0);
    }

    function test_wrongRecipient_localMessengerOnly() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.recipient = _b32(address(vault)); // vault is not the local TokenMessenger
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongMessageRecipient.selector, _b32(address(vault))));
    }

    function test_sourceDomain_mustMatchPositionDestination() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        vm.prank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(remoteMessengerAddr));
        Msg memory m = _msg(SENT, 0, NONCE);
        m.sourceDomain = OTHER_DOMAIN; // valid remote, but not the domain this position was sent to
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongSourceDomain.selector, REMOTE_DOMAIN, OTHER_DOMAIN));
    }

    // ───────────── body checks precede replay; replay precedes receiveMessage ─────────────

    function test_bodyChecks_precedeReplay_andReplayPrecedesReceive() public {
        uint64 id1 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id2 = _deploy(REMOTE_DOMAIN, SENT);
        _settle(id1, _msg(SENT, 0, NONCE), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, NONCE));

        Msg memory m = _msg(SENT, 0, NONCE); // replayed nonce for position 2
        m.bodyVersion = 2;
        _expectSettleRevert(id2, m, abi.encodeWithSelector(CctpMessageDecoder.WrongBodyVersion.selector, uint32(2)));
        m.bodyVersion = 1;
        m.mintRecipient = BAD;
        _expectSettleRevert(id2, m, abi.encodeWithSelector(AutonomousVault.WrongMintRecipient.selector, BAD));
        m.mintRecipient = _b32(address(vault));

        // Replay is rejected before the transmitter is ever invoked (even if it would return false).
        transmitter.setRet(false);
        uint256 callsBefore = transmitter.calls();
        _expectSettleRevert(id2, m, abi.encodeWithSelector(AutonomousVault.InboundAlreadyConsumed.selector));
        assertEq(transmitter.calls(), callsBefore);
        assertEq(vault.pendingCrossChain(id2), SENT);
    }

    // ───────────── 32-byte nonce high bits ─────────────

    function test_nonce_highBitsPreserved_distinctNoncesSettleDistinctPositions() public {
        bytes32 n1 = bytes32(uint256(1));
        bytes32 n2 = bytes32(uint256(1) | (uint256(0xAA) << 248));
        bytes32 n3 = bytes32(uint256(1) | (uint256(0xBB) << 128)); // differ only in the middle
        uint64 id1 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id2 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id3 = _deploy(REMOTE_DOMAIN, SENT);

        _settle(id1, _msg(SENT, 0, n1), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, n1));
        assertFalse(vault.consumedInbound(REMOTE_DOMAIN, n2), "high-bit-only variant must be distinct");
        assertFalse(vault.consumedInbound(REMOTE_DOMAIN, n3));

        _settle(id2, _msg(SENT, 0, n2), SENT);
        _settle(id3, _msg(SENT, 0, n3), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, n2));
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, n3));
        assertEq(vault.totalPendingCrossChain(), 0);
    }

    function test_nonce_consumedKeyCannotSettleAnotherPosition() public {
        uint64 id1 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id2 = _deploy(REMOTE_DOMAIN, 4_000e6);
        _settle(id1, _msg(SENT, 0, NONCE), SENT);
        // Same inbound key presented for position 2 is a replay.
        transmitter.arm(address(vault), 4_000e6);
        bytes memory message = _encode(_msg(4_000e6, 0, NONCE));
        vm.prank(manager);
        vm.expectRevert(AutonomousVault.InboundAlreadyConsumed.selector);
        vault.settleCrossChainWithMessage(id2, message, "");
        assertEq(vault.pendingCrossChain(id2), 4_000e6);
        assertEq(vault.totalPendingCrossChain(), 4_000e6);
    }

    function test_nonce_sameValueDifferentSourceDomain_isIndependentKey() public {
        vm.prank(owner);
        vault.setRemoteTokenMessenger(OTHER_DOMAIN, _b32(remoteMessengerAddr));
        uint64 id1 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id2 = _deploy(OTHER_DOMAIN, SENT);
        _settle(id1, _msg(SENT, 0, NONCE), SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.sourceDomain = OTHER_DOMAIN;
        _settle(id2, m, SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, NONCE));
        assertTrue(vault.consumedInbound(OTHER_DOMAIN, NONCE));
    }

    function testFuzz_nonce_anyTwoDistinctNonces_bothConsumable(bytes32 a, bytes32 b) public {
        vm.assume(a != b);
        uint64 id1 = _deploy(REMOTE_DOMAIN, SENT);
        uint64 id2 = _deploy(REMOTE_DOMAIN, SENT);
        _settle(id1, _msg(SENT, 0, a), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, a));
        assertFalse(vault.consumedInbound(REMOTE_DOMAIN, b));
        _settle(id2, _msg(SENT, 0, b), SENT);
        assertTrue(vault.consumedInbound(REMOTE_DOMAIN, b));
    }

    // ───────────── decoder bounds ─────────────

    function test_decoder_exact376Bytes_passes() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        assertEq(_encode(m).length, 376);
        _settle(id, m, SENT);
        assertEq(vault.pendingCrossChain(id), 0);
    }

    function test_decoder_trailingHookData_passes() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.hookData = hex"deadbeefcafebabe0102030405060708090a0b0c0d0e0f10";
        assertEq(_encode(m).length, 376 + 24);
        _settle(id, m, SENT);
        assertEq(vault.pendingCrossChain(id), 0);
        assertEq(transmitter.lastMsgHash(), keccak256(_encode(m)), "full message incl. hook forwarded");
    }

    function test_decoder_375Bytes_revertsInvalidMessageRange() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        bytes memory cut = _truncate(_encode(_msg(SENT, 0, NONCE)), 375);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(CctpMessageDecoder.InvalidMessageRange.selector, 375, 0, 376));
        vault.settleCrossChainWithMessage(id, cut, "");
        assertEq(vault.pendingCrossChain(id), SENT);
    }

    function test_decoder_headerOnly148Bytes_failsAtBodyBound() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        bytes memory cut = _truncate(_encode(_msg(SENT, 0, NONCE)), 148);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(CctpMessageDecoder.InvalidMessageRange.selector, 148, 0, 376));
        vault.settleCrossChainWithMessage(id, cut, "");
    }

    function test_decoder_headerShorterThan148_reverts() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        bytes memory full = _encode(_msg(SENT, 0, NONCE));
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(CctpMessageDecoder.InvalidMessageRange.selector, 147, 0, 148));
        vault.settleCrossChainWithMessage(id, _truncate(full, 147), "");
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(CctpMessageDecoder.InvalidMessageRange.selector, 0, 0, 148));
        vault.settleCrossChainWithMessage(id, "", "");
    }

    function testFuzz_decoder_anyLengthBelow376_reverts(uint256 len) public {
        len = bound(len, 148, 375);
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        bytes memory cut = _truncate(_encode(_msg(SENT, 0, NONCE)), len);
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(CctpMessageDecoder.InvalidMessageRange.selector, len, 0, 376));
        vault.settleCrossChainWithMessage(id, cut, "");
    }

    function testFuzz_decoder_wrongHeaderVersion_reverts(uint32 v) public {
        vm.assume(v != 1);
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.headerVersion = v;
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongHeaderVersion.selector, v));
    }

    function testFuzz_decoder_wrongBodyVersion_reverts(uint32 v) public {
        vm.assume(v != 1);
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.bodyVersion = v;
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongBodyVersion.selector, v));
    }

    function test_decoder_headerVersionZeroAndTwo_revert() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.headerVersion = 0;
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongHeaderVersion.selector, uint32(0)));
        m.headerVersion = 2;
        _expectSettleRevert(id, m, abi.encodeWithSelector(CctpMessageDecoder.WrongHeaderVersion.selector, uint32(2)));
    }

    // ───────────── local domain resolution ─────────────

    function test_localDomain_transmitterReportedValueIsLive() public {
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        transmitter.setDomain(30); // transmitter now reports 30; stored value is stale
        Msg memory m = _msg(SENT, 0, NONCE);
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, uint32(30), LOCAL_DOMAIN));
        m.destinationDomain = 30;
        _settle(id, m, SENT);
        assertEq(vault.pendingCrossChain(id), 0);
    }

    function test_localDomain_fallbackToStoredWhenTransmitterLacksLocalDomain() public {
        MockTransmitterM plain = new MockTransmitterM(usdc);
        vm.prank(owner);
        vault.setMessageTransmitter(address(plain));
        assertEq(vault.localDomain(), LOCAL_DOMAIN, "fallback to constructor sourceDomain");
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        m.destinationDomain = 5;
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, LOCAL_DOMAIN, uint32(5)));
        m.destinationDomain = LOCAL_DOMAIN;
        plain.arm(address(vault), SENT);
        bytes memory message = _encode(m);
        vm.prank(manager);
        vault.settleCrossChainWithMessage(id, message, "");
        assertEq(vault.pendingCrossChain(id), 0);
    }

    function test_localDomain_zeroIsValid_forInboundDestination() public {
        transmitter.setDomain(0);
        vm.prank(owner);
        vault.setMessageTransmitter(address(transmitter)); // refresh stored domain from transmitter
        assertEq(vault.localDomain(), 0);
        uint64 id = _deploy(REMOTE_DOMAIN, SENT);
        Msg memory m = _msg(SENT, 0, NONCE);
        _expectSettleRevert(id, m, abi.encodeWithSelector(AutonomousVault.WrongDestinationDomain.selector, uint32(0), LOCAL_DOMAIN));
        m.destinationDomain = 0;
        _settle(id, m, SENT);
        assertEq(vault.pendingCrossChain(id), 0);
    }
}

contracts/test/TaskNFixesTest.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Vm}      from "forge-std/Vm.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20}  from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {ShariahVaultV2}         from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TaskNDustBase}          from "./TaskNTest.DustBase.t.sol";

/// @dev Minimal gold adapter with scriptable value / price sanity.
contract MockGoldAdapterFix {
    function isGoldStrategy() external pure returns (bool) { return true; }
    uint256 public currentValue;
    bool    public isPriceSane = true;
    function set(uint256 v_, bool sane_) external { currentValue = v_; isPriceSane = sane_; }
}

/// @dev R-1 (effectiveDustThreshold) and R-3 (gold adapter exposure lock) — run on V1 and V2.
abstract contract TaskNFixesCommon is TaskNDustBase {
    uint256 internal constant NAV = 1_000_000e6; // cap = 5_000e6

    function _mock(uint256 val, bool sane) internal returns (MockGoldAdapterFix m) {
        m = new MockGoldAdapterFix();
        m.set(val, sane);
    }

    function _confirmThreshold(uint256 val) internal {
        _propose(val);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), val, "threshold confirmed");
    }

    function _aliceCanDeposit(uint256 amt) internal returns (bool ok) {
        usdc.mint(alice, amt);
        vm.startPrank(alice);
        usdc.approve(address(v), type(uint256).max);
        try v.deposit(amt, alice) { ok = true; } catch { ok = false; }
        vm.stopPrank();
    }

    // ───────────────────────── R-1 ─────────────────────────

    function test_R1_constants() public view {
        assertEq(v.MIN_DUST_CAP(), 1e6);
        assertEq(v.MAX_DUST_BPS(), 50);
    }

    function test_R1_shrinkingAum_clampsEffective_andRepausesStaleGold() public {
        _setAssets(NAV);
        _openGold(4_000e6);
        uint256 X = goldAdapter.currentValue();
        assertGt(X, 500e6, "X above clamped value");
        assertLe(X, 5_000e6, "X within confirmed threshold");

        _confirmThreshold(5_000e6);
        // Matching principal bookkeeping now recognizes the stale haircut in NAV; restore the intended AUM boundary.
        _setAssets(NAV);
        assertFalse(goldAdapter.isPriceSane(), "oracle stale");
        assertEq(v.effectiveDustThreshold(), 5_000e6, "full threshold at 1M AUM");
        assertGt(v.maxDeposit(alice), 0, "deposits open at 1M AUM");
        assertGt(v.maxMint(alice), 0, "mints open at 1M AUM");
        assertTrue(_aliceCanDeposit(10e6));

        _setAssets(100_000e6);
        assertEq(v.dustThreshold(), 5_000e6, "stored threshold unchanged by shrink");
        assertEq(v.effectiveDustThreshold(), 500e6, "effective clamped to 0.5% of AUM");
        assertEq(v.maxDeposit(alice), 0, "deposits paused again");
        assertEq(v.maxMint(alice), 0, "mints paused again");
        assertFalse(_aliceCanDeposit(10e6));

        // AUM recovery lifts the clamp again.
        _setAssets(NAV);
        assertEq(v.effectiveDustThreshold(), 5_000e6);
        assertGt(v.maxDeposit(alice), 0, "resumed after AUM recovery");
    }

    function test_R1_defaultThreshold_atHighAum_isStoredValue() public {
        _setAssets(NAV);
        assertEq(v.dustThreshold(), 1e6);
        assertEq(v.effectiveDustThreshold(), 1e6);
    }

    function test_R1_floor_whenAssetsTinyOrZero() public {
        _setAssets(NAV);
        _confirmThreshold(5_000e6);

        _setAssets(0);
        assertEq(v.effectiveDustThreshold(), 1e6, "zero assets -> floor");
        _setAssets(1);
        assertEq(v.effectiveDustThreshold(), 1e6, "1 wei -> floor");
        _setAssets(199_999_999); // cap = 999_999 < floor
        assertEq(v.effectiveDustThreshold(), 1e6, "sub-floor cap -> floor");
        _setAssets(200e6); // cap == 1e6
        assertEq(v.effectiveDustThreshold(), 1e6);
        _setAssets(400e6); // cap == 2e6
        assertEq(v.effectiveDustThreshold(), 2e6);
        assertEq(v.dustThreshold(), 5_000e6, "stored never mutated");
    }

    function test_R1_zeroAssets_defaultThreshold() public view {
        assertEq(v.totalAssets(), 0);
        assertEq(v.effectiveDustThreshold(), 1e6);
    }

    function test_R1_storedBelowCap_staysStored_untilCapFallsBelowIt() public {
        _setAssets(NAV);
        _confirmThreshold(2_000e6);
        assertEq(v.effectiveDustThreshold(), 2_000e6);
        _setAssets(300_000e6); // cap 1_500e6
        assertEq(v.effectiveDustThreshold(), 1_500e6);
        _setAssets(4_000_000e6); // cap 20_000e6, never above stored
        assertEq(v.effectiveDustThreshold(), 2_000e6);
    }

    function test_R1_boundary_positionEqualToEffective_doesNotPause_oneAbovePauses() public {
        _setAssets(NAV);
        _confirmThreshold(5_000e6);
        MockGoldAdapterFix m = _mock(0, false);
        vm.prank(owner);
        v.setGoldAllocationAdapter(address(m));

        _setAssets(100_000e6); // effective = 500e6
        // Keep market value at zero: only funded principal decides the dust boundary.
        _setPrincipal(address(m), 500e6);
        _setAssets(100_000e6);
        assertGt(v.maxDeposit(alice), 0, "== effective: open");
        assertGt(v.maxMint(alice), 0);
        _setPrincipal(address(m), 500e6 + 1);
        _setAssets(100_000e6);
        assertEq(v.maxDeposit(alice), 0, "> effective & insane: paused");
        assertEq(v.maxMint(alice), 0);
        m.set(500e6 + 1, true);
        assertGt(v.maxDeposit(alice), 0, "sane price never pauses");
    }

    function testFuzz_R1_effectiveFormula(uint256 a1, uint256 t, uint256 a2) public {
        a1 = bound(a1, 0, 1e15);
        a2 = bound(a2, 0, 1e15);
        t  = bound(t, 0, _cap(a1));
        _setAssets(a1);
        _confirmThreshold(t);
        _setAssets(a2);

        uint256 eff = v.effectiveDustThreshold();
        uint256 c   = _cap(a2);
        assertLe(eff, v.dustThreshold(), "never exceeds stored");
        assertLe(eff, c, "never exceeds current cap");
        assertEq(eff, t < c ? t : c, "min(stored, max(floor, 0.5% AUM))");
        assertEq(v.dustThreshold(), t, "stored unchanged by AUM moves");
    }

    // Return transfers must retire strategy cost without changing base transfer/access/pause semantics.
    function test_returnCapital_retiresPrincipalClamped_andPreservesNav() public {
        _setAssets(NAV);
        MockGoldAdapterFix m = _mock(0, true);
        _setPrincipal(address(m), 100e6);
        usdc.mint(address(m), 150e6);
        vm.prank(address(m));
        usdc.approve(address(v), 150e6);
        uint256 nav = v.totalAssets();
        vm.expectEmit(true, false, false, true, address(v));
        emit ShariahVault.PrincipalRetired(address(m), 40e6, 40e6);
        vm.prank(manager);
        v.returnCapital(address(m), 40e6);
        assertEq(v.principalOf(address(m)), 60e6);
        assertEq(v.totalDeployed(), 60e6);
        assertEq(v.totalAssets(), nav);
        _setPrincipal(address(goldAdapter), 50e6);
        vm.prank(owner);
        v.returnCapital(address(m), 100e6);
        assertEq(v.principalOf(address(m)), 0);
        // G-3 excess proceeds are profit, not retirement of another position's cost.
        assertEq(v.totalDeployed(), 50e6, "other position remains deployed");
        assertEq(v.principalOf(address(goldAdapter)), 50e6);
    }

    // A zero market value cannot bypass either slot's cost lock; write-off is owner-only and atomic.
    function test_writeOffPrincipal_zeroValue_required_andClamped() public {
        _setAssets(NAV);
        MockGoldAdapterFix m = _mock(0, false);
        vm.startPrank(owner);
        v.setGoldAllocationAdapter(address(m));
        vm.stopPrank();
        _setPrincipal(address(m), 100e6);
        assertEq(v.maxDeposit(alice), 0, "zero value does not silence material cost");
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(m), uint256(100e6)));
        v.setGoldAllocationAdapter(address(0));
        m.set(1, false);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(m), uint256(1)));
        v.writeOffAdapterPrincipal(address(m));
        vm.stopPrank();
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, manager));
        v.writeOffAdapterPrincipal(address(m));
        m.set(0, false);
        // Simulate historical aggregate desync: full adapter cost retires while aggregate subtraction clamps.
        _setAggregateDeployed(50e6);
        vm.expectEmit(true, false, false, true, address(v));
        emit ShariahVault.PrincipalRetired(address(m), 100e6, 0);
        vm.prank(owner);
        v.writeOffAdapterPrincipal(address(m));
        assertEq(v.principalOf(address(m)), 0);
        assertEq(v.totalDeployed(), 0);
        vm.prank(owner);
        v.setGoldAllocationAdapter(address(0));
        assertGt(v.maxDeposit(alice), 0);
    }

    // ───────────────────────── R-3 ─────────────────────────

    function test_R3_spread_exposure_blocksReplaceClearAndSame() public {
        _openGold(4_000e6);
        uint256 val = goldAdapter.currentValue();
        assertGt(val, 0);
        MockGoldAdapterFix other = _mock(0, true);
        bytes memory err = abi.encodeWithSelector(
            ShariahVault.GoldAdapterHasExposure.selector, address(goldAdapter), val
        );
        vm.startPrank(owner);
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(other));
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(0));
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(goldAdapter));
        vm.stopPrank();
        assertEq(v.goldSpreadAdapter(), address(goldAdapter), "pointer unchanged");
    }

    function test_R3_spread_zeroValue_allowsReplaceClearSame_andFromZero() public {
        assertEq(goldAdapter.currentValue(), 0);
        MockGoldAdapterFix other = _mock(0, true);

        vm.startPrank(owner);
        v.setGoldSpreadAdapter(address(goldAdapter)); // same address, zero value
        vm.expectEmit(true, false, false, false, address(v));
        emit ShariahVault.GoldSpreadAdapterUpdated(address(other));
        v.setGoldSpreadAdapter(address(other)); // replace
        assertEq(v.goldSpreadAdapter(), address(other));
        v.setGoldSpreadAdapter(address(0)); // clear
        assertEq(v.goldSpreadAdapter(), address(0));
        v.setGoldSpreadAdapter(address(goldAdapter)); // from zero
        vm.stopPrank();
        assertEq(v.goldSpreadAdapter(), address(goldAdapter));
    }

    function test_R3_spread_replacementWithExposure_isLockedToo_thenUnlocksAtZero() public {
        MockGoldAdapterFix m = _mock(5, true);
        vm.startPrank(owner);
        v.setGoldSpreadAdapter(address(m));
        bytes memory err = abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(m), uint256(5));
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(0));
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(m));
        m.set(0, true);
        v.setGoldSpreadAdapter(address(0));
        vm.stopPrank();
        assertEq(v.goldSpreadAdapter(), address(0));
    }

    function test_R3_allocation_fromZero_allowed_andEmits() public {
        assertEq(v.goldAllocationAdapter(), address(0));
        MockGoldAdapterFix m = _mock(123e6, true); // value irrelevant while tracked is zero
        vm.expectEmit(true, false, false, false, address(v));
        emit ShariahVault.GoldAllocationAdapterUpdated(address(m));
        vm.prank(owner);
        v.setGoldAllocationAdapter(address(m));
        assertEq(v.goldAllocationAdapter(), address(m));
    }

    function test_R3_allocation_exposure_blocksReplaceClearAndSame() public {
        MockGoldAdapterFix m = _mock(1, true);
        MockGoldAdapterFix other = _mock(0, true);
        vm.startPrank(owner);
        v.setGoldAllocationAdapter(address(m));
        bytes memory err = abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(m), uint256(1));
        vm.expectRevert(err);
        v.setGoldAllocationAdapter(address(other));
        vm.expectRevert(err);
        v.setGoldAllocationAdapter(address(0));
        vm.expectRevert(err);
        v.setGoldAllocationAdapter(address(m));
        vm.stopPrank();
        assertEq(v.goldAllocationAdapter(), address(m), "pointer unchanged");
    }

    function test_R3_allocation_zeroValue_allowsReplaceClearSame() public {
        MockGoldAdapterFix m = _mock(0, true);
        MockGoldAdapterFix other = _mock(0, true);
        vm.startPrank(owner);
        v.setGoldAllocationAdapter(address(m));
        v.setGoldAllocationAdapter(address(m));
        v.setGoldAllocationAdapter(address(other));
        assertEq(v.goldAllocationAdapter(), address(other));
        v.setGoldAllocationAdapter(address(0));
        vm.stopPrank();
        assertEq(v.goldAllocationAdapter(), address(0));
    }

    function test_R3_exposureOnOneSlot_doesNotLockTheOther() public {
        _openGold(4_000e6); // spread has exposure
        MockGoldAdapterFix m = _mock(0, true);
        vm.startPrank(owner);
        v.setGoldAllocationAdapter(address(m));
        v.setGoldAllocationAdapter(address(0));
        vm.stopPrank();
        m.set(9, true);
        vm.startPrank(owner);
        v.setGoldAllocationAdapter(address(0)); // already zero -> allowed
        v.setGoldAllocationAdapter(address(m));
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(m), uint256(9)));
        v.setGoldAllocationAdapter(address(0));
        vm.stopPrank();
    }

    function test_R3_nonOwner_cannotSetAdapters() public {
        vm.startPrank(stranger);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, stranger));
        v.setGoldSpreadAdapter(address(0));
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, stranger));
        v.setGoldAllocationAdapter(address(0));
        vm.stopPrank();
    }

    function test_R3_attack_unlinkToSilenceDepositPause_isBlockedWhileStalePositionExists() public {
        _setAssets(NAV);
        _openGold(4_000e6);
        vm.warp(block.timestamp + 2 days);
        assertFalse(goldAdapter.isPriceSane(), "oracle stale");
        uint256 X = goldAdapter.currentValue();
        assertGt(X, v.effectiveDustThreshold());
        assertEq(v.maxDeposit(alice), 0, "paused by stale position");

        MockGoldAdapterFix clean = _mock(0, true);
        bytes memory err = abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector, address(goldAdapter), X);
        vm.startPrank(owner);
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(0));
        vm.expectRevert(err);
        v.setGoldSpreadAdapter(address(clean));
        vm.stopPrank();
        assertEq(v.maxDeposit(alice), 0, "still paused");
        assertEq(v.maxMint(alice), 0);
        assertFalse(_aliceCanDeposit(10e6));

        // Zero value alone cannot unlink unretired cost; explicitly recognize the loss first.
        vm.mockCall(address(goldAdapter), abi.encodeWithSignature("currentValue()"), abi.encode(uint256(0)));
        vm.startPrank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.GoldAdapterHasExposure.selector,
            address(goldAdapter), v.principalOf(address(goldAdapter))));
        v.setGoldSpreadAdapter(address(0));
        v.writeOffAdapterPrincipal(address(goldAdapter));
        v.setGoldSpreadAdapter(address(0));
        vm.stopPrank();
        assertGt(v.maxDeposit(alice), 0);
    }
}

contract TaskNFixesV1Test is TaskNFixesCommon {
    function _deployVault() internal override {
        v = new ShariahVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0));
    }
    function _board() internal view override returns (address) { return owner; }
    function _denied() internal view override returns (address[] memory d) { d = new address[](0); }
}

/// @dev V2 flavour + R-2 registry replacement (propose / confirm / cancel with 30-day timelock).
contract TaskNFixesV2Test is TaskNFixesCommon {
    ShariahAdapterRegistry internal registry; // board = boardMember, registry owner = owner (NOT board)
    ShariahAdapterRegistry internal r2;       // honest replacement, board = newBoard
    ShariahVaultV2         internal v2;
    address internal newBoard = makeAddr("newBoard");
    address internal strat    = makeAddr("strat");

    function _deployVault() internal override {
        registry = new ShariahAdapterRegistry(owner, boardMember);
        v = new ShariahVaultV2(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0), address(registry)
        );
        v2 = ShariahVaultV2(address(v));
        r2 = new ShariahAdapterRegistry(owner, newBoard);
    }
    function _board() internal view override returns (address) { return boardMember; }
    function _denied() internal view override returns (address[] memory d) { d = new address[](0); }

    function _nbe(address who) internal pure returns (bytes memory) {
        return abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who);
    }
    function _proposeReg(address r) internal {
        vm.prank(boardMember);
        v2.proposeRegistry(r);
    }
    function _pendingReg() internal view returns (address nr, uint256 ea, bool ex) {
        return v2.pendingRegistry();
    }

    // ── surface ──

    function test_R2_timelockConstant_andNoSetRegistry() public {
        assertEq(v2.REGISTRY_TIMELOCK(), 30 days);
        (bool okOwner,) = address(v2).call(abi.encodeWithSignature("setRegistry(address)", address(r2)));
        assertFalse(okOwner, "setRegistry removed");
        vm.prank(owner);
        (bool ok,) = address(v2).call(abi.encodeWithSignature("setRegistry(address)", address(r2)));
        assertFalse(ok, "setRegistry removed (owner)");
        assertEq(address(v2.registry()), address(registry));
        (, , bool ex) = _pendingReg();
        assertFalse(ex);
    }

    // ── authorization against a live registry ──

    function test_R2_ownerWithoutBoardRole_cannotProposeConfirmOrCancel() public {
        assertFalse(registry.isBoard(owner));
        vm.prank(owner);
        vm.expectRevert(_nbe(owner));
        v2.proposeRegistry(address(r2));

        _proposeReg(address(r2));
        vm.warp(block.timestamp + 30 days);
        vm.startPrank(owner);
        vm.expectRevert(_nbe(owner));
        v2.confirmRegistry();
        vm.expectRevert(_nbe(owner));
        v2.cancelRegistry();
        vm.stopPrank();

        address[3] memory others = [stranger, manager, alice];
        for (uint256 i = 0; i < others.length; i++) {
            vm.startPrank(others[i]);
            vm.expectRevert(_nbe(others[i]));
            v2.proposeRegistry(address(r2));
            vm.expectRevert(_nbe(others[i]));
            v2.confirmRegistry();
            vm.expectRevert(_nbe(others[i]));
            v2.cancelRegistry();
            vm.stopPrank();
        }
        (address nr, , bool ex) = _pendingReg();
        assertTrue(ex);
        assertEq(nr, address(r2));
        assertEq(address(v2.registry()), address(registry));
    }

    function test_R2_boardMember_proposeAndConfirm_afterTimelock() public {
        uint256 t0 = block.timestamp;
        vm.expectEmit(false, false, false, true, address(v));
        emit ShariahVaultV2.RegistryProposed(address(r2), t0 + 30 days);
        _proposeReg(address(r2));
        (address nr, uint256 ea, bool ex) = _pendingReg();
        assertEq(nr, address(r2));
        assertEq(ea, t0 + 30 days);
        assertTrue(ex);
        assertEq(address(v2.registry()), address(registry), "not applied on propose");

        vm.warp(t0 + 30 days);
        vm.expectEmit(true, false, false, false, address(v));
        emit ShariahVaultV2.RegistryUpdated(address(r2));
        vm.prank(boardMember);
        v2.confirmRegistry();
        assertEq(address(v2.registry()), address(r2));
        (address nr2, uint256 ea2, bool ex2) = _pendingReg();
        assertEq(nr2, address(0));
        assertEq(ea2, 0);
        assertFalse(ex2, "pending cleared");

        // Governance now follows the new registry.
        vm.prank(boardMember);
        vm.expectRevert(_nbe(boardMember));
        v.proposeDustThreshold(1e6);
        vm.prank(newBoard);
        v.proposeDustThreshold(1e6);
    }

    function test_R2_confirm_oneSecondEarly_reverts_exactTimelock_succeeds() public {
        uint256 t0 = block.timestamp;
        _proposeReg(address(r2));
        vm.warp(t0 + 30 days - 1);
        vm.prank(boardMember);
        vm.expectRevert(abi.encodeWithSelector(
            ShariahVaultV2.RegistryTimelockNotElapsed.selector, t0 + 30 days, t0 + 30 days - 1
        ));
        v2.confirmRegistry();
        assertEq(address(v2.registry()), address(registry));

        vm.warp(t0 + 30 days);
        vm.prank(boardMember);
        v2.confirmRegistry();
        assertEq(address(v2.registry()), address(r2));
    }

    function test_R2_confirmAndCancel_withoutProposal_revert() public {
        vm.startPrank(boardMember);
        vm.expectRevert(ShariahVaultV2.NoPendingRegistryProposal.selector);
        v2.confirmRegistry();
        vm.expectRevert(ShariahVaultV2.NoPendingRegistryProposal.selector);
        v2.cancelRegistry();
        vm.stopPrank();
    }

    function test_R2_cancel_clearsPending_blocksConfirm_andAllowsRepropose() public {
        _proposeReg(address(r2));
        vm.expectEmit(false, false, false, false, address(v));
        emit ShariahVaultV2.RegistryProposalCancelled();
        vm.prank(boardMember);
        v2.cancelRegistry(); // no waiting needed
        (, , bool ex) = _pendingReg();
        assertFalse(ex);

        vm.warp(block.timestamp + 30 days);
        vm.prank(boardMember);
        vm.expectRevert(ShariahVaultV2.NoPendingRegistryProposal.selector);
        v2.confirmRegistry();

        ShariahAdapterRegistry r3 = new ShariahAdapterRegistry(owner, newBoard);
        uint256 t1 = block.timestamp;
        vm.prank(boardMember);
        v2.proposeRegistry(address(r3));
        (address nr, uint256 ea, bool ex2) = _pendingReg();
        assertEq(nr, address(r3));
        assertEq(ea, t1 + 30 days, "fresh timelock after re-propose");
        assertTrue(ex2);
        assertEq(address(v2.registry()), address(registry));
    }

    function test_R2_duplicatePropose_reverts() public {
        _proposeReg(address(r2));
        ShariahAdapterRegistry r3 = new ShariahAdapterRegistry(owner, newBoard);
        vm.startPrank(boardMember);
        vm.expectRevert(ShariahVaultV2.RegistryProposalAlreadyExists.selector);
        v2.proposeRegistry(address(r2));
        vm.expectRevert(ShariahVaultV2.RegistryProposalAlreadyExists.selector);
        v2.proposeRegistry(address(r3));
        vm.stopPrank();
        (address nr, , ) = _pendingReg();
        assertEq(nr, address(r2), "original proposal retained");
    }

    function test_R2_proposeZeroRegistry_reverts() public {
        vm.prank(boardMember);
        vm.expectRevert(ShariahVaultV2.ZeroRegistry.selector);
        v2.proposeRegistry(address(0));
        (, , bool ex) = _pendingReg();
        assertFalse(ex);
    }

    // ── interaction with dust governance ──

    function test_R2_confirm_clearsPendingDustProposal_andEmits() public {
        _setAssets(NAV);
        _propose(2_000e6);
        _proposeReg(address(r2));
        vm.warp(block.timestamp + 30 days);
        vm.expectEmit(false, false, false, false, address(v));
        emit ShariahVault.DustThresholdProposalCancelled();
        vm.prank(boardMember);
        v2.confirmRegistry();
        (, , bool exists) = _pending();
        assertFalse(exists, "dust proposal cleared");
        assertEq(v.dustThreshold(), 1e6, "stored threshold untouched");
    }

    function test_R2_confirm_withoutDustProposal_emitsNoDustCancelled() public {
        _proposeReg(address(r2));
        vm.warp(block.timestamp + 30 days);
        vm.recordLogs();
        vm.prank(boardMember);
        v2.confirmRegistry();
        Vm.Log[] memory logs = vm.getRecordedLogs();
        bytes32 dustSig = keccak256("DustThresholdProposalCancelled()");
        bytes32 updSig  = keccak256("RegistryUpdated(address)");
        bool sawUpdated;
        for (uint256 i = 0; i < logs.length; i++) {
            assertTrue(logs[i].topics[0] != dustSig, "no dust cancel event");
            if (logs[i].topics[0] == updSig) sawUpdated = true;
        }
        assertTrue(sawUpdated);
    }

    // ── the review attack ──

    function test_R2_attack_ownerSwapsInOwnedRegistryToSelfAppointBoard_isImpossible() public {
        _setAssets(NAV);
        _propose(2_000e6);                         // honest board proposal ...
        vm.warp(block.timestamp + DUST_TIMELOCK);  // ... matured

        // Owner builds a registry where owner is board.
        ShariahAdapterRegistry evil = new ShariahAdapterRegistry(owner, owner);
        assertTrue(evil.isBoard(owner));

        vm.startPrank(owner);
        vm.expectRevert(_nbe(owner));
        v2.proposeRegistry(address(evil));
        vm.expectRevert(_nbe(owner));
        v2.confirmRegistry();
        vm.expectRevert(_nbe(owner));
        v2.cancelRegistry();
        vm.expectRevert(_nbe(owner));
        v.confirmDustThreshold(); // cannot confirm the matured proposal either
        (bool ok,) = address(v2).call(abi.encodeWithSignature("setRegistry(address)", address(evil)));
        assertFalse(ok);
        vm.stopPrank();

        assertEq(address(v2.registry()), address(registry), "registry unchanged");
        (, , bool pendingReg) = _pendingReg();
        assertFalse(pendingReg);
        (, , bool dustPending) = _pending();
        assertTrue(dustPending, "dust proposal untouched");
        assertEq(v.dustThreshold(), 1e6);

        // The honest board can still finish its own proposal.
        _confirm();
        assertEq(v.dustThreshold(), 2_000e6);
    }

    // ── deployCapital screening follows the OLD registry until confirm ──

    function test_R2_deployCapital_oldRegistryScreening_appliesUntilConfirm() public {
        _setAssets(NAV);
        uint256 t0 = block.timestamp;
        vm.startPrank(boardMember);
        registry.proposeScreening(strat, keccak256("old"), t0 + 300 days);
        v2.proposeRegistry(address(r2));
        vm.stopPrank();
        vm.warp(t0 + 30 days);
        vm.prank(boardMember);
        registry.executeScreening(strat);

        vm.prank(manager);
        v.deployCapital(strat, 1_000e6, ""); // proposal pending, old registry still decides
        assertEq(usdc.balanceOf(strat), 1_000e6);

        vm.prank(boardMember);
        v2.confirmRegistry();
        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(ShariahVaultV2.NotScreened.selector, strat));
        v.deployCapital(strat, 1_000e6, "");
    }

    function test_R2_deployCapital_newRegistryScreening_ignoredUntilConfirm() public {
        _setAssets(NAV);
        uint256 t0 = block.timestamp;
        vm.prank(newBoard);
        r2.proposeScreening(strat, keccak256("new"), t0 + 300 days);
        _proposeReg(address(r2));
        vm.warp(t0 + 30 days);
        vm.prank(newBoard);
        r2.executeScreening(strat);

        vm.prank(manager);
        vm.expectRevert(abi.encodeWithSelector(ShariahVaultV2.NotScreened.selector, strat));
        v.deployCapital(strat, 1_000e6, "");

        vm.prank(boardMember);
        v2.confirmRegistry();
        vm.prank(manager);
        v.deployCapital(strat, 1_000e6, "");
        assertEq(usdc.balanceOf(strat), 1_000e6);
    }

    // ── bootstrap (current registry == address(0)) ──

    function _zeroRegVault() internal returns (ShariahVaultV2 z) {
        z = new ShariahVaultV2(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0), address(0)
        );
    }

    function test_R2_bootstrap_nonOwner_cannotPropose_confirm_orCancel() public {
        ShariahVaultV2 z = _zeroRegVault();
        address[3] memory who = [boardMember, alice, stranger];
        for (uint256 i = 0; i < who.length; i++) {
            bytes memory err = abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, who[i]);
            vm.startPrank(who[i]);
            vm.expectRevert(err);
            z.proposeRegistry(address(registry));
            vm.expectRevert(err);
            z.confirmRegistry();
            vm.expectRevert(err);
            z.cancelRegistry();
            vm.stopPrank();
        }
    }

    function test_R2_bootstrap_ownerProposesAndConfirmsImmediately_noBoardCheck() public {
        ShariahVaultV2 z = _zeroRegVault();
        assertFalse(registry.isBoard(owner), "owner is not board anywhere");

        vm.expectEmit(false, false, false, true, address(z));
        emit ShariahVaultV2.RegistryProposed(address(registry), block.timestamp);
        vm.startPrank(owner);
        z.proposeRegistry(address(registry));
        vm.expectEmit(true, false, false, false, address(z));
        emit ShariahVaultV2.RegistryUpdated(address(registry));
        z.confirmRegistry(); // same block, no delay
        vm.stopPrank();

        assertEq(address(z.registry()), address(registry));
        (, , bool ex) = z.pendingRegistry();
        assertFalse(ex);
    }

    function test_R2_bootstrap_zeroDuplicateMissingAndCancel() public {
        ShariahVaultV2 z = _zeroRegVault();
        vm.startPrank(owner);
        vm.expectRevert(ShariahVaultV2.ZeroRegistry.selector);
        z.proposeRegistry(address(0));
        vm.expectRevert(ShariahVaultV2.NoPendingRegistryProposal.selector);
        z.confirmRegistry();
        vm.expectRevert(ShariahVaultV2.NoPendingRegistryProposal.selector);
        z.cancelRegistry();

        z.proposeRegistry(address(registry));
        vm.expectRevert(ShariahVaultV2.RegistryProposalAlreadyExists.selector);
        z.proposeRegistry(address(r2));
        z.cancelRegistry();
        (, , bool ex) = z.pendingRegistry();
        assertFalse(ex);
        z.proposeRegistry(address(r2));
        z.confirmRegistry();
        vm.stopPrank();
        assertEq(address(z.registry()), address(r2));
    }

    function test_R2_bootstrap_stopsBeingImmediate_afterRegistrySet() public {
        ShariahVaultV2 z = _zeroRegVault();
        vm.startPrank(owner);
        z.proposeRegistry(address(registry));
        z.confirmRegistry();
        // Owner (not board of `registry`) has lost the bootstrap powers.
        vm.expectRevert(_nbe(owner));
        z.proposeRegistry(address(r2));
        vm.expectRevert(_nbe(owner));
        z.cancelRegistry();
        vm.stopPrank();

        uint256 t0 = block.timestamp;
        vm.prank(boardMember);
        z.proposeRegistry(address(r2));
        (, uint256 ea, ) = z.pendingRegistry();
        assertEq(ea, t0 + 30 days, "delay applies after bootstrap");
        vm.prank(boardMember);
        vm.expectRevert(abi.encodeWithSelector(
            ShariahVaultV2.RegistryTimelockNotElapsed.selector, t0 + 30 days, t0
        ));
        z.confirmRegistry();
        vm.prank(owner);
        vm.expectRevert(_nbe(owner));
        z.confirmRegistry();
    }
}

