// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {TreasuryModule}         from "../TreasuryModule.sol";
import {GoldExchangeAdapter}    from "../adapters/GoldExchangeAdapter.sol";
import {GoldAllocationAdapter}  from "../adapters/GoldAllocationAdapter.sol";
import {MockERC20}              from "../test-helpers/MockERC20.sol";
import {MockAllocatedGold}      from "../test-helpers/MockAllocatedGold.sol";
import {MockXAUT}               from "../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}   from "../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT}  from "../test-helpers/MockUniswapV3PoolXAUT.sol";
import {RemoteRecipientFixture, MockTokenMessengerI}    from "./TaskITest.Base.t.sol";

/// @dev Fixed-price USDC<->PAXG router (price = USDC 6-dec units per 1e18 PAXG).
contract MockGoldRouterN {
    address public immutable usdc;
    uint256 public priceUsdc;

    // G-1 recall regressions need execution prices to follow oracle appreciation.
    function setPrice(uint256 price) external { priceUsdc = price; }

    constructor(address usdc_, uint256 priceUsdc_) {
        usdc = usdc_;
        priceUsdc = priceUsdc_;
    }

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata p) external returns (uint256 out) {
        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        out = p.tokenIn == usdc ? (p.amountIn * 1e18) / priceUsdc : (p.amountIn * priceUsdc) / 1e18;
        require(out >= p.amountOutMinimum, "MockGoldRouterN: slippage");
        IERC20(p.tokenOut).transfer(p.recipient, out);
    }
}

/// @dev Permissive IStrategyAdapter so RiskTieredExecutor (which is not the vault) can
///      run its `adapter.deploy()` leg. Holds whatever USDC the vault sent.
contract MockStrategyAdapterN {
    address public vault;
    constructor(address vault_) { vault = vault_; }
    // Record the caller to distinguish vault-funded execution from the unchanged conventional flow.
    address public lastDeployCaller;
    bool public reenter;
    function setReenter(bool enabled) external { reenter = enabled; }
    function deploy(uint256 amount) external returns (uint256) {
        lastDeployCaller = msg.sender;
        if (reenter) ShariahVault(vault).deployCapitalAndExecute(address(this), amount, "");
        return amount;
    }
    function recall(uint256) external pure returns (uint256) { return 0; }
    function currentValue() external pure returns (uint256) { return 0; }
    function protocolName() external pure returns (string memory) { return "MockStrategyN"; }
}

/// @dev Shared N1 fixture: ShariahVault holding REAL gold in both S2-H (GoldExchangeAdapter)
///      and S6-H (GoldAllocationAdapter), with a configured mock TokenMessenger.
///      No test/fuzz/invariant functions here.
abstract contract TaskNBase is Test {
    address internal owner    = makeAddr("owner");
    address internal manager  = makeAddr("manager");
    address internal alice    = makeAddr("alice");
    address internal stranger = makeAddr("stranger");

    uint32  internal constant SOURCE_DOMAIN = 26;
    uint32  internal constant DEST_DOMAIN   = 3;
    uint8   internal constant ETH_SPREAD    = 0;
    uint8   internal constant GOLD_SPREAD   = 1;
    uint8   internal constant HALAL_LP      = 2;
    uint8   internal constant MURABAHA      = 3;
    uint8   internal constant GOLD_ALLOC    = 5;
    uint256 internal constant PAXG_PRICE    = 3_300e6;
    uint256 internal constant POOL_PRICE    = 3_300_000_000;
    uint256 internal constant DEPOSIT       = 1_000_000e6;
    uint256 internal constant GOLD_BUY      = 100_000e6;

    MockERC20             internal usdc;
    MockAllocatedGold     internal paxg;
    MockXAUT              internal xaut;
    MockXauUsdAggregator  internal oracle;
    MockUniswapV3PoolXAUT internal pool;
    MockGoldRouterN       internal router;
    MockTokenMessengerI   internal messenger;
    TreasuryModule        internal treasury;
    ShariahVault          internal svault;
    GoldExchangeAdapter   internal goldAdapter;   // S2-H
    GoldAllocationAdapter internal allocAdapter;  // S6-H

    function setUp() public virtual {
        vm.warp(1_700_000_000);

        usdc      = new MockERC20("Mock USDC", "mUSDC", 6);
        paxg      = new MockAllocatedGold();
        xaut      = new MockXAUT();
        oracle    = new MockXauUsdAggregator();
        pool      = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), POOL_PRICE);
        router    = new MockGoldRouterN(address(usdc), PAXG_PRICE);
        messenger = new MockTokenMessengerI();

        vm.startPrank(owner);
        // adminFeeBps = 0 so Wakala accrual never needs a feeSource.
        treasury = new TreasuryModule("Shariah", address(0), address(usdc), 0, 0, 0, owner);
        svault = new ShariahVault(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0)
        );
        svault.setManager(manager);
        goldAdapter = new GoldExchangeAdapter(
            address(usdc), address(paxg), address(router), 3000,
            address(svault), owner, address(oracle)
        );
        allocAdapter = new GoldAllocationAdapter(
            address(usdc), address(xaut), address(pool), 3000,
            address(oracle), address(svault), 3600, owner
        );
        svault.setScreened(address(goldAdapter), true);
        svault.setScreened(address(allocAdapter), true);
        svault.setGoldSpreadAdapter(address(goldAdapter));
        svault.setGoldAllocationAdapter(address(allocAdapter));
        svault.setTokenMessenger(address(messenger));
        svault.setMaxPendingCrossChainBps(5_000);
        vm.stopPrank();

        // Liquidity for the swap venues.
        paxg.mint(address(router), 1_000_000e18);
        usdc.mint(address(router), 50_000_000e6);
        usdc.mint(address(this), 50_000_000e6);
        xaut.mint(address(this), 20_000e6);
        usdc.approve(address(pool), 50_000_000e6);
        xaut.approve(address(pool), 20_000e6);
        pool.fundPool(50_000_000e6, 20_000e6);

        usdc.mint(alice, DEPOSIT);
        vm.startPrank(alice);
        usdc.approve(address(svault), DEPOSIT);
        svault.deposit(DEPOSIT, alice);
        vm.stopPrank();

        RemoteRecipientFixture.approve(vm, svault, owner, DEST_DOMAIN, _bytes32(alice));
        oracle.setPrice(330_000_000_000);

        // Hold gold in BOTH adapters.
        _buyGold(address(goldAdapter), GOLD_BUY);
        // Check realistic 6/18-dec valuation before any oracle refresh can hide entry scaling errors.
        assertApproxEqAbs(goldAdapter.currentValue(), GOLD_BUY, 1);
        assertApproxEqAbs(goldAdapter.lastGoodPrice(), PAXG_PRICE, 1);
        goldAdapter.pokePrice(); // Entry and oracle prices now share units; retain oracle-refresh coverage.
        _buyGold(address(allocAdapter), GOLD_BUY);
    }

    function _buyGold(address adapter, uint256 amount) internal {
        vm.prank(manager);
        svault.deployCapitalAndExecute(adapter, amount, "");
    }

    function _bytes32(address a) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(a)));
    }
}

contracts/test/TaskNTest.DustBase.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {stdStorage, StdStorage} from "forge-std/StdStorage.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {TreasuryModule}         from "../TreasuryModule.sol";
import {GoldExchangeAdapter}    from "../adapters/GoldExchangeAdapter.sol";
import {MockERC20}              from "../test-helpers/MockERC20.sol";
import {MockAllocatedGold}      from "../test-helpers/MockAllocatedGold.sol";
import {MockXauUsdAggregator}   from "../test-helpers/MockXauUsdAggregator.sol";
import {MockGoldRouterN}        from "./TaskNTest.Base.t.sol";

/// @dev N2 fixture. A ShariahVault flavour (V1 or V2) is created by the concrete subclass
///      via `_deployVault()`. Starts with ZERO assets; use `_setAssets` to move NAV.
///      No test/fuzz/invariant functions here.
abstract contract TaskNDustBase is Test {
    using stdStorage for StdStorage;

    // Synthetic adapter positions must include funded cost now that materiality is principal-based.
    function _setPrincipal(address adapter, uint256 principal) internal {
        uint256 old = v.principalOf(adapter);
        stdstore.target(address(v)).sig("principalOf(address)").with_key(adapter).checked_write(principal);
        stdstore.target(address(v)).sig("totalDeployed()").checked_write(v.totalDeployed() - old + principal);
    }
    function _setAggregateDeployed(uint256 amount) internal {
        stdstore.target(address(v)).sig("totalDeployed()").checked_write(amount);
    }

    address internal owner       = makeAddr("owner");
    address internal manager     = makeAddr("manager");
    address internal alice       = makeAddr("alice");
    address internal stranger    = makeAddr("stranger");
    address internal boardMember = makeAddr("boardMember");

    uint32  internal constant SOURCE_DOMAIN = 26;
    uint256 internal constant DUST_TIMELOCK = 30 days;
    uint256 internal constant PAXG_PRICE    = 3_300e6;

    MockERC20             internal usdc;
    MockAllocatedGold     internal paxg;
    MockXauUsdAggregator  internal oracle;
    MockGoldRouterN       internal router;
    TreasuryModule        internal treasury;
    GoldExchangeAdapter   internal goldAdapter;
    ShariahVault          internal v;

    /// @dev Concrete subclass creates `v` (and any registry) with `owner` as vault owner.
    function _deployVault() internal virtual;
    /// @dev The account that must be accepted as board by this vault flavour.
    function _board() internal view virtual returns (address);
    /// @dev Accounts that must be rejected with NotBoardRole.
    function _denied() internal view virtual returns (address[] memory);

    function setUp() public virtual {
        vm.warp(1_700_000_000);
        usdc   = new MockERC20("Mock USDC", "mUSDC", 6);
        paxg   = new MockAllocatedGold();
        oracle = new MockXauUsdAggregator();
        router = new MockGoldRouterN(address(usdc), PAXG_PRICE);
        paxg.mint(address(router), 1_000_000e18);
        usdc.mint(address(router), 50_000_000e6);

        treasury = new TreasuryModule("Shariah", address(0), address(usdc), 0, 0, 0, owner);
        _deployVault();

        vm.startPrank(owner);
        v.setManager(manager);
        goldAdapter = new GoldExchangeAdapter(
            address(usdc), address(paxg), address(router), 3000, address(v), owner, address(oracle)
        );
        v.setGoldSpreadAdapter(address(goldAdapter));
        vm.stopPrank();
    }

    /// @dev Move vault NAV (totalAssets) to exactly `target` by donating / burning USDC held by the vault.
    function _setAssets(uint256 target) internal {
        uint256 cur = v.totalAssets();
        if (target > cur) usdc.mint(address(v), target - cur);
        else if (target < cur) usdc.burn(address(v), cur - target);
        assertEq(v.totalAssets(), target, "NAV set");
    }

    function _cap(uint256 assets) internal pure returns (uint256 c) {
        c = (assets * 50) / 10_000;
        if (c < 1e6) c = 1e6;
    }

    function _pending() internal view returns (uint256 newValue, uint256 executeAfter, bool exists) {
        return v.pendingDustThreshold();
    }

    function _propose(uint256 value) internal {
        vm.prank(_board());
        v.proposeDustThreshold(value);
    }

    function _confirm() internal {
        vm.prank(_board());
        v.confirmDustThreshold();
    }

    function _cancel() internal {
        vm.prank(_board());
        v.cancelDustThreshold();
    }

    /// @dev Open a gold position of `usdcIn` in S2-H directly (adapter is vault-gated, so prank the vault).
    function _openGold(uint256 usdcIn) internal {
        oracle.setPrice(int256(PAXG_PRICE * 100));
        usdc.mint(address(goldAdapter), usdcIn);
        vm.prank(address(v));
        goldAdapter.deploy(usdcIn);
        goldAdapter.pokePrice(); // value the position at the oracle price
        // Direct adapter execution bypasses vault bookkeeping, so seed matching principal for dust tests.
        _setPrincipal(address(goldAdapter), v.principalOf(address(goldAdapter)) + usdcIn);
    }
}

contracts/test/TaskNTest.Eco.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {ShariahVaultV2}         from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TaskNDustBase}          from "./TaskNTest.DustBase.t.sol";

/// @dev Economic behaviour: a stale gold position larger than dustThreshold pauses deposits;
///      only a board-confirmed (30-day timelocked, NAV-capped) raise can resume them.
abstract contract TaskNEconomic is TaskNDustBase {
    uint256 internal constant NAV = 1_000_000e6; // cap = 5_000e6

    function _seedNavAndGold(uint256 goldUsdc) internal {
        usdc.mint(alice, NAV);
        vm.startPrank(alice);
        usdc.approve(address(v), type(uint256).max);
        v.deposit(NAV, alice);
        vm.stopPrank();
        _openGold(goldUsdc);
    }

    function _makeOracleStale() internal {
        vm.warp(block.timestamp + 2 days); // adapter heartbeat window is 1 day
        assertFalse(goldAdapter.isPriceSane(), "oracle stale");
    }

    function _aliceCanDeposit(uint256 amt) internal returns (bool ok) {
        usdc.mint(alice, amt);
        vm.prank(alice);
        try v.deposit(amt, alice) { ok = true; } catch { ok = false; }
    }

    function test_eco_staleGoldAboveDust_pauses_andResumesOnlyAfterConfirmedRaise() public {
        _seedNavAndGold(3_000e6);
        assertGt(v.maxDeposit(alice), 0, "fresh oracle: open");
        assertTrue(_aliceCanDeposit(10e6));

        _makeOracleStale();
        // Pause materiality uses funded cost, not the haircutted market value.
        uint256 X = v.principalOf(address(goldAdapter));
        assertGt(X, v.dustThreshold(), "position above default dust");
        assertLe(X, _cap(v.totalAssets()), "X is within the NAV cap");
        assertEq(v.maxDeposit(alice), 0, "deposits paused");
        assertEq(v.maxMint(alice), 0, "mints paused");
        assertFalse(_aliceCanDeposit(10e6));

        // proposing alone changes nothing
        uint256 t0 = block.timestamp;
        _propose(X);
        assertEq(v.maxDeposit(alice), 0, "still paused after propose");

        // 1s before the timelock: confirm fails, still paused
        vm.warp(t0 + DUST_TIMELOCK - 1);
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustTimelockNotElapsed.selector, t0 + DUST_TIMELOCK, t0 + DUST_TIMELOCK - 1));
        v.confirmDustThreshold();
        assertEq(v.maxDeposit(alice), 0);
        assertFalse(goldAdapter.isPriceSane());

        // at the timelock: confirm, deposits resume (X > X is false)
        vm.warp(t0 + DUST_TIMELOCK);
        assertEq(v.principalOf(address(goldAdapter)), X, "funded cost is time-independent");
        _confirm();
        assertEq(v.dustThreshold(), X);
        assertGt(v.maxDeposit(alice), 0, "deposits resume");
        assertGt(v.maxMint(alice), 0);
        assertTrue(_aliceCanDeposit(10e6));
    }

    function test_eco_thresholdOneBelowPosition_staysPaused() public {
        _seedNavAndGold(3_000e6);
        _makeOracleStale();
        // Pause materiality uses funded cost, not the haircutted market value.
        uint256 X = v.principalOf(address(goldAdapter));
        _propose(X - 1);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), X - 1);
        assertEq(v.maxDeposit(alice), 0, "X > X-1 still pauses");
    }

    function test_eco_smallStalePosition_doesNotPause() public {
        _seedNavAndGold(1e6); // stale value ~0.95e6 <= default dust 1e6
        _makeOracleStale();
        // Equality at the funded-cost boundary stays open even after the stale haircut.
        assertLe(v.principalOf(address(goldAdapter)), v.dustThreshold());
        assertGt(v.maxDeposit(alice), 0);
        assertTrue(_aliceCanDeposit(10e6));
    }

    function test_eco_positionAboveCap_cannotBeSilenced_untilNavGrows() public {
        _seedNavAndGold(10_000e6);
        _makeOracleStale();
        // Pause materiality uses funded cost, not the haircutted market value.
        uint256 X = v.principalOf(address(goldAdapter));
        uint256 cap = _cap(v.totalAssets());
        assertGt(X, cap, "position larger than cap");
        assertEq(v.maxDeposit(alice), 0);

        // Cannot propose above the cap.
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, X, cap));
        v.proposeDustThreshold(X);

        // Max allowed raise still leaves deposits paused.
        _propose(cap);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), cap);
        assertEq(v.maxDeposit(alice), 0, "X > cap: still paused");

        // NAV doubles (e.g. via donation) => cap doubles to cover X.
        usdc.mint(address(v), NAV * 2);
        uint256 cap2 = _cap(v.totalAssets());
        assertGe(cap2, X);
        _propose(X);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertGt(v.maxDeposit(alice), 0, "resumed after cap allowed the raise");
    }

    function test_eco_navShrinkBetweenProposeAndConfirm_blocksResume() public {
        _seedNavAndGold(3_000e6);
        _makeOracleStale();
        // Pause materiality uses funded cost, not the haircutted market value.
        uint256 X = v.principalOf(address(goldAdapter));
        _propose(X);
        vm.warp(block.timestamp + DUST_TIMELOCK);

        // Withdraw most NAV: cap collapses below X.
        uint256 sh = v.balanceOf(alice);
        vm.prank(alice);
        v.redeem(sh * 9 / 10, alice, alice);
        uint256 cap = _cap(v.totalAssets());
        assertLt(cap, X);

        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, X, cap));
        v.confirmDustThreshold();
        assertEq(v.maxDeposit(alice), 0, "still paused");
        (, , bool exists) = _pending();
        assertTrue(exists, "proposal retained");
    }
}

contract TaskNEconomicV1Test is TaskNEconomic {
    function _deployVault() internal override {
        v = new ShariahVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0));
    }
    function _board() internal view override returns (address) { return owner; }
    function _denied() internal view override returns (address[] memory d) { d = new address[](0); }
}

contract TaskNEconomicV2Test is TaskNEconomic {
    function _deployVault() internal override {
        ShariahAdapterRegistry reg = new ShariahAdapterRegistry(owner, boardMember);
        v = new ShariahVaultV2(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0), address(reg)
        );
    }
    function _board() internal view override returns (address) { return boardMember; }
    function _denied() internal view override returns (address[] memory d) { d = new address[](0); }
}

contracts/test/TaskNTest.N2.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {ShariahVaultV2}         from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TaskNDustBase}          from "./TaskNTest.DustBase.t.sol";

/// @dev Behaviour that must hold for BOTH vault flavours (V1 owner-board, V2 registry-board).
abstract contract TaskNDustCommon is TaskNDustBase {

    // ── constants / removal ─────────────────────────────────────────────

    function test_constants_and_default() public view {
        assertEq(v.DUST_TIMELOCK(), 30 days);
        assertEq(v.MAX_DUST_BPS(), 50);
        assertEq(v.MIN_DUST_CAP(), 1e6);
        assertEq(v.dustThreshold(), 1e6, "default 1 USDC");
        (, , bool exists) = _pending();
        assertFalse(exists);
    }

    function test_setDustThreshold_removed() public {
        vm.prank(_board());
        (bool ok,) = address(v).call(abi.encodeWithSignature("setDustThreshold(uint256)", 5e6));
        assertFalse(ok, "setDustThreshold must no longer exist");
        vm.prank(owner);
        (ok,) = address(v).call(abi.encodeWithSignature("setDustThreshold(uint256)", 5e6));
        assertFalse(ok);
        assertEq(v.dustThreshold(), 1e6);
    }

    // ── access control ──────────────────────────────────────────────────

    function test_nonBoard_cannotPropose() public {
        address[] memory d = _denied();
        for (uint256 i = 0; i < d.length; i++) {
            vm.prank(d[i]);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, d[i]));
            v.proposeDustThreshold(1e6);
        }
    }

    function test_nonBoard_cannotConfirm_orCancel_evenWithPendingProposal() public {
        _propose(1e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        address[] memory d = _denied();
        for (uint256 i = 0; i < d.length; i++) {
            vm.prank(d[i]);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, d[i]));
            v.confirmDustThreshold();
            vm.prank(d[i]);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, d[i]));
            v.cancelDustThreshold();
        }
        (, , bool exists) = _pending();
        assertTrue(exists, "proposal untouched");
    }

    function testFuzz_randomCaller_cannotPropose(address caller) public {
        vm.assume(caller != _board());
        vm.prank(caller);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, caller));
        v.proposeDustThreshold(0);
    }

    function test_nonBoard_errorPrecedesNothingPending() public {
        // Unauthorised caller gets NotBoardRole, not NoPendingDustProposal.
        vm.prank(stranger);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, stranger));
        v.confirmDustThreshold();
        vm.prank(stranger);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, stranger));
        v.cancelDustThreshold();
    }

    // ── propose ─────────────────────────────────────────────────────────

    function test_propose_recordsValueAndTime_andLeavesActiveUnchanged() public {
        _setAssets(1_000_000e6);
        uint256 t0 = block.timestamp;

        vm.expectEmit(false, false, false, true, address(v));
        emit ShariahVault.DustThresholdProposed(2_500e6, t0 + DUST_TIMELOCK);
        _propose(2_500e6);

        (uint256 nv, uint256 ea, bool exists) = _pending();
        assertEq(nv, 2_500e6);
        assertEq(ea, t0 + DUST_TIMELOCK);
        assertTrue(exists);
        assertEq(v.dustThreshold(), 1e6, "active threshold unchanged until confirm");
    }

    function test_propose_duplicate_reverts_evenSameValue() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);
        vm.prank(_board());
        vm.expectRevert(ShariahVault.DustProposalAlreadyExists.selector);
        v.proposeDustThreshold(3_000e6);
        vm.prank(_board());
        vm.expectRevert(ShariahVault.DustProposalAlreadyExists.selector);
        v.proposeDustThreshold(2_000e6);
        (uint256 nv, , ) = _pending();
        assertEq(nv, 2_000e6, "original proposal retained");
    }

    function test_propose_zeroThreshold_accepted_andConfirms() public {
        _propose(0);
        (uint256 nv, , bool exists) = _pending();
        assertEq(nv, 0);
        assertTrue(exists);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), 0);
    }

    // ── cap math ────────────────────────────────────────────────────────

    function test_cap_exactAccepted_capPlusOneReverts_atPropose() public {
        _setAssets(1_000_000e6); // cap = 5_000e6
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 5_000e6 + 1, 5_000e6));
        v.proposeDustThreshold(5_000e6 + 1);
        _propose(5_000e6);
        (uint256 nv, , ) = _pending();
        assertEq(nv, 5_000e6);
    }

    function test_cap_zeroAssets_usesFloor() public {
        assertEq(v.totalAssets(), 0);
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 1e6 + 1, 1e6));
        v.proposeDustThreshold(1e6 + 1);
        _propose(1e6);
        (uint256 nv, , ) = _pending();
        assertEq(nv, 1e6);
    }

    function test_cap_crossover_200usdc_isExactly1e6() public {
        _setAssets(200e6); // 200e6 * 50 / 10_000 == 1e6
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 1e6 + 1, 1e6));
        v.proposeDustThreshold(1e6 + 1);
        _propose(1e6);
    }

    function test_cap_belowCrossover_floorStillApplies() public {
        _setAssets(199e6); // bps cap = 995_000 < floor
        _propose(1e6);
        (uint256 nv, , ) = _pending();
        assertEq(nv, 1e6);
    }

    function test_cap_aboveCrossover_bpsGovern() public {
        _setAssets(400e6); // cap 2e6
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 2e6 + 1, 2e6));
        v.proposeDustThreshold(2e6 + 1);
        _propose(2e6);
    }

    function testFuzz_cap_boundary(uint256 assets, uint256 proposed) public {
        assets = bound(assets, 0, 1e18);
        _setAssets(assets);
        uint256 cap = _cap(assets);
        proposed = bound(proposed, 0, cap * 2 + 10);
        if (proposed <= cap) {
            _propose(proposed);
            (uint256 nv, , bool exists) = _pending();
            assertEq(nv, proposed);
            assertTrue(exists);
        } else {
            vm.prank(_board());
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, proposed, cap));
            v.proposeDustThreshold(proposed);
            (, , bool exists) = _pending();
            assertFalse(exists);
        }
    }

    function test_cap_exactlyCapAndCapPlusOne_atBoundaryOfAssets() public {
        // assets 1e12-1 => cap 4_999_999_999 ; assets 1e12 => cap 5_000_000_000
        _setAssets(1_000_000e6 - 1);
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 5_000e6, 5_000e6 - 1));
        v.proposeDustThreshold(5_000e6);
        _propose(5_000e6 - 1);
    }

    // ── confirm / timelock ──────────────────────────────────────────────

    function test_confirm_nothingPending_reverts() public {
        vm.prank(_board());
        vm.expectRevert(ShariahVault.NoPendingDustProposal.selector);
        v.confirmDustThreshold();
    }

    function test_cancel_nothingPending_reverts() public {
        vm.prank(_board());
        vm.expectRevert(ShariahVault.NoPendingDustProposal.selector);
        v.cancelDustThreshold();
    }

    function test_confirm_oneSecondEarly_reverts() public {
        _setAssets(1_000_000e6);
        uint256 t0 = block.timestamp;
        _propose(2_000e6);
        vm.warp(t0 + DUST_TIMELOCK - 1);
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(
            ShariahVault.DustTimelockNotElapsed.selector, t0 + DUST_TIMELOCK, t0 + DUST_TIMELOCK - 1
        ));
        v.confirmDustThreshold();
        assertEq(v.dustThreshold(), 1e6);
        (, , bool exists) = _pending();
        assertTrue(exists);
    }

    function test_confirm_atExactly30Days_succeeds_emits_andClearsState() public {
        _setAssets(1_000_000e6);
        uint256 t0 = block.timestamp;
        _propose(2_000e6);
        vm.warp(t0 + DUST_TIMELOCK);

        vm.expectEmit(false, false, false, true, address(v));
        emit ShariahVault.DustThresholdUpdated(1e6, 2_000e6);
        _confirm();

        assertEq(v.dustThreshold(), 2_000e6);
        (uint256 nv, uint256 ea, bool exists) = _pending();
        assertEq(nv, 0);
        assertEq(ea, 0);
        assertFalse(exists);

        // second confirm has nothing to do
        vm.prank(_board());
        vm.expectRevert(ShariahVault.NoPendingDustProposal.selector);
        v.confirmDustThreshold();
    }

    function test_confirm_afterLongDelay_stillSucceeds() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);
        vm.warp(block.timestamp + 365 days);
        _confirm();
        assertEq(v.dustThreshold(), 2_000e6);
    }

    function test_confirm_thenRepropose_usesPreviousAsPrevious() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        _propose(3_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        vm.expectEmit(false, false, false, true, address(v));
        emit ShariahVault.DustThresholdUpdated(2_000e6, 3_000e6);
        _confirm();
        assertEq(v.dustThreshold(), 3_000e6);
    }

    function test_confirm_rechecksCap_capPlusOne_reverts_proposalKept() public {
        _setAssets(1_000_000e6);
        _propose(5_000e6); // exactly cap now
        vm.warp(block.timestamp + DUST_TIMELOCK);
        usdc.burn(address(v), 1); // assets 1e12 - 1 => cap = 5_000e6 - 1
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 5_000e6, 5_000e6 - 1));
        v.confirmDustThreshold();
        (uint256 nv, , bool exists) = _pending();
        assertTrue(exists, "proposal kept");
        assertEq(nv, 5_000e6);
        assertEq(v.dustThreshold(), 1e6, "active unchanged");
    }

    function test_confirm_shrinkingAssets_reverts_thenRecoveryAllowsConfirm() public {
        _setAssets(1_000_000e6);
        _propose(4_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _setAssets(100_000e6); // cap 500e6 < 4_000e6
        vm.prank(_board());
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.DustThresholdAboveCap.selector, 4_000e6, 500e6));
        v.confirmDustThreshold();
        (, , bool exists) = _pending();
        assertTrue(exists);
        _setAssets(1_000_000e6); // NAV recovers
        _confirm();
        assertEq(v.dustThreshold(), 4_000e6);
    }

    function test_confirm_shrinkingToZero_floorStillAllowsSmallProposal() public {
        _setAssets(1_000_000e6);
        _propose(1e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _setAssets(0);
        _confirm(); // 1e6 <= floor
        assertEq(v.dustThreshold(), 1e6);
    }

    function test_confirm_growingAssets_doesNotRaiseAlreadyProposedValue() public {
        _setAssets(1_000_000e6);
        _propose(1_000e6);
        _setAssets(10_000_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), 1_000e6);
    }

    // ── cancel ──────────────────────────────────────────────────────────

    function test_cancel_emits_clears_andAllowsRepropose() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);

        vm.expectEmit(false, false, false, false, address(v));
        emit ShariahVault.DustThresholdProposalCancelled();
        _cancel();

        (uint256 nv, uint256 ea, bool exists) = _pending();
        assertEq(nv, 0);
        assertEq(ea, 0);
        assertFalse(exists);
        assertEq(v.dustThreshold(), 1e6);

        // cancelled proposal cannot be confirmed
        vm.warp(block.timestamp + DUST_TIMELOCK);
        vm.prank(_board());
        vm.expectRevert(ShariahVault.NoPendingDustProposal.selector);
        v.confirmDustThreshold();

        // fresh proposal restarts the clock
        uint256 t1 = block.timestamp;
        _propose(3_000e6);
        (nv, ea, exists) = _pending();
        assertEq(nv, 3_000e6);
        assertEq(ea, t1 + DUST_TIMELOCK);
        assertTrue(exists);
    }

    function test_cancel_ignoresTimelockAndCap() public {
        _setAssets(1_000_000e6);
        _propose(5_000e6);
        _setAssets(0); // proposal now above cap; cancel must still work
        _cancel();
        (, , bool exists) = _pending();
        assertFalse(exists);
    }
}

// ─────────────────────────────────────────────────────────────────────────
//  V1: board == owner
// ─────────────────────────────────────────────────────────────────────────
contract TaskNDustV1Test is TaskNDustCommon {
    function _deployVault() internal override {
        v = new ShariahVault(IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0));
    }

    function _board() internal view override returns (address) { return owner; }

    function _denied() internal view override returns (address[] memory d) {
        d = new address[](4);
        d[0] = alice; d[1] = stranger; d[2] = manager; d[3] = boardMember;
    }

    function test_v1_owner_canDoAllThree() public {
        _setAssets(1_000_000e6);
        vm.startPrank(owner);
        v.proposeDustThreshold(2_000e6);
        v.cancelDustThreshold();
        v.proposeDustThreshold(3_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        v.confirmDustThreshold();
        vm.stopPrank();
        assertEq(v.dustThreshold(), 3_000e6);
    }

    function test_v1_ownershipTransfer_movesBoardRole() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);
        address newOwner = makeAddr("newOwner");
        vm.prank(owner);
        v.transferOwnership(newOwner);
        vm.prank(newOwner);
        v.acceptOwnership();

        vm.warp(block.timestamp + DUST_TIMELOCK);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v.confirmDustThreshold();

        vm.prank(newOwner);
        v.confirmDustThreshold();
        assertEq(v.dustThreshold(), 2_000e6);
    }
}

contracts/test/TaskNTest.N2V2.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../ShariahVault.sol";
import {ShariahVaultV2}         from "../ShariahVaultV2.sol";
import {ShariahAdapterRegistry} from "../ShariahAdapterRegistry.sol";
import {TaskNDustBase}          from "./TaskNTest.DustBase.t.sol";
import {TaskNDustCommon}        from "./TaskNTest.N2.t.sol";

/// @dev V2: board == registry.isBoard(account); vault owner is NOT board unless registry says so.
contract TaskNDustV2Test is TaskNDustCommon {
    ShariahAdapterRegistry internal registry;
    address internal newBoard = makeAddr("newBoard");

    function _deployVault() internal override {
        registry = new ShariahAdapterRegistry(owner, boardMember); // owner != board
        v = new ShariahVaultV2(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0), address(registry)
        );
    }

    function _board() internal view override returns (address) { return boardMember; }

    function _denied() internal view override returns (address[] memory d) {
        d = new address[](4);
        d[0] = alice; d[1] = stranger; d[2] = manager; d[3] = owner;
    }

    function test_v2_registryBoardMember_canDoAllThree() public {
        _setAssets(1_000_000e6);
        vm.startPrank(boardMember);
        v.proposeDustThreshold(2_000e6);
        v.cancelDustThreshold();
        v.proposeDustThreshold(3_000e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        v.confirmDustThreshold();
        vm.stopPrank();
        assertEq(v.dustThreshold(), 3_000e6);
    }

    function test_v2_ownerWithoutBoardRole_cannotPropose_confirm_orCancel() public {
        assertFalse(registry.boardRole(owner));
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v.proposeDustThreshold(1e6);

        _propose(1e6);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v.confirmDustThreshold();
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v.cancelDustThreshold();
    }

    function test_v2_zeroRegistry_atConstruction_deniesEveryone() public {
        ShariahVaultV2 z = new ShariahVaultV2(
            IERC20(address(usdc)), owner, SOURCE_DOMAIN, address(treasury), address(0), address(0)
        );
        address[5] memory who = [owner, boardMember, alice, stranger, address(0)];
        for (uint256 i = 0; i < who.length; i++) {
            vm.startPrank(who[i]);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.proposeDustThreshold(0);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.confirmDustThreshold();
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.cancelDustThreshold();
            bytes32 recipient = bytes32(uint256(uint160(alice)));
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.proposeRemoteRecipient(0, recipient, true);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.confirmRemoteRecipient(0, recipient);
            vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, who[i]));
            z.cancelRemoteRecipient(0, recipient);
            vm.stopPrank();
        }
    }

    function test_v2_proposeZeroRegistry_reverts_andKeepsDustProposal() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);
        vm.prank(boardMember);
        vm.expectRevert(ShariahVaultV2.ZeroRegistry.selector);
        ShariahVaultV2(address(v)).proposeRegistry(address(0));

        assertEq(address(ShariahVaultV2(address(v)).registry()), address(registry));
        (, , bool exists) = _pending();
        assertTrue(exists);
        vm.warp(block.timestamp + DUST_TIMELOCK);
        _confirm();
        assertEq(v.dustThreshold(), 2_000e6);
    }

    function test_v2_membershipRevoked_deniesLaterCalls_proposalKept() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);

        vm.prank(owner); // registry owner = owner
        registry.emergencyRevokeBoardRole(boardMember);

        vm.warp(block.timestamp + DUST_TIMELOCK);
        vm.startPrank(boardMember);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, boardMember));
        v.confirmDustThreshold();
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, boardMember));
        v.cancelDustThreshold();
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, boardMember));
        v.proposeDustThreshold(1e6);
        vm.stopPrank();
        (, , bool exists) = _pending();
        assertTrue(exists, "proposal survives revocation");
    }

    function test_v2_membershipGranted_newMemberCanActOnExistingProposal() public {
        _setAssets(1_000_000e6);
        _propose(2_000e6);

        // board adds newBoard through the registry's own 30-day flow
        vm.prank(newBoard);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, newBoard));
        v.cancelDustThreshold();

        vm.prank(boardMember);
        registry.proposeBoardRoleChange(newBoard, true);
        vm.warp(block.timestamp + 30 days);
        vm.prank(boardMember);
        registry.executeBoardRoleChange(newBoard);

        vm.prank(newBoard);
        v.confirmDustThreshold();
        assertEq(v.dustThreshold(), 2_000e6);

        vm.prank(newBoard);
        v.proposeDustThreshold(1_000e6);
        vm.prank(newBoard);
        v.cancelDustThreshold();
    }

    function test_v2_replacedRegistry_changesWhoIsBoard() public {
        ShariahAdapterRegistry r2 = new ShariahAdapterRegistry(owner, owner);
        ShariahVaultV2 v2 = ShariahVaultV2(address(v));
        _propose(1e6);
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v2.proposeRegistry(address(r2));
        vm.prank(boardMember);
        v2.proposeRegistry(address(r2));
        vm.warp(block.timestamp + DUST_TIMELOCK);

        // Membership in the proposed registry grants no authority before confirmation.
        vm.prank(owner);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, owner));
        v2.confirmRegistry();
        vm.prank(boardMember);
        vm.expectEmit(false, false, false, true, address(v));
        emit ShariahVault.DustThresholdProposalCancelled();
        v2.confirmRegistry();
        (, , bool exists) = _pending();
        assertFalse(exists, "old governance proposal cleared");

        vm.prank(boardMember);
        vm.expectRevert(abi.encodeWithSelector(ShariahVault.NotBoardRole.selector, boardMember));
        v.proposeDustThreshold(1e6);

        vm.prank(owner);
        v.proposeDustThreshold(1e6);
        (uint256 nv, , bool newExists) = _pending();
        assertEq(nv, 1e6);
        assertTrue(newExists);
    }
}

contracts/test/TaskNTest.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AutonomousVault}         from "../AutonomousVault.sol";
import {ShariahVault}            from "../ShariahVault.sol";
import {RiskTieredExecutor}      from "../RiskTieredExecutor.sol";
import {ScoreAggregator}         from "../ScoreAggregator.sol";
import {ShariahScoreAggregator}  from "../ShariahScoreAggregator.sol";
import {RemoteRecipientFixture} from "./TaskITest.Base.t.sol";
import {TaskNBase, MockStrategyAdapterN} from "./TaskNTest.Base.t.sol";

/// @title TaskNTest — N1: gold guard moved from vault-wide flag to strategy-tagged entry point.
contract TaskNTest is TaskNBase {
    ShariahScoreAggregator internal shAgg;
    ScoreAggregator        internal conv;
    MockStrategyAdapterN   internal stratAdapter;

    function setUp() public override {
        super.setUp();
        shAgg = new ShariahScoreAggregator(owner);
        conv  = new ScoreAggregator(owner);
        stratAdapter = new MockStrategyAdapterN(address(svault));
    }

    // ─────────────────────────────────────────────────────────────────────
    // Fixture sanity: gold really is held in both adapters
    // ─────────────────────────────────────────────────────────────────────

    function test_fixture_goldHeldInBothAdapters() public view {
        assertGt(goldAdapter.paxgHeld(), 0, "S2-H holds PAXG");
        assertGt(allocAdapter.xautHeld(), 0, "S6-H holds XAUT");
        assertGt(goldAdapter.currentValue(), 0, "S2-H valued");
        assertGt(allocAdapter.currentValue(), 0, "S6-H valued");
        assertEq(svault.totalDeployed(), 2 * GOLD_BUY);
    }

    // ─────────────────────────────────────────────────────────────────────
    // (a) idx 0 USDC cross-chain succeeds while gold is held
    // ─────────────────────────────────────────────────────────────────────

    function test_a_forStrategy_idx0_succeeds_withGoldHeld_andUpdatesPending() public {
        uint256 amt = 10_000e6;
        bytes32 rcpt = _bytes32(alice);
        // Task M: predict the next local position ID for pending/event assertions.
        uint64 nonce = svault.crossChainPositionCounter() + 1;
        uint256 deployedBefore = svault.totalDeployed();

        vm.expectEmit(true, true, false, true, address(svault));
        emit AutonomousVault.CapitalDeployedCrossChain(DEST_DOMAIN, rcpt, amt, nonce);
        vm.prank(manager);
        svault.deployCrossChainForStrategy(ETH_SPREAD, DEST_DOMAIN, rcpt, amt);

        assertEq(svault.pendingCrossChain(nonce), amt);
        assertEq(svault.pendingCrossChainDestinationDomain(nonce), DEST_DOMAIN);
        assertEq(svault.totalPendingCrossChain(), amt);
        assertEq(svault.totalDeployed(), deployedBefore + amt);
    }

    function test_a_plainDeployCrossChain_succeeds_withGoldHeld_andUpdatesPending() public {
        uint256 amt = 10_000e6;
        bytes32 rcpt = _bytes32(alice);
        // Task M: predict the next local position ID for pending/event assertions.
        uint64 nonce = svault.crossChainPositionCounter() + 1;
        uint256 deployedBefore = svault.totalDeployed();

        vm.expectEmit(true, true, false, true, address(svault));
        emit AutonomousVault.CapitalDeployedCrossChain(DEST_DOMAIN, rcpt, amt, nonce);
        vm.prank(manager);
        svault.deployCrossChain(DEST_DOMAIN, rcpt, amt);

        assertEq(svault.pendingCrossChain(nonce), amt);
        assertEq(svault.pendingCrossChainDestinationDomain(nonce), DEST_DOMAIN);
        assertEq(svault.totalPendingCrossChain(), amt);
        assertEq(svault.totalDeployed(), deployedBefore + amt);
    }

    function test_a_ownerCanAlsoDeployCrossChain_bothEntryPoints() public {
        vm.startPrank(owner);
        svault.deployCrossChainForStrategy(ETH_SPREAD, DEST_DOMAIN, _bytes32(alice), 1_000e6);
        svault.deployCrossChain(DEST_DOMAIN, _bytes32(alice), 2_000e6);
        vm.stopPrank();
        assertEq(svault.totalPendingCrossChain(), 3_000e6);
    }

    function testFuzz_a_nonGoldIdx_anyDomain_succeeds(uint8 idx, uint32 domain, bytes32 rcpt, uint256 amt) public {
        vm.assume(idx != GOLD_SPREAD && idx != GOLD_ALLOC);
        vm.assume(domain != SOURCE_DOMAIN);
        vm.assume(rcpt != bytes32(0));
        RemoteRecipientFixture.approve(vm, svault, owner, domain, rcpt);
        amt = bound(amt, 0, 400_000e6);
        // Task M: predict the next local position ID for pending/event assertions.
        uint64 nonce = svault.crossChainPositionCounter() + 1;

        vm.prank(manager);
        svault.deployCrossChainForStrategy(idx, domain, rcpt, amt);

        assertEq(svault.pendingCrossChain(nonce), amt);
        assertEq(svault.pendingCrossChainDestinationDomain(nonce), domain);
        assertEq(svault.totalPendingCrossChain(), amt);
    }

    function test_a_goldCrossChainBlocked_removed() public {
        // Selector no longer exists on the vault: low-level calls hit no function (no fallback) => revert.
        (bool ok,) = address(svault).staticcall(abi.encodeWithSignature("goldCrossChainBlocked()"));
        assertFalse(ok, "goldCrossChainBlocked getter removed");
        vm.prank(owner);
        (bool ok2,) = address(svault).call(abi.encodeWithSignature("setGoldCrossChainBlocked(bool)", true));
        assertFalse(ok2, "setter removed");
    }

    // ─────────────────────────────────────────────────────────────────────
    // (b) gold idx 1 / 5 with nonzero domain reverts NonAtomicGoldExchange
    // ─────────────────────────────────────────────────────────────────────

    function _expectNonAtomicAndNoStateChange(address caller, uint8 idx, uint32 domain, bytes32 rcpt, uint256 amt) internal {
        uint256 pendingBefore = svault.totalPendingCrossChain();
        uint256 deployedBefore = svault.totalDeployed();
        uint64 nonceBefore = messenger.callCount();

        vm.prank(caller);
        vm.expectRevert(ShariahVault.NonAtomicGoldExchange.selector);
        svault.deployCrossChainForStrategy(idx, domain, rcpt, amt);

        assertEq(svault.totalPendingCrossChain(), pendingBefore);
        assertEq(svault.totalDeployed(), deployedBefore);
        assertEq(messenger.callCount(), nonceBefore, "messenger must not be called");
    }

    function testFuzz_b_goldIdx_nonzeroDomain_reverts(bool pickAlloc, bool useOwner, uint32 domain, bytes32 rcpt, uint256 amt) public {
        domain = uint32(bound(domain, 1, type(uint32).max));
        _expectNonAtomicAndNoStateChange(
            useOwner ? owner : manager, pickAlloc ? GOLD_ALLOC : GOLD_SPREAD, domain, rcpt, amt
        );
    }

    function test_b_goldIdx_sourceDomain_reverts_beforeSameDomainCheck() public {
        _expectNonAtomicAndNoStateChange(manager, GOLD_SPREAD, SOURCE_DOMAIN, _bytes32(alice), 1e6);
        _expectNonAtomicAndNoStateChange(manager, GOLD_ALLOC, SOURCE_DOMAIN, _bytes32(alice), 1e6);
    }

    function test_b_goldIdx_amountZeroAndMax_reverts() public {
        _expectNonAtomicAndNoStateChange(manager, GOLD_SPREAD, DEST_DOMAIN, _bytes32(alice), 0);
        _expectNonAtomicAndNoStateChange(manager, GOLD_ALLOC, DEST_DOMAIN, _bytes32(alice), 0);
        _expectNonAtomicAndNoStateChange(manager, GOLD_SPREAD, DEST_DOMAIN, _bytes32(alice), type(uint256).max);
        _expectNonAtomicAndNoStateChange(manager, GOLD_ALLOC, DEST_DOMAIN, _bytes32(alice), type(uint256).max);
    }

    function test_b_goldIdx_maxDomain_zeroRecipient_reverts() public {
        _expectNonAtomicAndNoStateChange(owner, GOLD_SPREAD, type(uint32).max, bytes32(0), 5e6);
        _expectNonAtomicAndNoStateChange(owner, GOLD_ALLOC, 1, bytes32(0), 5e6);
    }

    /// @dev Domain 0 is a real CCTP domain (Ethereum), not "local". The strategy-tagged entry point
    ///      is cross-chain by definition, so gold indices revert for domain 0 as well.
    function testFuzz_b_goldIdx_domainZero_alsoReverts(bool pickAlloc, bytes32 rcpt, uint256 amt) public {
        uint8 idx = pickAlloc ? GOLD_ALLOC : GOLD_SPREAD;
        amt = bound(amt, 0, 400_000e6);
        _expectNonAtomicAndNoStateChange(manager, idx, 0, rcpt, amt);
    }

    function test_b_goldIdx_domainZero_reverts_noPendingBooked() public {
        _expectNonAtomicAndNoStateChange(manager, GOLD_SPREAD, 0, _bytes32(alice), 1_000e6);
        _expectNonAtomicAndNoStateChange(owner, GOLD_ALLOC, 0, _bytes32(alice), 1_000e6);
    }

    function test_b_plainDeployCrossChain_notBlockedByGold_forGoldAdapters() public {
        // Gold held in both adapters; the plain entry point has no gold guard at all.
        vm.prank(manager);
        svault.deployCrossChain(DEST_DOMAIN, _bytes32(alice), 1_000e6);
        assertEq(svault.totalPendingCrossChain(), 1_000e6);
    }

    // ─────────────────────────────────────────────────────────────────────
    // (c) NotManager for strangers
    // ─────────────────────────────────────────────────────────────────────

    function testFuzz_c_stranger_forStrategy_reverts_NotManager(
        address caller, uint8 idx, uint32 domain, bytes32 rcpt, uint256 amt
    ) public {
        vm.assume(caller != owner && caller != manager);
        vm.prank(caller);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        svault.deployCrossChainForStrategy(idx, domain, rcpt, amt);
    }

    function test_c_stranger_goldIdx_nonzeroDomain_getsNotManager_notGoldError() public {
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        svault.deployCrossChainForStrategy(GOLD_SPREAD, DEST_DOMAIN, _bytes32(alice), 1e6);
    }

    function test_c_stranger_plainDeployCrossChain_reverts_NotManager() public {
        vm.prank(stranger);
        vm.expectRevert(AutonomousVault.NotManager.selector);
        svault.deployCrossChain(DEST_DOMAIN, _bytes32(alice), 1e6);
    }

    // ─────────────────────────────────────────────────────────────────────
    // (d) RiskTieredExecutor — Shariah tiers
    // ─────────────────────────────────────────────────────────────────────

    function _mkExec(RiskTieredExecutor.RiskTier tier) internal returns (RiskTieredExecutor ex) {
        vm.startPrank(owner);
        ex = new RiskTieredExecutor(address(svault), address(conv), tier, owner);
        ex.setShariahAggregator(address(shAgg));
        svault.setManager(address(ex));
        svault.setScreened(address(stratAdapter), true);
        uint8[5] memory idxs = [0, 1, 2, 3, 5];
        for (uint256 i = 0; i < idxs.length; i++) {
            ex.setShariahStrategyConfig(idxs[i], address(stratAdapter), _bytes32(alice), true, 1, 10_000e6);
            shAgg.setEnabled(ShariahScoreAggregator.ShariahStrategy(idxs[i]), true);
        }
        vm.stopPrank();
    }

    function _score(uint8 idx, uint32 domain) internal {
        vm.prank(owner);
        shAgg.writeScore(ShariahScoreAggregator.ShariahStrategy(idx), 95, keccak256("n1"), domain);
    }

    function _assertExecutedLocally(RiskTieredExecutor ex, uint256 deployedBefore) internal view {
        assertEq(svault.totalDeployed(), deployedBefore + 10_000e6, "local deployCapital booked");
        assertEq(usdc.balanceOf(address(stratAdapter)), 10_000e6, "adapter funded");
        // Atomic tiers call the adapter from the vault; conventional tiers retain the executor caller.
        bool atomicTier = ex.riskTier() == RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE
            || ex.riskTier() == RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC;
        assertEq(stratAdapter.lastDeployCaller(), atomicTier ? address(svault) : address(ex));
        assertEq(svault.totalPendingCrossChain(), 0, "no cross-chain pending");
        assertEq(messenger.callCount(), 0, "messenger untouched");
        assertEq(ex.lastExecutionTime(), block.timestamp);
    }

    function _goldRevertsForTier(RiskTieredExecutor.RiskTier tier) internal {
        RiskTieredExecutor ex = _mkExec(tier);
        uint8[2] memory golds = [GOLD_SPREAD, GOLD_ALLOC];
        for (uint256 i = 0; i < 2; i++) {
            // zero out the other gold score so the intended gold index is the winner (ties go to the lower idx)
            vm.prank(owner);
            shAgg.writeScore(ShariahScoreAggregator.ShariahStrategy(golds[1 - i]), 0, bytes32(0), 0);
            _score(golds[i], 7);
            vm.expectRevert(RiskTieredExecutor.NonAtomicGoldExchange.selector);
            ex.executeWinner();
        }
        assertEq(ex.lastExecutionTime(), 0, "no execution recorded");
        assertEq(messenger.callCount(), 0);
    }

    function test_d_conservative_goldWinner_nonzeroDomain_reverts() public {
        _goldRevertsForTier(RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE);
    }

    function test_d_dynamic_goldWinner_nonzeroDomain_reverts() public {
        _goldRevertsForTier(RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC);
    }

    function testFuzz_d_goldWinner_anyNonzeroDomain_reverts(bool pickAlloc, bool dynamicTier, uint32 domain) public {
        domain = uint32(bound(domain, 1, type(uint32).max));
        RiskTieredExecutor ex = _mkExec(
            dynamicTier ? RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC : RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE
        );
        _score(pickAlloc ? GOLD_ALLOC : GOLD_SPREAD, domain);
        vm.expectRevert(RiskTieredExecutor.NonAtomicGoldExchange.selector);
        ex.executeWinner();
    }

    function _goldDomainZeroLocal(RiskTieredExecutor.RiskTier tier, uint8 idx) internal {
        RiskTieredExecutor ex = _mkExec(tier);
        uint256 before_ = svault.totalDeployed();
        _score(idx, 0);

        vm.expectEmit(true, true, false, true, address(ex));
        emit RiskTieredExecutor.ShariahExecutionTriggered(
            ShariahScoreAggregator.ShariahStrategy(idx), 95, 10_000e6, address(stratAdapter), tier
        );
        ex.executeWinner();
        _assertExecutedLocally(ex, before_);
    }

    // Execute a real onlyVault adapter so permissive mocks cannot hide caller-authorization regressions.
    function test_d_conservative_realGoldAdapter_executesAtomically() public {
        RiskTieredExecutor ex = _mkExec(RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE);
        vm.prank(owner);
        ex.setShariahStrategyConfig(GOLD_SPREAD, address(goldAdapter), _bytes32(alice), true, 1, 10_000e6);
        _score(GOLD_SPREAD, 0);
        uint256 heldBefore = goldAdapter.paxgHeld();
        uint256 deployedBefore = svault.totalDeployed();
        ex.executeWinner();
        assertGt(goldAdapter.paxgHeld(), heldBefore);
        assertEq(usdc.balanceOf(address(goldAdapter)), 0);
        assertEq(svault.totalDeployed(), deployedBefore + 10_000e6);
        assertEq(svault.totalPendingCrossChain(), 0);
    }

    // An authorized adapter callback must not nest the atomic entry point, and failure must clear the lock.
    function test_atomicDeployment_reentryRevertsAndRollsBack() public {
        vm.startPrank(owner);
        svault.setManager(address(stratAdapter));
        svault.setScreened(address(stratAdapter), true);
        stratAdapter.setReenter(true);
        uint256 before_ = svault.totalDeployed();
        vm.expectRevert(ShariahVault.AdapterExecutionReentered.selector);
        svault.deployCapitalAndExecute(address(stratAdapter), 1_000e6, "");
        assertEq(svault.totalDeployed(), before_);
        assertEq(usdc.balanceOf(address(stratAdapter)), 0);
        stratAdapter.setReenter(false);
        svault.deployCapitalAndExecute(address(stratAdapter), 1_000e6, "");
        vm.stopPrank();
        assertEq(svault.totalDeployed(), before_ + 1_000e6);
    }

    function test_d_conservative_goldSpread_domainZero_executesLocally() public {
        _goldDomainZeroLocal(RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE, GOLD_SPREAD);
    }

    function test_d_conservative_goldAlloc_domainZero_executesLocally() public {
        _goldDomainZeroLocal(RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE, GOLD_ALLOC);
    }

    function test_d_dynamic_goldSpread_domainZero_executesLocally() public {
        _goldDomainZeroLocal(RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC, GOLD_SPREAD);
    }

    function test_d_dynamic_goldAlloc_domainZero_executesLocally() public {
        _goldDomainZeroLocal(RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC, GOLD_ALLOC);
    }

    function test_d_conservative_nonGold_nonzeroDomain_executesLocally() public {
        RiskTieredExecutor ex = _mkExec(RiskTieredExecutor.RiskTier.SHARIAH_CONSERVATIVE);
        uint256 before_ = svault.totalDeployed();
        _score(HALAL_LP, 7);
        ex.executeWinner();
        _assertExecutedLocally(ex, before_);
    }

    function testFuzz_d_dynamic_nonGold_nonzeroDomain_executesLocally(uint8 pick, uint32 domain) public {
        domain = uint32(bound(domain, 1, type(uint32).max));
        uint8[3] memory nonGold = [ETH_SPREAD, HALAL_LP, MURABAHA];
        RiskTieredExecutor ex = _mkExec(RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC);
        uint256 before_ = svault.totalDeployed();
        _score(nonGold[pick % 3], domain);
        ex.executeWinner();
        _assertExecutedLocally(ex, before_);
    }

    function test_d_higherScoredNonGoldWinsOverRemoteGold_executesLocally() public {
        // Gold score 90 w/ remote domain would win -> revert; a higher non-gold score wins -> local.
        RiskTieredExecutor ex = _mkExec(RiskTieredExecutor.RiskTier.SHARIAH_DYNAMIC);
        _score(GOLD_SPREAD, 9);
        vm.prank(owner);
        shAgg.writeScore(ShariahScoreAggregator.ShariahStrategy.HALAL_LP, 99, keccak256("lp"), 0);
        uint256 before_ = svault.totalDeployed();
        ex.executeWinner();
        _assertExecutedLocally(ex, before_);
    }

    function test_d_conventionalTier_routingUnchanged_crossChainViaPlainDeploy() public {
        RiskTieredExecutor ex = new RiskTieredExecutor(
            address(svault), address(conv), RiskTieredExecutor.RiskTier.PASSIVE, owner
        );
        vm.startPrank(owner);
        svault.setManager(address(ex));
        ex.setStrategyConfig(
            ScoreAggregator.Strategy.STABLECOIN_SPREAD, address(stratAdapter), _bytes32(alice), true, 1, 10_000e6
        );
        conv.writeScore(ScoreAggregator.Strategy.STABLECOIN_SPREAD, 95, keccak256("c"), DEST_DOMAIN);
        vm.stopPrank();

        // Task M: predict the next local position ID for pending/event assertions.
        uint64 nonce = svault.crossChainPositionCounter() + 1;
        ex.executeWinner(); // gold held in both adapters; plain deployCrossChain is not gold-blocked
        assertEq(svault.pendingCrossChain(nonce), 10_000e6);
        assertEq(svault.pendingCrossChainDestinationDomain(nonce), DEST_DOMAIN);
        assertEq(svault.totalPendingCrossChain(), 10_000e6);
        assertEq(usdc.balanceOf(address(stratAdapter)), 0);
    }

    function test_d_conventionalTier_domainZero_executesLocally() public {
        RiskTieredExecutor ex = new RiskTieredExecutor(
            address(svault), address(conv), RiskTieredExecutor.RiskTier.PASSIVE, owner
        );
        vm.startPrank(owner);
        svault.setManager(address(ex));
        svault.setScreened(address(stratAdapter), true);
        ex.setStrategyConfig(
            ScoreAggregator.Strategy.STABLECOIN_SPREAD, address(stratAdapter), _bytes32(alice), true, 1, 10_000e6
        );
        conv.writeScore(ScoreAggregator.Strategy.STABLECOIN_SPREAD, 95, keccak256("c"), 0);
        vm.stopPrank();

        uint256 before_ = svault.totalDeployed();
        ex.executeWinner();
        _assertExecutedLocally(ex, before_);
    }
}

