// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {RemoteRecipientFixture} from "../TaskITest.Base.t.sol";
import {Test}      from "forge-std/Test.sol";
import {IERC20}    from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ShariahVault}           from "../../ShariahVault.sol";
import {TreasuryModule}         from "../../TreasuryModule.sol";
import {CharityModule}          from "../../CharityModule.sol";
import {PurificationEscrow}     from "../../PurificationEscrow.sol";
import {GoldExchangeAdapter}    from "../../adapters/GoldExchangeAdapter.sol";
import {GoldAllocationAdapter}  from "../../adapters/GoldAllocationAdapter.sol";
import {MockERC20}              from "../../test-helpers/MockERC20.sol";
import {MockAllocatedGold}      from "../../test-helpers/MockAllocatedGold.sol";
import {MockXAUT}               from "../../test-helpers/MockXAUT.sol";
import {MockXauUsdAggregator}   from "../../test-helpers/MockXauUsdAggregator.sol";
import {MockUniswapV3PoolXAUT}  from "../../test-helpers/MockUniswapV3PoolXAUT.sol";

// ── Minimal mock registry: only the manager is a board member ─────────────────
contract MockRegistryInv {
    address public boardMember;
    constructor(address b) { boardMember = b; }
    function isBoard(address a) external view returns (bool) { return a == boardMember; }
}

// ── Mock PAXG swap router: fixed-ratio USDC↔PAXG swaps ──────────────────────
// 1 PAXG (18 dec) = 3_300_000_000 USDC (6 dec)
contract MockPaxgRouter {
    IERC20 public usdc;
    IERC20 public paxg;
    uint256 public USDC_PER_PAXG = 3_300_000_000;

    function setPrice(uint256 price) external { USDC_PER_PAXG = price; }

    constructor(address usdc_, address paxg_) {
        usdc = IERC20(usdc_);
        paxg = IERC20(paxg_);
    }

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata p)
        external returns (uint256 amountOut)
    {
        require(block.timestamp <= p.deadline, "deadline");
        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        if (p.tokenIn == address(usdc)) {
            amountOut = (p.amountIn * 1e18) / USDC_PER_PAXG;
        } else {
            amountOut = (p.amountIn * USDC_PER_PAXG) / 1e18;
        }
        require(amountOut >= p.amountOutMinimum, "slippage");
        IERC20(p.tokenOut).transfer(p.recipient, amountOut);
    }
}

// ── Mock CCTP TokenMessenger V2: no return value, transfers out the burned amount ──
// N-06 needs real idle-balance removal so cross-chain actions cannot hide gold losses with phantom funding.
contract MockMessengerInv {
    // Task M: V2 burns have no return; the invariant handler tracks vault position IDs.
    bytes public lastCall;
    function depositForBurn(uint256 amount, uint32 domain, bytes32 recipient, address token,
        bytes32 caller, uint256 maxFee, uint32 finality) external {
        lastCall = abi.encode(amount, domain, recipient, token, caller, maxFee, finality);
        IERC20(token).transferFrom(msg.sender, address(this), amount);
    }
}

// ── Mock CCTP MessageTransmitter: settable mint-on-receiveMessage ─────────────
contract MockTransmitterInv {
    address public usdc;
    address public target; // vault
    uint256 public mintAmount;

    constructor(address usdc_, address target_) {
        usdc   = usdc_;
        target = target_;
    }

    function setMintAmount(uint256 a) external { mintAmount = a; }

    function receiveMessage(bytes calldata, bytes calldata) external returns (bool) {
        if (mintAmount > 0) {
            MockERC20Like2(usdc).mint(target, mintAmount);
        }
        return true;
    }
}

interface MockERC20Like2 {
    function mint(address to, uint256 amount) external;
}

// ── Shared base: deploys the full ShariahVault stack ─────────────────────────
abstract contract VaultInvariantBase is Test {

    // ── Actors ──────────────────────────────────────────────────────────────
    address public owner   = makeAddr("owner");
    address public manager = makeAddr("manager");
    address public alice   = makeAddr("alice");
    address public bob     = makeAddr("bob");
    address public carol   = makeAddr("carol");
    address public charity = makeAddr("charity");

    address[3] public actors;

    // ── Tokens ───────────────────────────────────────────────────────────────
    MockERC20            public usdc;
    MockAllocatedGold    public paxg;
    MockXAUT             public xaut;
    MockXauUsdAggregator public xauOracle;          // S6-H oracle (XAU/USD)
    MockXauUsdAggregator public goldSpreadOracle_;  // S2-H oracle (K2: mandatory)
    MockUniswapV3PoolXAUT public xautPool;
    MockPaxgRouter       public paxgRouter;

    // ── CCTP mocks ───────────────────────────────────────────────────────────
    MockMessengerInv    public mockMessenger_;
    MockTransmitterInv  public mockTransmitter_;

    // ── Protocol ─────────────────────────────────────────────────────────────
    TreasuryModule       public treasury;
    CharityModule        public charityModule;
    PurificationEscrow   public purificationEscrow;
    GoldExchangeAdapter  public goldSpreadAdp;
    GoldAllocationAdapter public goldAllocAdp;
    ShariahVault         public vault;
    MockRegistryInv      public registry;

    // ── Constants ─────────────────────────────────────────────────────────────
    uint32  internal constant SOURCE_DOMAIN     = 26;
    uint256 internal constant POOL_USDC_PER_XAUT = 3_300_000_000;
    int256  internal constant ORACLE_PRICE      = 330_000_000_000; // 8 dec
    uint256 internal constant MAX_STALENESS     = 30 days;

    // ── Accessor helpers for handler ─────────────────────────────────────────
    function goldSpreadOracle()  public view returns (MockXauUsdAggregator) { return goldSpreadOracle_;  }
    function mockMessenger()     public view returns (MockMessengerInv)     { return mockMessenger_;     }
    function mockTransmitter()   public view returns (MockTransmitterInv)   { return mockTransmitter_;   }

    function setUp() public virtual {
        vm.warp(1_700_000_000); // realistic start time

        actors = [alice, bob, carol];

        // Pre-compute escrow address.
        // Deploys from address(this) in order:
        //   +0: usdc
        //   +1: paxg
        //   +2: xaut
        //   +3: xauOracle
        //   +4: goldSpreadOracle_   (NEW — K2)
        //   +5: xautPool
        //   +6: paxgRouter
        //   +7: mockMessenger_      (NEW — PR2)
        //   +8: registry
        //   +9: treasury
        //   +10: purificationEscrow
        uint256 startNonce = vm.getNonce(address(this));
        address expectedEscrow = vm.computeCreateAddress(address(this), startNonce + 10);

        // ── Tokens ────────────────────────────────────────────────────────────
        usdc             = new MockERC20("Mock USDC", "mUSDC", 6);
        paxg             = new MockAllocatedGold();
        xaut             = new MockXAUT();
        xauOracle        = new MockXauUsdAggregator();
        goldSpreadOracle_ = new MockXauUsdAggregator(); // K2: separate oracle for S2-H
        goldSpreadOracle_.setPrice(ORACLE_PRICE);
        xautPool         = new MockUniswapV3PoolXAUT(address(usdc), address(xaut), POOL_USDC_PER_XAUT);
        paxgRouter       = new MockPaxgRouter(address(usdc), address(paxg));

        // ── CCTP mocks ────────────────────────────────────────────────────────
        mockMessenger_ = new MockMessengerInv();

        // Seed pool with liquidity
        usdc.mint(address(this), 100_000_000e6);
        xaut.mint(address(this), 100_000e6);
        usdc.approve(address(xautPool), 100_000_000e6);
        xaut.approve(address(xautPool), 100_000e6);
        xautPool.fundPool(100_000_000e6, 100_000e6);

        // Seed PAXG router
        paxg.mint(address(paxgRouter), 10_000e18);
        usdc.mint(address(paxgRouter), 100_000_000e6);

        // ── Registry ──────────────────────────────────────────────────────────
        registry = new MockRegistryInv(manager);

        // ── Treasury ─────────────────────────────────────────────────────────
        treasury = new TreasuryModule(
            "Shariah",
            expectedEscrow,
            address(usdc),
            50,   // wakalaFeeBps 0.5%
            1000, // musharakahShareBps 10%
            400,  // hurdleRateBps 4%
            owner
        );

        vm.startPrank(owner);

        charityModule = new CharityModule(
            charity,
            address(usdc),
            expectedEscrow,
            owner,
            address(registry)
        );

        vault = new ShariahVault(
            IERC20(address(usdc)),
            owner,
            SOURCE_DOMAIN,
            address(treasury),
            address(0) // no ZakatModule
        );
        vault.setManager(manager);
        vault.setShariahScreening(false);
        vault.setMaxAllocationBps(8000);
        // Wire CCTP for cross-chain handler actions (PR2)
        vault.setTokenMessenger(address(mockMessenger_));
        // Task M: authenticate return messages from the handler's remote domain.
        vault.setRemoteTokenMessenger(6, bytes32(uint256(0xCC7)));
        vault.setMaxPendingCrossChainBps(2000); // 20% cap

        goldSpreadAdp = new GoldExchangeAdapter(
            address(usdc), address(paxg), address(paxgRouter), 3000,
            address(vault), owner, address(goldSpreadOracle_) // K2: mandatory oracle
        );

        goldAllocAdp = new GoldAllocationAdapter(
            address(usdc),
            address(xaut),
            address(xautPool),
            3000,
            address(xauOracle),
            address(vault),
            MAX_STALENESS,
            owner
        );

        vault.setScreened(address(goldSpreadAdp), true);
        vault.setScreened(address(goldAllocAdp), true);
        vault.setGoldSpreadAdapter(address(goldSpreadAdp));
        vault.setGoldAllocationAdapter(address(goldAllocAdp));

        vm.stopPrank();

        purificationEscrow = new PurificationEscrow(
            address(vault),
            address(usdc),
            address(charityModule),
            address(treasury),
            owner,
            address(registry)
        );
        require(address(purificationEscrow) == expectedEscrow, "escrow addr mismatch");

        // Deploy MockTransmitter AFTER vault address is known
        // (doesn't count in the escrow nonce since it's after purificationEscrow)
        mockTransmitter_ = new MockTransmitterInv(address(usdc), address(vault));

        vm.startPrank(owner);
        vault.setPurificationEscrow(address(purificationEscrow));
        // N-20: authorize time-based booking separately so strict deployment actions remain reachable.
        treasury.setFeeSource(address(vault));
        treasury.setProfitRecorder(address(purificationEscrow));
        vault.setMessageTransmitter(address(mockTransmitter_));
        vm.stopPrank();

        RemoteRecipientFixture.approve(vm, vault, owner, 6, bytes32(uint256(uint160(makeAddr("dest")))));
        xauOracle.setPrice(ORACLE_PRICE);
        goldSpreadOracle_.setPrice(ORACLE_PRICE);

        // ── Seed depositors ────────────────────────────────────────────────────
        for (uint256 i = 0; i < actors.length; i++) {
            usdc.mint(actors[i], 1_000_000e6);
            vm.prank(actors[i]);
            usdc.approve(address(vault), type(uint256).max);
        }
    }

    // ── Helper: compute _currentLockedProfit() inline ────────────────────────
    function _currentLockedProfitPublic() internal view returns (uint256) {
        uint256 lp = vault.lockedProfit();
        if (lp == 0) return 0;
        uint256 ua = vault.unlockedAt();
        if (block.timestamp >= ua) return 0;
        uint256 period   = vault.profitUnlockPeriod();
        // Mirror the defensive schedule guards so the NAV accounting oracle cannot underflow.
        if (period == 0 || ua < period || ua - period > block.timestamp) return 0;
        uint256 elapsed  = block.timestamp - (ua - period);
        if (elapsed >= period) return 0;
        return (lp * (period - elapsed)) / period;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Test}   from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {VaultInvariantBase} from "./VaultInvariant.Base.t.sol";
import {MockERC20}          from "../../test-helpers/MockERC20.sol";
import {ShariahVault}       from "../../ShariahVault.sol";

/// @dev Handler that exercises the ShariahVault stack for invariant testing.
///      PR2: extended with cross-chain actions, gold price drop, stale oracle,
///      fee settle, write-off, and loss-making recall so the fuzzer can produce
///      real losses and observe the new invariants.
contract VaultHandler is Test {

    VaultInvariantBase internal s; // shared state from base

    // ── Ghost variables for no-dilution invariant ─────────────────────────────
    // Tracks each actor's USDC value of shares (totalAssets * balance / totalSupply)
    // snapshots taken AROUND other actors' deposits and redeems.
    mapping(address => uint256) public preActionShares;   // shares held before an other-actor action
    mapping(address => uint256) public preActionAssets;   // totalAssets before the action
    mapping(address => uint256) public preActionSupply;   // totalSupply before the action
    mapping(address => bool)    public hasDeposited;

    // Legacy fields kept for HWM invariant
    uint256 public hwmDeficitBeforeClaim;
    uint256 public lastVaultShareFromClaim;
    bool    public claimWasAboveHWM;
    bool public recoveryShareViolation;
    uint256 public successfulClaims;
    uint256 public recoveryOnlyClaims;

    // ── Ghost: cross-chain nonce tracking for totalPendingCrossChain invariant ─
    uint64[] public openNonces;
    mapping(uint64 => bool)    public nonceOpen;
    mapping(uint64 => uint256) public nonceSent;   // amount stored when nonce opened
    uint256 public pendingCrossChainGhost;          // sum of open pendingCrossChain[nonce]

    uint256 public callCount;
    // N-06 caps apply at deployment; later market losses may reduce NAV without a new allocation.
    bool public goldCapViolation;
    bool public crossChainCapViolation;
    bool public dilutionViolation;

    function _checkUserDilution() internal {
        uint256 assetsNow = s.vault().totalAssets();
        uint256 supplyNow = s.vault().totalSupply();
        for (uint256 i = 0; i < 3; i++) {
            address actor = s.actors(i);
            uint256 previousAssets = preActionAssets[actor];
            if (preActionSupply[actor] == 0 || preActionShares[actor] == 0 || supplyNow == 0) continue;
            if (assetsNow * preActionSupply[actor] + 2e6 * supplyNow < previousAssets * supplyNow) {
                dilutionViolation = true;
            }
        }
    }

    // Per-function call counts for -vv summary (PR2: report losses actually happen)
    uint256 public depositCalls;
    uint256 public redeemCalls;
    uint256 public deploySpreadCalls;
    uint256 public deployAllocCalls;
    uint256 public recallSpreadCalls;
    uint256 public recallAllocCalls;
    uint256 public claimProfitCalls;
    uint256 public warpTimeCalls;
    uint256 public moveOracleCalls;
    uint256 public makeOracleStaleCalls;
    uint256 public refreshOracleCalls;
    uint256 public dropGoldPriceCalls;
    uint256 public deployCCCalls;          // deployCrossChain
    uint256 public settleWithFeeCalls;
    uint256 public settleShortfallCalls;
    uint256 public writeOffCalls;
    uint256 public lossRecallCalls;

    constructor(VaultInvariantBase _s) {
        s = _s;
    }

    function _pickActor(uint8 seed) internal view returns (address) {
        return s.actors(seed % 3);
    }

    // ── Snapshot helpers ─────────────────────────────────────────────────────

    function _snapshotForActor(address actor) internal {
        preActionShares[actor]  = s.vault().balanceOf(actor);
        preActionAssets[actor]  = s.vault().totalAssets();
        preActionSupply[actor]  = s.vault().totalSupply();
    }

    function _snapshotAll() internal {
        for (uint256 i = 0; i < 3; i++) {
            _snapshotForActor(s.actors(i));
        }
    }

    // ── Action 1: deposit ─────────────────────────────────────────────────────────
    function deposit(uint96 assets, uint8 actorSeed) external {
        callCount++; depositCalls++;
        uint256 amount = bound(uint256(assets), 1e6, 100_000e6);
        address actor  = _pickActor(actorSeed);

        uint256 bal = s.usdc().balanceOf(actor);
        if (bal < amount) {
            s.usdc().mint(actor, amount - bal);
        }

        _snapshotAll();

        vm.prank(actor);
        try s.vault().deposit(amount, actor) {
            hasDeposited[actor] = true;
            // N-06 isolates dilution checks from subsequent market-driven NAV changes.
            _checkUserDilution();
        } catch {}
    }

    // ── Action 2: redeem ──────────────────────────────────────────────────────────
    function redeem(uint96 shares, uint8 actorSeed) external {
        callCount++; redeemCalls++;
        address actor = _pickActor(actorSeed);
        uint256 maxSh = s.vault().maxRedeem(actor);
        if (maxSh == 0) return;

        uint256 amount = bound(uint256(shares), 1, maxSh);

        _snapshotAll();

        vm.prank(actor);
        // N-06 checks dilution only around the user action, not around unrelated later losses.
        try s.vault().redeem(amount, actor, actor) { _checkUserDilution(); } catch {}
    }

    // ── Action 3: deployToSpread ──────────────────────────────────────────────
    function deployToSpread(uint96 amount) external {
        callCount++; deploySpreadCalls++;
        if (s.vault().paused()) return;
        uint256 totalA = s.vault().totalAssets();
        if (totalA == 0) return;
        uint256 maxDeploy = (totalA * s.vault().maxAllocationBps()) / 10_000;
        uint256 already   = s.vault().totalDeployed();
        if (already >= maxDeploy) return;

        uint256 canDeploy = maxDeploy - already;
        uint256 amt = bound(uint256(amount), 1e6, 10_000e6);
        amt = amt > canDeploy ? canDeploy : amt;
        if (amt == 0) return;

        uint256 vaultBal = s.usdc().balanceOf(address(s.vault()));
        if (vaultBal < amt) return;

        // N-06 records cap compliance at entry so later losses cannot invalidate a permitted deployment.
        uint256 combined = s.goldSpreadAdp().currentValue() + s.goldAllocAdp().currentValue() + amt;
        uint256 cap = totalA * s.vault().MAX_GOLD_BPS() / 10_000;
        vm.prank(manager());
        try s.vault().deployCapitalAndExecute(address(s.goldSpreadAdp()), amt, "") {
            if (combined > cap) goldCapViolation = true;
        } catch {}
    }

    // ── Action 4: deployToAllocation ─────────────────────────────────────────
    function deployToAllocation(uint96 amount) external {
        callCount++; deployAllocCalls++;
        if (s.vault().paused()) return;
        uint256 totalA = s.vault().totalAssets();
        if (totalA == 0) return;
        uint256 maxDeploy = (totalA * s.vault().maxAllocationBps()) / 10_000;
        uint256 already   = s.vault().totalDeployed();
        if (already >= maxDeploy) return;

        uint256 canDeploy = maxDeploy - already;
        uint256 amt = bound(uint256(amount), 1e6, 10_000e6);
        amt = amt > canDeploy ? canDeploy : amt;
        if (amt == 0) return;

        if (!s.goldAllocAdp().isPriceSane()) return;

        uint256 vaultBal = s.usdc().balanceOf(address(s.vault()));
        if (vaultBal < amt) return;

        // N-06 records cap compliance at entry while retaining price-drop and loss-recall actions.
        uint256 combined = s.goldSpreadAdp().currentValue() + s.goldAllocAdp().currentValue() + amt;
        uint256 cap = totalA * s.vault().MAX_GOLD_BPS() / 10_000;
        vm.prank(manager());
        try s.vault().deployCapitalAndExecute(address(s.goldAllocAdp()), amt, "") {
            if (combined > cap) goldCapViolation = true;
        } catch {}
    }

    // ── Action 5: recallFromSpread ────────────────────────────────────────────
    function recallFromSpread() external {
        callCount++; recallSpreadCalls++;
        if (s.vault().paused()) return;
        uint256 deployed = s.goldSpreadAdp().totalDeployed();
        if (deployed == 0) return;

        vm.prank(manager());
        try s.vault().recallCapital(address(s.goldSpreadAdp()), deployed) {} catch {}
    }

    // ── Action 6: recallFromAllocation ───────────────────────────────────────
    function recallFromAllocation() external {
        callCount++; recallAllocCalls++;
        if (s.vault().paused()) return;
        uint256 deployed = s.goldAllocAdp().totalDeployed();
        if (deployed == 0) return;

        vm.prank(manager());
        try s.vault().recallCapital(address(s.goldAllocAdp()), deployed) {} catch {}
    }

    // ── Action 7: claimProfit ─────────────────────────────────────────────────
    function claimProfit(uint96 grossProfit) external {
        callCount++; claimProfitCalls++;
        uint256 gross = bound(uint256(grossProfit), 1e6, 10_000e6);

        s.usdc().mint(address(s.vault()), gross);
        // Bound claims to net realized profit so losses/locked profit never turn principal into fees.
        uint256 available = s.vault().realizedProfit();
        if (available == 0) return;
        gross = bound(gross, 1, available);
        // N-21: compare the pre-claim processed price and record only successful claims, excluding Wakala booking.
        uint256 deficit = _preProfitDeficit();
        uint256 fees = s.treasury().pendingFees();
        uint256 unbooked = s.vault().pendingWakalaFee();
        uint256 net = gross - gross * s.purificationEscrow().purificationBps() / 10_000;
        net -= net * s.charityModule().charityBps() / 10_000;
        // Resolve every external getter before the prank: a call in the try expression would consume it.
        ShariahVault v = s.vault();
        address mgr = manager();
        vm.prank(mgr);
        try v.claimMusharakahProfit(gross) {
            successfulClaims++;
            hwmDeficitBeforeClaim = deficit;
            claimWasAboveHWM = deficit == 0;
            lastVaultShareFromClaim = s.treasury().pendingFees() - fees - unbooked;
            if (deficit > 0 && net <= deficit) {
                recoveryOnlyClaims++;
                if (lastVaultShareFromClaim != 0) recoveryShareViolation = true;
            }
        } catch {}
    }

    function _preProfitDeficit() internal view returns (uint256) {
        uint256 nav = s.vault().totalAssets();
        uint256 gain = s.vault().goldUnrealizedGain();
        nav = nav > gain ? nav - gain : 0;
        uint256 period = s.vault().profitUnlockPeriod();
        uint256 end = s.vault().unlockedAt();
        if (period != 0 && block.timestamp < end && end >= period && end - period <= block.timestamp) {
            nav += Math.mulDiv(s.vault().lockedProfit(), end - block.timestamp, period);
        }
        nav = Math.min(nav, s.vault().profitBase());
        uint256 supply = s.vault().totalSupply() + 1e6;
        uint256 price = Math.mulDiv(nav + 1, 1e18, supply);
        uint256 high = s.vault().highWaterMarkPerShare();
        return high > price ? Math.mulDiv(high - price, supply, 1e18) : 0;
    }

    // ── Action 8: warpTime ────────────────────────────────────────────────────
    function warpTime(uint32 secs) external {
        callCount++; warpTimeCalls++;
        uint256 elapsed = bound(uint256(secs), 1, 7 days);
        vm.warp(block.timestamp + elapsed);
    }

    // ── Action 9: moveOraclePrice ─────────────────────────────────────────────
    function moveOraclePrice(int16 pctBps) external {
        callCount++; moveOracleCalls++;
        int256 delta = bound(int256(pctBps), -1000, 1000);
        int256 current = s.xauOracle().price();
        int256 newPrice = current + (current * delta) / 10_000;
        if (newPrice <= 0) newPrice = 1e8;
        s.xauOracle().setPrice(newPrice);
        uint256 newPoolPrice = (uint256(newPrice) * 1e6) / 1e8;
        if (newPoolPrice == 0) newPoolPrice = 1;
        s.xautPool().setPrice(newPoolPrice);
    }

    // ── Action 10: makeOracleStale ────────────────────────────────────────────
    function makeOracleStale() external {
        callCount++; makeOracleStaleCalls++;
        uint256 staleBy = s.goldAllocAdp().maxStalenessSecs() + 1;
        vm.warp(block.timestamp + staleBy);
        // Do NOT update oracle's updatedAt → it becomes stale
    }

    // ── Action 11: refreshOracle ──────────────────────────────────────────────
    function refreshOracle() external {
        callCount++; refreshOracleCalls++;
        s.xauOracle().setUpdatedAt(block.timestamp);
        s.xauOracle().setPrice(s.xauOracle().price());
        // Also refresh GoldExchangeAdapter's S2-H oracle timestamp
        s.goldSpreadOracle().setUpdatedAt(block.timestamp);
        s.goldSpreadOracle().setPrice(s.goldSpreadOracle().price());
    }

    // ── Action 12 (PR2): dropGoldPrice — large price drop causes NAV to fall ──
    // This proves the handler CAN produce losses (share price CAN fall).
    function dropGoldPrice(uint8 pctDrop) external {
        callCount++; dropGoldPriceCalls++;
        // Drop price 1%–30%
        uint256 drop = bound(uint256(pctDrop), 100, 3000); // bps
        int256 current = s.xauOracle().price();
        if (current <= 0) return;
        int256 newPrice = current - (current * int256(drop)) / 10_000;
        if (newPrice <= 0) newPrice = 1e8;
        s.xauOracle().setPrice(newPrice);
        // Pool price drops proportionally
        uint256 newPoolPrice = (uint256(newPrice) * 1e6) / 1e8;
        if (newPoolPrice == 0) newPoolPrice = 1;
        s.xautPool().setPrice(newPoolPrice);
        // Also drop S2-H oracle price
        int256 cur2 = s.goldSpreadOracle().price();
        if (cur2 > 0) {
            int256 np2 = cur2 - (cur2 * int256(drop)) / 10_000;
            if (np2 <= 0) np2 = 1e8;
            s.goldSpreadOracle().setPrice(np2);
            s.paxgRouter().setPrice(uint256(np2) / 100);
        }
        // N-06 refreshes cached gold values so the drop action immediately exercises vault writedowns.
        s.goldSpreadAdp().pokePrice();
        s.goldAllocAdp().pokePrice();
    }

    // ── Action 13 (PR2): deployCrossChain — put capital in-flight ────────────
    function deployCrossChainAction(uint96 amount) external {
        callCount++; deployCCCalls++;
        if (s.vault().paused()) return;
        if (address(s.mockMessenger()) == address(0)) return;

        uint256 totalA = s.vault().totalAssets();
        if (totalA == 0) return;

        uint256 maxDeploy = (totalA * s.vault().maxAllocationBps()) / 10_000;
        uint256 already   = s.vault().totalDeployed();
        if (already >= maxDeploy) return;

        uint256 canDeploy = maxDeploy - already;
        uint256 maxPending = (totalA * s.vault().maxPendingCrossChainBps()) / 10_000;
        uint256 inFlight   = s.vault().totalPendingCrossChain();
        if (inFlight >= maxPending) return;
        uint256 canPend = maxPending - inFlight;

        uint256 amt = bound(uint256(amount), 1e6, 5_000e6);
        amt = amt > canDeploy ? canDeploy : amt;
        amt = amt > canPend   ? canPend   : amt;
        if (amt == 0) return;

        uint256 vaultBal = s.usdc().balanceOf(address(s.vault()));
        if (vaultBal < amt) return;

        // Task M: ghost keys track local positions rather than Circle's offchain nonce.
        uint64 nonceNow = s.vault().crossChainPositionCounter() + 1;

        vm.prank(manager());
        try s.vault().deployCrossChain(6, bytes32(uint256(uint160(makeAddr("dest")))), amt) {
            // N-06 checks the entry-time pending cap, not a smaller NAV after subsequent losses.
            if (inFlight + amt > maxPending) crossChainCapViolation = true;
            nonceOpen[nonceNow]    = true;
            nonceSent[nonceNow]    = amt;
            openNonces.push(nonceNow);
            pendingCrossChainGhost += amt;
        } catch {}
    }

    // ── Action 14 (PR2): settleWithFee — return most capital with a CCTP fee ──
    function settleWithFee(uint8 nonceSeed, uint8 feePctBps) external {
        callCount++; settleWithFeeCalls++;
        if (openNonces.length == 0) return;

        uint256 idx   = uint256(nonceSeed) % openNonces.length;
        uint64  nonce = openNonces[idx];
        if (!nonceOpen[nonce]) return;

        uint256 sent    = nonceSent[nonce];
        uint256 feeAmt  = bound(uint256(feePctBps), 0, 300) * sent / 10_000;
        uint256 netAmt  = sent - feeAmt; // received after fee

        // Task M: mint inside receiveMessage so atomic balance-delta accounting is exercised.
        bytes memory msg_ = _buildCctpMsg(nonce, sent, feeAmt);
        s.mockTransmitter().setMintAmount(netAmt);

        vm.prank(manager());
        try s.vault().settleCrossChainWithMessage(nonce, msg_, "") {
            _removeNonce(idx, nonce, sent);
        } catch {}
    }

    // ── Action 15 (PR2): settleShortfall — strategy returned less ────────────
    function settleShortfall(uint8 nonceSeed, uint8 returnPctBps) external {
        callCount++; settleShortfallCalls++;
        if (openNonces.length == 0) return;

        uint256 idx   = uint256(nonceSeed) % openNonces.length;
        uint64  nonce = openNonces[idx];
        if (!nonceOpen[nonce]) return;

        uint256 sent      = nonceSent[nonce];
        uint256 returnPct = bound(uint256(returnPctBps), 7000, 10_000); // 70%-100% returned
        uint256 netAmt    = sent * returnPct / 10_000;

        // Task M: the transmitter mints during the measured atomic settle call.
        bytes memory msg_ = _buildCctpMsg(nonce, netAmt, 0); // no fee, just shortfall
        s.mockTransmitter().setMintAmount(netAmt);

        vm.prank(manager());
        try s.vault().settleCrossChainWithMessage(nonce, msg_, "") {
            _removeNonce(idx, nonce, sent);
        } catch {}
    }

    // ── Action 16 (PR2): writeOff — book a cross-chain loss (owner only) ─────
    function writeOff(uint8 nonceSeed) external {
        callCount++; writeOffCalls++;
        if (openNonces.length == 0) return;

        uint256 idx   = uint256(nonceSeed) % openNonces.length;
        uint64  nonce = openNonces[idx];
        if (!nonceOpen[nonce]) return;

        uint256 sent = nonceSent[nonce];

        vm.prank(owner_());
        try s.vault().settleCrossChain(nonce, 0) {
            _removeNonce(idx, nonce, sent);
        } catch {}
    }

    // ── Action 17 (PR2): lossRecall — recall when market moved against position
    function lossRecall() external {
        callCount++; lossRecallCalls++;
        if (s.vault().paused()) return;

        // Drop gold price dramatically before recalling allocation adapter
        int256 current = s.xauOracle().price();
        if (current > 0) {
            int256 lower = current * 85 / 100; // 15% drop
            if (lower <= 0) lower = 1e8;
            s.xauOracle().setPrice(lower);
            uint256 newPool = (uint256(lower) * 1e6) / 1e8;
            if (newPool == 0) newPool = 1;
            s.xautPool().setPrice(newPool);
        }

        uint256 deployed = s.goldAllocAdp().totalDeployed();
        if (deployed == 0) return;

        vm.prank(manager());
        try s.vault().recallCapital(address(s.goldAllocAdp()), deployed) {} catch {}
    }

    // ── Internal helpers ──────────────────────────────────────────────────────

    /// @dev Build a minimal CCTP V2 BurnMessageV2 (376 bytes: 148 header + 228 body).
    ///      Body layout: version(4)+burnToken(32)+mintRecipient(32)+amount(32)+
    ///                   messageSender(32)+maxFee(32)+feeExecuted(32)+expirationBlock(32).
    function _buildCctpMsg(uint64 nonce_, uint256 amount_, uint256 feeExecuted_)
        internal view returns (bytes memory)
    {
        // Task M: native header with bytes32 nonce and registered remote messenger.
        uint32 remoteDomain = s.vault().pendingCrossChainDestinationDomain(nonce_);
        bytes memory header = abi.encodePacked(
            uint32(1), remoteDomain, s.vault().localDomain(), bytes32(uint256(nonce_)),
            s.vault().remoteTokenMessenger(remoteDomain),
            bytes32(uint256(uint160(s.vault().tokenMessenger()))),
            bytes32(uint256(uint160(address(s.vault())))), uint32(2000), uint32(2000) // destinationCaller = vault
        );
        bytes memory body = new bytes(228);
        body[3] = 0x01;
        // mintRecipient at body[36..67] = vault address
        bytes32 recipientWord = bytes32(uint256(uint160(address(s.vault()))));
        for (uint256 i = 0; i < 32; i++) {
            body[36 + i] = recipientWord[i];
        }
        // amount at body[68..99]
        bytes32 amountWord = bytes32(amount_);
        for (uint256 i = 0; i < 32; i++) {
            body[68 + i] = amountWord[i];
        }
        // maxFee at body[132..163] — set equal to feeExecuted as a valid ceiling
        bytes32 maxFeeWord = bytes32(feeExecuted_);
        for (uint256 i = 0; i < 32; i++) {
            body[132 + i] = maxFeeWord[i];
        }
        // feeExecuted at body[164..195] (actual fee taken; 0 for Standard Transfer)
        bytes32 feeWord = bytes32(feeExecuted_);
        for (uint256 i = 0; i < 32; i++) {
            body[164 + i] = feeWord[i];
        }
        // expirationBlock at body[196..227] — left zero
        return abi.encodePacked(header, body);
    }

    function _removeNonce(uint256 idx, uint64 nonce, uint256 sent) internal {
        nonceOpen[nonce]        = false;
        pendingCrossChainGhost  = pendingCrossChainGhost >= sent
            ? pendingCrossChainGhost - sent : 0;
        // swap-and-pop
        uint256 last = openNonces.length - 1;
        if (idx != last) {
            openNonces[idx] = openNonces[last];
        }
        openNonces.pop();
    }

    function manager()  internal view returns (address) { return s.manager();  }
    function owner_()   internal view returns (address) { return s.owner();    }

    function openNoncesLength() external view returns (uint256) {
        return openNonces.length;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {VaultInvariantBase} from "./VaultInvariant.Base.t.sol";
import {VaultHandler}       from "./VaultInvariant.Handler.t.sol";

/// @title  VaultInvariantTest
/// @notice Invariant test suite for ShariahVault.
///
/// PR2 updates:
///   - Invariant 4 REPLACED: "share-price monotone" → "no dilution from other users"
///     (share price CAN fall from gold drops, cross-chain shortfalls, fees, write-offs).
///   - Invariant 7 ADDED: totalPendingCrossChain == Σ open pendingCrossChain[nonce].
///   - Invariant 8 ADDED: cross-chain cap never exceeded after every deploy.
///
/// Run with:
///   forge test --match-path 'contracts/test/invariant/*' --invariant-runs 256 --invariant-depth 50 -vv
contract VaultInvariantTest is VaultInvariantBase {

    VaultHandler internal handler;

    function setUp() public override {
        super.setUp();
        handler = new VaultHandler(this);
        targetContract(address(handler));
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 1 — redeem(maxRedeem) never reverts for any actor with shares
    // ══════════════════════════════════════════════════════════════════════════
    function invariant_redeemNeverReverts() public {
        for (uint256 i = 0; i < 3; i++) {
            address actor = actors[i];
            uint256 maxSh = vault.maxRedeem(actor);
            // N-06 prices losses immediately but does not auto-recall: only assert exits covered by idle liquidity.
            uint256 liquidShares = vault.convertToShares(usdc.balanceOf(address(vault)));
            if (maxSh > liquidShares) maxSh = liquidShares;
            if (maxSh == 0) continue;

            uint256 snap = vm.snapshot();
            vm.prank(actor);
            try vault.redeem(maxSh, actor, actor) {
                // success — ok
            } catch (bytes memory err) {
                vm.revertTo(snap);
                bytes memory msg_ = abi.encodePacked(
                    "invariant_redeemNeverReverts: redeem failed for actor ",
                    err
                );
                revert(string(msg_));
            }
            vm.revertTo(snap);
        }
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 2 — totalAssets accounting is self-consistent
    // ══════════════════════════════════════════════════════════════════════════
    /// @notice N-06 deducts gold writedowns as well as locked profit and fees, within 2 USDC tolerance.
    function invariant_totalAssetsAccounting() public view {
        uint256 idle          = usdc.balanceOf(address(vault));
        uint256 deployed      = vault.totalDeployed();
        uint256 lockedProfitNow = _currentLockedProfitPublic();
        uint256 base          = idle + deployed;
        uint256 writedown     = vault.goldWritedown();
        base = base > writedown ? base - writedown : 0;
        // G-1 includes oracle/cache appreciation in share NAV, never in distributable profit.
        base += vault.goldUnrealizedGain();
        uint256 expected      = base > lockedProfitNow ? base - lockedProfitNow : 0;
        uint256 fees          = treasury.pendingFees();
        expected = expected > fees ? expected - fees : 0;
        // N-20: share NAV includes unbooked time fees even before a state-changing accrual.
        uint256 unbooked = vault.pendingWakalaFee();
        expected = expected > unbooked ? expected - unbooked : 0;
        uint256 actual        = vault.totalAssets();

        uint256 diff = actual > expected ? actual - expected : expected - actual;
        assertLe(diff, 2e6, "totalAssets accounting: deviation > 2 USDC");
    }

    // G-1 allows marked NAV above cost but never distributes unrealized appreciation.
    function invariant_unrealizedGainsNeverDistributable() public view {
        uint256 cost = usdc.balanceOf(address(vault)) + vault.totalDeployed();
        uint256 deductions = _currentLockedProfitPublic() + treasury.pendingFees() + vault.profitBase();
        uint256 available = cost > deductions ? cost - deductions : 0;
        assertLe(vault.realizedProfit(), available);
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 3 — combined gold cap never exceeded
    // ══════════════════════════════════════════════════════════════════════════
    function invariant_goldCapNotExceeded() public view {
        // N-06 loss recognition can shrink NAV after entry; enforce the cap at each deployment instead.
        assertFalse(handler.goldCapViolation(), "gold deployment exceeded entry-time cap");
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 4 (PR2) — no dilution: no actor's share value grows due to
    //                     another actor depositing or redeeming.
    //                     (Share value CAN fall from gold drops, cross-chain loss,
    //                     fees, or write-offs — those are NOT invariant violations.)
    // ══════════════════════════════════════════════════════════════════════════
    /// @notice For each actor: if they held shares BEFORE another actor's action,
    ///         their pro-rata USDC value must not have INCREASED.
    ///         Check: preValue = preAssets * preShares / preSupply
    ///                curValue  = curAssets  * preShares / curSupply
    ///         Dilution would mean curValue < preValue (another actor's deposit
    ///         added assets to the pool, which should never decrease an existing
    ///         holder's share value; a redeem increases others' per-share value —
    ///         that is also fine).
    ///
    ///         Formally: preAssets/preSupply <= curAssets/curSupply + epsilon
    ///         i.e. another actor's action must not lower the exchange rate for
    ///         existing holders (beyond ERC-4626 rounding).
    function invariant_noDilutionFromOtherUsers() public view {
        // N-06 market losses are valid; the handler latches dilution only around deposits/redeems.
        assertFalse(handler.dilutionViolation(), "user action diluted existing shares");
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 5 — vaultShare == 0 when HWM deficit exists before claim
    // ══════════════════════════════════════════════════════════════════════════
    function invariant_vaultShareZero_when_hwmDeficit() public view {
        // N-21: successful recovery-only waterfalls must never book a manager share; excess may earn a split.
        assertFalse(handler.recoveryShareViolation(), "manager earned on unrecovered loss");
    }

    // N-21: prove the recovery ghost observes a successful below-high waterfall rather than only caught reverts.
    function test_N21_recoveryInvariant_observesSuccessfulClaim() public {
        // A full processed peak plus entry after loss creates genuine flow-neutral recovery.
        vm.prank(owner);
        treasury.setAdminFeeBps(0);
        handler.deposit(uint96(1_000e6), 0);
        handler.claimProfit(uint96(300e6));
        assertEq(handler.successfulClaims(), 1);
        skip(vault.profitUnlockPeriod());
        usdc.burn(address(vault), 200e6);
        handler.deposit(uint96(1_000e6), 1);
        // Only half of the loss is recovered: realized profit is measured above the processed basis, so nothing is claimable.
        usdc.mint(address(vault), 100e6);
        handler.claimProfit(uint96(50e6));
        assertEq(handler.successfulClaims(), 1, "no claim while NAV is below the processed basis");
        // Recovery past the old high leaves genuine profit; only that excess can be claimed.
        usdc.mint(address(vault), 200e6);
        handler.claimProfit(uint96(50e6));
        assertEq(handler.successfulClaims(), 2);
        assertEq(handler.recoveryOnlyClaims(), 0, "a claim above the processed basis is never recovery-only");
        assertFalse(handler.recoveryShareViolation());
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 6 — lockedProfit decays to 0 after unlockedAt
    // ══════════════════════════════════════════════════════════════════════════
    function invariant_lockedProfitDecaysToZero() public view {
        uint256 ua = vault.unlockedAt();
        if (ua == 0) return;
        if (block.timestamp >= ua) {
            uint256 currentLocked = _currentLockedProfitPublic();
            assertEq(currentLocked, 0, "lockedProfit must be 0 after unlockedAt");
        }
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 7 (PR2) — totalPendingCrossChain == Σ open pendingCrossChain[nonce]
    // ══════════════════════════════════════════════════════════════════════════
    /// @notice The on-chain totalPendingCrossChain must equal the handler's ghost
    ///         sum of still-open nonces.  Any settled/written-off nonce is removed
    ///         from both.
    function invariant_totalPendingCrossChain_consistent() public view {
        uint256 onChain = vault.totalPendingCrossChain();
        uint256 ghost   = handler.pendingCrossChainGhost();
        // Allow 1 USDC tolerance for any rounding during settle
        uint256 diff = onChain > ghost ? onChain - ghost : ghost - onChain;
        assertLe(diff, 1e6, "totalPendingCrossChain deviates from ghost sum");
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Invariant 8 (PR2) — cross-chain pending cap never exceeded
    // ══════════════════════════════════════════════════════════════════════════
    /// @notice After every deploy, totalPendingCrossChain must remain <=
    ///         maxPendingCrossChainBps * totalAssets / 10_000.
    ///         (The handler's deployCrossChainAction only deploys when the cap
    ///         permits; this invariant catches any code path that bypasses the guard.)
    function invariant_crossChainCapNeverExceeded() public view {
        // N-06 gold losses may shrink NAV after a valid burn without increasing pending principal.
        assertFalse(handler.crossChainCapViolation(), "cross-chain deployment exceeded entry-time cap");
    }
}

